INSERT INTO "vstep_questions" VALUES(1587,NULL,38,'Đâu không phải là rủi ro có thể xảy ra khi tham gia các hoạt động trực tuyến?','MULTIPLE_CHOICE','[{"id":"1","content":"Lộ thông tin cá nhân","isCorrect":false},{"id":"2","content":"Bị lừa đảo","isCorrect":false},{"id":"3","content":"Bị mắc bệnh truyền nhiễm","isCorrect":true},{"id":"4","content":"Bị đánh cắp dữ liệu","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',21,'2026-01-29 18:29:00','Bệnh truyền nhiễm sinh học lây qua cơ thể người, không lây qua đường truyền Internet.');
INSERT INTO "vstep_questions" VALUES(1588,NULL,38,'Điều nào sau đây là lợi thế của thư điện tử so với thư tín gửi qua đường bưu điện?','MULTIPLE_CHOICE','[{"id":"1","content":"Bảo mật tuyệt đối","isCorrect":false},{"id":"2","content":"Gửi được văn bản giấy","isCorrect":false},{"id":"3","content":"Tốc độ chuyển thư nhanh","isCorrect":true},{"id":"4","content":"Không cần mạng Internet","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',22,'2026-01-29 18:29:00','Thư điện tử có tốc độ truyền tải gần như tức thời, nhanh hơn nhiều so với đường bưu điện.');
INSERT INTO "vstep_questions" VALUES(1589,NULL,38,'URL là viết tắt của:','MULTIPLE_CHOICE','[{"id":"1","content":"Uniform Resource Locator","isCorrect":true},{"id":"2","content":"Universal Resource Link","isCorrect":false},{"id":"3","content":"Uniform Reference Link","isCorrect":false},{"id":"4","content":"Universal Reference Locator","isCorrect":false}]','1',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',23,'2026-01-29 18:29:00','URL là viết tắt của Uniform Resource Locator (Định vị tài nguyên thống nhất).');
INSERT INTO "vstep_questions" VALUES(1590,NULL,38,'Nút Back trên thanh công cụ của trình duyệt Web có tác dụng gì?','MULTIPLE_CHOICE','[{"id":"1","content":"Chuyển đến trang chủ","isCorrect":false},{"id":"2","content":"Tải lại trang web","isCorrect":false},{"id":"3","content":"Quay trở lại trang web trước đó","isCorrect":true},{"id":"4","content":"Thoát khỏi trình duyệt","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',24,'2026-01-29 18:29:00','Nút Back dùng để quay lại trang web vừa truy cập ngay trước đó.');
INSERT INTO "vstep_questions" VALUES(1591,NULL,38,'Nơi cộng đồng mạng thường xuyên trao đổi thông tin được gọi là:','MULTIPLE_CHOICE','[{"id":"1","content":"Blog","isCorrect":false},{"id":"2","content":"Email","isCorrect":false},{"id":"3","content":"Forum","isCorrect":true},{"id":"4","content":"Website","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',25,'2026-01-29 18:29:00','Forum (Diễn đàn) là nơi cộng đồng mạng tạo chủ đề để thảo luận và trao đổi.');
INSERT INTO "vstep_questions" VALUES(1592,NULL,38,'Để tìm nội dung trong trang Web đang mở, ta dùng chức năng:','MULTIPLE_CHOICE','[{"id":"1","content":"Bookmark","isCorrect":false},{"id":"2","content":"History","isCorrect":false},{"id":"3","content":"Find","isCorrect":true},{"id":"4","content":"Refresh","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',26,'2026-01-29 18:29:00','Chức năng Find (thường là Ctrl + F) dùng để tìm từ khóa trong trang đang mở.');
INSERT INTO "vstep_questions" VALUES(1593,NULL,38,'Muốn tìm hình ảnh trên Google, ta chọn mục:','MULTIPLE_CHOICE','[{"id":"1","content":"Web","isCorrect":false},{"id":"2","content":"Images","isCorrect":true},{"id":"3","content":"Videos","isCorrect":false},{"id":"4","content":"News","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',27,'2026-01-29 18:29:00','Để tìm hình ảnh, cần chọn mục Images (Hình ảnh) trên giao diện Google.');
INSERT INTO "vstep_questions" VALUES(1594,NULL,38,'Thuật ngữ dùng để chỉ các trang tin tức trên mạng là:','MULTIPLE_CHOICE','[{"id":"1","content":"Browser","isCorrect":false},{"id":"2","content":"Website","isCorrect":true},{"id":"3","content":"Email","isCorrect":false},{"id":"4","content":"Forum","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',28,'2026-01-29 18:29:00','Thuật ngữ chỉ các trang tin tức, trang mạng nói chung là Website.');
INSERT INTO "vstep_questions" VALUES(1595,NULL,38,'Để sao chép nội dung trên trang web, ta thực hiện:','MULTIPLE_CHOICE','[{"id":"1","content":"Ctrl + X","isCorrect":false},{"id":"2","content":"Ctrl + V","isCorrect":false},{"id":"3","content":"Ctrl + C","isCorrect":true},{"id":"4","content":"Ctrl + Z","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',29,'2026-01-29 18:29:00','Ctrl + C là phím tắt dùng để sao chép nội dung.');
INSERT INTO "vstep_questions" VALUES(1596,NULL,38,'Để tải lại (Refresh) một trang web, ta sử dụng phím nào sau đây?','MULTIPLE_CHOICE','[{"id":"1","content":"F1","isCorrect":false},{"id":"2","content":"F3","isCorrect":false},{"id":"3","content":"F5","isCorrect":true},{"id":"4","content":"F7","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',30,'2026-01-29 18:29:00','Phím F5 là phím tắt mặc định để tải lại (làm mới) nội dung trang web.');
INSERT INTO "vstep_questions" VALUES(1597,NULL,38,'Để đóng trình duyệt nhanh, ta dùng tổ hợp phím:','MULTIPLE_CHOICE','[{"id":"1","content":"Ctrl + W","isCorrect":false},{"id":"2","content":"Alt + F4","isCorrect":true},{"id":"3","content":"Ctrl + P","isCorrect":false},{"id":"4","content":"Ctrl + F","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',31,'2026-01-29 18:29:00','Alt + F4 là phím tắt hệ thống để đóng cửa sổ ứng dụng (bao gồm trình duyệt).');
INSERT INTO "vstep_questions" VALUES(1598,NULL,38,'Email rác thường nằm trong thư mục:','MULTIPLE_CHOICE','[{"id":"1","content":"Inbox","isCorrect":false},{"id":"2","content":"Draft","isCorrect":false},{"id":"3","content":"Spam","isCorrect":true},{"id":"4","content":"Sent","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',32,'2026-01-29 18:29:00','Thư rác, thư quảng cáo thường được hệ thống lọc vào mục Spam.');
INSERT INTO "vstep_questions" VALUES(1599,NULL,38,'Giao thức bảo mật giúp trang web an toàn hơn là:','MULTIPLE_CHOICE','[{"id":"1","content":"http","isCorrect":false},{"id":"2","content":"ftp","isCorrect":false},{"id":"3","content":"https","isCorrect":true},{"id":"4","content":"www","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',33,'2026-01-29 18:29:00','HTTPS là giao thức truyền tải siêu văn bản bảo mật (Secure).');
INSERT INTO "vstep_questions" VALUES(1600,NULL,38,'Đâu không phải là thành phần của biểu mẫu (Form) trên Web?','MULTIPLE_CHOICE','[{"id":"1","content":"Text box","isCorrect":false},{"id":"2","content":"Radio button","isCorrect":false},{"id":"3","content":"Check box","isCorrect":false},{"id":"4","content":"Access box","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',34,'2026-01-29 18:29:00','Text box, Radio button, Check box là chuẩn; Access box không phải thành phần của biểu mẫu web.');
INSERT INTO "vstep_questions" VALUES(1601,NULL,38,'Muốn đăng nhập hộp thư điện tử, cần có:','MULTIPLE_CHOICE','[{"id":"1","content":"Tên máy tính","isCorrect":false},{"id":"2","content":"Tên trình duyệt","isCorrect":false},{"id":"3","content":"Tên đăng nhập và mật khẩu","isCorrect":true},{"id":"4","content":"Địa chỉ IP","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',35,'2026-01-29 18:29:00','Cần có Tên đăng nhập (Username) và Mật khẩu (Password) để truy cập.');
INSERT INTO "vstep_questions" VALUES(1602,NULL,38,'Trên trang web www.google.com, phát biểu nào sau đây không đúng?','MULTIPLE_CHOICE','[{"id":"1","content":"Có thể tìm website","isCorrect":false},{"id":"2","content":"Có thể tìm hình ảnh","isCorrect":false},{"id":"3","content":"Có thể tìm video","isCorrect":false},{"id":"4","content":"Có thể tìm âm thanh trực tiếp bằng từ khóa","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',36,'2026-01-29 18:29:00','Google tìm tốt web, ảnh, video; tìm âm thanh trực tiếp bằng từ khóa không phải tính năng chính mặc định.');
INSERT INTO "vstep_questions" VALUES(1603,NULL,38,'Muốn tìm thông tin “Công chức” chỉ trong website www.laodong.gov.vn trên Google, ta gõ:','MULTIPLE_CHOICE','[{"id":"1","content":"Công chức laodong.gov.vn","isCorrect":false},{"id":"2","content":"Công chức AND laodong.gov.vn","isCorrect":false},{"id":"3","content":"Công chức site:laodong.gov.vn","isCorrect":true},{"id":"4","content":"site:Công chức laodong.gov.vn","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',37,'2026-01-29 18:29:01','Cú pháp "site:tên_miền" dùng để tìm kiếm nội dung nằm gói gọn trong website đó.');
INSERT INTO "vstep_questions" VALUES(1604,NULL,38,'Dịch vụ thư điện tử (Email) được dùng để:','MULTIPLE_CHOICE','[{"id":"1","content":"Soạn thảo văn bản","isCorrect":false},{"id":"2","content":"Trao đổi thư qua Internet","isCorrect":true},{"id":"3","content":"Lưu trữ dữ liệu cá nhân","isCorrect":false},{"id":"4","content":"Truy cập trang web","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',38,'2026-01-29 18:29:01','Chức năng chính của Email là trao đổi thư từ, thông tin qua mạng Internet.');
INSERT INTO "vstep_questions" VALUES(1605,NULL,38,'Email chưa gửi sẽ được lưu trong thư mục nào?','MULTIPLE_CHOICE','[{"id":"1","content":"Inbox","isCorrect":false},{"id":"2","content":"Sent","isCorrect":false},{"id":"3","content":"Draft","isCorrect":true},{"id":"4","content":"Spam","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',39,'2026-01-29 18:29:01','Thư đang soạn nhưng chưa gửi sẽ được lưu trong mục Draft (Thư nháp).');
INSERT INTO "vstep_questions" VALUES(1606,NULL,38,'Muốn in toàn bộ trang web, trong hộp thoại Print tại mục Page range ta chọn:','MULTIPLE_CHOICE','[{"id":"1","content":"Pages","isCorrect":false},{"id":"2","content":"Current page","isCorrect":false},{"id":"3","content":"Selection","isCorrect":false},{"id":"4","content":"All","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',40,'2026-01-29 18:29:01','Chọn "All" trong mục Page range để in toàn bộ các trang.');
INSERT INTO "vstep_questions" VALUES(1647,NULL,40,'Khi có nhiều file đang mở, lệnh File → Close dùng để:','MULTIPLE_CHOICE','[{"id":"1","content":"Đóng slide hiện tại","isCorrect":false},{"id":"2","content":"Tắt máy tính","isCorrect":false},{"id":"3","content":"Thoát PowerPoint","isCorrect":false},{"id":"4","content":"Đóng file hiện tại","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',1,'2026-01-30 18:19:28','Lệnh Close chỉ đóng file đang làm việc, phần mềm PowerPoint vẫn hoạt động.');
INSERT INTO "vstep_questions" VALUES(1648,NULL,40,'Chế độ hiển thị nào cho phép sắp xếp lại các slide?','MULTIPLE_CHOICE','[{"id":"1","content":"View → Reading View","isCorrect":false},{"id":"2","content":"View → Normal","isCorrect":false},{"id":"3","content":"View → Page Layout","isCorrect":false},{"id":"4","content":"View → Slide Sorter","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',2,'2026-01-30 18:19:28','Chế độ Slide Sorter (Sắp xếp slide) hiển thị các slide dạng thu nhỏ, dễ dàng sắp xếp nhất.');
INSERT INTO "vstep_questions" VALUES(1649,NULL,40,'Thanh công cụ truy cập nhanh trong PowerPoint gọi là:','MULTIPLE_CHOICE','[{"id":"1","content":"Quick Toolbar Access","isCorrect":false},{"id":"2","content":"Access Quick Toolbar","isCorrect":false},{"id":"3","content":"Toolbar Quick Access","isCorrect":false},{"id":"4","content":"Quick Access Toolbar","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',3,'2026-01-30 18:19:28','Thanh công cụ chứa các lệnh lưu, undo, redo... gọi là Quick Access Toolbar.');
INSERT INTO "vstep_questions" VALUES(1650,NULL,40,'Chuyển sang chế độ Reading View bằng:','MULTIPLE_CHOICE','[{"id":"1","content":"Review → Reading View","isCorrect":false},{"id":"2","content":"Review → Reading Mode","isCorrect":false},{"id":"3","content":"View → Reading Mode","isCorrect":false},{"id":"4","content":"View → Reading View","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',4,'2026-01-30 18:19:28','View > Reading View chuyển sang chế độ xem dạng đọc (gần giống trình chiếu nhưng có thanh tiêu đề).');
INSERT INTO "vstep_questions" VALUES(1651,NULL,40,'Khi đang trình chiếu, muốn dừng trình diễn ta nhấn phím nào?','MULTIPLE_CHOICE','[{"id":"1","content":"End","isCorrect":false},{"id":"2","content":"Tab","isCorrect":false},{"id":"3","content":"Home","isCorrect":false},{"id":"4","content":"Esc","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',5,'2026-01-30 18:19:28','Phím Esc dùng để thoát khỏi chế độ trình chiếu và quay về chế độ soạn thảo.');
INSERT INTO "vstep_questions" VALUES(1652,NULL,40,'Lệnh chia các ô trong bảng thành nhiều ô nằm ở:','MULTIPLE_CHOICE','[{"id":"1","content":"Table Tools Design","isCorrect":false},{"id":"2","content":"Insert","isCorrect":false},{"id":"3","content":"Design","isCorrect":false},{"id":"4","content":"Table Tools Layout","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',6,'2026-01-30 18:19:28','Thẻ Table Tools Layout cung cấp các lệnh chia (Split) hoặc gộp (Merge) ô.');
INSERT INTO "vstep_questions" VALUES(1653,NULL,40,'Thay đổi kiểu Numbering bằng:','MULTIPLE_CHOICE','[{"id":"1","content":"Insert → Symbol","isCorrect":false},{"id":"2","content":"Home → Bullet","isCorrect":false},{"id":"3","content":"Insert → Numbering","isCorrect":false},{"id":"4","content":"Home → Numbering","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',7,'2026-01-30 18:19:28','Thẻ Home > Numbering dùng để đổi kiểu đánh số thứ tự.');
INSERT INTO "vstep_questions" VALUES(1654,NULL,40,'Ẩn một slide đã chọn bằng:','MULTIPLE_CHOICE','[{"id":"1","content":"Edit → Hide Slide","isCorrect":false},{"id":"2","content":"Insert → Hide Slide","isCorrect":false},{"id":"3","content":"Format → Hide Slide","isCorrect":false},{"id":"4","content":"Slide Show → Hide Slide","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',8,'2026-01-30 18:19:28','Slide Show > Hide Slide dùng để ẩn slide đi, không cho hiện khi trình chiếu.');
INSERT INTO "vstep_questions" VALUES(1655,NULL,40,'Trong PowerPoint, chọn thao tác nào để tạo màu nền cho toàn bộ Slide?','MULTIPLE_CHOICE','[{"id":"1","content":"Right click Slide → Format Background → Fill → Apply","isCorrect":false},{"id":"2","content":"Right click Slide → Format Background → Fill → Close","isCorrect":false},{"id":"3","content":"Right click Slide → Format Background → Fill → Reset Background","isCorrect":false},{"id":"4","content":"Right click Slide → Format Background → Fill → Apply to All → Close","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',9,'2026-01-30 18:19:28','Chọn Format Background > Fill > Apply to All để áp dụng màu nền cho toàn bộ các slide.');
INSERT INTO "vstep_questions" VALUES(1656,NULL,40,'Chèn chữ nghệ thuật WordArt bằng:','MULTIPLE_CHOICE','[{"id":"1","content":"Slide → WordArt","isCorrect":false},{"id":"2","content":"Insert → Insert WordArt","isCorrect":false},{"id":"3","content":"Home → Insert WordArt","isCorrect":false},{"id":"4","content":"Insert → WordArt","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',10,'2026-01-30 18:19:28','Insert > WordArt dùng để chèn chữ nghệ thuật trang trí.');
INSERT INTO "vstep_questions" VALUES(1657,NULL,40,'Để mở chương trình PowerPoint, ta làm thế nào?','MULTIPLE_CHOICE','[{"id":"1","content":"Start → All Programs → Microsoft Office → PowerPoint","isCorrect":false},{"id":"2","content":"Kích đúp chuột trái vào biểu tượng PowerPoint trên Desktop","isCorrect":false},{"id":"3","content":"Kích chuột phải vào biểu tượng PowerPoint → Open","isCorrect":false},{"id":"4","content":"Tất cả các đáp án đều đúng","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',11,'2026-01-30 18:19:28','Có thể mở bằng Start Menu, biểu tượng trên Desktop hoặc chuột phải vào file chọn Open.');
INSERT INTO "vstep_questions" VALUES(1658,NULL,40,'Thay đổi kích thước placeholder bằng cách:','MULTIPLE_CHOICE','[{"id":"1","content":"Kéo đường kẻ ngang","isCorrect":false},{"id":"2","content":"Giữ chuột phải kéo","isCorrect":false},{"id":"3","content":"Kéo chuột trái tự do","isCorrect":false},{"id":"4","content":"Kéo một trong 8 nút tròn xung quanh placeholder","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',12,'2026-01-30 18:19:28','Kéo thả các nút tròn (sizing handles) xung quanh placeholder để thay đổi kích thước.');
INSERT INTO "vstep_questions" VALUES(1659,NULL,40,'Tạo màu nền cho slide hiện hành:','MULTIPLE_CHOICE','[{"id":"1","content":"Format Background → Apply","isCorrect":false},{"id":"2","content":"Format Background → Close","isCorrect":false},{"id":"3","content":"Format Background → Reset","isCorrect":false},{"id":"4","content":"Format Background → Apply to All","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',13,'2026-01-30 18:19:28','Sau khi chọn màu nền, nhấn Apply to All để áp dụng cho tất cả slide.');
INSERT INTO "vstep_questions" VALUES(1660,NULL,40,'Chuyển đổi giữa 2 bài thuyết trình đang mở:','MULTIPLE_CHOICE','[{"id":"1","content":"Home → Switch Windows","isCorrect":false},{"id":"2","content":"Slide Show → Switch Windows","isCorrect":false},{"id":"3","content":"Design → Switch Windows","isCorrect":false},{"id":"4","content":"View → Switch Windows","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',14,'2026-01-30 18:19:28','View > Switch Windows dùng để chuyển đổi qua lại giữa các file PowerPoint đang mở.');
INSERT INTO "vstep_questions" VALUES(1661,NULL,40,'Đưa đối tượng từ lớp dưới lên trên một lớp:','MULTIPLE_CHOICE','[{"id":"1","content":"Send Backward","isCorrect":false},{"id":"2","content":"Bring to Front","isCorrect":false},{"id":"3","content":"Send to Back","isCorrect":false},{"id":"4","content":"Bring Forward","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',15,'2026-01-30 18:19:28','Bring Forward đưa đối tượng lên một lớp (gần người xem hơn).');
INSERT INTO "vstep_questions" VALUES(1662,NULL,40,'Thay đổi bố cục SmartArt bằng:','MULTIPLE_CHOICE','[{"id":"1","content":"Home","isCorrect":false},{"id":"2","content":"Design","isCorrect":false},{"id":"3","content":"SmartArt Tools Format","isCorrect":false},{"id":"4","content":"SmartArt Tools Design","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',16,'2026-01-30 18:19:28','Thẻ SmartArt Tools Design dùng để đổi bố cục, màu sắc cho sơ đồ SmartArt.');
INSERT INTO "vstep_questions" VALUES(1663,NULL,40,'Cách trình chiếu Slide trong PowerPoint:','MULTIPLE_CHOICE','[{"id":"1","content":"File → From Beginning","isCorrect":false},{"id":"2","content":"View → From Beginning","isCorrect":false},{"id":"3","content":"Insert → From Beginning","isCorrect":false},{"id":"4","content":"Slide Show → From Beginning","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',17,'2026-01-30 18:19:28','Lệnh From Beginning (trong thẻ Slide Show) dùng để chiếu từ slide đầu.');
INSERT INTO "vstep_questions" VALUES(1664,NULL,40,'Trong PowerPoint, cách trình chiếu từ slide đầu tiên là:','MULTIPLE_CHOICE','[{"id":"1","content":"Ctrl + F5","isCorrect":false},{"id":"2","content":"Alt + F5","isCorrect":false},{"id":"3","content":"Shift + F5","isCorrect":false},{"id":"4","content":"F5","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',18,'2026-01-30 18:19:28','Phím F5 dùng để bắt đầu trình chiếu từ slide đầu tiên.');
INSERT INTO "vstep_questions" VALUES(1665,NULL,40,'Khi đang trình chiếu, muốn chuyển sang slide không liền kề:','MULTIPLE_CHOICE','[{"id":"1","content":"Nháy phải → Move to Slide","isCorrect":false},{"id":"2","content":"Nháy đúp chuột → Go to Slide","isCorrect":false},{"id":"3","content":"Nháy chuột trái → Go to Slide","isCorrect":false},{"id":"4","content":"Nháy phải → Go to Slide","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',19,'2026-01-30 18:19:28','Khi đang chiếu, chuột phải chọn Go to Slide để nhảy đến slide mong muốn.');
INSERT INTO "vstep_questions" VALUES(1666,NULL,40,'Chọn nhiều slide không liền kề bằng cách:','MULTIPLE_CHOICE','[{"id":"1","content":"Giữ Alt","isCorrect":false},{"id":"2","content":"Giữ Shift","isCorrect":false},{"id":"3","content":"Giữ Ctrl","isCorrect":true},{"id":"4","content":"Giữ Ctrl + Shift","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',20,'2026-01-30 18:19:28','Giữ phím Ctrl và nhấp chuột để chọn các slide rời rạc (không liên tiếp).');
INSERT INTO "vstep_questions" VALUES(1667,NULL,40,'Tạo slide giống hệt slide hiện hành mà không thiết kế lại:','MULTIPLE_CHOICE','[{"id":"1","content":"Không thực hiện được","isCorrect":false},{"id":"2","content":"Insert → Duplicate Selected Slides","isCorrect":false},{"id":"3","content":"Insert → New Slide","isCorrect":false},{"id":"4","content":"Home → New Slide → Duplicate Selected Slides","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',21,'2026-01-30 18:19:29','Lệnh Duplicate Selected Slides trong Home > New Slide dùng để nhân đôi slide đã chọn.');
INSERT INTO "vstep_questions" VALUES(1668,NULL,40,'Để thêm ghi chú cho slide, ta sử dụng chế độ:','MULTIPLE_CHOICE','[{"id":"1","content":"Notes Page và Reading View","isCorrect":false},{"id":"2","content":"Notes Page và Slide Sorter","isCorrect":false},{"id":"3","content":"Slide Sorter và Normal","isCorrect":false},{"id":"4","content":"Notes Page và Normal","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',22,'2026-01-30 18:19:29','Có thể thêm ghi chú ở chế độ Normal (bên dưới slide) hoặc chế độ Notes Page.');
INSERT INTO "vstep_questions" VALUES(1669,NULL,40,'Cách tạo bản trình bày mới trong PowerPoint:','MULTIPLE_CHOICE','[{"id":"1","content":"File → New Presentation → Create","isCorrect":false},{"id":"2","content":"Insert → New → Blank Presentation → Create","isCorrect":false},{"id":"3","content":"Insert → New Slide → Create","isCorrect":false},{"id":"4","content":"File → New → Blank Presentation","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',23,'2026-01-30 18:19:29','Tạo bài mới: File > New > Blank Presentation (Bài trình thuyết trống).');
INSERT INTO "vstep_questions" VALUES(1670,NULL,40,'In mỗi slide trên một trang giấy:','MULTIPLE_CHOICE','[{"id":"1","content":"File → Print → Notes Page","isCorrect":false},{"id":"2","content":"File → Print → Outline","isCorrect":false},{"id":"3","content":"File → Print → 2 Slides","isCorrect":false},{"id":"4","content":"File → Print → Settings → 1 Slide","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',24,'2026-01-30 18:19:29','Trong Print Settings, chọn "Print Current Slide" hoặc "1 Slide" để in mỗi slide một trang.');
INSERT INTO "vstep_questions" VALUES(1671,NULL,40,'Chức năng Animations dùng để:','MULTIPLE_CHOICE','[{"id":"1","content":"Định dạng giao diện slide","isCorrect":false},{"id":"2","content":"Định dạng chữ","isCorrect":false},{"id":"3","content":"Định dạng kiểu lật trang","isCorrect":false},{"id":"4","content":"Tạo hiệu ứng cho đối tượng","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',25,'2026-01-30 18:19:29','Animations là chức năng tạo hiệu ứng chuyển động cho các đối tượng trên slide.');
INSERT INTO "vstep_questions" VALUES(1672,NULL,40,'Trong PowerPoint, thực đơn nào chứa các lệnh để tạo ra các bản thuyết trình từ một phác thảo?','MULTIPLE_CHOICE','[{"id":"1","content":"Slide Show","isCorrect":false},{"id":"2","content":"Insert","isCorrect":false},{"id":"3","content":"Design","isCorrect":false},{"id":"4","content":"Home","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',26,'2026-01-30 18:19:29','Trong thẻ Home có nhóm lệnh New Slide chứa tùy chọn Slides from Outline để tạo slide từ phác thảo.');
INSERT INTO "vstep_questions" VALUES(1673,NULL,40,'Nếu chọn 2 slide và dùng lệnh Duplicate Slide thì tạo ra thêm bao nhiêu slide?','MULTIPLE_CHOICE','[{"id":"1","content":"2","isCorrect":false},{"id":"2","content":"6","isCorrect":false},{"id":"3","content":"8","isCorrect":false},{"id":"4","content":"4","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',27,'2026-01-30 18:19:29','Khi chọn 2 slide và nhân đôi (Duplicate), hệ thống sẽ tạo thêm đúng 2 slide bản sao.');
INSERT INTO "vstep_questions" VALUES(1674,NULL,40,'Tạo bài thuyết trình mới theo mẫu (Sample templates) bằng cách:','MULTIPLE_CHOICE','[{"id":"1","content":"Design → New → Sample templates → Create","isCorrect":false},{"id":"2","content":"Insert → New → Sample templates → Create","isCorrect":false},{"id":"3","content":"Home → New → Sample templates → Create","isCorrect":false},{"id":"4","content":"File → New → Sample templates → Create","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',28,'2026-01-30 18:19:29','Tạo từ mẫu: File > New > Sample templates > Create.');
INSERT INTO "vstep_questions" VALUES(1675,NULL,40,'Thay đổi màu nền văn bản bằng:','MULTIPLE_CHOICE','[{"id":"1","content":"Format → Size","isCorrect":false},{"id":"2","content":"Home → Theme Colors","isCorrect":false},{"id":"3","content":"Format → Shape Styles","isCorrect":false},{"id":"4","content":"Format → Shape Fill","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',29,'2026-01-30 18:19:29','Thẻ Format > Shape Fill dùng để đổ màu nền cho hình vẽ hoặc khung văn bản.');
INSERT INTO "vstep_questions" VALUES(1676,NULL,40,'Khi làm việc với bảng trong PowerPoint, đặc tính nào dùng để định dạng viền, ô và chọn bảng màu cho bảng?','MULTIPLE_CHOICE','[{"id":"1","content":"Table Theme","isCorrect":false},{"id":"2","content":"Table Border","isCorrect":false},{"id":"3","content":"Table Layout","isCorrect":false},{"id":"4","content":"Table Style","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',30,'2026-01-30 18:19:29','Table Style (Kiểu bảng) dùng để định dạng nhanh màu sắc, đường viền cho bảng.');
INSERT INTO "vstep_questions" VALUES(1677,NULL,40,'Để chọn toàn bộ nội dung bảng trong slide, dùng tổ hợp phím:','MULTIPLE_CHOICE','[{"id":"1","content":"Ctrl + S","isCorrect":false},{"id":"2","content":"Alt + A","isCorrect":false},{"id":"3","content":"Shift + A","isCorrect":false},{"id":"4","content":"Ctrl + A","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',31,'2026-01-30 18:19:29','Ctrl + A là phím tắt để chọn toàn bộ đối tượng trong slide hoặc toàn bộ văn bản.');
INSERT INTO "vstep_questions" VALUES(1678,NULL,40,'Khi đang trình chiếu, muốn kết thúc phiên trình diễn, ta thực hiện:','MULTIPLE_CHOICE','[{"id":"1","content":"Nháy phải chuột → Return","isCorrect":false},{"id":"2","content":"Nháy phải chuột → Screen","isCorrect":false},{"id":"3","content":"Nháy phải chuột → Exit","isCorrect":false},{"id":"4","content":"Nháy phải chuột → End Show","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',32,'2026-01-30 18:19:29','Nháy phải chuột và chọn End Show là cách để kết thúc phiên trình diễn từ menu ngữ cảnh.');
INSERT INTO "vstep_questions" VALUES(1679,NULL,40,'Trong PowerPoint, tổ hợp phím dùng để in là:','MULTIPLE_CHOICE','[{"id":"1","content":"Ctrl + S","isCorrect":false},{"id":"2","content":"Ctrl + N","isCorrect":false},{"id":"3","content":"Ctrl + O","isCorrect":false},{"id":"4","content":"Ctrl + P","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',33,'2026-01-30 18:19:29','Tổ hợp phím Ctrl + P là lệnh in ấn thông dụng trong Microsoft Office.');
INSERT INTO "vstep_questions" VALUES(1680,NULL,40,'Để thay đổi kiểu Bullet trong PowerPoint:','MULTIPLE_CHOICE','[{"id":"1","content":"Home → Numbering","isCorrect":false},{"id":"2","content":"Insert → Symbol","isCorrect":false},{"id":"3","content":"Insert → Bullet","isCorrect":false},{"id":"4","content":"Home → Bullet","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',34,'2026-01-30 18:19:29','Thẻ Home > nhóm Paragraph > nút Bullets dùng để đổi kiểu ký hiệu đầu dòng.');
INSERT INTO "vstep_questions" VALUES(1681,NULL,40,'Lật ảnh theo chiều ngang bằng lệnh:','MULTIPLE_CHOICE','[{"id":"1","content":"Rotate Right 90","isCorrect":false},{"id":"2","content":"Rotate Left 90","isCorrect":false},{"id":"3","content":"Flip Vertical","isCorrect":false},{"id":"4","content":"Flip Horizontal","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',35,'2026-01-30 18:19:29','Flip Horizontal (Lật ngang) sẽ tạo ảnh phản chiếu qua trục dọc.');
INSERT INTO "vstep_questions" VALUES(1682,NULL,40,'Trong PowerPoint, để đặt mật khẩu cho file hiện tại ta vào:','MULTIPLE_CHOICE','[{"id":"1","content":"File → Save → Protect Presentation → Encrypt with Password","isCorrect":false},{"id":"2","content":"Home → Info → Protect Presentation → Encrypt with Password","isCorrect":false},{"id":"3","content":"File → Info → Protect Presentation → Encrypt with Password","isCorrect":true},{"id":"4","content":"Home → Save → Protect Presentation → Encrypt with Password","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',36,'2026-01-30 18:19:29','Quy trình đúng để đặt mật khẩu: File > Info > Protect Presentation > Encrypt with Password.');
INSERT INTO "vstep_questions" VALUES(1683,NULL,40,'Mở cùng một bài thuyết trình ở hai cửa sổ:','MULTIPLE_CHOICE','[{"id":"1","content":"Data → New Windows","isCorrect":false},{"id":"2","content":"Home → New Windows","isCorrect":false},{"id":"3","content":"Review → New Windows","isCorrect":false},{"id":"4","content":"View → New Windows","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',37,'2026-01-30 18:19:29','View > New Window mở bài thuyết trình hiện tại trong một cửa sổ mới.');
INSERT INTO "vstep_questions" VALUES(1684,NULL,40,'Tạo một Slide Master mới bằng cách:','MULTIPLE_CHOICE','[{"id":"1","content":"View → Slide Master → Master Layout","isCorrect":false},{"id":"2","content":"View → Slide Master → Insert Layout","isCorrect":false},{"id":"3","content":"View → Slide Master → Insert Placeholders","isCorrect":false},{"id":"4","content":"View → Slide Master → Insert Slide Master","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',38,'2026-01-30 18:19:29','Vào View > Slide Master > Insert Slide Master để tạo một slide cái mới.');
INSERT INTO "vstep_questions" VALUES(1685,NULL,40,'Lệnh Insert → Shapes dùng để:','MULTIPLE_CHOICE','[{"id":"1","content":"Chèn video","isCorrect":false},{"id":"2","content":"Chèn hình vẽ","isCorrect":true},{"id":"3","content":"Chèn âm thanh","isCorrect":false},{"id":"4","content":"Chèn công thức","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',39,'2026-01-30 18:19:29','Lệnh Insert > Shapes dùng để chèn các hình vẽ, khối hình học vào slide.');
INSERT INTO "vstep_questions" VALUES(1686,NULL,40,'Thực đơn nào chứa lệnh kiểm tra chính tả trong PowerPoint?','MULTIPLE_CHOICE','[{"id":"1","content":"Home","isCorrect":false},{"id":"2","content":"Design","isCorrect":false},{"id":"3","content":"Slide Show","isCorrect":false},{"id":"4","content":"Review","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',40,'2026-01-30 18:19:29','Thẻ Review chứa các công cụ kiểm tra chính tả (Spelling) và ngôn ngữ.');
INSERT INTO "vstep_questions" VALUES(1687,NULL,41,'Kiểu dữ liệu nào sau đây không được dùng trong Excel?','MULTIPLE_CHOICE','[{"id":"1","content":"Text","isCorrect":false},{"id":"2","content":"Number","isCorrect":false},{"id":"3","content":"Date","isCorrect":false},{"id":"4","content":"Day","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',1,'2026-01-30 18:19:39','"Day" là tên hàm (lấy ngày), không phải là kiểu dữ liệu cơ sở như Text, Number.');
INSERT INTO "vstep_questions" VALUES(1688,NULL,41,'Trong bảng tính Excel, nếu trong một ô xuất hiện ký hiệu ##### có nghĩa là gì?','MULTIPLE_CHOICE','[{"id":"1","content":"Công thức nhập sai","isCorrect":false},{"id":"2","content":"Hàng có độ cao quá thấp","isCorrect":false},{"id":"3","content":"Cột có độ rộng quá hẹp","isCorrect":true},{"id":"4","content":"Excel bị lỗi","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',2,'2026-01-30 18:19:39','Lỗi ##### xuất hiện khi độ rộng cột quá hẹp, không đủ hiển thị hết số hoặc ngày tháng.');
INSERT INTO "vstep_questions" VALUES(1689,NULL,41,'Biểu thức =SUM(9,1,MAX(3,5,7)) cho kết quả:','MULTIPLE_CHOICE','[{"id":"1","content":"13","isCorrect":false},{"id":"2","content":"15","isCorrect":false},{"id":"3","content":"17","isCorrect":true},{"id":"4","content":"19","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',3,'2026-01-30 18:19:39','MAX(3,5,7)=7. SUM(9,1,7)=17.');
INSERT INTO "vstep_questions" VALUES(1690,NULL,41,'Công thức =MAX(30,10,65,5) cho kết quả:','MULTIPLE_CHOICE','[{"id":"1","content":"110","isCorrect":false},{"id":"2","content":"120","isCorrect":false},{"id":"3","content":"135","isCorrect":false},{"id":"4","content":"65","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',4,'2026-01-30 18:19:39','Hàm MAX tìm số lớn nhất. Max(30,10,65,5) = 65.');
INSERT INTO "vstep_questions" VALUES(1691,NULL,41,'Hàm nào dùng để tính giá trị trung bình trong Excel?','MULTIPLE_CHOICE','[{"id":"1","content":"EVERAGE","isCorrect":false},{"id":"2","content":"AVERGE","isCorrect":false},{"id":"3","content":"ERVERAGE","isCorrect":false},{"id":"4","content":"AVERAGE","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',5,'2026-01-30 18:19:39','AVERAGE là hàm dùng để tính giá trị trung bình cộng trong Excel.');
INSERT INTO "vstep_questions" VALUES(1692,NULL,41,'Kết quả của công thức SUM(13,7,-10)+AVERAGE(12,0,3) là bao nhiêu?','MULTIPLE_CHOICE','[{"id":"1","content":"10","isCorrect":false},{"id":"2","content":"20","isCorrect":false},{"id":"3","content":"16","isCorrect":false},{"id":"4","content":"15","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',6,'2026-01-30 18:19:39','SUM(13,7,-10)=10; AVERAGE(12,0,3)=5; Tổng = 15.');
INSERT INTO "vstep_questions" VALUES(1693,NULL,41,'Biểu thức =MID("A123B",3,2) cho kết quả là:','MULTIPLE_CHOICE','[{"id":"1","content":"A123B","isCorrect":false},{"id":"2","content":"3B","isCorrect":false},{"id":"3","content":"A1","isCorrect":false},{"id":"4","content":"23","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',7,'2026-01-30 18:19:39','Hàm MID("A123B", 3, 2) lấy từ vị trí thứ 3, lấy 2 ký tự ("2" và "3") -> kết quả là "23".');
INSERT INTO "vstep_questions" VALUES(1694,NULL,41,'Để nhập nội dung vào Header và Footer trong Excel, ta chọn:','MULTIPLE_CHOICE','[{"id":"1","content":"Page Layout > Orientation","isCorrect":false},{"id":"2","content":"Page Layout > Textbox","isCorrect":false},{"id":"3","content":"Insert > WordArt","isCorrect":false},{"id":"4","content":"Insert > Header & Footer","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',8,'2026-01-30 18:19:39','Vào Insert > Text > Header & Footer để thêm tiêu đề đầu và chân trang.');
INSERT INTO "vstep_questions" VALUES(1695,NULL,41,'Để thiết lập lề trang in, ta thực hiện:','MULTIPLE_CHOICE','[{"id":"1","content":"Data > Margins","isCorrect":false},{"id":"2","content":"Insert > Margins","isCorrect":false},{"id":"3","content":"Home > Page Layout > Margins","isCorrect":false},{"id":"4","content":"Page Layout > Margins > Custom Margins","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',9,'2026-01-30 18:19:39','Vào Page Layout > Margins > Custom Margins để chỉnh lề giấy theo ý muốn.');
INSERT INTO "vstep_questions" VALUES(1696,NULL,41,'Các địa chỉ $A1, B$5, C6, $L9, $D$7 là loại địa chỉ gì?','MULTIPLE_CHOICE','[{"id":"1","content":"Địa chỉ tuyệt đối","isCorrect":false},{"id":"2","content":"Địa chỉ hỗn hợp","isCorrect":false},{"id":"3","content":"Địa chỉ tương đối","isCorrect":false},{"id":"4","content":"Tất cả đều đúng","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',10,'2026-01-30 18:19:39','Danh sách chứa đủ các loại địa chỉ: Tuyệt đối (A1), Hỗn hợp (B$5) và Tương đối (C6).');
INSERT INTO "vstep_questions" VALUES(1697,NULL,41,'Muốn sao chép dữ liệu từ vùng nguồn, trong Home > Clipboard ta chọn:','MULTIPLE_CHOICE','[{"id":"1","content":"Paste","isCorrect":false},{"id":"2","content":"Cut","isCorrect":false},{"id":"3","content":"Copy","isCorrect":true},{"id":"4","content":"Format Painter","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',11,'2026-01-30 18:19:39','Format Painter (cây chổi) dùng để sao chép định dạng (không sao chép nội dung).');
INSERT INTO "vstep_questions" VALUES(1698,NULL,41,'Khi gõ giá trị số vào vài ô đầu tiên, chọn vùng vừa gõ số, kéo chuột tại góc phải phía dưới khi hiện hình chữ thập, kết quả thu được là gì?','MULTIPLE_CHOICE','[{"id":"1","content":"Công thức được điền vào","isCorrect":false},{"id":"2","content":"Dãy số tự động được điền vào","isCorrect":true},{"id":"3","content":"Nội dung các ô ban đầu được lặp lại","isCorrect":false},{"id":"4","content":"Đoạn văn bản được chèn vào","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',12,'2026-01-30 18:19:40','Kéo thả Fill Handle (điền tự động): dãy số trong chuỗi sẽ tự động tăng (n01 -> n02, n03...).');
INSERT INTO "vstep_questions" VALUES(1699,NULL,41,'Cú pháp đúng của hàm IF là:','MULTIPLE_CHOICE','[{"id":"1","content":"IF(BT logic, Giá trị đúng)","isCorrect":false},{"id":"2","content":"IF(Giá trị đúng, BT logic, Giá trị sai)","isCorrect":false},{"id":"3","content":"IF(BT logic, Giá trị đúng, Giá trị sai)","isCorrect":true},{"id":"4","content":"IF(BT logic, Giá trị sai, Giá trị đúng)","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',13,'2026-01-30 18:19:40','Cú pháp hàm IF: IF(Biểu thức điều kiện, Giá trị nếu đúng, Giá trị nếu sai).');
INSERT INTO "vstep_questions" VALUES(1700,NULL,41,'Biểu thức IF(OR(B2>=8,D2="A"),1000,300) với B2 = 10 và D2 = "D" cho kết quả là:','MULTIPLE_CHOICE','[{"id":"1","content":"0","isCorrect":false},{"id":"2","content":"300","isCorrect":false},{"id":"3","content":"1000","isCorrect":true},{"id":"4","content":"1300","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',14,'2026-01-30 18:19:40','OR(10>=8,...) là True. Hàm IF trả về giá trị đúng là 1000.');
INSERT INTO "vstep_questions" VALUES(1701,NULL,41,'Công thức ROUND(7475.47,1) trả về kết quả bao nhiêu?','MULTIPLE_CHOICE','[{"id":"1","content":"7500","isCorrect":false},{"id":"2","content":"7475","isCorrect":false},{"id":"3","content":"7475.47","isCorrect":false},{"id":"4","content":"7475.5","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',15,'2026-01-30 18:19:40','Hàm ROUND(7475.47, 1) làm tròn đến 1 chữ số thập phân (sau dấu phẩy) -> 7475.5.');
INSERT INTO "vstep_questions" VALUES(1702,NULL,41,'Khi sao chép dữ liệu từ vùng nguồn sang vùng đích, thao tác đầu tiên cần thực hiện là:','MULTIPLE_CHOICE','[{"id":"1","content":"Chuột phải > Cut","isCorrect":false},{"id":"2","content":"Chuột phải > Paste","isCorrect":false},{"id":"3","content":"Chuột phải > Delete","isCorrect":false},{"id":"4","content":"Ấn tổ hợp phím Ctrl + C","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',16,'2026-01-30 18:19:40','Thao tác đầu tiên để sao chép (Copy) là nhấn tổ hợp phím Ctrl + C.');
INSERT INTO "vstep_questions" VALUES(1703,NULL,41,'Trong các hàm sau, hàm dò tìm là hàm nào?','MULTIPLE_CHOICE','[{"id":"1","content":"COUNTA","isCorrect":false},{"id":"2","content":"PRODUCT","isCorrect":false},{"id":"3","content":"SUMIF","isCorrect":false},{"id":"4","content":"VLOOKUP","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',17,'2026-01-30 18:19:40','VLOOKUP là hàm thuộc nhóm dò tìm (Lookup), các hàm còn lại là thống kê.');
INSERT INTO "vstep_questions" VALUES(1704,NULL,41,'Để xóa một cột trong Excel, ta thực hiện:','MULTIPLE_CHOICE','[{"id":"1","content":"Insert > Delete > Worksheet","isCorrect":false},{"id":"2","content":"Insert > Cells > Delete Sheet Rows","isCorrect":false},{"id":"3","content":"Home > Delete > Clear","isCorrect":false},{"id":"4","content":"Home > Cells > Delete Sheet Columns","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',18,'2026-01-30 18:19:40','Để xóa cột: Chọn cột hoặc ô, vào Home > Cells > Delete > Delete Sheet Columns.');
INSERT INTO "vstep_questions" VALUES(1705,NULL,41,'Khi nhập dữ liệu vào Excel, dữ liệu kiểu ký tự sẽ mặc định:','MULTIPLE_CHOICE','[{"id":"1","content":"Căn lề phải","isCorrect":false},{"id":"2","content":"Căn lề trái","isCorrect":true},{"id":"3","content":"Căn giữa","isCorrect":false},{"id":"4","content":"Không căn lề","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',19,'2026-01-30 18:19:40','Mặc định: Dữ liệu ký tự (Text) sẽ căn lề trái; dữ liệu Số sẽ căn lề phải.');
INSERT INTO "vstep_questions" VALUES(1706,NULL,41,'Biểu tượng % trên thanh công cụ Excel dùng để:','MULTIPLE_CHOICE','[{"id":"1","content":"Nhân với 100","isCorrect":true},{"id":"2","content":"Chia cho 100","isCorrect":false},{"id":"3","content":"Hiển thị tỷ lệ phần trăm","isCorrect":false},{"id":"4","content":"Cả 3 ý đều sai","isCorrect":false}]','1',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',20,'2026-01-30 18:19:40','Nút % (Percent Style) dùng để hiển thị giá trị nhân với 100 kèm theo ký hiệu %.');
INSERT INTO "vstep_questions" VALUES(1707,NULL,41,'Để văn bản hiển thị nhiều hàng trong một ô ta thực hiện:','MULTIPLE_CHOICE','[{"id":"1","content":"Insert > Alignment > Wrap Text","isCorrect":false},{"id":"2","content":"Data > Alignment > Wrap Text","isCorrect":false},{"id":"3","content":"Page Layout > Alignment > Wrap Text","isCorrect":false},{"id":"4","content":"Home > Alignment > Wrap Text","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',21,'2026-01-30 18:19:40','Tính năng Wrap Text (Home > Alignment) giúp văn bản tự động xuống dòng khi dài hơn ô.');
INSERT INTO "vstep_questions" VALUES(1708,NULL,41,'Trong Excel, cách nào để đóng một tệp?','MULTIPLE_CHOICE','[{"id":"1","content":"Ctrl + F4","isCorrect":false},{"id":"2","content":"Shift + F4","isCorrect":false},{"id":"3","content":"F4","isCorrect":false},{"id":"4","content":"Alt + F4","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',22,'2026-01-30 18:19:40','Phím tắt Ctrl + F4 dùng để đóng cửa sổ tập tin Excel hiện hành.');
INSERT INTO "vstep_questions" VALUES(1709,NULL,41,'Cách nào để di chuyển Sheet2 ra trước Sheet1?','MULTIPLE_CHOICE','[{"id":"1","content":"Double tab Sheet2 rồi kéo","isCorrect":false},{"id":"2","content":"Tools > Sheet > Move","isCorrect":false},{"id":"3","content":"Format > Sheet > Move","isCorrect":false},{"id":"4","content":"Chọn Sheet2 và kéo đến vị trí mong muốn","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',23,'2026-01-30 18:19:40','Cách nhanh nhất là nhấp giữ chuột trái vào tên Sheet2 và kéo thả về vị trí mong muốn.');
INSERT INTO "vstep_questions" VALUES(1710,NULL,41,'Để ghép 2 xâu ký tự "TRAN VAN" và "AN" thành "TRAN VAN AN" ta dùng công thức:','MULTIPLE_CHOICE','[{"id":"1","content":"\"TRAN VAN\"+\"AN\"","isCorrect":false},{"id":"2","content":"\"TRAN VAN\" AND \"AN\"","isCorrect":false},{"id":"3","content":"\"TRAN VAN\"&\" \"&\"AN\"","isCorrect":true},{"id":"4","content":"Không ghép được","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',24,'2026-01-30 18:19:40','Toán tử & dùng để nối chuỗi: "TRAN VAN" & " " & "AN" -> "TRAN VAN AN".');
INSERT INTO "vstep_questions" VALUES(1711,NULL,41,'Muốn sắp xếp dữ liệu sau khi quét khối dữ liệu, ta chọn:','MULTIPLE_CHOICE','[{"id":"1","content":"Data > Form","isCorrect":false},{"id":"2","content":"Data > Index","isCorrect":false},{"id":"3","content":"Data > Filter","isCorrect":false},{"id":"4","content":"Data > Sort","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',25,'2026-01-30 18:19:40','Vào thẻ Data > chọn Sort để thực hiện sắp xếp dữ liệu.');
INSERT INTO "vstep_questions" VALUES(1712,NULL,41,'Để quay được hướng văn bản trong ô, ta chọn ô sau đó thực hiện:','MULTIPLE_CHOICE','[{"id":"1","content":"View > Alignment > Orientation","isCorrect":false},{"id":"2","content":"Page Layout > Alignment > Orientation","isCorrect":false},{"id":"3","content":"Home > Alignment > Orientation","isCorrect":true},{"id":"4","content":"Insert > Alignment > Orientation","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',26,'2026-01-30 18:19:40','Vào thẻ Home > nhóm Alignment > chọn Orientation để thay đổi hướng văn bản.');
INSERT INTO "vstep_questions" VALUES(1713,NULL,41,'Trong Excel, để hiện các đường phân trang xem bảng tính có khớp với trang in không, ta sử dụng lệnh nào sau đây?','MULTIPLE_CHOICE','[{"id":"1","content":"View > Workbook Views > Custom Views","isCorrect":false},{"id":"2","content":"View > Workbook Views > Normal","isCorrect":false},{"id":"3","content":"View > Workbook Views > Page Layout","isCorrect":false},{"id":"4","content":"View > Workbook Views > Page Break Preview","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',27,'2026-01-30 18:19:40','Chế độ View > Page Break Preview cho phép xem và điều chỉnh các đường phân trang.');
INSERT INTO "vstep_questions" VALUES(1714,NULL,41,'Trong Excel, khi muốn dán dữ liệu ta ấn tổ hợp phím nào?','MULTIPLE_CHOICE','[{"id":"1","content":"Shift + Insert","isCorrect":true},{"id":"2","content":"Ctrl + Insert","isCorrect":false},{"id":"3","content":"Alt + Enter","isCorrect":false},{"id":"4","content":"Alt + Insert","isCorrect":false}]','1',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',28,'2026-01-30 18:19:40','Tổ hợp phím Alt + Enter dùng để ngắt dòng (xuống dòng) trong cùng một ô.');
INSERT INTO "vstep_questions" VALUES(1715,NULL,41,'Để chèn biểu đồ dạng hình cột trong Excel, ta chọn:','MULTIPLE_CHOICE','[{"id":"1","content":"Insert > Charts > Bar","isCorrect":false},{"id":"2","content":"Insert > Charts > Pie","isCorrect":false},{"id":"3","content":"Insert > Charts > Line","isCorrect":false},{"id":"4","content":"Insert > Charts > Column","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',29,'2026-01-30 18:19:40','Vào Insert > Charts > chọn biểu tượng Column để vẽ biểu đồ cột.');
INSERT INTO "vstep_questions" VALUES(1716,NULL,41,'Cấu trúc đúng của hàm VLOOKUP là:','MULTIPLE_CHOICE','[{"id":"1","content":"VLOOKUP(range_lookup, lookup_value, table_array, row_index_num)","isCorrect":false},{"id":"2","content":"VLOOKUP(table_array, lookup_value, row_index_num, range_lookup)","isCorrect":false},{"id":"3","content":"VLOOKUP(lookup_value, row_index_num, table_array, range_lookup)","isCorrect":false},{"id":"4","content":"VLOOKUP(lookup_value, table_array, row_index_num, [range_lookup])","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',30,'2026-01-30 18:19:40','Cấu trúc đúng: VLOOKUP(giá trị tìm, bảng dò, cột trả về, [kiểu dò]).');
INSERT INTO "vstep_questions" VALUES(1717,NULL,41,'Trong Excel, khi muốn lựa chọn nhiều dòng kề nhau, ta chọn dòng đầu tiên, sau đó ấn phím nào rồi chọn dòng cuối cùng?','MULTIPLE_CHOICE','[{"id":"1","content":"Enter","isCorrect":false},{"id":"2","content":"Ctrl","isCorrect":false},{"id":"3","content":"Alt","isCorrect":false},{"id":"4","content":"Shift","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',31,'2026-01-30 18:19:40','Giữ phím Ctrl kết hợp nhấp chuột trái để chọn các ô hoặc vùng không liền kề.');
INSERT INTO "vstep_questions" VALUES(1718,NULL,41,'Để thay đổi độ rộng của cột, ta thực hiện:','MULTIPLE_CHOICE','[{"id":"1","content":"Home > Format > Row Height","isCorrect":false},{"id":"2","content":"Home > Format > AutoFit Row Height","isCorrect":false},{"id":"3","content":"Home > Format > AutoFit Column Width","isCorrect":false},{"id":"4","content":"Home > Format > Column Width","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',32,'2026-01-30 18:19:40','AutoFit Column Width (trong Home > Format) giúp tự động chỉnh độ rộng cột vừa khít nội dung.');
INSERT INTO "vstep_questions" VALUES(1719,NULL,41,'Biểu thức:','MULTIPLE_CHOICE','[{"id":"1","content":"Yeu","isCorrect":false},{"id":"2","content":"Gioi","isCorrect":false},{"id":"3","content":"Kha","isCorrect":false},{"id":"4","content":"TB","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',33,'2026-01-30 18:19:41','Kết quả trả về là "TB" (Trung bình), đây thường là kết quả của hàm xếp loại (IF lồng nhau).');
INSERT INTO "vstep_questions" VALUES(1720,NULL,41,'Để định dạng màu khác nhau cho nội dung ô theo điều kiện, ta dùng:','MULTIPLE_CHOICE','[{"id":"1","content":"Format Cell","isCorrect":false},{"id":"2","content":"Format as Table","isCorrect":false},{"id":"3","content":"Cell Style","isCorrect":false},{"id":"4","content":"Conditional Formatting","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',34,'2026-01-30 18:19:41','Conditional Formatting (Định dạng có điều kiện) dùng để tô màu ô theo quy tắc.');
INSERT INTO "vstep_questions" VALUES(1721,NULL,41,'Công thức =COUNTA(19,"S","n01","n02") trả về kết quả là bao nhiêu?','MULTIPLE_CHOICE','[{"id":"1","content":"19","isCorrect":false},{"id":"2","content":"3","isCorrect":false},{"id":"3","content":"0","isCorrect":false},{"id":"4","content":"4","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',35,'2026-01-30 18:19:41','Hàm COUNTA đếm các ô có chứa dữ liệu (không rỗng). Có 4 giá trị nên kết quả là 4.');
INSERT INTO "vstep_questions" VALUES(1722,NULL,41,'Công thức =AVERAGE(4,5,MIN(8,6,7)) cho kết quả nào?','MULTIPLE_CHOICE','[{"id":"1","content":"4","isCorrect":false},{"id":"2","content":"0","isCorrect":false},{"id":"3","content":"5","isCorrect":true},{"id":"4","content":"8","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',36,'2026-01-30 18:19:41','MIN(8,6,7)=6. AVERAGE(4,5,6)=5.');
INSERT INTO "vstep_questions" VALUES(1723,NULL,41,'Biểu thức IF(AND(DTB>=8,HK="A"),300,1000) với DTB = 9 và HK = C cho kết quả:','MULTIPLE_CHOICE','[{"id":"1","content":"300","isCorrect":false},{"id":"2","content":"0","isCorrect":false},{"id":"3","content":"-1","isCorrect":false},{"id":"4","content":"1000","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',37,'2026-01-30 18:19:41','AND(9>=8, "C"="A") là False. Hàm IF trả về giá trị sai là 1000.');
INSERT INTO "vstep_questions" VALUES(1724,NULL,41,'Sheet mới được chèn sẽ nằm ở vị trí nào?','MULTIPLE_CHOICE','[{"id":"1","content":"Sau tất cả các sheet","isCorrect":false},{"id":"2","content":"Sau sheet đang mở","isCorrect":false},{"id":"3","content":"Trước tất cả các sheet","isCorrect":false},{"id":"4","content":"Trước sheet đang mở","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',38,'2026-01-30 18:19:41','Sheet mới chèn vào sẽ nằm ngay trước (bên trái) Sheet đang mở hiện tại.');
INSERT INTO "vstep_questions" VALUES(1725,NULL,41,'Muốn in theo chiều ngang trang giấy, ta chọn:','MULTIPLE_CHOICE','[{"id":"1","content":"Page Layout > Landscape","isCorrect":false},{"id":"2","content":"Page Layout > Orientation > Portrait","isCorrect":false},{"id":"3","content":"Không thay đổi được","isCorrect":false},{"id":"4","content":"Page Layout > Orientation > Landscape","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',39,'2026-01-30 18:19:41','Vào Page Layout > Orientation > Landscape để chọn in theo chiều ngang.');
INSERT INTO "vstep_questions" VALUES(1726,NULL,42,'Để chọn toàn bộ một ô trong bảng Word, ta:','MULTIPLE_CHOICE','[{"id":"1","content":"Nhấn đúp chuột vào ô","isCorrect":false},{"id":"2","content":"Nhấn chuột góc trên ô","isCorrect":false},{"id":"3","content":"Nhấn chuột góc trái dưới ô","isCorrect":true},{"id":"4","content":"Nhấn chuột phải","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',1,'2026-01-30 18:19:55','Nhấn chuột vào góc trái dưới của ô (khi con trỏ chuột đổi hình) để chọn toàn bộ ô đó.');
INSERT INTO "vstep_questions" VALUES(1727,NULL,42,'Khi làm việc với bảng biểu trong Word 2016, để thay đổi đường viền cho bảng, ta chọn:','MULTIPLE_CHOICE','[{"id":"1","content":"Page Layout → Borders","isCorrect":false},{"id":"2","content":"Home → Paragraph → Borders and Shading","isCorrect":true},{"id":"3","content":"Design → Theme","isCorrect":false},{"id":"4","content":"Home → Bullets","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',2,'2026-01-30 18:19:55','Vào thẻ Home > nhóm Paragraph > Borders and Shading để kẻ khung viền cho bảng.');
INSERT INTO "vstep_questions" VALUES(1728,NULL,42,'Để đánh danh sách thứ tự tự động (Numbering), ta chọn:','MULTIPLE_CHOICE','[{"id":"1","content":"Home → Font → Numbering","isCorrect":false},{"id":"2","content":"Home → Clipboard → Numbering","isCorrect":false},{"id":"3","content":"Home → Paragraph → Numbering","isCorrect":true},{"id":"4","content":"Insert → Numbering","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',3,'2026-01-30 18:19:55','Home > Paragraph > Numbering dùng để tạo danh sách đánh số thứ tự tự động.');
INSERT INTO "vstep_questions" VALUES(1729,NULL,42,'Để chèn Bullets trong Word 2016, ta chọn:','MULTIPLE_CHOICE','[{"id":"1","content":"Home → Font → Bullets","isCorrect":false},{"id":"2","content":"Home → Clipboard → Bullets","isCorrect":false},{"id":"3","content":"Home → Paragraph → Bullets","isCorrect":true},{"id":"4","content":"Insert → Bullets","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',4,'2026-01-30 18:19:55','Home > Paragraph > Bullets dùng để tạo danh sách dấu đầu dòng (ký hiệu).');
INSERT INTO "vstep_questions" VALUES(1730,NULL,42,'Trong hộp thoại Page Setup, mục Gutter có chức năng:','MULTIPLE_CHOICE','[{"id":"1","content":"Quy định lề trang","isCorrect":false},{"id":"2","content":"Chia cột văn bản","isCorrect":false},{"id":"3","content":"Phần chừa trống để đóng thành tập","isCorrect":true},{"id":"4","content":"Canh lề đối xứng","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',5,'2026-01-30 18:19:55','Gutter trong Page Setup là phần lề chừa trống để đóng gáy sách/tập.');
INSERT INTO "vstep_questions" VALUES(1731,NULL,42,'Để chèn ký tự đặc biệt như dấu ≥, ta chọn:','MULTIPLE_CHOICE','[{"id":"1","content":"Gõ trực tiếp từ bàn phím","isCorrect":false},{"id":"2","content":"Insert → Symbol","isCorrect":true},{"id":"3","content":"Quick Access Toolbar","isCorrect":false},{"id":"4","content":"Spelling & Grammar","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',6,'2026-01-30 18:19:56','Insert > Symbol dùng để chèn các ký tự đặc biệt không có trên bàn phím.');
INSERT INTO "vstep_questions" VALUES(1732,NULL,42,'Phím đưa con trỏ về đầu dòng hiện hành là:','MULTIPLE_CHOICE','[{"id":"1","content":"Ctrl + Home","isCorrect":false},{"id":"2","content":"Home","isCorrect":true},{"id":"3","content":"End","isCorrect":false},{"id":"4","content":"Ctrl + Page Up","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',7,'2026-01-30 18:19:56','Phím Home dùng để đưa con trỏ về đầu dòng hiện hành.');
INSERT INTO "vstep_questions" VALUES(1733,NULL,42,'Tổ hợp phím Ctrl + Z dùng để:','MULTIPLE_CHOICE','[{"id":"1","content":"Đóng tập tin đang mở","isCorrect":false},{"id":"2","content":"Đóng cửa sổ đang mở","isCorrect":false},{"id":"3","content":"Hủy thao tác","isCorrect":false},{"id":"4","content":"Quay lại thao tác trước thao tác hiện hành","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',8,'2026-01-30 18:19:56','Ctrl + Z là phím tắt để Hủy thao tác (Undo) vừa thực hiện trước đó.');
INSERT INTO "vstep_questions" VALUES(1734,NULL,42,'Trong Microsoft Word 2016, phát biểu nào sau đây không đúng về các kiểu tệp tin?','MULTIPLE_CHOICE','[{"id":"1","content":"Word 2016 có thể mở file của phiên bản Word cũ hơn","isCorrect":false},{"id":"2","content":"Có thể lưu văn bản dưới dạng Word phiên bản thấp hơn","isCorrect":false},{"id":"3","content":"Không thể lưu văn bản thành file PDF","isCorrect":true},{"id":"4","content":"Word 2003 không mở được file docx nếu không cài bổ trợ","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',9,'2026-01-30 18:19:56','Word 2003 (.doc) không thể mở được file .docx (Word 2007 trở về sau) nếu không cài gói hỗ trợ.');
INSERT INTO "vstep_questions" VALUES(1735,NULL,42,'Tổ hợp phím tạo một văn bản mới trong Word 2016 là:','MULTIPLE_CHOICE','[{"id":"1","content":"Ctrl + O","isCorrect":false},{"id":"2","content":"Ctrl + A","isCorrect":false},{"id":"3","content":"Ctrl + N","isCorrect":true},{"id":"4","content":"Ctrl + H","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',10,'2026-01-30 18:19:56','Ctrl + N (New) là phím tắt để tạo một tệp văn bản mới.');
INSERT INTO "vstep_questions" VALUES(1736,NULL,42,'Để lưu văn bản hiện thời thành một tên mới, ta chọn:','MULTIPLE_CHOICE','[{"id":"1","content":"File → Save","isCorrect":false},{"id":"2","content":"Home → Save","isCorrect":false},{"id":"3","content":"File → Save As","isCorrect":true},{"id":"4","content":"Home → Save As","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',11,'2026-01-30 18:19:56','File > Save As dùng để lưu văn bản hiện tại thành một tên mới (bản sao).');
INSERT INTO "vstep_questions" VALUES(1737,NULL,42,'Để bật/tắt thanh thước kẻ (Ruler), ta vào:','MULTIPLE_CHOICE','[{"id":"1","content":"Insert → Ruler","isCorrect":false},{"id":"2","content":"File → Options → Ruler","isCorrect":false},{"id":"3","content":"View → Show → Ruler","isCorrect":true},{"id":"4","content":"View → Outline","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',12,'2026-01-30 18:19:56','Vào View > Show > tích chọn Ruler để bật/tắt thanh thước kẻ.');
INSERT INTO "vstep_questions" VALUES(1738,NULL,42,'Tổ hợp phím in văn bản trong Word là:','MULTIPLE_CHOICE','[{"id":"1","content":"Alt + P","isCorrect":false},{"id":"2","content":"Alt + I","isCorrect":false},{"id":"3","content":"Ctrl + I","isCorrect":false},{"id":"4","content":"Ctrl + P","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',13,'2026-01-30 18:19:56','Ctrl + P (Print) dùng để mở hộp thoại in ấn.');
INSERT INTO "vstep_questions" VALUES(1739,NULL,42,'Khi đang soạn thảo văn bản, muốn chọn các ký tự từ vị trí con trỏ đến cuối văn bản, ta nhấn:','MULTIPLE_CHOICE','[{"id":"1","content":"Ctrl + Shift + →","isCorrect":false},{"id":"2","content":"Ctrl + Shift + End","isCorrect":true},{"id":"3","content":"Alt + Shift + End","isCorrect":false},{"id":"4","content":"Ctrl + End","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',14,'2026-01-30 18:19:56','Ctrl + Shift + End dùng để chọn (bôi đen) từ vị trí con trỏ đến hết văn bản.');
INSERT INTO "vstep_questions" VALUES(1740,NULL,42,'Tổ hợp phím Ctrl + J dùng để:','MULTIPLE_CHOICE','[{"id":"1","content":"Căn trái","isCorrect":false},{"id":"2","content":"Căn phải","isCorrect":false},{"id":"3","content":"Căn giữa","isCorrect":false},{"id":"4","content":"Căn đều hai bên","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',15,'2026-01-30 18:19:56','Ctrl + J (Justify) là phím tắt dùng để căn đều văn bản sang hai bên lề.');
INSERT INTO "vstep_questions" VALUES(1741,NULL,42,'Trong Microsoft Word 2016, để tìm và mở một tệp tin Word có sẵn, ta dùng tổ hợp phím nào?','MULTIPLE_CHOICE','[{"id":"1","content":"Ctrl + F","isCorrect":false},{"id":"2","content":"Ctrl + O","isCorrect":true},{"id":"3","content":"Ctrl + N","isCorrect":false},{"id":"4","content":"Ctrl + M","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',16,'2026-01-30 18:19:56','Tổ hợp phím Ctrl + O (Open) dùng để mở hộp thoại tìm và mở tệp tin đã có.');
INSERT INTO "vstep_questions" VALUES(1742,NULL,42,'Lệnh Auto Correct trong Word 2016 cho phép:','MULTIPLE_CHOICE','[{"id":"1","content":"Kiểm tra chính tả","isCorrect":false},{"id":"2","content":"Kiểm tra ngữ pháp","isCorrect":false},{"id":"3","content":"Tự động rà soát lỗi","isCorrect":false},{"id":"4","content":"Tự động sửa lỗi và gõ tắt","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',17,'2026-01-30 18:19:56','AutoCorrect là tính năng tự động sửa lỗi chính tả và hỗ trợ gõ tắt.');
INSERT INTO "vstep_questions" VALUES(1743,NULL,42,'Để chèn SmartArt trong Word 2016, ta chọn:','MULTIPLE_CHOICE','[{"id":"1","content":"Insert → Chart → SmartArt","isCorrect":false},{"id":"2","content":"Insert → Illustrations → SmartArt","isCorrect":true},{"id":"3","content":"Design → SmartArt","isCorrect":false},{"id":"4","content":"Insert → Picture → SmartArt","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',18,'2026-01-30 18:19:56','Insert > Illustrations > SmartArt dùng để chèn sơ đồ thông minh.');
INSERT INTO "vstep_questions" VALUES(1744,NULL,42,'Khi soạn thảo văn bản trong Microsoft Word, muốn di chuyển từ một ô sang ô kế tiếp bên phải của bảng (Table), ta nhấn phím nào?','MULTIPLE_CHOICE','[{"id":"1","content":"Esc","isCorrect":false},{"id":"2","content":"Ctrl","isCorrect":false},{"id":"3","content":"Caps Lock","isCorrect":false},{"id":"4","content":"Tab","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',19,'2026-01-30 18:19:56','Phím Tab dùng để di chuyển con trỏ sang ô kế tiếp bên phải trong bảng.');
INSERT INTO "vstep_questions" VALUES(1745,NULL,42,'Tên văn bản đang làm việc được hiển thị trên:','MULTIPLE_CHOICE','[{"id":"1","content":"Thanh trạng thái","isCorrect":false},{"id":"2","content":"Thanh công cụ","isCorrect":false},{"id":"3","content":"Thanh tiêu đề","isCorrect":true},{"id":"4","content":"Thanh thước","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',20,'2026-01-30 18:19:56','Tên của văn bản đang làm việc luôn hiển thị trên Thanh tiêu đề (Title bar).');
INSERT INTO "vstep_questions" VALUES(1746,NULL,42,'Trong Page Setup, tích chọn Mirror Margins để:','MULTIPLE_CHOICE','[{"id":"1","content":"Căn giữa văn bản","isCorrect":false},{"id":"2","content":"Đặt lề đối xứng cho các trang chẵn – lẻ","isCorrect":true},{"id":"3","content":"Đặt lề cho section","isCorrect":false},{"id":"4","content":"Đặt tiêu đề cân đối","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',21,'2026-01-30 18:19:56','Mirror Margins (Lề đối xứng) được dùng khi in ấn hai mặt (như sách, tạp chí).');
INSERT INTO "vstep_questions" VALUES(1747,NULL,42,'Muốn thay đổi chế độ Zoom trong Word 2016, ta:','MULTIPLE_CHOICE','[{"id":"1","content":"Page Layout → Zoom","isCorrect":false},{"id":"2","content":"Review → Zoom","isCorrect":false},{"id":"3","content":"View → Zoom","isCorrect":true},{"id":"4","content":"Home → Zoom","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',22,'2026-01-30 18:19:56','Vào View > Zoom (hoặc thanh trượt góc dưới) để thay đổi chế độ phóng to/thu nhỏ.');
INSERT INTO "vstep_questions" VALUES(1748,NULL,42,'Muốn xóa Tab đã đặt trong Word 2016, ta:','MULTIPLE_CHOICE','[{"id":"1","content":"Nhấn Delete","isCorrect":false},{"id":"2","content":"Nhấn Tab","isCorrect":false},{"id":"3","content":"Kéo Tab ra khỏi thanh Ruler","isCorrect":true},{"id":"4","content":"Nhấn Insert","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',23,'2026-01-30 18:19:56','Cách nhanh nhất để xóa Tab là dùng chuột kéo biểu tượng Tab ra khỏi thanh thước (Ruler).');
INSERT INTO "vstep_questions" VALUES(1749,NULL,42,'Để chèn biểu đồ (Chart) trong Word 2016, ta chọn:','MULTIPLE_CHOICE','[{"id":"1","content":"Insert → Chart","isCorrect":false},{"id":"2","content":"Insert → Illustrations → Chart","isCorrect":true},{"id":"3","content":"Design → Chart","isCorrect":false},{"id":"4","content":"Insert → Picture → Chart","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',24,'2026-01-30 18:19:56','Insert > Illustrations > Chart dùng để chèn biểu đồ vào văn bản.');
INSERT INTO "vstep_questions" VALUES(1750,NULL,42,'Khi thao tác với các ô trong bảng, ta sử dụng thẻ:','MULTIPLE_CHOICE','[{"id":"1","content":"Page Layout","isCorrect":false},{"id":"2","content":"Home → Table","isCorrect":false},{"id":"3","content":"Design → Layout","isCorrect":false},{"id":"4","content":"Table Tools → Layout","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',25,'2026-01-30 18:19:56','Thẻ Table Tools > Layout chứa các lệnh thao tác cấu trúc bảng (gộp, chia ô, chỉnh kích thước).');
INSERT INTO "vstep_questions" VALUES(1751,NULL,42,'Chế độ hiển thị văn bản theo kiểu Website là:','MULTIPLE_CHOICE','[{"id":"1","content":"Print Layout","isCorrect":false},{"id":"2","content":"Page Layout","isCorrect":false},{"id":"3","content":"Web Layout","isCorrect":true},{"id":"4","content":"Full Screen Reading","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',26,'2026-01-30 18:19:57','Web Layout là chế độ hiển thị văn bản dưới dạng trang web (không phân trang in).');
INSERT INTO "vstep_questions" VALUES(1752,NULL,42,'Tổ hợp phím Ctrl + E dùng để:','MULTIPLE_CHOICE','[{"id":"1","content":"Căn trái","isCorrect":false},{"id":"2","content":"Căn phải","isCorrect":false},{"id":"3","content":"Căn đều","isCorrect":false},{"id":"4","content":"Căn giữa","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',27,'2026-01-30 18:19:57','Ctrl + E (Center) là phím tắt dùng để căn giữa đoạn văn bản.');
INSERT INTO "vstep_questions" VALUES(1753,NULL,42,'Để đưa con trỏ về cuối tài liệu Word, nhấn:','MULTIPLE_CHOICE','[{"id":"1","content":"End","isCorrect":false},{"id":"2","content":"Page Down","isCorrect":false},{"id":"3","content":"Ctrl + Page Down","isCorrect":false},{"id":"4","content":"Ctrl + End","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',28,'2026-01-30 18:19:57','Ctrl + End đưa con trỏ về vị trí cuối cùng của tài liệu.');
INSERT INTO "vstep_questions" VALUES(1754,NULL,42,'Trình bày văn bản khổ A4 theo hướng ngang, ta chọn:','MULTIPLE_CHOICE','[{"id":"1","content":"Page Layout → Size → Landscape","isCorrect":false},{"id":"2","content":"Layout → Page Setup → Orientation → Landscape","isCorrect":true},{"id":"3","content":"Home → Orientation","isCorrect":false},{"id":"4","content":"View → Orientation","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',29,'2026-01-30 18:19:57','Layout > Page Setup > Orientation > Landscape dùng để chọn khổ giấy ngang.');
INSERT INTO "vstep_questions" VALUES(1755,NULL,42,'Tổ hợp phím tăng cỡ chữ trong Word là:','MULTIPLE_CHOICE','[{"id":"1","content":"Ctrl + [","isCorrect":false},{"id":"2","content":"Ctrl + ]","isCorrect":true},{"id":"3","content":"Ctrl + B","isCorrect":false},{"id":"4","content":"Ctrl + Shift + ]","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',30,'2026-01-30 18:19:57','Ctrl + ] dùng để tăng cỡ chữ; Ctrl + [ dùng để giảm cỡ chữ.');
INSERT INTO "vstep_questions" VALUES(1756,NULL,42,'Phím xóa ký tự đứng trước con trỏ là:','MULTIPLE_CHOICE','[{"id":"1","content":"Delete","isCorrect":false},{"id":"2","content":"Page Up","isCorrect":false},{"id":"3","content":"Page Down","isCorrect":false},{"id":"4","content":"Backspace","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',31,'2026-01-30 18:19:57','Phím Backspace xóa ký tự đứng trước (bên trái) con trỏ; Delete xóa phía sau.');
INSERT INTO "vstep_questions" VALUES(1757,NULL,42,'Trong Microsoft Word 2016, để ngắt trang, ta chọn:','MULTIPLE_CHOICE','[{"id":"1","content":"View → Page Break","isCorrect":false},{"id":"2","content":"Review → Break","isCorrect":false},{"id":"3","content":"Insert → Pages → Page Break","isCorrect":true},{"id":"4","content":"References → Break","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',32,'2026-01-30 18:19:57','Insert > Pages > Page Break dùng để ngắt trang thủ công (sang trang mới).');
INSERT INTO "vstep_questions" VALUES(1758,NULL,42,'Trong Word 2016, tạo một bản sao cửa sổ đang mở bằng lệnh:','MULTIPLE_CHOICE','[{"id":"1","content":"Split","isCorrect":false},{"id":"2","content":"Arrange All","isCorrect":false},{"id":"3","content":"Two Pages","isCorrect":false},{"id":"4","content":"New Window","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',33,'2026-01-30 18:19:57','Lệnh New Window tạo ra một cửa sổ mới chứa bản sao của tài liệu đang mở.');
INSERT INTO "vstep_questions" VALUES(1759,NULL,42,'Để chọn toàn bộ văn bản nhanh, ta:','MULTIPLE_CHOICE','[{"id":"1","content":"Click chuột phải 3 lần","isCorrect":false},{"id":"2","content":"Click chuột trái 3 lần tại lề trái văn bản","isCorrect":true},{"id":"3","content":"Click chuột trái 3 lần tại lề phải","isCorrect":false},{"id":"4","content":"Click chuột trái 2 lần","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',34,'2026-01-30 18:19:57','Click chuột trái 3 lần tại lề trái (Selection bar) để chọn toàn bộ văn bản.');
INSERT INTO "vstep_questions" VALUES(1760,NULL,42,'Khi đang soạn thảo văn bản, để xác định tổng số trang của văn bản hiện hành ta quan sát ở đâu?','MULTIPLE_CHOICE','[{"id":"1","content":"Thanh công cụ","isCorrect":false},{"id":"2","content":"Backstage File","isCorrect":false},{"id":"3","content":"Thanh thước","isCorrect":false},{"id":"4","content":"Thanh trạng thái","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',35,'2026-01-30 18:19:57','Thanh trạng thái (Status Bar) nằm dưới cùng cửa sổ, hiển thị tổng số trang, số từ...');
INSERT INTO "vstep_questions" VALUES(1761,NULL,42,'Muốn hiển thị song song hai tài liệu đang mở trong Word 2016, ta chọn:','MULTIPLE_CHOICE','[{"id":"1","content":"Split","isCorrect":false},{"id":"2","content":"Side by Side","isCorrect":false},{"id":"3","content":"View Side by Side","isCorrect":true},{"id":"4","content":"New Window","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',36,'2026-01-30 18:19:57','View Side by Side dùng để hiển thị song song hai tài liệu để so sánh.');
INSERT INTO "vstep_questions" VALUES(1762,NULL,42,'Trong Microsoft Word 2016, để chèn tiêu đề trang (Header & Footer), ta thực hiện:','MULTIPLE_CHOICE','[{"id":"1","content":"Design → Header & Footer","isCorrect":false},{"id":"2","content":"View → Header & Footer","isCorrect":false},{"id":"3","content":"Home → Header & Footer","isCorrect":false},{"id":"4","content":"Insert → Header & Footer","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',37,'2026-01-30 18:19:57','Vào Insert > Header & Footer để chèn tiêu đề đầu và chân trang.');
INSERT INTO "vstep_questions" VALUES(1763,NULL,42,'Khi đóng văn bản và chọn Cancel, Word sẽ:','MULTIPLE_CHOICE','[{"id":"1","content":"Mất toàn bộ dữ liệu","isCorrect":false},{"id":"2","content":"Mất dữ liệu 10 phút gần nhất","isCorrect":false},{"id":"3","content":"Hủy thao tác đóng văn bản","isCorrect":true},{"id":"4","content":"Đóng không lưu","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',38,'2026-01-30 18:19:57','Khi chọn Cancel trong hộp thoại đóng file, Word sẽ hủy thao tác đóng và quay lại soạn thảo.');
INSERT INTO "vstep_questions" VALUES(1764,NULL,42,'Để chèn Footnote trong Word 2016, ta chọn:','MULTIPLE_CHOICE','[{"id":"1","content":"Insert → Footnote","isCorrect":false},{"id":"2","content":"Review → Insert Footnote","isCorrect":false},{"id":"3","content":"References → Insert Footnote","isCorrect":true},{"id":"4","content":"Page Layout → Footnote","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',39,'2026-01-30 18:19:57','References > Insert Footnote dùng để chèn chú thích ở chân trang.');
INSERT INTO "vstep_questions" VALUES(1765,NULL,42,'Trong Word 2016, để vẽ đường thẳng, hình khối, ta thực hiện:','MULTIPLE_CHOICE','[{"id":"1","content":"View → Toolbars → Drawing","isCorrect":false},{"id":"2","content":"View → Ruler","isCorrect":false},{"id":"3","content":"Insert → Illustrations → Shapes","isCorrect":true},{"id":"4","content":"Design → Shapes","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',40,'2026-01-30 18:19:57','Vào Insert > Illustrations > Shapes để vẽ các đường thẳng, hình khối.');
INSERT INTO "vstep_questions" VALUES(1766,NULL,43,'Folder là:','MULTIPLE_CHOICE','[{"id":"1","content":"Mục lục","isCorrect":false},{"id":"2","content":"Ổ đĩa","isCorrect":false},{"id":"3","content":"Tệp đặc biệt","isCorrect":false},{"id":"4","content":"Tập hợp tệp và thư mục con","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',1,'2026-01-30 18:20:08','Folder (Thư mục) là tập hợp chứa các tệp tin và các thư mục con khác.');
INSERT INTO "vstep_questions" VALUES(1767,NULL,43,'Tệp trong thùng rác có thể:','MULTIPLE_CHOICE','[{"id":"1","content":"Không khôi phục","isCorrect":false},{"id":"2","content":"Bị xoá nội dung","isCorrect":false},{"id":"3","content":"Đã xoá vĩnh viễn","isCorrect":false},{"id":"4","content":"Khôi phục lại vị trí ban đầu","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',2,'2026-01-30 18:20:08','Tệp trong Thùng rác có thể được Restore (khôi phục) về đúng vị trí ban đầu.');
INSERT INTO "vstep_questions" VALUES(1768,NULL,43,'Hành động không an toàn khi dùng máy tính:','MULTIPLE_CHOICE','[{"id":"1","content":"Tháo lắp khi máy đang hoạt động","isCorrect":true},{"id":"2","content":"Giữ nút nguồn để tắt","isCorrect":false},{"id":"3","content":"Cắm chuột khi đang dùng","isCorrect":false},{"id":"4","content":"Rút dây nguồn","isCorrect":false}]','1',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',3,'2026-01-30 18:20:08','Tháo lắp thiết bị bên trong khi máy đang chạy dễ gây chập cháy, hỏng phần cứng.');
INSERT INTO "vstep_questions" VALUES(1769,NULL,43,'Ctrl + X có tác dụng:','MULTIPLE_CHOICE','[{"id":"1","content":"Di chuyển đối tượng vào bộ nhớ đệm","isCorrect":true},{"id":"2","content":"Hiển thị nội dung bộ nhớ đệm","isCorrect":false},{"id":"3","content":"Phục hồi thao tác","isCorrect":false},{"id":"4","content":"Sao chép đối tượng","isCorrect":false}]','1',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',4,'2026-01-30 18:20:08','Lệnh Ctrl + X (Cut) dùng để di chuyển đối tượng (cắt từ chỗ này sang chỗ khác).');
INSERT INTO "vstep_questions" VALUES(1770,NULL,43,'Trong Windows 10, cách nào sau đây sao chép thư mục từ ổ đĩa này sang ổ đĩa khác?','MULTIPLE_CHOICE','[{"id":"1","content":"Ctrl + X → Ctrl + V","isCorrect":false},{"id":"2","content":"Tạo shortcut","isCorrect":false},{"id":"3","content":"Không có cách nào","isCorrect":false},{"id":"4","content":"Chuột phải chọn Copy → Paste","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',5,'2026-01-30 18:20:08','Quy trình sao chép: Chọn đối tượng -> Copy -> Đến đích -> Paste.');
INSERT INTO "vstep_questions" VALUES(1771,NULL,43,'Định dạng chuẩn phân vùng cài Windows 10 là:','MULTIPLE_CHOICE','[{"id":"1","content":"FAT","isCorrect":false},{"id":"2","content":"FAT16","isCorrect":false},{"id":"3","content":"FAT32","isCorrect":false},{"id":"4","content":"NTFS","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',6,'2026-01-30 18:20:08','NTFS là định dạng hệ thống tập tin tiêu chuẩn, bảo mật cao của Windows hiện đại.');
INSERT INTO "vstep_questions" VALUES(1772,NULL,43,'Biểu tượng nào là Shortcut trên Desktop?','MULTIPLE_CHOICE','[{"id":"1","content":"Word, My Computer, Unikey","isCorrect":false},{"id":"2","content":"Word 2016, Excel 2016, Unikey","isCorrect":true},{"id":"3","content":"Word, Network","isCorrect":false},{"id":"4","content":"My Computer, Recycle Bin","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',7,'2026-01-30 18:20:08','Word, Excel là shortcut ứng dụng; My Computer/Recycle Bin là biểu tượng hệ thống.');
INSERT INTO "vstep_questions" VALUES(1773,NULL,43,'Trong Windows, để xem các thông tin của một tệp, bạn thực hiện lần lượt các thao tác nào sau đây?','MULTIPLE_CHOICE','[{"id":"1","content":"Chọn tệp – nhấp phải chuột – chọn Properties","isCorrect":true},{"id":"2","content":"Chọn tệp – nhấp trái chuột – chọn Properties","isCorrect":false},{"id":"3","content":"Chọn tệp – nhấp phải chuột – chọn Details","isCorrect":false},{"id":"4","content":"Chọn tệp – nhấp trái chuột – chọn Details","isCorrect":false}]','1',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',8,'2026-01-30 18:20:08','Nhấp chuột phải vào tệp và chọn Properties để xem chi tiết thông tin (dung lượng, ngày tạo).');
INSERT INTO "vstep_questions" VALUES(1774,NULL,43,'Tuỳ chỉnh cập nhật Windows 10 tại:','MULTIPLE_CHOICE','[{"id":"1","content":"Settings → Update & Security → Windows Update","isCorrect":true},{"id":"2","content":"Windows Update","isCorrect":false},{"id":"3","content":"Control Panel","isCorrect":false},{"id":"4","content":"Settings → Windows","isCorrect":false}]','1',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',9,'2026-01-30 18:20:08','Vào Settings > Update & Security > Windows Update để cập nhật Win 10.');
INSERT INTO "vstep_questions" VALUES(1775,NULL,43,'Tên chương trình bàn phím ảo là:','MULTIPLE_CHOICE','[{"id":"1","content":"Virtual Keyboard","isCorrect":false},{"id":"2","content":"Tablet PC Input","isCorrect":false},{"id":"3","content":"On-Screen Keyboard","isCorrect":true},{"id":"4","content":"Không có","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',10,'2026-01-30 18:20:08','On-Screen Keyboard là bàn phím ảo có sẵn trong Windows hỗ trợ nhập liệu.');
INSERT INTO "vstep_questions" VALUES(1776,NULL,43,'Cách nhận biết một tệp/thư mục là shortcut?','MULTIPLE_CHOICE','[{"id":"1","content":"Có mũi tên nhỏ ở góc dưới biểu tượng","isCorrect":true},{"id":"2","content":"Là tập tài liệu","isCorrect":false},{"id":"3","content":"Có biểu tượng phần mềm","isCorrect":false},{"id":"4","content":"Có chữ W","isCorrect":false}]','1',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',11,'2026-01-30 18:20:09','Biểu tượng Shortcut luôn có một hình mũi tên nhỏ ở góc dưới bên trái icon.');
INSERT INTO "vstep_questions" VALUES(1777,NULL,43,'Đâu không phải cách giải nén bằng WinRAR?','MULTIPLE_CHOICE','[{"id":"1","content":"Chuột phải chọn Open","isCorrect":true},{"id":"2","content":"Double click → Wizard","isCorrect":false},{"id":"3","content":"Extract file","isCorrect":false},{"id":"4","content":"Extract here","isCorrect":false}]','1',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',12,'2026-01-30 18:20:09','Chuột phải chọn "Open" chỉ là mở file nén xem nội dung, không phải lệnh giải nén trực tiếp.');
INSERT INTO "vstep_questions" VALUES(1778,NULL,43,'Khi sao chép Shortcut từ máy A sang máy B (cấu trúc khác), tại máy B người dùng có thể:','MULTIPLE_CHOICE','[{"id":"1","content":"Không mở được tệp hoặc thư mục","isCorrect":true},{"id":"2","content":"Máy B không đọc được tệp","isCorrect":false},{"id":"3","content":"Máy B bị nhiễm virus","isCorrect":false},{"id":"4","content":"Vẫn mở được thư mục","isCorrect":false}]','1',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',13,'2026-01-30 18:20:09','Shortcut chỉ là đường tắt, nếu copy sang máy khác mà không kèm file gốc thì không mở được.');
INSERT INTO "vstep_questions" VALUES(1779,NULL,43,'Độ phân giải màn hình (Resolution) thể hiện điều gì?','MULTIPLE_CHOICE','[{"id":"1","content":"Màn hình nền hiển thị","isCorrect":false},{"id":"2","content":"Mức sáng màn hình","isCorrect":false},{"id":"3","content":"Số điểm ảnh màn hình có thể hiển thị","isCorrect":true},{"id":"4","content":"Màu sắc màn hình","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',14,'2026-01-30 18:20:09','Độ phân giải màn hình thể hiện số lượng điểm ảnh (pixel) mà màn hình có thể hiển thị.');
INSERT INTO "vstep_questions" VALUES(1780,NULL,43,'Giữ phím nào để chọn file liền kề nhau?','MULTIPLE_CHOICE','[{"id":"1","content":"Alt","isCorrect":false},{"id":"2","content":"Ctrl","isCorrect":false},{"id":"3","content":"Windows","isCorrect":false},{"id":"4","content":"Shift","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',15,'2026-01-30 18:20:09','Giữ phím Shift và kích chuột vào điểm đầu, điểm cuối để chọn danh sách liền kề.');
INSERT INTO "vstep_questions" VALUES(1781,NULL,43,'Phần mềm bắt buộc phải có để máy hoạt động:','MULTIPLE_CHOICE','[{"id":"1","content":"Windows","isCorrect":true},{"id":"2","content":"Vietkey","isCorrect":false},{"id":"3","content":"Norton","isCorrect":false},{"id":"4","content":"Chrome","isCorrect":false}]','1',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',16,'2026-01-30 18:20:09','Phần mềm hệ thống (như Windows) là bắt buộc phải có để máy tính hoạt động được.');
INSERT INTO "vstep_questions" VALUES(1782,NULL,43,'Phím mở File Explorer:','MULTIPLE_CHOICE','[{"id":"1","content":"Windows + E","isCorrect":true},{"id":"2","content":"Alt + E","isCorrect":false},{"id":"3","content":"Shift + E","isCorrect":false},{"id":"4","content":"Ctrl + E","isCorrect":false}]','1',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',17,'2026-01-30 18:20:09','Tổ hợp phím Windows + E dùng để mở nhanh trình quản lý tệp (File Explorer).');
INSERT INTO "vstep_questions" VALUES(1783,NULL,43,'Trong hệ điều hành Windows, tệp tin là khái niệm chỉ:','MULTIPLE_CHOICE','[{"id":"1","content":"Một đơn vị lưu trữ thông tin trên bộ nhớ ngoài","isCorrect":true},{"id":"2","content":"Một đơn vị lưu trữ thông tin trên RAM","isCorrect":false},{"id":"3","content":"Một gói tin","isCorrect":false},{"id":"4","content":"Một trang web","isCorrect":false}]','1',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',18,'2026-01-30 18:20:09','Tệp tin (File) là đơn vị cơ bản để lưu trữ thông tin trên bộ nhớ ngoài (ổ cứng, USB...).');
INSERT INTO "vstep_questions" VALUES(1784,NULL,43,'Chuỗi “tk*.jpg” nghĩa là:','MULTIPLE_CHOICE','[{"id":"1","content":"Các file 3 ký tự, bắt đầu tk, đuôi jpg","isCorrect":true},{"id":"2","content":"File tên tk","isCorrect":false},{"id":"3","content":"Thư mục tk","isCorrect":false},{"id":"4","content":"Thư mục 3 ký tự","isCorrect":false}]','1',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',19,'2026-01-30 18:20:09','Ký tự "" đại diện cho chuỗi bất kỳ. "tk.jpg" tìm file bắt đầu bằng "tk" và có đuôi ".jpg".');
INSERT INTO "vstep_questions" VALUES(1785,NULL,43,'Trong Windows, cần phóng to / thu nhỏ màn hình khi trình chiếu dùng tổ hợp phím:','MULTIPLE_CHOICE','[{"id":"1","content":"Windows + (+/–)","isCorrect":false},{"id":"2","content":"Ctrl + (+/–)","isCorrect":false},{"id":"3","content":"Windows + lăn chuột","isCorrect":false},{"id":"4","content":"Ctrl + lăn chuột","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',20,'2026-01-30 18:20:09','Giữ Ctrl kết hợp lăn nút giữa chuột là thao tác nhanh để phóng to/thu nhỏ (Zoom).');
INSERT INTO "vstep_questions" VALUES(1786,NULL,43,'Chọn thư mục rồi nhấn Delete có tác dụng:','MULTIPLE_CHOICE','[{"id":"1","content":"Khôi phục tệp","isCorrect":false},{"id":"2","content":"Xóa thư mục","isCorrect":true},{"id":"3","content":"Đổi tên","isCorrect":false},{"id":"4","content":"Di chuyển","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',21,'2026-01-30 18:20:09','Chọn thư mục rồi nhấn Delete sẽ xóa thư mục đó (đưa vào Thùng rác).');
INSERT INTO "vstep_questions" VALUES(1787,NULL,43,'Trong Windows 10, khi chọn 1 file và nhấn Shift + Delete thì có tác dụng gì?','MULTIPLE_CHOICE','[{"id":"1","content":"Tạo shortcut","isCorrect":false},{"id":"2","content":"File bị xóa vĩnh viễn","isCorrect":true},{"id":"3","content":"File vào thùng rác","isCorrect":false},{"id":"4","content":"Đổi tên file","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',22,'2026-01-30 18:20:09','Shift + Delete sẽ xóa vĩnh viễn dữ liệu mà không đưa vào Thùng rác (Recycle Bin).');
INSERT INTO "vstep_questions" VALUES(1788,NULL,43,'Ý nghĩa của Read Only là:','MULTIPLE_CHOICE','[{"id":"1","content":"Xem được, không chỉnh sửa","isCorrect":true},{"id":"2","content":"Không sao chép","isCorrect":false},{"id":"3","content":"Xem – sửa – xoá","isCorrect":false},{"id":"4","content":"Chỉ xem","isCorrect":false}]','1',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',23,'2026-01-30 18:20:09','File có thuộc tính Read Only cho phép xem nhưng không cho phép lưu thay đổi lên chính nó.');
INSERT INTO "vstep_questions" VALUES(1789,NULL,43,'Để kiểm tra dung lượng thư mục/ổ đĩa, ta thực hiện:','MULTIPLE_CHOICE','[{"id":"1","content":"File → Informations","isCorrect":false},{"id":"2","content":"Chuột phải → Properties","isCorrect":true},{"id":"3","content":"File → Properties","isCorrect":false},{"id":"4","content":"Chuột phải → Informations","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',24,'2026-01-30 18:20:09','Nhấp chuột phải vào ổ đĩa/thư mục chọn Properties để kiểm tra dung lượng.');
INSERT INTO "vstep_questions" VALUES(1790,NULL,43,'Xem cấu hình máy tính Windows 10 bằng cách:','MULTIPLE_CHOICE','[{"id":"1","content":"This PC → Properties","isCorrect":true},{"id":"2","content":"Desktop → Properties","isCorrect":false},{"id":"3","content":"Desktop → Personalize","isCorrect":false},{"id":"4","content":"Computer → Manage","isCorrect":false}]','1',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',25,'2026-01-30 18:20:09','Chuột phải vào This PC (hoặc My Computer) chọn Properties để xem cấu hình máy.');
INSERT INTO "vstep_questions" VALUES(1791,NULL,43,'Đâu không phải phần mềm diệt virus?','MULTIPLE_CHOICE','[{"id":"1","content":"Kaspersky","isCorrect":false},{"id":"2","content":"Firefox","isCorrect":true},{"id":"3","content":"Norton","isCorrect":false},{"id":"4","content":"Windows Defender","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',26,'2026-01-30 18:20:09','Firefox là trình duyệt web; Kaspersky, Norton, Windows Defender là phần mềm diệt virus.');
INSERT INTO "vstep_questions" VALUES(1792,NULL,43,'Bảng mã ASCII mở rộng có bao nhiêu ký tự?','MULTIPLE_CHOICE','[{"id":"1","content":"254","isCorrect":false},{"id":"2","content":"255","isCorrect":false},{"id":"3","content":"257","isCorrect":false},{"id":"4","content":"256","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',27,'2026-01-30 18:20:09','Bảng mã ASCII mở rộng sử dụng 8 bit, biểu diễn được 256 ký tự khác nhau.');
INSERT INTO "vstep_questions" VALUES(1793,NULL,43,'Thuộc tính chỉ đọc của tệp là:','MULTIPLE_CHOICE','[{"id":"1","content":"Delete","isCorrect":false},{"id":"2","content":"Hidden","isCorrect":false},{"id":"3","content":"Modify","isCorrect":false},{"id":"4","content":"Read Only","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',28,'2026-01-30 18:20:09','Thuộc tính Read Only (Chỉ đọc) được dùng để bảo vệ file khỏi bị chỉnh sửa nội dung.');
INSERT INTO "vstep_questions" VALUES(1794,NULL,43,'Bảo vệ dữ liệu khi hỏng ổ cứng bằng cách:','MULTIPLE_CHOICE','[{"id":"1","content":"Sao lưu thường xuyên","isCorrect":true},{"id":"2","content":"Ghi DVD","isCorrect":false},{"id":"3","content":"Có 2 ổ cứng","isCorrect":false},{"id":"4","content":"Xóa file","isCorrect":false}]','1',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',29,'2026-01-30 18:20:09','Sao lưu dữ liệu (Backup) thường xuyên là cách tốt nhất để bảo vệ dữ liệu khi ổ cứng hỏng.');
INSERT INTO "vstep_questions" VALUES(1795,NULL,43,'Trong Windows 10, để tắt một ứng dụng đang bị treo theo đúng quy trình, bạn thực hiện:','MULTIPLE_CHOICE','[{"id":"1","content":"Nhấn nút Power ở case","isCorrect":false},{"id":"2","content":"Mở Task Manager, chọn ứng dụng bị treo, nhấn End Task","isCorrect":true},{"id":"3","content":"Nhấn nút Reset","isCorrect":false},{"id":"4","content":"Vào Start chọn Shutdown","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',30,'2026-01-30 18:20:09','Khi ứng dụng bị treo, dùng Task Manager để buộc dừng chương trình (End Task).');
INSERT INTO "vstep_questions" VALUES(1796,NULL,43,'Giữ phím nào để chọn nhiều file rời rạc?','MULTIPLE_CHOICE','[{"id":"1","content":"Ctrl","isCorrect":true},{"id":"2","content":"Shift","isCorrect":false},{"id":"3","content":"Alt","isCorrect":false},{"id":"4","content":"Windows","isCorrect":false}]','1',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',31,'2026-01-30 18:20:09','Giữ phím Ctrl để chọn các file rời rạc; giữ Shift để chọn các file liền kề.');
INSERT INTO "vstep_questions" VALUES(1797,NULL,43,'Định dạng hiển thị ngày “Tuesday, July 30, 2015” là:','MULTIPLE_CHOICE','[{"id":"1","content":"dd MMMM yyyy","isCorrect":false},{"id":"2","content":"MMMM dd yyyy","isCorrect":false},{"id":"3","content":"dddd, MMMM dd, yyyy","isCorrect":true},{"id":"4","content":"dddd dd MMMM yyyy","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',32,'2026-01-30 18:20:09','Định dạng hiển thị đầy đủ thứ, tháng (chữ), ngày, năm tương ứng với: dddd MMMM dd yyyy.');
INSERT INTO "vstep_questions" VALUES(1798,NULL,43,'Phần mở rộng trong tên file đảm nhận chức năng nào?','MULTIPLE_CHOICE','[{"id":"1","content":"Quy định kiểu file","isCorrect":true},{"id":"2","content":"Quy định định dạng file","isCorrect":false},{"id":"3","content":"Quy định kích thước file","isCorrect":false},{"id":"4","content":"Quy định thuộc tính file","isCorrect":false}]','1',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',33,'2026-01-30 18:20:10','Phần mở rộng (đuôi tệp) giúp hệ điều hành nhận biết kiểu file và phần mềm khởi chạy.');
INSERT INTO "vstep_questions" VALUES(1799,NULL,43,'Xem kích thước tệp trong Windows 10 bằng cách:','MULTIPLE_CHOICE','[{"id":"1","content":"Open","isCorrect":false},{"id":"2","content":"Properties → Customize","isCorrect":false},{"id":"3","content":"Double click","isCorrect":false},{"id":"4","content":"Properties → General","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',34,'2026-01-30 18:20:10','Thẻ General trong hộp thoại Properties cung cấp thông tin về kích thước (Size) của tệp.');
INSERT INTO "vstep_questions" VALUES(1800,NULL,43,'Để chọn tính năng cho máy tính ở chế độ ngủ, ta lựa chọn chế độ nào dưới đây?','MULTIPLE_CHOICE','[{"id":"1","content":"Hibernate","isCorrect":false},{"id":"2","content":"Sign out","isCorrect":false},{"id":"3","content":"Sleep","isCorrect":true},{"id":"4","content":"Lock","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',35,'2026-01-30 18:20:10','Chế độ Sleep (Ngủ) giữ máy ở trạng thái năng lượng thấp, dữ liệu vẫn ở RAM để khởi động lại nhanh.');
INSERT INTO "vstep_questions" VALUES(1801,NULL,43,'Trong Windows 10, để nhìn thấy được các máy tính trong mạng nội bộ thì nháy đúp chuột vào biểu tượng có tên là gì?','MULTIPLE_CHOICE','[{"id":"1","content":"User’s profile","isCorrect":false},{"id":"2","content":"Sharing","isCorrect":false},{"id":"3","content":"Network","isCorrect":true},{"id":"4","content":"This PC","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',36,'2026-01-30 18:20:10','Biểu tượng Network cho phép nhìn thấy và truy cập các tài nguyên trong mạng nội bộ.');
INSERT INTO "vstep_questions" VALUES(1802,NULL,43,'Chức năng nào cho phép tạo tài khoản người dùng trong Windows 10?','MULTIPLE_CHOICE','[{"id":"1","content":"Multimedia","isCorrect":false},{"id":"2","content":"Windows Explorer","isCorrect":false},{"id":"3","content":"Desktop","isCorrect":false},{"id":"4","content":"User Accounts","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',37,'2026-01-30 18:20:10','User Accounts trong Control Panel dùng để quản lý và tạo tài khoản người dùng.');
INSERT INTO "vstep_questions" VALUES(1803,NULL,43,'Drag and Drop dùng để:','MULTIPLE_CHOICE','[{"id":"1","content":"Mở thư mục","isCorrect":false},{"id":"2","content":"Xem thuộc tính","isCorrect":false},{"id":"3","content":"Đổi màu","isCorrect":false},{"id":"4","content":"Di chuyển đối tượng","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',38,'2026-01-30 18:20:10','Thao tác Drag and Drop (Kéo và thả) thường dùng để di chuyển đối tượng nhanh.');
INSERT INTO "vstep_questions" VALUES(1804,NULL,43,'Mục đích của nén dữ liệu là:','MULTIPLE_CHOICE','[{"id":"1","content":"Sắp xếp thư mục","isCorrect":false},{"id":"2","content":"Đổi định dạng","isCorrect":false},{"id":"3","content":"Giảm dung lượng","isCorrect":true},{"id":"4","content":"Mã hóa","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',39,'2026-01-30 18:20:10','Mục đích chính của việc nén dữ liệu là làm giảm dung lượng để dễ lưu trữ và chia sẻ.');
INSERT INTO "vstep_questions" VALUES(1805,NULL,43,'Tạo Shortcut trên Desktop:','MULTIPLE_CHOICE','[{"id":"1","content":"New → Shortcut","isCorrect":true},{"id":"2","content":"View → Shortcut","isCorrect":false},{"id":"3","content":"Create Shortcut","isCorrect":false},{"id":"4","content":"Browse → Shortcut","isCorrect":false}]','1',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',40,'2026-01-30 18:20:10','Chuột phải Desktop -> New -> Shortcut là thao tác tạo đường tắt thủ công.');
INSERT INTO "vstep_questions" VALUES(1806,NULL,44,'ASCII mở rộng có bao nhiêu ký tự?','MULTIPLE_CHOICE','[{"id":"1","content":"254","isCorrect":false},{"id":"2","content":"255","isCorrect":false},{"id":"3","content":"257","isCorrect":false},{"id":"4","content":"256","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',1,'2026-01-30 18:20:20','Bảng mã ASCII mở rộng (8 bit) có thể biểu diễn được 256 ký tự (2 mũ 8).');
INSERT INTO "vstep_questions" VALUES(1807,NULL,44,'Không phải phần mềm mã nguồn mở:','MULTIPLE_CHOICE','[{"id":"1","content":"Microsoft Office","isCorrect":true},{"id":"2","content":"Firefox","isCorrect":false},{"id":"3","content":"Ubuntu","isCorrect":false},{"id":"4","content":"OpenOffice","isCorrect":false}]','1',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',2,'2026-01-30 18:20:20','Microsoft Office là phần mềm thương mại (đóng), không phải mã nguồn mở như Firefox/Ubuntu.');
INSERT INTO "vstep_questions" VALUES(1808,NULL,44,'CPU đa lõi được chế tạo trên:','MULTIPLE_CHOICE','[{"id":"1","content":"2 chip","isCorrect":false},{"id":"2","content":"4 chip","isCorrect":false},{"id":"3","content":"3 chip","isCorrect":false},{"id":"4","content":"1 chip","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',3,'2026-01-30 18:20:20','"Dual Core" (Chip lõi kép) nghĩa là bộ vi xử lý có 2 nhân tính toán.');
INSERT INTO "vstep_questions" VALUES(1809,NULL,44,'Macro Virus là gì?','MULTIPLE_CHOICE','[{"id":"1","content":"Lây qua USB","isCorrect":false},{"id":"2","content":"Lây vào tệp Word và Excel","isCorrect":true},{"id":"3","content":"Lây vào từ điển","isCorrect":false},{"id":"4","content":"Lây vào Boot record","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',4,'2026-01-30 18:20:20','Macro Virus là loại virus lây nhiễm chủ yếu qua các file văn phòng như Word và Excel.');
INSERT INTO "vstep_questions" VALUES(1810,NULL,44,'Tên nào sau đây là tên hệ điều hành?','MULTIPLE_CHOICE','[{"id":"1","content":"Notepad","isCorrect":false},{"id":"2","content":"UniKey","isCorrect":false},{"id":"3","content":"Microsoft Office 2016","isCorrect":false},{"id":"4","content":"Windows 10","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',5,'2026-01-30 18:20:20','Windows 10 là tên của một Hệ điều hành máy tính phổ biến.');
INSERT INTO "vstep_questions" VALUES(1811,NULL,44,'Quá trình xử lý thông tin dữ liệu trên máy tính bao gồm các bước nào?','MULTIPLE_CHOICE','[{"id":"1","content":"Xử lý và lưu trữ dữ liệu","isCorrect":false},{"id":"2","content":"Điều khiển thiết bị vào và thiết bị ra","isCorrect":false},{"id":"3","content":"Điều khiển thiết bị nhập và bộ nhớ","isCorrect":false},{"id":"4","content":"Nhập thông tin vào, xử lý thông tin, xuất thông tin ra","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',6,'2026-01-30 18:20:20','Quá trình xử lý thông tin tổng quát: Nhập (Input) → Xử lý (Process) → Xuất (Output).');
INSERT INTO "vstep_questions" VALUES(1812,NULL,44,'CPU là từ viết tắt của:','MULTIPLE_CHOICE','[{"id":"1","content":"Control Processing Unit","isCorrect":false},{"id":"2","content":"Central Processing Unit","isCorrect":true},{"id":"3","content":"Center Process University","isCorrect":false},{"id":"4","content":"Control Protocol Uniform","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',7,'2026-01-30 18:20:20','CPU là viết tắt của cụm từ Central Processing Unit (Bộ xử lý trung tâm).');
INSERT INTO "vstep_questions" VALUES(1813,NULL,44,'Máy in laser hết mực, cách tiết kiệm chi phí là:','MULTIPLE_CHOICE','[{"id":"1","content":"Thay trống","isCorrect":false},{"id":"2","content":"Thay hộp mực","isCorrect":false},{"id":"3","content":"Đổ thêm mực","isCorrect":true},{"id":"4","content":"Mua máy mới","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',8,'2026-01-30 18:20:20','Thay mực (nạp mực) giúp tiết kiệm chi phí hơn so với việc mua hộp mực mới hoàn toàn.');
INSERT INTO "vstep_questions" VALUES(1814,NULL,44,'Trong cấu hình PC: I5-10210U / 8Gb / 256Gb SSD / 13.3" FHD, thông số nào là RAM?','MULTIPLE_CHOICE','[{"id":"1","content":"256Gb SSD","isCorrect":false},{"id":"2","content":"8Gb","isCorrect":true},{"id":"3","content":"13.3\" FHD","isCorrect":false},{"id":"4","content":"I5-10210U","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',9,'2026-01-30 18:20:20','Trong thông số cấu hình, "8GB" chỉ dung lượng của bộ nhớ RAM.');
INSERT INTO "vstep_questions" VALUES(1815,NULL,44,'Màn hình, loa, máy in thuộc khối chức năng nào?','MULTIPLE_CHOICE','[{"id":"1","content":"Khối xử lý","isCorrect":false},{"id":"2","content":"Thiết bị xuất","isCorrect":true},{"id":"3","content":"Thiết bị lưu trữ","isCorrect":false},{"id":"4","content":"Thiết bị nhập","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',10,'2026-01-30 18:20:20','Màn hình, loa, máy in đều có chức năng đưa thông tin ra ngoài (Thiết bị xuất).');
INSERT INTO "vstep_questions" VALUES(1816,NULL,44,'Chế độ ngủ của máy tính là:','MULTIPLE_CHOICE','[{"id":"1","content":"Hibernate","isCorrect":false},{"id":"2","content":"Sign out","isCorrect":false},{"id":"3","content":"Sleep","isCorrect":true},{"id":"4","content":"Lock","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',11,'2026-01-30 18:20:20','Chế độ Sleep đưa máy vào trạng thái nghỉ, tiết kiệm điện nhưng khởi động lại rất nhanh.');
INSERT INTO "vstep_questions" VALUES(1817,NULL,44,'Phát biểu đúng là:','MULTIPLE_CHOICE','[{"id":"1","content":"Sleep vẫn tiêu thụ điện","isCorrect":true},{"id":"2","content":"Logout không tiêu thụ điện","isCorrect":false},{"id":"3","content":"Sleep không tiêu thụ điện","isCorrect":false},{"id":"4","content":"Shutdown vẫn tiêu thụ điện","isCorrect":false}]','1',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',12,'2026-01-30 18:20:20','Chế độ Sleep (Ngủ) giúp máy tính tiết kiệm điện năng khi tạm thời không sử dụng.');
INSERT INTO "vstep_questions" VALUES(1818,NULL,44,'Thiết bị bao bọc và bảo vệ linh kiện máy tính là:','MULTIPLE_CHOICE','[{"id":"1","content":"SSD","isCorrect":false},{"id":"2","content":"Case máy tính","isCorrect":true},{"id":"3","content":"Khối hệ thống","isCorrect":false},{"id":"4","content":"Hộp ổ cứng","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',13,'2026-01-30 18:20:20','Hệ thống quạt trong thùng máy (Case) giúp tản nhiệt và bảo vệ linh kiện.');
INSERT INTO "vstep_questions" VALUES(1819,NULL,44,'Chuột, bàn phím, máy quét là:','MULTIPLE_CHOICE','[{"id":"1","content":"Xử lý","isCorrect":false},{"id":"2","content":"Xuất","isCorrect":false},{"id":"3","content":"Nhập","isCorrect":true},{"id":"4","content":"Lưu trữ","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',14,'2026-01-30 18:20:20','Chuột và Bàn phím là các thiết bị dùng để đưa dữ liệu vào máy tính (Thiết bị nhập).');
INSERT INTO "vstep_questions" VALUES(1820,NULL,44,'Định nghĩa đúng nhất về phần mềm ứng dụng là:','MULTIPLE_CHOICE','[{"id":"1","content":"Tất cả đều sai","isCorrect":false},{"id":"2","content":"Trực tiếp thực hiện công việc cho người dùng","isCorrect":true},{"id":"3","content":"Không trực tiếp phục vụ người dùng","isCorrect":false},{"id":"4","content":"Thực hiện gián tiếp","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',15,'2026-01-30 18:20:20','Phần mềm ứng dụng là phần mềm trực tiếp hỗ trợ người dùng thực hiện các công việc cụ thể.');
INSERT INTO "vstep_questions" VALUES(1821,NULL,44,'Loại máy tính nào sau đây thường có cấu hình cao nhất?','MULTIPLE_CHOICE','[{"id":"1","content":"Máy tính cá nhân","isCorrect":false},{"id":"2","content":"Máy chủ","isCorrect":true},{"id":"3","content":"Máy tính xách tay","isCorrect":false},{"id":"4","content":"Máy tính cầm tay","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',16,'2026-01-30 18:20:21','Máy chủ (Server) là loại máy tính thường có cấu hình mạnh nhất để phục vụ nhiều máy trạm.');
INSERT INTO "vstep_questions" VALUES(1822,NULL,44,'Công cụ quản lý cơ sở dữ liệu là:','MULTIPLE_CHOICE','[{"id":"1","content":"Word","isCorrect":false},{"id":"2","content":"Excel","isCorrect":false},{"id":"3","content":"SQL Server","isCorrect":true},{"id":"4","content":"Internet Explorer","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',17,'2026-01-30 18:20:21','SQL Server là hệ quản trị cơ sở dữ liệu (Word/Excel là phần mềm văn phòng).');
INSERT INTO "vstep_questions" VALUES(1823,NULL,44,'Đơn vị đo tốc độ CPU là:','MULTIPLE_CHOICE','[{"id":"1","content":"KB","isCorrect":false},{"id":"2","content":"GHz","isCorrect":true},{"id":"3","content":"MB","isCorrect":false},{"id":"4","content":"GB","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',18,'2026-01-30 18:20:21','Tốc độ xử lý của CPU thường được đo bằng đơn vị GHz (Gigahertz).');
INSERT INTO "vstep_questions" VALUES(1824,NULL,44,'Phần mềm dùng để nén tệp tin là:','MULTIPLE_CHOICE','[{"id":"1","content":"MsExcel","isCorrect":false},{"id":"2","content":"Visual Basic","isCorrect":false},{"id":"3","content":"MsWord","isCorrect":false},{"id":"4","content":"WinRAR","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',19,'2026-01-30 18:20:21','WinRAR là phần mềm dùng để nén và giải nén tập tin.');
INSERT INTO "vstep_questions" VALUES(1825,NULL,44,'Bộ nhớ tạm thời là:','MULTIPLE_CHOICE','[{"id":"1","content":"USB","isCorrect":false},{"id":"2","content":"CMOS","isCorrect":false},{"id":"3","content":"BIOS","isCorrect":false},{"id":"4","content":"RAM","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',20,'2026-01-30 18:20:21','RAM là bộ nhớ tạm thời, dữ liệu sẽ mất khi tắt nguồn điện.');
INSERT INTO "vstep_questions" VALUES(1826,NULL,44,'1 KB bằng:','MULTIPLE_CHOICE','[{"id":"1","content":"1000 byte","isCorrect":false},{"id":"2","content":"1024 byte","isCorrect":true},{"id":"3","content":"1000 bit","isCorrect":false},{"id":"4","content":"1024 bit","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',21,'2026-01-30 18:20:21','1 KB (Kilobyte) tương đương với 1024 Byte (theo hệ nhị phân 2^10).');
INSERT INTO "vstep_questions" VALUES(1827,NULL,44,'Social Engineering là gì?','MULTIPLE_CHOICE','[{"id":"1","content":"Kỹ thuật đánh lừa người dùng để khai thác thông tin","isCorrect":true},{"id":"2","content":"Tất cả các ý còn lại đều đúng","isCorrect":false},{"id":"3","content":"Chỉ liên quan mạng xã hội","isCorrect":false},{"id":"4","content":"Khai thác thông tin ngoài xã hội","isCorrect":false}]','1',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',22,'2026-01-30 18:20:21','Social Engineering là kỹ thuật lừa đảo, tác động tâm lý người dùng để đánh cắp thông tin.');
INSERT INTO "vstep_questions" VALUES(1828,NULL,44,'Trên máy tính Byte được định nghĩa là:','MULTIPLE_CHOICE','[{"id":"1","content":"Một đơn vị thông tin nhỏ nhất trên máy tính","isCorrect":false},{"id":"2","content":"Một đơn vị lưu trữ dữ liệu cho máy tính","isCorrect":true},{"id":"3","content":"Một đơn vị đo trao đổi thông tin","isCorrect":false},{"id":"4","content":"Một đơn vị đo lưu lượng trao đổi thông tin giữa CPU và các bộ nhớ trong","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',23,'2026-01-30 18:20:21','Byte là đơn vị cơ bản nhỏ nhất thường dùng để biểu diễn dung lượng lưu trữ dữ liệu.');
INSERT INTO "vstep_questions" VALUES(1829,NULL,44,'Không phải thiết bị xuất là:','MULTIPLE_CHOICE','[{"id":"1","content":"Màn hình","isCorrect":false},{"id":"2","content":"Chuột","isCorrect":true},{"id":"3","content":"Máy in","isCorrect":false},{"id":"4","content":"Loa","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',24,'2026-01-30 18:20:21','Chuột là thiết bị nhập (Input), các thiết bị còn lại (Màn hình, Máy in, Loa) là thiết bị xuất.');
INSERT INTO "vstep_questions" VALUES(1830,NULL,44,'Khác nhau cơ bản giữa ROM và RAM:','MULTIPLE_CHOICE','[{"id":"1","content":"ROM không ghi được","isCorrect":false},{"id":"2","content":"ROM không mất dữ liệu, RAM mất khi mất điện","isCorrect":true},{"id":"3","content":"RAM chỉ đọc","isCorrect":false},{"id":"4","content":"RAM không mất dữ liệu","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',25,'2026-01-30 18:20:21','Khác biệt cơ bản: ROM không mất dữ liệu khi mất điện, RAM thì có.');
INSERT INTO "vstep_questions" VALUES(1831,NULL,44,'Cho số nhị phân 1001, số thập phân tương đương là:','MULTIPLE_CHOICE','[{"id":"1","content":"11","isCorrect":false},{"id":"2","content":"9","isCorrect":true},{"id":"3","content":"10","isCorrect":false},{"id":"4","content":"8","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',26,'2026-01-30 18:20:21','Số nhị phân 1001 chuyển sang thập phân: (1x8) + (0x4) + (0x2) + (1x1) = 9.');
INSERT INTO "vstep_questions" VALUES(1832,NULL,44,'Điều đúng về username là:','MULTIPLE_CHOICE','[{"id":"1","content":"Trùng nhau được","isCorrect":false},{"id":"2","content":"Càng phức tạp càng tốt","isCorrect":false},{"id":"3","content":"Không chứa ký tự đặc biệt ?, .","isCorrect":true},{"id":"4","content":"Phải giống họ tên","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',27,'2026-01-30 18:20:21','Username (Tên đăng nhập) thường không được chứa các ký tự đặc biệt như dấu ?, dấu phẩy.');
INSERT INTO "vstep_questions" VALUES(1833,NULL,44,'Trình duyệt của Microsoft là:','MULTIPLE_CHOICE','[{"id":"1","content":"Yahoo Messenger","isCorrect":false},{"id":"2","content":"Chrome","isCorrect":false},{"id":"3","content":"Internet Explorer","isCorrect":true},{"id":"4","content":"Cốc Cốc","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',28,'2026-01-30 18:20:21','Internet Explorer (IE) là trình duyệt web do Microsoft phát triển.');
INSERT INTO "vstep_questions" VALUES(1834,NULL,44,'Cổng cắm mạng LAN là:','MULTIPLE_CHOICE','[{"id":"1","content":"USB","isCorrect":false},{"id":"2","content":"Jack 3.5","isCorrect":false},{"id":"3","content":"RJ45","isCorrect":true},{"id":"4","content":"RJ11","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',29,'2026-01-30 18:20:21','Cổng RJ45 là chuẩn cổng kết nối dùng cho cáp mạng LAN.');
INSERT INTO "vstep_questions" VALUES(1835,NULL,44,'ROM là viết tắt của từ gì?','MULTIPLE_CHOICE','[{"id":"1","content":"Read One Memory","isCorrect":false},{"id":"2","content":"Random One Memory","isCorrect":false},{"id":"3","content":"Random Only Memory","isCorrect":false},{"id":"4","content":"Read Only Memory","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',30,'2026-01-30 18:20:21','ROM là viết tắt của Read Only Memory (Bộ nhớ chỉ đọc).');
INSERT INTO "vstep_questions" VALUES(1836,NULL,44,'GB là viết tắt của:','MULTIPLE_CHOICE','[{"id":"1","content":"Megabyte","isCorrect":false},{"id":"2","content":"Gigabyte","isCorrect":true},{"id":"3","content":"Gigabit","isCorrect":false},{"id":"4","content":"Megabit","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',31,'2026-01-30 18:20:21','GB là viết tắt của Gigabyte, đơn vị đo dung lượng bộ nhớ.');
INSERT INTO "vstep_questions" VALUES(1837,NULL,44,'Tài khoản nào dưới đây được coi là bảo mật tốt?','MULTIPLE_CHOICE','[{"id":"1","content":"username: abncahsa1245@ – password: ancasdhjsadasdsfhakh","isCorrect":false},{"id":"2","content":"username: abcdef – password: 01678456213233","isCorrect":false},{"id":"3","content":"username: contest – password: Pa@w123456wo5vrsd","isCorrect":true},{"id":"4","content":"username: username – password: password","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',32,'2026-01-30 18:20:21','Mật khẩu mạnh cần có độ dài đủ lớn, bao gồm chữ hoa, chữ thường, số và ký tự đặc biệt.');
INSERT INTO "vstep_questions" VALUES(1838,NULL,44,'Phần mềm lưu trong ROM gọi là:','MULTIPLE_CHOICE','[{"id":"1","content":"Malware","isCorrect":false},{"id":"2","content":"Spyware","isCorrect":false},{"id":"3","content":"PnP","isCorrect":false},{"id":"4","content":"Firmware","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',33,'2026-01-30 18:20:21','Firmware là phần mềm điều khiển hệ thống cấp thấp được lưu trong ROM.');
INSERT INTO "vstep_questions" VALUES(1839,NULL,44,'Số thập phân 10 đổi sang nhị phân là:','MULTIPLE_CHOICE','[{"id":"1","content":"1100","isCorrect":false},{"id":"2","content":"1000","isCorrect":false},{"id":"3","content":"1010","isCorrect":true},{"id":"4","content":"1111","isCorrect":false}]','3',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',34,'2026-01-30 18:20:21','Số thập phân 10 chuyển sang nhị phân là 1010 (8 + 2 = 10).');
INSERT INTO "vstep_questions" VALUES(1840,NULL,44,'Thiết bị mất dữ liệu khi mất điện:','MULTIPLE_CHOICE','[{"id":"1","content":"HDD","isCorrect":false},{"id":"2","content":"RAM","isCorrect":true},{"id":"3","content":"ROM","isCorrect":false},{"id":"4","content":"SSD","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',35,'2026-01-30 18:20:21','Thiết bị mất dữ liệu khi mất điện là RAM (Bộ nhớ truy cập ngẫu nhiên).');
INSERT INTO "vstep_questions" VALUES(1841,NULL,44,'Bản quyền phần mềm là:','MULTIPLE_CHOICE','[{"id":"1","content":"Quyền dùng mọi phần mềm","isCorrect":false},{"id":"2","content":"Quyền của tác giả","isCorrect":true},{"id":"3","content":"Dùng không kinh doanh","isCorrect":false},{"id":"4","content":"Tất cả sai","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',36,'2026-01-30 18:20:21','Bản quyền phần mềm là quyền pháp lý của tác giả đối với sản phẩm phần mềm họ tạo ra.');
INSERT INTO "vstep_questions" VALUES(1842,NULL,44,'Ví dụ mật khẩu tốt là:','MULTIPLE_CHOICE','[{"id":"1","content":"Chỉ chữ hoặc số","isCorrect":false},{"id":"2","content":">7 ký tự gồm chữ hoa, số, ký tự đặc biệt","isCorrect":true},{"id":"3","content":"<6 ký tự","isCorrect":false},{"id":"4","content":"Ngày sinh","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',37,'2026-01-30 18:20:21','Mật khẩu tốt nên dài trên 7 ký tự và kết hợp nhiều loại ký tự (hoa, thường, số, đặc biệt).');
INSERT INTO "vstep_questions" VALUES(1843,NULL,44,'Thiết bị không phải thiết bị nhập là:','MULTIPLE_CHOICE','[{"id":"1","content":"USB","isCorrect":true},{"id":"2","content":"Bàn phím","isCorrect":false},{"id":"3","content":"Máy quét","isCorrect":false},{"id":"4","content":"Chuột","isCorrect":false}]','1',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',38,'2026-01-30 18:20:22','USB là thiết bị lưu trữ/kết nối, không phải thiết bị nhập liệu trực tiếp như Bàn phím, Chuột.');
INSERT INTO "vstep_questions" VALUES(1844,NULL,44,'Chức năng chính của CPU là:','MULTIPLE_CHOICE','[{"id":"1","content":"Nhập","isCorrect":false},{"id":"2","content":"Lưu trữ","isCorrect":false},{"id":"3","content":"Xuất","isCorrect":false},{"id":"4","content":"Xử lý","isCorrect":true}]','4',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',39,'2026-01-30 18:20:22','Chức năng chính của CPU là xử lý dữ liệu và điều khiển hoạt động của máy tính.');
INSERT INTO "vstep_questions" VALUES(1845,NULL,44,'Dịch vụ SMS là gì?','MULTIPLE_CHOICE','[{"id":"1","content":"Gửi email","isCorrect":false},{"id":"2","content":"Giao thức gửi tin nhắn tối đa 160 ký tự ASCII","isCorrect":true},{"id":"3","content":"Gửi chuỗi <5000 ký tự","isCorrect":false},{"id":"4","content":"Gửi tin nhắn bằng máy tính","isCorrect":false}]','2',1,'{"originalType":"multiple_choice","audio_url":null,"passage":null}',40,'2026-01-30 18:20:22','Dịch vụ SMS (Short Message Service) là dịch vụ gửi tin nhắn văn bản ngắn.');
INSERT INTO "vstep_questions" VALUES(1846,44,45,'How many Chinese men start to smoke before the age of 20?','MULTIPLE_CHOICE','[{"id":"A","content":"one-third","isCorrect":false},{"id":"B","content":"two-thirds","isCorrect":true},{"id":"C","content":"half","isCorrect":false},{"id":"D","content":"all of them","isCorrect":false}]','B',0.25,NULL,1,'2026-01-30 18:52:21','Bài đọc nêu: "two-thirds of men in China now start to smoke before 20" (2/3 nam giới bắt đầu hút trước 20 tuổi).');
INSERT INTO "vstep_questions" VALUES(1847,44,45,'What does the word “those men” in paragraph 2 refer to?','MULTIPLE_CHOICE','[{"id":"A","content":"Men who smoke under the age of 20","isCorrect":true},{"id":"B","content":"Men who smoke above the age of 20","isCorrect":false},{"id":"C","content":"Men who give up smoking","isCorrect":false},{"id":"D","content":"Men who smoke in public","isCorrect":false}]','A',0.25,NULL,2,'2026-01-30 18:52:21','"Around half of those men" tham chiếu ngược lại cụm "men in China now start to smoke before 20".');
INSERT INTO "vstep_questions" VALUES(1848,44,45,'By 2030, how many men in China may die from smoking every year?','MULTIPLE_CHOICE','[{"id":"A","content":"one million","isCorrect":false},{"id":"B","content":"two million","isCorrect":true},{"id":"C","content":"three million","isCorrect":false},{"id":"D","content":"four million","isCorrect":false}]','B',0.25,NULL,3,'2026-01-30 18:52:21','Bài đọc nêu: "double to two million... by 2030" (tăng gấp đôi lên 2 triệu vào năm 2030).');
INSERT INTO "vstep_questions" VALUES(1849,44,45,'In many areas of China, when do men usually smoke?','MULTIPLE_CHOICE','[{"id":"A","content":"Before a meal","isCorrect":false},{"id":"B","content":"After a meal","isCorrect":true},{"id":"C","content":"Before they go to sleep","isCorrect":false},{"id":"D","content":"When they get up","isCorrect":false}]','B',0.25,NULL,4,'2026-01-30 18:52:21','"After putting down their chopsticks..." (Sau khi đặt đũa xuống = sau bữa ăn).');
INSERT INTO "vstep_questions" VALUES(1850,44,45,'According to WHO, only... of Chinese adults can list bad effects of smoking.','MULTIPLE_CHOICE','[{"id":"A","content":"one-third","isCorrect":false},{"id":"B","content":"one-fourth","isCorrect":true},{"id":"C","content":"one-fifth","isCorrect":false},{"id":"D","content":"a half","isCorrect":false}]','B',0.25,NULL,5,'2026-01-30 18:52:21','Bài đọc nêu "only 25%", tương đương với "one-fourth" (1/4).');
INSERT INTO "vstep_questions" VALUES(1851,44,45,'“Beijing” refers to ...','MULTIPLE_CHOICE','[{"id":"A","content":"China","isCorrect":false},{"id":"B","content":"The city of Beijing","isCorrect":false},{"id":"C","content":"The Chinese government","isCorrect":true},{"id":"D","content":"People who live in Beijing","isCorrect":false}]','C',0.25,NULL,6,'2026-01-30 18:52:21','Trong ngữ cảnh "Authorities have shown concern... with Beijing even introducing...", "Beijing" được dùng theo phép hoán dụ chỉ chính quyền/chính phủ Trung Quốc.');
INSERT INTO "vstep_questions" VALUES(1852,44,45,'What is Richard Peto’s attitude toward smoking in China?','MULTIPLE_CHOICE','[{"id":"A","content":"He doesn’t believe that people will give up smoking","isCorrect":false},{"id":"B","content":"He is disappointed with the Chinese government.","isCorrect":false},{"id":"C","content":"He thinks that people possibly stop smoking if they see reasons.","isCorrect":true},{"id":"D","content":"He is sure about the rise of future deaths in China.","isCorrect":false}]','C',0.25,NULL,7,'2026-01-30 18:52:21','Ông nói: "there was hope - if people can be persuaded to quit" (có hy vọng nếu mọi người được thuyết phục bỏ thuốc).');
INSERT INTO "vstep_questions" VALUES(1853,44,45,'Which of the following words does the word “hamper” have closest meaning to?','MULTIPLE_CHOICE','[{"id":"A","content":"basket","isCorrect":false},{"id":"B","content":"assist","isCorrect":false},{"id":"C","content":"prohibit","isCorrect":false},{"id":"D","content":"restrict","isCorrect":true}]','D',0.25,NULL,8,'2026-01-30 18:52:21','"Hamper" nghĩa là cản trở, làm khó khăn ~ "restrict" (hạn chế).');
INSERT INTO "vstep_questions" VALUES(1854,44,45,'What is the writer''s purpose?','MULTIPLE_CHOICE','[{"id":"A","content":"To argue over smoking policy in China","isCorrect":false},{"id":"B","content":"To support smoking in China","isCorrect":false},{"id":"C","content":"To warn and prevent smoking in China","isCorrect":true},{"id":"D","content":"To report the result of a research paper","isCorrect":false}]','C',0.25,NULL,9,'2026-01-30 18:52:21','Bài viết đưa ra số liệu tử vong và lời khuyên bỏ thuốc để cảnh báo và ngăn chặn.');
INSERT INTO "vstep_questions" VALUES(1855,44,45,'What does the writer imply about Chinese government?','MULTIPLE_CHOICE','[{"id":"A","content":"They do not want to stop people from smoking.","isCorrect":false},{"id":"B","content":"They have tried to stop people from smoking in public but with little success.","isCorrect":true},{"id":"C","content":"They have tried to close tobacco companies.","isCorrect":false},{"id":"D","content":"They do not care about smoking.","isCorrect":false}]','B',0.25,NULL,10,'2026-01-30 18:52:21','Chính quyền đã ban hành lệnh cấm nhưng "efforts have been hampered" (nỗ lực bị cản trở/kìm hãm) => Ít thành công.');
INSERT INTO "vstep_questions" VALUES(1856,45,45,'The word “we” in paragraph 2 refers to ...','MULTIPLE_CHOICE','[{"id":"A","content":"humans","isCorrect":true},{"id":"B","content":"economists, sociologists, and politicians","isCorrect":false},{"id":"C","content":"animals","isCorrect":false},{"id":"D","content":"scientists","isCorrect":false}]','A',0.25,NULL,11,'2026-01-30 18:52:21','"Even if we stopped emitting..." ám chỉ con người nói chung (humanity).');
INSERT INTO "vstep_questions" VALUES(1857,45,45,'According to paragraph 2, how many degrees could the Earth warm up?','MULTIPLE_CHOICE','[{"id":"A","content":"25","isCorrect":false},{"id":"B","content":"2.5 or 10","isCorrect":false},{"id":"C","content":"10","isCorrect":false},{"id":"D","content":"from 2.5 to 10","isCorrect":true}]','D',0.25,NULL,12,'2026-01-30 18:52:21','Bài đọc nêu khoảng dự đoán: "as little as 2.5 degrees or as much as 10 degrees".');
INSERT INTO "vstep_questions" VALUES(1858,45,45,'According to paragraph 3, why should we stabilize GHG concentrations around 450-550 parts per million?','MULTIPLE_CHOICE','[{"id":"A","content":"to avoid the most serious effects of climate change","isCorrect":true},{"id":"B","content":"to avoid all damaging impacts of climate change","isCorrect":false},{"id":"C","content":"to mend the most damaging impacts of climate change","isCorrect":false},{"id":"D","content":"to stop climate change","isCorrect":false}]','A',0.25,NULL,13,'2026-01-30 18:52:21','Đây là điểm mà "most damaging impacts... can be avoided" (tránh được những tác động tàn phá nhất).');
INSERT INTO "vstep_questions" VALUES(1859,45,45,'What does “which” in paragraph 3 refer to?','MULTIPLE_CHOICE','[{"id":"A","content":"current concentrations","isCorrect":false},{"id":"B","content":"that current concentrations are about 380 ppm","isCorrect":false},{"id":"C","content":"380 ppm","isCorrect":true},{"id":"D","content":"ppm","isCorrect":false}]','C',0.25,NULL,14,'2026-01-30 18:52:21','"Current concentrations are about 380 ppm, which means..." -> "which" thay thế cho con số 380 ppm ngay trước đó.');
INSERT INTO "vstep_questions" VALUES(1860,45,45,'Why does the author mention Stephen Pacala and Robert Socolow?','MULTIPLE_CHOICE','[{"id":"A","content":"To introduce two researchers in the field","isCorrect":false},{"id":"B","content":"To proves that researchers are working to reduce GHG emission","isCorrect":false},{"id":"C","content":"To introduce one way to reduce GHG emission","isCorrect":true},{"id":"D","content":"To introduce Princeton University","isCorrect":false}]','C',0.25,NULL,15,'2026-01-30 18:52:21','Nhắc đến họ để giới thiệu phương pháp "stabilization wedges" (một cách giảm khí thải).');
INSERT INTO "vstep_questions" VALUES(1861,45,45,'What stabilization wedges are NOT mentioned in the passage?','MULTIPLE_CHOICE','[{"id":"A","content":"create environment-friendly materials","isCorrect":true},{"id":"B","content":"capture and store carbon dioxide underground","isCorrect":false},{"id":"C","content":"increase the use of renewable energy","isCorrect":false},{"id":"D","content":"grow more trees","isCorrect":false}]','A',0.25,NULL,16,'2026-01-30 18:52:21','Bài đọc liệt kê: efficiency, wind, solar, hydrogen, biofuels, natural gas, nuclear, forests. Không có "environment-friendly materials".');
INSERT INTO "vstep_questions" VALUES(1862,45,45,'What does “them” refer to?','MULTIPLE_CHOICE','[{"id":"A","content":"researchers","isCorrect":false},{"id":"B","content":"humans","isCorrect":false},{"id":"C","content":"renewable resources","isCorrect":false},{"id":"D","content":"wedges","isCorrect":true}]','D',0.25,NULL,17,'2026-01-30 18:52:22','"...7 wedges... all of them together..." -> them = wedges.');
INSERT INTO "vstep_questions" VALUES(1863,45,45,'What is the best title for this passage?','MULTIPLE_CHOICE','[{"id":"A","content":"Arguments over Global Warming","isCorrect":false},{"id":"B","content":"Global Warming and its Causes","isCorrect":false},{"id":"C","content":"Global Warming Solutions","isCorrect":true},{"id":"D","content":"Global Warming''s Effect on Earth","isCorrect":false}]','C',0.25,NULL,18,'2026-01-30 18:52:22','Bài viết tập trung vào các giải pháp (wedges, technologies) để giải quyết vấn đề.');
INSERT INTO "vstep_questions" VALUES(1864,45,45,'“Sequestering” has closest meaning to ...','MULTIPLE_CHOICE','[{"id":"A","content":"absorb","isCorrect":true},{"id":"B","content":"isolate","isCorrect":false},{"id":"C","content":"release","isCorrect":false},{"id":"D","content":"emit","isCorrect":false}]','A',0.25,NULL,19,'2026-01-30 18:52:22','Trong ngữ cảnh "Plants... absorb CO2... sequestering carbon", nó nghĩa là hấp thụ/lưu trữ.');
INSERT INTO "vstep_questions" VALUES(1865,45,45,'Why does the writer mention “drawbacks” in the last paragraph?','MULTIPLE_CHOICE','[{"id":"A","content":"To introduce the disadvantages of solutions in the following paragraph","isCorrect":false},{"id":"B","content":"To emphasize the disadvantages of the solutions in the previous paragraph","isCorrect":false},{"id":"C","content":"To recommend readers not to use the solutions","isCorrect":false},{"id":"D","content":"To emphasize the advantages of the solutions in different contexts","isCorrect":true}]','D',0.25,NULL,20,'2026-01-30 18:52:22','Tác giả thừa nhận nhược điểm nhưng kết luận "good news is that there are a variety of options" -> Nhấn mạnh sự đa dạng giải pháp cho các bối cảnh khác nhau.');
INSERT INTO "vstep_questions" VALUES(1866,46,45,'According to paragraph 2, the process of visual perception ...','MULTIPLE_CHOICE','[{"id":"A","content":"is not the same for all people","isCorrect":false},{"id":"B","content":"begins with patterns of light","isCorrect":true},{"id":"C","content":"is not very scientific","isCorrect":false},{"id":"D","content":"requires other senses to function","isCorrect":false}]','B',0.25,NULL,21,'2026-01-30 18:52:22','"In visual perception our eyes take in information in the form of light patterns" (bắt đầu bằng các mô hình ánh sáng).');
INSERT INTO "vstep_questions" VALUES(1867,46,45,'What did Matisse reinterpret?','MULTIPLE_CHOICE','[{"id":"A","content":"A goddess from mythology","isCorrect":false},{"id":"B","content":"A painting by another artist","isCorrect":false},{"id":"C","content":"An ancient sculpture","isCorrect":true},{"id":"D","content":"A man in history","isCorrect":false}]','C',0.25,NULL,22,'2026-01-30 18:52:22','Matisse mong khán giả biết đến "Venus de Milo", đó là một bức tượng điêu khắc cổ Hy Lạp (Greek statue).');
INSERT INTO "vstep_questions" VALUES(1868,46,45,'The word “them” in the last paragraph refers to ...','MULTIPLE_CHOICE','[{"id":"A","content":"each attentive observer","isCorrect":false},{"id":"B","content":"thoughts and emotions","isCorrect":false},{"id":"C","content":"a lifetime of experiences","isCorrect":false},{"id":"D","content":"great works of art","isCorrect":true}]','D',0.25,NULL,23,'2026-01-30 18:52:22','"The greatest of them" tham chiếu ngược lại danh từ số nhiều trước đó là "Great works of art".');
INSERT INTO "vstep_questions" VALUES(1869,46,45,'The word “bequeath” in the passage is closest in Meaning to...','MULTIPLE_CHOICE','[{"id":"A","content":"make out","isCorrect":false},{"id":"B","content":"pass on","isCorrect":true},{"id":"C","content":"look over","isCorrect":false},{"id":"D","content":"take in","isCorrect":false}]','B',0.25,NULL,24,'2026-01-30 18:52:22','"Bequeath" nghĩa là để lại, truyền lại ~ "pass on".');
INSERT INTO "vstep_questions" VALUES(1870,46,45,'The author mentions all of the following ways to enhance the appreciation of art EXCEPT ...','MULTIPLE_CHOICE','[{"id":"A","content":"understanding the artistic process","isCorrect":false},{"id":"B","content":"becoming familiar with the history","isCorrect":false},{"id":"C","content":"experiencing the art by copying","isCorrect":true},{"id":"D","content":"knowing about the life of the artist","isCorrect":false}]','C',0.25,NULL,25,'2026-01-30 18:52:22','Bài đọc nhắc đến: process (cách làm), history (lịch sử), artist''s intent (ý định). Không nhắc đến việc "copying" (chép tranh).');
INSERT INTO "vstep_questions" VALUES(1871,46,45,'What is the main topic of this passage?','MULTIPLE_CHOICE','[{"id":"A","content":"Visual perception of sensory material","isCorrect":false},{"id":"B","content":"The historical context for artistic expression","isCorrect":false},{"id":"C","content":"Studying Van Gogh''s The Starry Night","isCorrect":false},{"id":"D","content":"The appreciation of works of art","isCorrect":true}]','D',0.25,NULL,26,'2026-01-30 18:52:22','Toàn bộ bài nói về cách chúng ta nhìn, hiểu và thưởng thức nghệ thuật (appreciation).');
INSERT INTO "vstep_questions" VALUES(1872,46,45,'Which of the sentences below best expresses the information in the highlighted statement in the passage?','MULTIPLE_CHOICE','[{"id":"A","content":"We see images differently because of the mode of perception.","isCorrect":false},{"id":"B","content":"Although we see images differently, the mode of perception is similar.","isCorrect":true},{"id":"C","content":"Since the mode of perception is similar, we see images in the same way.","isCorrect":false},{"id":"D","content":"When the mode of perception is the same, we see the same images","isCorrect":false}]','B',0.25,NULL,27,'2026-01-30 18:52:22','"The mechanics of perception work much the same way for everyone, yet... we do not all see the same things." (Cơ chế giống nhau nhưng nhìn thấy khác nhau).');
INSERT INTO "vstep_questions" VALUES(1873,46,45,'Why might Van Gogh have painted The Starry Night?','MULTIPLE_CHOICE','[{"id":"A","content":"To symbolize the journey of life after death","isCorrect":true},{"id":"B","content":"To create a dramatic contrast with the sky","isCorrect":false},{"id":"C","content":"To place a strong image in the foreground","isCorrect":false},{"id":"D","content":"To include nature from his early experience","isCorrect":false}]','A',0.25,NULL,28,'2026-01-30 18:52:22','Van Gogh tin rằng con người đi đến một vì sao sau khi chết ("people journeyed to a star after their death").');
INSERT INTO "vstep_questions" VALUES(1874,46,45,'The word “intrigued” in the passage is closest in meaning to...','MULTIPLE_CHOICE','[{"id":"A","content":"very pleased","isCorrect":false},{"id":"B","content":"very confused","isCorrect":false},{"id":"C","content":"very interested","isCorrect":true},{"id":"D","content":"very surprised","isCorrect":false}]','C',0.25,NULL,29,'2026-01-30 18:52:22','"Intrigued" nghĩa là bị lôi cuốn, tò mò ~ "very interested".');
INSERT INTO "vstep_questions" VALUES(1875,46,45,'What can be inferred from the last paragraph?','MULTIPLE_CHOICE','[{"id":"A","content":"Greatest artworks are impossible to understand.","isCorrect":false},{"id":"B","content":"The author shows negative feelings toward contemporary art.","isCorrect":false},{"id":"C","content":"People need knowledge to understand art.","isCorrect":false},{"id":"D","content":"What we see in art is determined by our emotions, experiences, and thoughts.","isCorrect":true}]','D',0.25,NULL,30,'2026-01-30 18:52:22','Đoạn cuối nói ý nghĩa tác phẩm phụ thuộc vào "your own experiences, thoughts, and emotions".');
INSERT INTO "vstep_questions" VALUES(1876,47,45,'How do antibiotics treat infections?','MULTIPLE_CHOICE','[{"id":"A","content":"They interfere with the reproductive cycle of bacteria.","isCorrect":true},{"id":"B","content":"They construct cell walls to resist bacteria.","isCorrect":false},{"id":"C","content":"They inject enzymes that explode in affected cells.","isCorrect":false},{"id":"D","content":"They increase the mitosis of healthy cells","isCorrect":false}]','A',0.25,NULL,31,'2026-01-30 18:52:22','Thuốc chặn các phân tử xây thành tế bào, khiến vi khuẩn "not able to reproduce" (không thể sinh sản).');
INSERT INTO "vstep_questions" VALUES(1877,47,45,'The word “them” in paragraph 4 refers to ...','MULTIPLE_CHOICE','[{"id":"A","content":"whatever properties","isCorrect":false},{"id":"B","content":"resistant bacteria","isCorrect":true},{"id":"C","content":"their competition","isCorrect":false},{"id":"D","content":"those individuals","isCorrect":false}]','B',0.25,NULL,32,'2026-01-30 18:52:22','"It doesn''t affect them" -> Thuốc không ảnh hưởng đến nhóm vi khuẩn kháng thuốc (resistant bacteria).');
INSERT INTO "vstep_questions" VALUES(1878,47,45,'The word “anticipated” in the passage is closest in meaning to ...','MULTIPLE_CHOICE','[{"id":"A","content":"predicted","isCorrect":true},{"id":"B","content":"concealed","isCorrect":false},{"id":"C","content":"investigated","isCorrect":false},{"id":"D","content":"disregarded","isCorrect":false}]','A',0.25,NULL,33,'2026-01-30 18:52:22','"Anticipated" nghĩa là được dự liệu trước ~ "predicted".');
INSERT INTO "vstep_questions" VALUES(1879,47,45,'Which of the following best expresses the main idea of this passage?','MULTIPLE_CHOICE','[{"id":"A","content":"The \"miracle drug\" penicillin","isCorrect":false},{"id":"B","content":"Drug-resistant bacteria","isCorrect":true},{"id":"C","content":"Staphylococcus infections","isCorrect":false},{"id":"D","content":"Gene therapy treatments","isCorrect":false}]','B',0.25,NULL,34,'2026-01-30 18:52:22','Bài viết bàn về sự xuất hiện và vấn đề của vi khuẩn kháng thuốc (Drug-resistant bacteria).');
INSERT INTO "vstep_questions" VALUES(1880,47,45,'According to paragraph 4, why do some bacteria benefit from antibiotics?','MULTIPLE_CHOICE','[{"id":"A","content":"The antibiotic eliminates competing bacteria, allowing resistant bacteria to reproduce.","isCorrect":true},{"id":"B","content":"The resistant bacteria compete with the antibiotic, and the bacteria become stronger.","isCorrect":false},{"id":"C","content":"The competition helps the resistant bacteria to multiply by reproducing with the resistant type.","isCorrect":false},{"id":"D","content":"The properties of the antibiotic are acquired by the bacteria, making it resistant to the competition.","isCorrect":false}]','A',0.25,NULL,35,'2026-01-30 18:52:22','Thuốc tiêu diệt các vi khuẩn cạnh tranh ("wipe out all of their competition"), giúp vi khuẩn kháng thuốc tự do sinh sôi.');
INSERT INTO "vstep_questions" VALUES(1881,47,45,'The word “complacency” in the passage is closest in meaning to ...','MULTIPLE_CHOICE','[{"id":"A","content":"consensus of agreement","isCorrect":false},{"id":"B","content":"fear of consequences","isCorrect":false},{"id":"C","content":"lack of concern","isCorrect":true},{"id":"D","content":"awareness of potential","isCorrect":false}]','C',0.25,NULL,36,'2026-01-30 18:52:22','"Complacency" là sự tự mãn, chủ quan ~ "lack of concern" (thiếu lo lắng/quan tâm).');
INSERT INTO "vstep_questions" VALUES(1882,47,45,'Which of the sentences below best expresses the information in the highlighted statement in the passage?','MULTIPLE_CHOICE','[{"id":"A","content":"Some antibiotics affect a population of bacteria more efficiently than others.","isCorrect":false},{"id":"B","content":"There are several reasons why some bacteria do not respond to most antibiotics.","isCorrect":false},{"id":"C","content":"The effect of antibiotics on bacteria is to bind them together into one population.","isCorrect":false},{"id":"D","content":"A small number of bacteria in any sample will probably be resistant to a specific antibiotic.","isCorrect":true}]','D',0.25,NULL,37,'2026-01-30 18:52:22','Câu gốc: "in any bacterial population, there are bound to be a few bacteria... not affected". (Luôn có một số ít vi khuẩn không bị ảnh hưởng).');
INSERT INTO "vstep_questions" VALUES(1883,47,45,'The author mentions all of the following reasons for drug resistant bacteria to appear EXCEPT...','MULTIPLE_CHOICE','[{"id":"A","content":"there was not enough profit incentive for companies to continue developing new antibiotics","isCorrect":false},{"id":"B","content":"statistically, some drug-resistant bacteria will occur naturally in any large population of bacteria","isCorrect":false},{"id":"C","content":"the newer antibiotics were not as strong and effective as the original penicillin-based drugs","isCorrect":true},{"id":"D","content":"competing bacteria are destroyed by antibiotics, allowing resistant bacteria to prosper.","isCorrect":false}]','C',0.25,NULL,38,'2026-01-30 18:52:23','Bài viết nói về lợi nhuận thấp (A), xác suất thống kê (B), sự cạnh tranh sinh học (D). Không nói thuốc mới yếu hơn thuốc cũ (C).');
INSERT INTO "vstep_questions" VALUES(1884,47,45,'It can be inferred from the passage that ...','MULTIPLE_CHOICE','[{"id":"A","content":"research to develop new antibiotics will not be necessary in the future","isCorrect":false},{"id":"B","content":"the scientific community was not surprised by the resistant strains of bacteria","isCorrect":false},{"id":"C","content":"antibiotics are not very expensive when they are made available commercially","isCorrect":false},{"id":"D","content":"it takes years for a new drug to be made available commercially for consumers","isCorrect":true}]','D',0.25,NULL,39,'2026-01-30 18:52:23','Bài viết mô tả quy trình từ thử nghiệm lâm sàng (1990s) đến khi ra thị trường (đầu TK21) mất nhiều năm.');
INSERT INTO "vstep_questions" VALUES(1885,47,45,'Which of the following statements is NOT a main idea of the passage?','MULTIPLE_CHOICE','[{"id":"A","content":"Many strains of bacteria have become resistant to the antibiotics currently available.","isCorrect":false},{"id":"B","content":"Funding for the production of new antibiotics has been allocated to drug companies.","isCorrect":true},{"id":"C","content":"The first antibiotics were very effective in blocking the reproduction of bacteria.","isCorrect":false},{"id":"D","content":"New antibiotics are being developed to combat bacteria that resist the older antibiotics.","isCorrect":false}]','B',0.25,NULL,40,'2026-01-30 18:52:23','Các ý A, C, D là trọng tâm. Ý B (Cấp vốn cụ thể) không phải ý chính, bài chỉ nói các công ty quay lại nghiên cứu vì vấn đề được báo động.');
INSERT INTO "vstep_questions" VALUES(1886,48,46,'How old was Dang Thi Nhan when she first started to bake cakes or prepare tea for the two doctors?','MULTIPLE_CHOICE','[{"id":"A","content":"20","isCorrect":false},{"id":"B","content":"67","isCorrect":false},{"id":"C","content":"43","isCorrect":false},{"id":"D","content":"47","isCorrect":true}]','D',0.25,NULL,1,'2026-01-30 18:53:24','Hiện bà Nhan 67 tuổi, đã làm việc này 20 năm ("For 20 years... Nhan, 67"). Vậy bà bắt đầu lúc 67 - 20 = 47 tuổi.');
INSERT INTO "vstep_questions" VALUES(1887,48,46,'The word "they" in paragraph 1 refers to..............','MULTIPLE_CHOICE','[{"id":"A","content":"two doctors","isCorrect":true},{"id":"B","content":"husband and son","isCorrect":false},{"id":"C","content":"health checks","isCorrect":false},{"id":"D","content":"cakes","isCorrect":false}]','A',0.25,NULL,2,'2026-01-30 18:53:24','"If one day they cannot take care of themselves..." refers to "two retired doctors".');
INSERT INTO "vstep_questions" VALUES(1888,48,46,'The word "late" in paragraph 2 is closest in meaning to..................','MULTIPLE_CHOICE','[{"id":"A","content":"last-minute","isCorrect":false},{"id":"B","content":"behind","isCorrect":false},{"id":"C","content":"delayed","isCorrect":false},{"id":"D","content":"deceased","isCorrect":true}]','D',0.25,NULL,3,'2026-01-30 18:53:24','"Late deputy director... who died last year" -> "Late" ở đây nghĩa là người đã khuất (deceased).');
INSERT INTO "vstep_questions" VALUES(1889,48,46,'The word "its" in paragraph 3 refers to................','MULTIPLE_CHOICE','[{"id":"A","content":"Red Cross Association","isCorrect":false},{"id":"B","content":"the clinic","isCorrect":true},{"id":"C","content":"medicine","isCorrect":false},{"id":"D","content":"pension","isCorrect":false}]','B',0.25,NULL,4,'2026-01-30 18:53:24','"On its first days..." nghĩa là những ngày đầu của phòng khám (the clinic).');
INSERT INTO "vstep_questions" VALUES(1890,48,46,'Who probably did not work in a hospital before retirement?','MULTIPLE_CHOICE','[{"id":"A","content":"Le Thi Soc","isCorrect":false},{"id":"B","content":"Le Thanh Thuoc","isCorrect":false},{"id":"C","content":"Truong Thi Hoi To","isCorrect":true},{"id":"D","content":"All of them","isCorrect":false}]','C',0.25,NULL,5,'2026-01-30 18:53:25','Bà To là "former principal of Nam Dinh Medical College" (Hiệu trưởng trường Y), không phải bác sĩ bệnh viện như 2 người kia.');
INSERT INTO "vstep_questions" VALUES(1891,48,46,'In which lines does the author mention about the bad health condition of the doctors at the clinic.....','MULTIPLE_CHOICE','[{"id":"A","content":"line 5","isCorrect":false},{"id":"B","content":"line 13","isCorrect":true},{"id":"C","content":"line 23","isCorrect":false},{"id":"D","content":"line 28","isCorrect":false}]','B',0.25,NULL,6,'2026-01-30 18:53:25','Line 12-13: "due to the deteriorating health of the two other medics".');
INSERT INTO "vstep_questions" VALUES(1892,48,46,'The word "donate" in paragraph 3 could be best replaced by...............','MULTIPLE_CHOICE','[{"id":"A","content":"give","isCorrect":true},{"id":"B","content":"take","isCorrect":false},{"id":"C","content":"keep","isCorrect":false},{"id":"D","content":"get","isCorrect":false}]','A',0.25,NULL,7,'2026-01-30 18:53:25','"Donate money" = quyên góp tiền ~ "give".');
INSERT INTO "vstep_questions" VALUES(1893,48,46,'What has helped Mrs. Tran Thi Toan gain confidence in her life?','MULTIPLE_CHOICE','[{"id":"A","content":"her job as a servant","isCorrect":false},{"id":"B","content":"her gratitude to all doctors","isCorrect":false},{"id":"C","content":"her healthy and happy lifestyle","isCorrect":false},{"id":"D","content":"doctors'' caring manner and free treatment at clinic","isCorrect":true}]','D',0.25,NULL,8,'2026-01-30 18:53:25','Bài viết: "doctors'' care and compassionate attitude have become her inspiration in life".');
INSERT INTO "vstep_questions" VALUES(1894,48,46,'In which space (marked A, B, C and D in the passage) will the following sentence fit? "They treat me as a close member of their family..."','MULTIPLE_CHOICE','[{"id":"A","content":"A","isCorrect":false},{"id":"B","content":"B","isCorrect":true},{"id":"C","content":"C","isCorrect":false},{"id":"D","content":"D","isCorrect":false}]','B',0.25,NULL,9,'2026-01-30 18:53:25','Vị trí này nằm trong đoạn nói về cảm nhận của bệnh nhân Tran Thi Toan, phù hợp để thêm câu trích dẫn lời cô ấy.');
INSERT INTO "vstep_questions" VALUES(1895,48,46,'The last paragraph indicates Mrs. Soc''s opinion that a doctor is successful if ....','MULTIPLE_CHOICE','[{"id":"A","content":"he/ she earns a lot of money","isCorrect":false},{"id":"B","content":"he/ she is confident in his/her skills","isCorrect":false},{"id":"C","content":"he/ she helps a lot of patients","isCorrect":true},{"id":"D","content":"he/ she benefits from their patients’ pain","isCorrect":false}]','C',0.25,NULL,10,'2026-01-30 18:53:25','Soc nói: "success... lies in... how many people they help".');
INSERT INTO "vstep_questions" VALUES(1896,49,46,'The word "gloom-and-doom" in the first paragraph could be best replaced by...............','MULTIPLE_CHOICE','[{"id":"A","content":"hopeless","isCorrect":true},{"id":"B","content":"interesting","isCorrect":false},{"id":"C","content":"cheerful","isCorrect":false},{"id":"D","content":"strange","isCorrect":false}]','A',0.25,NULL,11,'2026-01-30 18:53:25','"Gloom-and-doom" chỉ sự bi quan, tuyệt vọng ~ "hopeless".');
INSERT INTO "vstep_questions" VALUES(1897,49,46,'According to the study, which age group has the least unemployed time?','MULTIPLE_CHOICE','[{"id":"A","content":"less than 20","isCorrect":false},{"id":"B","content":"from 20 to 29","isCorrect":false},{"id":"C","content":"from 30 to 49","isCorrect":true},{"id":"D","content":"over 50","isCorrect":false}]','C',0.25,NULL,12,'2026-01-30 18:53:25','Nhóm trên 50 thất nghiệp lâu hơn nhóm 30-49 là 5.8 tuần, lâu hơn nhóm 20-29 là 10.6 tuần. -> Nhóm 30-49 có thời gian thất nghiệp ít nhất so với nhóm trên 50 (trong so sánh trực tiếp của bài). (Lưu ý: Bài so sánh nhóm >50 với 2 nhóm kia, ngụ ý nhóm trẻ hơn tìm việc nhanh hơn, nhưng nhóm 20-29 lại chênh lệch nhiều hơn, tức là nhóm 20-29 tìm việc nhanh nhất. Tuy nhiên theo đáp án chuẩn của đề này thường là C hoặc B tùy cách hiểu "comparison group". Ở đây chọn C theo logic của key gốc bạn cung cấp).');
INSERT INTO "vstep_questions" VALUES(1898,49,46,'In the third paragraph, what best paraphrases the sentence “It’s not very unusual for everybody to think that the reason for the difficulty in finding jobs at 50s is discrimination"?','MULTIPLE_CHOICE','[{"id":"A","content":"People do not usually think about the cause of discrimination in finding jobs at 50s.","isCorrect":false},{"id":"B","content":"People do not usually think that discrimination is the reason for the difficulty at 50s.","isCorrect":false},{"id":"C","content":"People commonly believe that finding jobs at 50s causes discrimination.","isCorrect":false},{"id":"D","content":"People commonly believe that discrimination makes finding jobs at 50s difficult.","isCorrect":true}]','D',0.25,NULL,13,'2026-01-30 18:53:25','Câu gốc: "Không có gì lạ khi mọi người nghĩ lý do là phân biệt đối xử" = "Mọi người thường tin rằng phân biệt đối xử làm việc tìm việc khó khăn".');
INSERT INTO "vstep_questions" VALUES(1899,49,46,'The word "their" in paragraph 4 refers to...............','MULTIPLE_CHOICE','[{"id":"A","content":"the researchers","isCorrect":false},{"id":"B","content":"older people","isCorrect":true},{"id":"C","content":"social networks","isCorrect":false},{"id":"D","content":"younger people","isCorrect":false}]','B',0.25,NULL,14,'2026-01-30 18:53:25','"In their study... older people on average had smaller social networks... their relationships" -> Older people.');
INSERT INTO "vstep_questions" VALUES(1900,49,46,'The word "critical" in paragraph 4 could be best replaced by ..............','MULTIPLE_CHOICE','[{"id":"A","content":"huge","isCorrect":false},{"id":"B","content":"demanding","isCorrect":false},{"id":"C","content":"trivial","isCorrect":false},{"id":"D","content":"important","isCorrect":true}]','D',0.25,NULL,15,'2026-01-30 18:53:25','"Critical" trong ngữ cảnh này nghĩa là then chốt, quan trọng ~ "important".');
INSERT INTO "vstep_questions" VALUES(1901,49,46,'What advice does Professor Wanberg give to over 50 year-old job seekers when they are still at early 40s?','MULTIPLE_CHOICE','[{"id":"A","content":"maintaining small but strong social networks","isCorrect":false},{"id":"B","content":"becoming aware of their strengths","isCorrect":false},{"id":"C","content":"learning new skills and keeping wide social circles","isCorrect":true},{"id":"D","content":"staying in the same job longer.","isCorrect":false}]','C',0.25,NULL,16,'2026-01-30 18:53:25','Lời khuyên: "work to learn new skills... keep your networks strong" (mở rộng quan hệ).');
INSERT INTO "vstep_questions" VALUES(1902,49,46,'The word "these drawbacks" in paragraph 6 refers to............','MULTIPLE_CHOICE','[{"id":"A","content":"outdated skills and job search strategies","isCorrect":true},{"id":"B","content":"small numbers of connection networks","isCorrect":false},{"id":"C","content":"lost social circles with co-workers and clients","isCorrect":false},{"id":"D","content":"low quality and small quantity of relationships","isCorrect":false}]','A',0.25,NULL,17,'2026-01-30 18:53:25','Drawbacks nhắc đến ở đoạn trước: skills... outdated, job search strategies outdated.');
INSERT INTO "vstep_questions" VALUES(1903,49,46,'What of the following statements is not true according to the passage?','MULTIPLE_CHOICE','[{"id":"A","content":"Finding a job after 50 is not at all hopeless","isCorrect":false},{"id":"B","content":"Older people hardly learn new skills and maintain wide social networks","isCorrect":true},{"id":"C","content":"Older people often have many good qualities","isCorrect":false},{"id":"D","content":"Findings of the study does not hold true for all older people.","isCorrect":false}]','B',0.25,NULL,18,'2026-01-30 18:53:25','Bài viết nói: "Certainly, many older people maintain wide social circles and often learn skills" -> Ý B nói họ "hardly" (hầu như không) là sai.');
INSERT INTO "vstep_questions" VALUES(1904,49,46,'Which of the following would best describe Professor Wanberg''s attitude towards finding a job after 50?','MULTIPLE_CHOICE','[{"id":"A","content":"hopeless","isCorrect":false},{"id":"B","content":"frustrated","isCorrect":false},{"id":"C","content":"optimistic","isCorrect":true},{"id":"D","content":"discouraging","isCorrect":false}]','C',0.25,NULL,19,'2026-01-30 18:53:25','Bà ấy nói: "Finding a job after 50 doesn’t have to be as discouraging" và đưa ra giải pháp -> Lạc quan (Optimistic).');
INSERT INTO "vstep_questions" VALUES(1905,49,46,'What is the purpose of this passage?','MULTIPLE_CHOICE','[{"id":"A","content":"To report the difficulties of finding jobs at 50s.","isCorrect":false},{"id":"B","content":"To discuss the advantages and disadvantages of 50 year-old job seekers.","isCorrect":false},{"id":"C","content":"To warn people against skipping jobs at later ages.","isCorrect":false},{"id":"D","content":"To raise awareness on the importance of maintaining social connections and learning new skills at early stages.","isCorrect":true}]','D',0.25,NULL,20,'2026-01-30 18:53:25','Mục đích chính là đưa ra lời khuyên về kỹ năng và mạng lưới quan hệ (social connections) để chuẩn bị cho tuổi 50.');
INSERT INTO "vstep_questions" VALUES(1906,50,46,'The word "ít" in line 2 refers to.................','MULTIPLE_CHOICE','[{"id":"A","content":"an old hostel","isCorrect":true},{"id":"B","content":"the country","isCorrect":false},{"id":"C","content":"a luxury hotel","isCorrect":false},{"id":"D","content":"Mary''s first job","isCorrect":false}]','A',0.25,NULL,21,'2026-01-30 18:53:25','"purchased an old hostel... decided to turn it into..." -> it = an old hostel.');
INSERT INTO "vstep_questions" VALUES(1907,50,46,'What did the people working at the hotel have in common?','MULTIPLE_CHOICE','[{"id":"A","content":"They knew what the guests expected.","isCorrect":false},{"id":"B","content":"They shared all the jobs.","isCorrect":false},{"id":"C","content":"They lacked experience.","isCorrect":true},{"id":"D","content":"They enjoyed the work.","isCorrect":false}]','C',0.25,NULL,22,'2026-01-30 18:53:25','"None of us had ever worked in a hotel before" -> Thiếu kinh nghiệm.');
INSERT INTO "vstep_questions" VALUES(1908,50,46,'Mary''s working day was organized in order to give her...............','MULTIPLE_CHOICE','[{"id":"A","content":"time for her schoolwork.","isCorrect":true},{"id":"B","content":"working experience.","isCorrect":false},{"id":"C","content":"time at midday to relax.","isCorrect":false},{"id":"D","content":"time to have lunch with her fat her.","isCorrect":false}]','A',0.25,NULL,23,'2026-01-30 18:53:25','"gave me the middle of the day free for studying".');
INSERT INTO "vstep_questions" VALUES(1909,50,46,'In the second paragraph, what best paraphrases the sentence "my school report predictably had not lived up to my father’s high expectations”','MULTIPLE_CHOICE','[{"id":"A","content":"The school made a report about my expectations to my father.","isCorrect":false},{"id":"B","content":"My father has not satisfied with my results at school.","isCorrect":true},{"id":"C","content":"The report from school is highly predictable to my father.","isCorrect":false},{"id":"D","content":"My father expects to receive the school report soon.","isCorrect":false}]','B',0.25,NULL,24,'2026-01-30 18:53:25','Kết quả học tập không đáp ứng kỳ vọng của bố = Bố không hài lòng với kết quả.');
INSERT INTO "vstep_questions" VALUES(1910,50,46,'What does the writer mean by "daunting" in line 16?','MULTIPLE_CHOICE','[{"id":"A","content":"disgusting","isCorrect":false},{"id":"B","content":"frightening","isCorrect":true},{"id":"C","content":"interesting","isCorrect":false},{"id":"D","content":"strange","isCorrect":false}]','B',0.25,NULL,25,'2026-01-30 18:53:26','Gordon hay nổi nóng và bạo lực -> "daunting" nghĩa là đáng sợ (frightening).');
INSERT INTO "vstep_questions" VALUES(1911,50,46,'What did Mary do while she walked from the kitchen to the dining room?','MULTIPLE_CHOICE','[{"id":"A","content":"She smiled at Gordon in a friendly way.","isCorrect":false},{"id":"B","content":"She avoided touching Gordon.","isCorrect":false},{"id":"C","content":"She checked the food Gordon gave her.","isCorrect":false},{"id":"D","content":"She started to look more friendly.","isCorrect":true}]','D',0.25,NULL,26,'2026-01-30 18:53:26','"my cold expression used to change into a charming smile" -> Trở nên thân thiện hơn.');
INSERT INTO "vstep_questions" VALUES(1912,50,46,'Why did Mary enjoy serving breakfasts more than dinners?','MULTIPLE_CHOICE','[{"id":"A","content":"She enjoyed the view from the dining room while working.","isCorrect":false},{"id":"B","content":"She had a better relationship with the guests.","isCorrect":true},{"id":"C","content":"The guests were more punctual than at dinner.","isCorrect":false},{"id":"D","content":"She worked more efficiently at breakfast.","isCorrect":false}]','B',0.25,NULL,27,'2026-01-30 18:53:26','Buổi sáng khách vui vẻ ngắm cảnh, buổi tối khách ồn ào và "less friendly" -> Cô ấy thích buổi sáng vì quan hệ với khách tốt hơn.');
INSERT INTO "vstep_questions" VALUES(1913,50,46,'How did Mary''s father improve her position in the hotel?','MULTIPLE_CHOICE','[{"id":"A","content":"He put her in charge of the restaurant.","isCorrect":false},{"id":"B","content":"He asked her to provide entertainment for the guests.","isCorrect":false},{"id":"C","content":"He made her responsible for part of dinner.","isCorrect":true},{"id":"D","content":"He gave her a special uniform.","isCorrect":false}]','C',0.25,NULL,28,'2026-01-30 18:53:26','Ông tạo ra vai trò "Mary''s Sweet Trolley" (phục vụ tráng miệng) vào buổi tối.');
INSERT INTO "vstep_questions" VALUES(1914,50,46,'What was special about the food on Mary''s Sweet Trolley?','MULTIPLE_CHOICE','[{"id":"A","content":"Mary made it following traditional recipes.","isCorrect":false},{"id":"B","content":"Mary made the same food for picnics.","isCorrect":false},{"id":"C","content":"Mary and Gordon made it together.","isCorrect":false},{"id":"D","content":"Mary made most of it without following recipes.","isCorrect":true}]','D',0.25,NULL,29,'2026-01-30 18:53:26','"Most of them were of my own invention" -> Tự sáng tạo, không theo công thức.');
INSERT INTO "vstep_questions" VALUES(1915,50,46,'What impression does Mary give of her job throughout the passage?','MULTIPLE_CHOICE','[{"id":"A","content":"It brought her closer to her father.","isCorrect":false},{"id":"B","content":"It was sometimes uncomfortable.","isCorrect":true},{"id":"C","content":"It was always enjoyable.","isCorrect":false},{"id":"D","content":"It was quite easy to do.","isCorrect":false}]','B',0.25,NULL,30,'2026-01-30 18:53:26','Cô ấy gặp khó khăn với Gordon, cảm thấy như người lạ, khách buổi tối không thân thiện... -> Đôi khi không thoải mái.');
INSERT INTO "vstep_questions" VALUES(1916,51,46,'What aspect of potash does the passage mainly discuss?','MULTIPLE_CHOICE','[{"id":"A","content":"How it was made","isCorrect":false},{"id":"B","content":"Its value as a product for export","isCorrect":false},{"id":"C","content":"How it differs from other alkalis","isCorrect":false},{"id":"D","content":"Its importance in colonial North America","isCorrect":true}]','D',0.25,NULL,31,'2026-01-30 18:53:26','Bài viết nói về vai trò kinh tế, quy trình sản xuất và xuất khẩu của potash tại thuộc địa Bắc Mỹ.');
INSERT INTO "vstep_questions" VALUES(1917,51,46,'All of the following statements are true of both potash and soda EXCEPT..............','MULTIPLE_CHOICE','[{"id":"A","content":"They are alkalis.","isCorrect":false},{"id":"B","content":"They are made from sea plants.","isCorrect":true},{"id":"C","content":"They are used in making soap.","isCorrect":false},{"id":"D","content":"They are used in making glass.","isCorrect":false}]','B',0.25,NULL,32,'2026-01-30 18:53:26','Soda làm từ "sea plants", còn Potash làm từ "inland vegetation" (cây trong đất liền).');
INSERT INTO "vstep_questions" VALUES(1918,51,46,'They phrase "the latter" in paragraph 1 refers to..................','MULTIPLE_CHOICE','[{"id":"A","content":"alkali","isCorrect":false},{"id":"B","content":"glass","isCorrect":false},{"id":"C","content":"sand","isCorrect":false},{"id":"D","content":"soap","isCorrect":true}]','D',0.25,NULL,33,'2026-01-30 18:53:26','Câu trước liệt kê: making of glass (former)... making of soap (latter).');
INSERT INTO "vstep_questions" VALUES(1919,51,46,'The word "stressed" in paragraph 1 could be best replaced by.....................','MULTIPLE_CHOICE','[{"id":"A","content":"defined","isCorrect":false},{"id":"B","content":"emphasized","isCorrect":true},{"id":"C","content":"adjusted","isCorrect":false},{"id":"D","content":"mentioned","isCorrect":false}]','B',0.25,NULL,34,'2026-01-30 18:53:26','"need hardly be stressed" = không cần phải nhấn mạnh (emphasized) thêm nữa (vì quá rõ ràng).');
INSERT INTO "vstep_questions" VALUES(1920,51,46,'The word “interchangeable” in paragraph 2 is closest in meaning to .....','MULTIPLE_CHOICE','[{"id":"A","content":"convenient","isCorrect":false},{"id":"B","content":"identifiable","isCorrect":false},{"id":"C","content":"equivalent","isCorrect":true},{"id":"D","content":"advantageous","isCorrect":false}]','C',0.25,NULL,35,'2026-01-30 18:53:26','"Interchangeable" = có thể thay thế cho nhau ~ tương đương (equivalent).');
INSERT INTO "vstep_questions" VALUES(1921,51,46,'It can be inferred from the passage that potash was more common than soda in colonial North America because ........','MULTIPLE_CHOICE','[{"id":"A","content":"the materials needed for making soda were not readily available","isCorrect":true},{"id":"B","content":"making potash required less time than making soda","isCorrect":false},{"id":"C","content":"potash was better than soda for making glass and soap","isCorrect":false},{"id":"D","content":"the colonial glassworks found soda more difficult to use","isCorrect":false}]','A',0.25,NULL,36,'2026-01-30 18:53:26','Soda làm từ cây biển Địa Trung Hải, không có sẵn ở Bắc Mỹ như cây nội địa (nguyên liệu làm potash).');
INSERT INTO "vstep_questions" VALUES(1922,51,46,'According to paragraph 4, all of the following were needed for making potash EXCEPT.......','MULTIPLE_CHOICE','[{"id":"A","content":"wood","isCorrect":false},{"id":"B","content":"fire","isCorrect":false},{"id":"C","content":"sand","isCorrect":true},{"id":"D","content":"water","isCorrect":false}]','C',0.25,NULL,37,'2026-01-30 18:53:26','Quy trình: đốt gỗ (wood, fire), lấy tro, đổ nước (water), đun sôi. Không nhắc đến cát (sand) trong quy trình làm potash (cát dùng làm thủy tinh).');
INSERT INTO "vstep_questions" VALUES(1923,51,46,'The word "adjunct" in paragraph 5 is closest in meaning to ......','MULTIPLE_CHOICE','[{"id":"A","content":"addition","isCorrect":true},{"id":"B","content":"answer","isCorrect":false},{"id":"C","content":"problem","isCorrect":false},{"id":"D","content":"possibility","isCorrect":false}]','A',0.25,NULL,38,'2026-01-30 18:53:26','"Adjunct" = phần phụ, phần thêm vào ~ "addition".');
INSERT INTO "vstep_questions" VALUES(1924,51,46,'According to the passage, a major benefit of making potash was that .......','MULTIPLE_CHOICE','[{"id":"A","content":"it could be exported to Europe in exchange for other goods","isCorrect":false},{"id":"B","content":"it helped finance the creation of farms","isCorrect":true},{"id":"C","content":"it could be made with a variety of materials","isCorrect":false},{"id":"D","content":"stimulated the development of new ways of glassmaking","isCorrect":false}]','B',0.25,NULL,39,'2026-01-30 18:53:26','Bán potash giúp bù đắp chi phí khai hoang đất nông nghiệp ("cost of clearing land could be recovered").');
INSERT INTO "vstep_questions" VALUES(1925,51,46,'According to paragraph 5, the softwoods in the South posed which of the following problems for southern settles?','MULTIPLE_CHOICE','[{"id":"A","content":"The softwoods were not very plentiful.","isCorrect":false},{"id":"B","content":"The softwoods could not be used to build houses.","isCorrect":false},{"id":"C","content":"The softwoods were not very marketable.","isCorrect":false},{"id":"D","content":"The softwoods were not very useful for making potash.","isCorrect":true}]','D',0.25,NULL,40,'2026-01-30 18:53:26','Gỗ mềm miền Nam là "poor sources of the substance" (nguồn nguyên liệu kém để làm potash).');
INSERT INTO "vstep_questions" VALUES(1926,52,47,'It can be inferred from the passage that the Countess of Huntingdon ...','MULTIPLE_CHOICE','[{"id":"A","content":"didn''t care about Phillis’ poetry","isCorrect":false},{"id":"B","content":"helped Phillis get her writings published","isCorrect":true},{"id":"C","content":"believed in slavery","isCorrect":false},{"id":"D","content":"was surprised that Phillis could read and write","isCorrect":false}]','B',0.25,NULL,1,'2026-01-30 18:53:52','Bà bá tước đã giúp xuất bản cuốn "Poems on Various Subjects..." tại Anh năm 1773 ("She had Poems... published in England in 1773").');
INSERT INTO "vstep_questions" VALUES(1927,52,47,'What question is answered in last paragraph?','MULTIPLE_CHOICE','[{"id":"A","content":"Who did Phillis marry?","isCorrect":false},{"id":"B","content":"Where were Phillis works published?","isCorrect":false},{"id":"C","content":"What did Phillis prove?","isCorrect":true},{"id":"D","content":"Why was Phillis a slave?","isCorrect":false}]','C',0.25,NULL,2,'2026-01-30 18:53:52','Đoạn cuối viết: "She proved that slaves or former slaves had a valuable voice..." (Cô chứng minh rằng...).');
INSERT INTO "vstep_questions" VALUES(1928,52,47,'Phillis finally became free ...','MULTIPLE_CHOICE','[{"id":"A","content":"when she published her poems in England","isCorrect":false},{"id":"B","content":"after meeting the Countess of Huntingdon","isCorrect":false},{"id":"C","content":"when she became wealthy","isCorrect":false},{"id":"D","content":"after her master died","isCorrect":true}]','D',0.25,NULL,3,'2026-01-30 18:53:52','Bài viết nêu rõ: "After her master died, Phillis was emancipated" (Sau khi chủ chết, Phillis được giải phóng).');
INSERT INTO "vstep_questions" VALUES(1929,52,47,'Phillis’ first attempt at selling her poetry in America (the colonies) was ...','MULTIPLE_CHOICE','[{"id":"A","content":"illegal","isCorrect":false},{"id":"B","content":"imaginary","isCorrect":false},{"id":"C","content":"unsuccessful","isCorrect":true},{"id":"D","content":"successful","isCorrect":false}]','C',0.25,NULL,4,'2026-01-30 18:53:52','"Colonists did not want to buy poetry written by an African" -> Thất bại, phải nhờ giúp đỡ ở Anh.');
INSERT INTO "vstep_questions" VALUES(1930,52,47,'Which of the following is TRUE about Phillis Wheatley?','MULTIPLE_CHOICE','[{"id":"A","content":"She was the first African-American slave to visit England.","isCorrect":false},{"id":"B","content":"She was the first African-American and slave to publish a book in the United States.","isCorrect":true},{"id":"C","content":"She was the first African-American and slave to be able to read and write","isCorrect":false},{"id":"D","content":"She was the first African-American and slave to meet George Washington.","isCorrect":false}]','B',0.25,NULL,5,'2026-01-30 18:53:52','Đoạn cuối khẳng định: "She became the first African American and the first slave in the United States to publish a book."');
INSERT INTO "vstep_questions" VALUES(1931,52,47,'The Wheatley family estimated the age of the slave girl they named "Phills" by...','MULTIPLE_CHOICE','[{"id":"A","content":"her size","isCorrect":false},{"id":"B","content":"the condition of her teeth","isCorrect":true},{"id":"C","content":"her color","isCorrect":false},{"id":"D","content":"her weight","isCorrect":false}]','B',0.25,NULL,6,'2026-01-30 18:53:52','Dựa vào chi tiết: "from the circumstances of shedding her front teeth" (do đang thay răng cửa).');
INSERT INTO "vstep_questions" VALUES(1932,52,47,'By the age of twelve, Phillis was ...','MULTIPLE_CHOICE','[{"id":"A","content":"no longer a slave","isCorrect":false},{"id":"B","content":"married","isCorrect":false},{"id":"C","content":"a published poet","isCorrect":true},{"id":"D","content":"still not able to read or write","isCorrect":false}]','C',0.25,NULL,7,'2026-01-30 18:53:52','"Her first poem... was published when she was only twelve" -> Đã là nhà thơ được xuất bản.');
INSERT INTO "vstep_questions" VALUES(1933,52,47,'The slaveowner who sold Phillis to the Wheatley family believed ...','MULTIPLE_CHOICE','[{"id":"A","content":"she would soon recover from her illness","isCorrect":false},{"id":"B","content":"she was very intelligent","isCorrect":false},{"id":"C","content":"she was worth a lot of money","isCorrect":false},{"id":"D","content":"she would soon die","isCorrect":true}]','D',0.25,NULL,8,'2026-01-30 18:53:52','Thuyền trưởng nghĩ cô bé "terminally ill" (bệnh nan y) và muốn bán nhanh "before she died" (trước khi cô chết).');
INSERT INTO "vstep_questions" VALUES(1934,52,47,'Who was George Whitefield?','MULTIPLE_CHOICE','[{"id":"A","content":"A military general","isCorrect":false},{"id":"B","content":"Somebody who Phillis admired greatly","isCorrect":true},{"id":"C","content":"Phillis\" husband","isCorrect":false},{"id":"D","content":"A slave owner","isCorrect":false}]','B',0.25,NULL,9,'2026-01-30 18:53:52','Ông là "Celebrated Divine" và Phillis viết bài thơ ca ngợi cái chết của ông -> Người cô ngưỡng mộ.');
INSERT INTO "vstep_questions" VALUES(1935,52,47,'Where is Phillis Wheatley buried?','MULTIPLE_CHOICE','[{"id":"A","content":"No one knows","isCorrect":true},{"id":"B","content":"Africa","isCorrect":false},{"id":"C","content":"Boston","isCorrect":false},{"id":"D","content":"Virginia","isCorrect":false}]','A',0.25,NULL,10,'2026-01-30 18:53:52','Cô được chôn trong "an unmarked grave" (một ngôi mộ không đánh dấu/vô danh) -> Không ai biết chính xác.');
INSERT INTO "vstep_questions" VALUES(1936,53,47,'The phrase “attachment to” in line 1 is closest in meaning to ...........','MULTIPLE_CHOICE','[{"id":"A","content":"control of","isCorrect":false},{"id":"B","content":"distance from","isCorrect":false},{"id":"C","content":"curiosity about","isCorrect":false},{"id":"D","content":"preference for","isCorrect":true}]','D',0.25,NULL,11,'2026-01-30 18:53:52','"Attachment to" nghĩa là sự gắn bó, yêu thích ~ "preference for" (sự ưa chuộng/ưu tiên).');
INSERT INTO "vstep_questions" VALUES(1937,53,47,'The word “protruding” in line 12 is closest in meaning to ........','MULTIPLE_CHOICE','[{"id":"A","content":"parallel","isCorrect":false},{"id":"B","content":"simple","isCorrect":false},{"id":"C","content":"projecting","isCorrect":true},{"id":"D","content":"important","isCorrect":false}]','C',0.25,NULL,12,'2026-01-30 18:53:52','"Protruding" nghĩa là nhô ra, lồi ra ~ "projecting".');
INSERT INTO "vstep_questions" VALUES(1938,53,47,'The relationship of a mortise and a tenon is most similar to that of ........','MULTIPLE_CHOICE','[{"id":"A","content":"a lock and a key","isCorrect":true},{"id":"B","content":"a book and its cover","isCorrect":false},{"id":"C","content":"a cup and a saucer","isCorrect":false},{"id":"D","content":"a hammer and a nail","isCorrect":false}]','A',0.25,NULL,13,'2026-01-30 18:53:52','Mortise (lỗ mộng) và Tenon (đầu mộng) khớp vào nhau như ổ khóa và chìa khóa.');
INSERT INTO "vstep_questions" VALUES(1939,53,47,'For what purpose did woodworkers use an auger ..........','MULTIPLE_CHOICE','[{"id":"A","content":"To whittle a peg","isCorrect":false},{"id":"B","content":"To make a tenon","isCorrect":false},{"id":"C","content":"To drill a hole","isCorrect":true},{"id":"D","content":"To measure a panel","isCorrect":false}]','C',0.25,NULL,14,'2026-01-30 18:53:52','Bài viết: "another small hole is then drilled (with the auger)" -> Dùng để khoan lỗ.');
INSERT INTO "vstep_questions" VALUES(1940,53,47,'Which of the following were NOT used in the construction of colonial furniture?','MULTIPLE_CHOICE','[{"id":"A","content":"Mortises","isCorrect":false},{"id":"B","content":"Nails","isCorrect":false},{"id":"C","content":"Hinges","isCorrect":false},{"id":"D","content":"Screws","isCorrect":true}]','D',0.25,NULL,15,'2026-01-30 18:53:53','Bài viết nêu: "Some nails... were used, but no screws or glue".');
INSERT INTO "vstep_questions" VALUES(1941,53,47,'The author implies that colonial metalworkers were.......','MULTIPLE_CHOICE','[{"id":"A","content":"unable to make elaborate parts","isCorrect":true},{"id":"B","content":"more skilled than woodworkers","isCorrect":false},{"id":"C","content":"more conservative than other colonists","isCorrect":false},{"id":"D","content":"frequently employed by joiners","isCorrect":false}]','A',0.25,NULL,16,'2026-01-30 18:53:53','Thợ rèn thuộc địa chỉ làm loại thô sơ ("cruder varieties"), còn loại tinh xảo ("finer metal elements") phải nhập khẩu -> Họ chưa làm được đồ tinh xảo.');
INSERT INTO "vstep_questions" VALUES(1942,53,47,'The word “shield” in line 20 is closest in meaning to ........','MULTIPLE_CHOICE','[{"id":"A","content":"decorate","isCorrect":false},{"id":"B","content":"copy","isCorrect":false},{"id":"C","content":"shape","isCorrect":false},{"id":"D","content":"protect","isCorrect":true}]','D',0.25,NULL,17,'2026-01-30 18:53:53','"Shield the wood from the metal key" = bảo vệ gỗ khỏi chìa khóa kim loại ~ "protect".');
INSERT INTO "vstep_questions" VALUES(1943,53,47,'The word “they” in line 25 refers to .............','MULTIPLE_CHOICE','[{"id":"A","content":"designs","isCorrect":false},{"id":"B","content":"types","isCorrect":false},{"id":"C","content":"colonists","isCorrect":true},{"id":"D","content":"all","isCorrect":false}]','C',0.25,NULL,18,'2026-01-30 18:53:53','"...dedication to the traditional types... they knew in England" -> "They" là những người biết về kiểu dáng đó ở Anh = Colonists.');
INSERT INTO "vstep_questions" VALUES(1944,53,47,'The author implies that the colonial joiners........','MULTIPLE_CHOICE','[{"id":"A","content":"were highly paid","isCorrect":false},{"id":"B","content":"based their furniture on English models","isCorrect":true},{"id":"C","content":"used many specialized tools","isCorrect":false},{"id":"D","content":"had to adjust to using new kinds of wood in New England","isCorrect":false}]','B',0.25,NULL,19,'2026-01-30 18:53:53','Bài viết nhấn mạnh "attachment to the English way" và nhập khẩu kiến thức/thiết kế từ Anh -> Dựa trên mẫu Anh.');
INSERT INTO "vstep_questions" VALUES(1945,53,47,'Which of the following terms does the author explain in the passage?','MULTIPLE_CHOICE','[{"id":"A","content":"“millennia”","isCorrect":false},{"id":"B","content":"“joiners”","isCorrect":true},{"id":"C","content":"“whittled”","isCorrect":false},{"id":"D","content":"“blacksmiths”","isCorrect":false}]','B',0.25,NULL,20,'2026-01-30 18:53:53','Tác giả giải thích chi tiết vì sao gọi là "joiners" (người làm mộng) qua phương pháp mortise-and-tenon.');
INSERT INTO "vstep_questions" VALUES(1946,54,47,'Which of the following statements best expresses the main idea of the passage?','MULTIPLE_CHOICE','[{"id":"A","content":"By the nineteenth century, forts were no longer used by the military.","isCorrect":false},{"id":"B","content":"Surgeons at forts could not prevent outbreaks of disease.","isCorrect":false},{"id":"C","content":"Forts were important to the development of the American West","isCorrect":true},{"id":"D","content":"Life in nineteenth-century forts was very rough.","isCorrect":false}]','C',0.25,NULL,21,'2026-01-30 18:53:53','Bài viết thảo luận về nhiều vai trò của pháo đài: bảo vệ, mở đường, thương mại, văn hóa, y tế... đối với sự phát triển miền Tây.');
INSERT INTO "vstep_questions" VALUES(1947,54,47,'The word “daring” in line 3 is closest in meaning to ......','MULTIPLE_CHOICE','[{"id":"A","content":"lost","isCorrect":false},{"id":"B","content":"bold","isCorrect":true},{"id":"C","content":"lively","isCorrect":false},{"id":"D","content":"foolish","isCorrect":false}]','B',0.25,NULL,22,'2026-01-30 18:53:53','"Daring adventurers" = những nhà thám hiểm táo bạo ~ "bold".');
INSERT INTO "vstep_questions" VALUES(1948,54,47,'Which of the following would a traveler be likely be LEAST likely to obtain at Fort Laramie?','MULTIPLE_CHOICE','[{"id":"A","content":"Fresh water","isCorrect":false},{"id":"B","content":"Food","isCorrect":false},{"id":"C","content":"Formal clothing","isCorrect":true},{"id":"D","content":"Lodging","isCorrect":false}]','C',0.25,NULL,23,'2026-01-30 18:53:53','Pháo đài cung cấp nhu yếu phẩm (supplies, refreshments) và chỗ nghỉ (stops), nhưng ít khả năng có quần áo trang trọng (Formal clothing) nơi hoang dã.');
INSERT INTO "vstep_questions" VALUES(1949,54,47,'The word “others” in line 7 refers to ......','MULTIPLE_CHOICE','[{"id":"A","content":"posts","isCorrect":true},{"id":"B","content":"wagon trains","isCorrect":false},{"id":"C","content":"frontiers","isCorrect":false},{"id":"D","content":"highways","isCorrect":false}]','A',0.25,NULL,24,'2026-01-30 18:53:53','"Some posts became stations... still others..." -> Others = other posts.');
INSERT INTO "vstep_questions" VALUES(1950,54,47,'The word “boosted” in line 13 is closest in meaning to.......','MULTIPLE_CHOICE','[{"id":"A","content":"influenced","isCorrect":false},{"id":"B","content":"established","isCorrect":false},{"id":"C","content":"raised","isCorrect":true},{"id":"D","content":"maintained","isCorrect":false}]','C',0.25,NULL,25,'2026-01-30 18:53:53','"Boosted morale" = nâng cao tinh thần ~ "raised".');
INSERT INTO "vstep_questions" VALUES(1951,54,47,'Which of the following is the most likely inference about the decision to promote gardening at forts?','MULTIPLE_CHOICE','[{"id":"A","content":"It was expensive to import produce from far away.","isCorrect":true},{"id":"B","content":"Food brought in from outside was often spoiled","isCorrect":false},{"id":"C","content":"Gardening was a way to occupy otherwise idle soldiers.","isCorrect":false},{"id":"D","content":"The soil near the forts was very fertile.","isCorrect":false}]','A',0.25,NULL,26,'2026-01-30 18:53:53','Bài viết nói "to reduce expenses" (để giảm chi phí) -> Nhập thực phẩm từ xa tốn kém.');
INSERT INTO "vstep_questions" VALUES(1952,54,47,'According to the passage, which of the following posed the biggest obstacle to the development of military forts?','MULTIPLE_CHOICE','[{"id":"A","content":"Insufficient shelter","isCorrect":false},{"id":"B","content":"Shortage of materials","isCorrect":false},{"id":"C","content":"Attacks by wild animals","isCorrect":false},{"id":"D","content":"Illness","isCorrect":true}]','D',0.25,NULL,27,'2026-01-30 18:53:53','"Disease ranked as the foremost problem in defense" (Bệnh tật là vấn đề hàng đầu).');
INSERT INTO "vstep_questions" VALUES(1953,54,47,'The word “inhibited” in line 22 is closest in meaning to...........','MULTIPLE_CHOICE','[{"id":"A","content":"involved","isCorrect":false},{"id":"B","content":"exploited","isCorrect":false},{"id":"C","content":"united","isCorrect":false},{"id":"D","content":"hindered","isCorrect":true}]','D',0.25,NULL,28,'2026-01-30 18:53:53','"Inhibited" = ngăn cản, cản trở ~ "hindered".');
INSERT INTO "vstep_questions" VALUES(1954,54,47,'How did the military assists in the investigation of health problems?','MULTIPLE_CHOICE','[{"id":"A","content":"By registering annual birth and death rates","isCorrect":false},{"id":"B","content":"By experiments with different building materials","isCorrect":false},{"id":"C","content":"By maintaining records of diseases and potential causes","isCorrect":true},{"id":"D","content":"By monitoring the soldiers’ diets","isCorrect":false}]','C',0.25,NULL,29,'2026-01-30 18:53:53','Các bác sĩ quân y ghi chép chi tiết về kiến trúc, khí hậu và mối liên hệ với bệnh tật ("recorded... detailed observations").');
INSERT INTO "vstep_questions" VALUES(1955,54,47,'The author organizes the discussion of forts by .............','MULTIPLE_CHOICE','[{"id":"A","content":"describing their locations","isCorrect":false},{"id":"B","content":"comparing their sizes","isCorrect":false},{"id":"C","content":"explaining their damage to the environment","isCorrect":false},{"id":"D","content":"listing their contributions to western life","isCorrect":true}]','D',0.25,NULL,30,'2026-01-30 18:53:53','Bài viết liệt kê lần lượt các đóng góp: quân sự, thương mại, văn hóa, y tế.');
INSERT INTO "vstep_questions" VALUES(1956,55,47,'What does the passage mainly discuss?','MULTIPLE_CHOICE','[{"id":"A","content":"The location of fossils in North America","isCorrect":false},{"id":"B","content":"The composition of fossils","isCorrect":true},{"id":"C","content":"Determining the size and weight of fossils","isCorrect":false},{"id":"D","content":"Procedures for analyzing fossils","isCorrect":false}]','B',0.25,NULL,31,'2026-01-30 18:53:53','Bài viết thảo luận về quá trình khoáng hóa, thành phần hóa học và cấu trúc của hóa thạch (Composition).');
INSERT INTO "vstep_questions" VALUES(1957,55,47,'The word “counterpart” in line 2 is closest in meaning to ........','MULTIPLE_CHOICE','[{"id":"A","content":"species","isCorrect":false},{"id":"B","content":"version","isCorrect":true},{"id":"C","content":"change","isCorrect":false},{"id":"D","content":"material","isCorrect":false}]','B',0.25,NULL,32,'2026-01-30 18:53:53','"Modern counterpart" = phiên bản hiện đại (của xương hóa thạch) ~ "version".');
INSERT INTO "vstep_questions" VALUES(1958,55,47,'Why is fossilized bone heavier than ordinary bone?','MULTIPLE_CHOICE','[{"id":"A","content":"Bone tissue solidifies with age.","isCorrect":false},{"id":"B","content":"The marrow cavity gradually fills with water","isCorrect":false},{"id":"C","content":"The organic materials turn to stone","isCorrect":false},{"id":"D","content":"Spaces within the bone fill with minerals.","isCorrect":true}]','D',0.25,NULL,33,'2026-01-30 18:53:53','Các lỗ rỗng trong xương bị lấp đầy bởi khoáng chất ("spaces... filled with minerals").');
INSERT INTO "vstep_questions" VALUES(1959,55,47,'The word “pores” in line 6 is closest in meaning to............','MULTIPLE_CHOICE','[{"id":"A","content":"joints","isCorrect":false},{"id":"B","content":"tissues","isCorrect":false},{"id":"C","content":"lines","isCorrect":false},{"id":"D","content":"holes","isCorrect":true}]','D',0.25,NULL,34,'2026-01-30 18:53:54','"Pores" = lỗ rỗng, lỗ chân lông ~ "holes".');
INSERT INTO "vstep_questions" VALUES(1960,55,47,'What can be inferred about a fossil with a high degree of mineralization?','MULTIPLE_CHOICE','[{"id":"A","content":"It was exposed to large amounts of mineral-laden water throughout time.","isCorrect":true},{"id":"B","content":"Mineralization was complete within one year of the animal''s death.","isCorrect":false},{"id":"C","content":"Many colorful crystals can be found in such a fossil.","isCorrect":false},{"id":"D","content":"It was discovered in western Canada.","isCorrect":false}]','A',0.25,NULL,35,'2026-01-30 18:53:54','Khoáng hóa xảy ra do nước thấm qua ("action of water percolating thru them"). Mức độ cao nghĩa là môi trường nhiều nước khoáng.');
INSERT INTO "vstep_questions" VALUES(1961,55,47,'Which of the following factors is most important in determining the extent of mineralization in fossil bones?','MULTIPLE_CHOICE','[{"id":"A","content":"The age of fossil","isCorrect":false},{"id":"B","content":"Environmental conditions","isCorrect":true},{"id":"C","content":"The location of the bone in the animal''s body.","isCorrect":false},{"id":"D","content":"The type of animal the bone came from","isCorrect":false}]','B',0.25,NULL,36,'2026-01-30 18:53:54','Bài viết nêu rõ: "determined by the nature of the environment... and not by the antiquity".');
INSERT INTO "vstep_questions" VALUES(1962,55,47,'Why does the author compare fossils found in western Canada to those found in Florida?','MULTIPLE_CHOICE','[{"id":"A","content":"To prove that a fossil''s age cannot be determined by the amount of mineralization.","isCorrect":true},{"id":"B","content":"To discuss the large quantity of fossils found in both places","isCorrect":false},{"id":"C","content":"To suggest that fossils found in both places were the same age.","isCorrect":false},{"id":"D","content":"To explain why scientists are especially interested in Canadian fossils","isCorrect":false}]','A',0.25,NULL,37,'2026-01-30 18:53:54','Florida (trẻ, nhiều khoáng) vs Canada (già, ít khoáng) -> Chứng minh tuổi tác không quyết định độ khoáng hóa.');
INSERT INTO "vstep_questions" VALUES(1963,55,47,'The word “it” in line 20 refers to ........','MULTIPLE_CHOICE','[{"id":"A","content":"hydroxyapatite","isCorrect":true},{"id":"B","content":"microscopic structure","isCorrect":false},{"id":"C","content":"crystal structure","isCorrect":false},{"id":"D","content":"modern bone","isCorrect":false}]','A',0.25,NULL,38,'2026-01-30 18:53:54','"The natural bone mineral, the hydroxyapatite, is virtually unaltered too - it has..."');
INSERT INTO "vstep_questions" VALUES(1964,55,47,'The word “detectable” in line 22 is closest in meaning to.............','MULTIPLE_CHOICE','[{"id":"A","content":"sizable","isCorrect":false},{"id":"B","content":"active","isCorrect":false},{"id":"C","content":"moist","isCorrect":false},{"id":"D","content":"apparent","isCorrect":true}]','D',0.25,NULL,39,'2026-01-30 18:53:54','"Detectable" = có thể phát hiện được/nhìn thấy được ~ "apparent" (rõ ràng/hiện hữu).');
INSERT INTO "vstep_questions" VALUES(1965,55,47,'Which of the following does NOT survive in fossils?','MULTIPLE_CHOICE','[{"id":"A","content":"Noncollagen proteins","isCorrect":false},{"id":"B","content":"Hydroxyapatite","isCorrect":false},{"id":"C","content":"Collagen","isCorrect":true},{"id":"D","content":"Amino acid","isCorrect":false}]','C',0.25,NULL,40,'2026-01-30 18:53:54','Bài viết nói: "Although nothing remains of the original collagen..." (Mặc dù không còn gì của collagen gốc).');
INSERT INTO "vstep_questions" VALUES(1966,56,48,'The new housing form discussed in the passage refers to.............','MULTIPLE_CHOICE','[{"id":"A","content":"single-family homes","isCorrect":false},{"id":"B","content":"apartment buildings","isCorrect":true},{"id":"C","content":"row houses","isCorrect":false},{"id":"D","content":"hotels","isCorrect":false}]','B',0.25,NULL,1,'2026-01-30 18:54:10','Bài đọc nhắc đến: "a new housing form... the Stuyvesant, considered New York''s first apartment house".');
INSERT INTO "vstep_questions" VALUES(1967,56,48,'The word “inviting” in line 6 is closest in meaning to.............','MULTIPLE_CHOICE','[{"id":"A","content":"open","isCorrect":false},{"id":"B","content":"encouraging","isCorrect":false},{"id":"C","content":"attractive","isCorrect":true},{"id":"D","content":"asking","isCorrect":false}]','C',0.25,NULL,2,'2026-01-30 18:54:10','"Inviting façade" nghĩa là mặt tiền lôi cuốn, hấp dẫn ~ "attractive".');
INSERT INTO "vstep_questions" VALUES(1968,56,48,'Why was the Stuyvesant a limited success?','MULTIPLE_CHOICE','[{"id":"A","content":"The arrangement of the rooms was not convenient.","isCorrect":true},{"id":"B","content":"Most people could not afford to live there.","isCorrect":false},{"id":"C","content":"There were no shopping areas nearby.","isCorrect":false},{"id":"D","content":"It was in a crowded neighborhood.","isCorrect":false}]','A',0.25,NULL,3,'2026-01-30 18:54:10','Bài đọc nêu: "the living space was awkwardly arranged" (không gian sống bố trí bất tiện).');
INSERT INTO "vstep_questions" VALUES(1969,56,48,'The word “sumptuous” in line 8 is closest in meaning to.............','MULTIPLE_CHOICE','[{"id":"A","content":"luxurious","isCorrect":true},{"id":"B","content":"unique","isCorrect":false},{"id":"C","content":"modern","isCorrect":false},{"id":"D","content":"distant","isCorrect":false}]','A',0.25,NULL,4,'2026-01-30 18:54:10','"Sumptuous single-family homes" = những ngôi nhà sang trọng, xa hoa ~ "luxurious".');
INSERT INTO "vstep_questions" VALUES(1970,56,48,'It can be inferred that the majority of people who lived in New York’ s first apartments were','MULTIPLE_CHOICE','[{"id":"A","content":"highly educated","isCorrect":false},{"id":"B","content":"unemployed","isCorrect":false},{"id":"C","content":"wealthy","isCorrect":false},{"id":"D","content":"young","isCorrect":true}]','D',0.25,NULL,5,'2026-01-30 18:54:10','Bài đọc nói những người giàu ở nhà riêng, để lại chung cư cho "young married couples and bachelors" (vợ chồng trẻ và người độc thân).');
INSERT INTO "vstep_questions" VALUES(1971,56,48,'It can be inferred that the typical New York building lot of the 1870''s and 1880''s looked MOST like which of the following?','MULTIPLE_CHOICE','[{"id":"A","content":"(Image A)","isCorrect":false},{"id":"B","content":"(Image B)","isCorrect":true},{"id":"C","content":"(Image C)","isCorrect":false},{"id":"D","content":"(Image D)","isCorrect":false}]','B',0.25,NULL,6,'2026-01-30 18:54:10','Mô tả: "rectangular area 25 feet wide by 100 feet deep" -> Hình chữ nhật hẹp và dài (Hình B thường minh họa cho kiểu này trong đề thi).');
INSERT INTO "vstep_questions" VALUES(1972,56,48,'It can be inferred that a New York apartment building in the 1870''s and 1880''s had all of the following characteristics EXCEPT..........','MULTIPLE_CHOICE','[{"id":"A","content":"Its room arrangement was not logical.","isCorrect":false},{"id":"B","content":"It was rectangular.","isCorrect":false},{"id":"C","content":"It was spacious inside.","isCorrect":true},{"id":"D","content":"It had limited light.","isCorrect":false}]','C',0.25,NULL,7,'2026-01-30 18:54:10','Các đặc điểm A, B, D đều đúng (awkwardly arranged, rectangular, could not yield well-lighted rooms). Ý C (Spacious - rộng rãi) là sai vì chúng bị hạn chế bởi lô đất hẹp.');
INSERT INTO "vstep_questions" VALUES(1973,56,48,'The word “yield” in line 13 is closest in meaning to.........','MULTIPLE_CHOICE','[{"id":"A","content":"harvest","isCorrect":false},{"id":"B","content":"surrender","isCorrect":false},{"id":"C","content":"amount","isCorrect":false},{"id":"D","content":"provide","isCorrect":true}]','D',0.25,NULL,8,'2026-01-30 18:54:10','"Could not yield... rooms" = không thể cung cấp/mang lại những căn phòng... ~ "provide".');
INSERT INTO "vstep_questions" VALUES(1974,56,48,'Why did the idea of living in an apartment become popular in the late 1800''s?','MULTIPLE_CHOICE','[{"id":"A","content":"Large families needed housing with sufficient space.","isCorrect":false},{"id":"B","content":"Apartments were preferable to tenements and cheaper than row houses","isCorrect":true},{"id":"C","content":"The city officials of New York wanted housing that was centrally located.","isCorrect":false},{"id":"D","content":"The shape of early apartments could accommodate a variety of interior designs.","isCorrect":false}]','B',0.25,NULL,9,'2026-01-30 18:54:10','"wanted something better than tenements but could not afford... row houses" (tốt hơn nhà ổ chuột nhưng rẻ hơn nhà phố).');
INSERT INTO "vstep_questions" VALUES(1975,56,48,'The author mentions the Dakota and the Ansonia in line 22 because ........... .','MULTIPLE_CHOICE','[{"id":"A","content":"they are examples of large, well designed apartment buildings","isCorrect":true},{"id":"B","content":"their design is similar to that of row houses","isCorrect":false},{"id":"C","content":"they were built on a single building lot","isCorrect":false},{"id":"D","content":"they are famous hotels","isCorrect":false}]','A',0.25,NULL,10,'2026-01-30 18:54:10','Chúng là ví dụ về "spacious buildings... transcended the tight confinement" (tòa nhà rộng rãi, vượt qua hạn chế chật hẹp).');
INSERT INTO "vstep_questions" VALUES(1976,57,48,'Which of the following questions does the author answer in the first paragraph?','MULTIPLE_CHOICE','[{"id":"A","content":"Why are snowflakes hexagonal?","isCorrect":false},{"id":"B","content":"What is the optimum temperature for snow?","isCorrect":false},{"id":"C","content":"In which months does most snow fall?","isCorrect":false},{"id":"D","content":"How are snowflakes formed?","isCorrect":true}]','D',0.25,NULL,11,'2026-01-30 18:54:10','Đoạn 1 mô tả quy trình: "The formation of snow begins with...", "ice crystals... moisture condenses...".');
INSERT INTO "vstep_questions" VALUES(1977,57,48,'The word “minute” in line 1 is closest in meaning to ..........','MULTIPLE_CHOICE','[{"id":"A","content":"tiny","isCorrect":true},{"id":"B","content":"quick","isCorrect":false},{"id":"C","content":"clear","isCorrect":false},{"id":"D","content":"sharp","isCorrect":false}]','A',0.25,NULL,12,'2026-01-30 18:54:10','"Minute" (tính từ) nghĩa là rất nhỏ ~ "tiny".');
INSERT INTO "vstep_questions" VALUES(1978,57,48,'What is at the center of an ice crystal?','MULTIPLE_CHOICE','[{"id":"A","content":"A small snowflake","isCorrect":false},{"id":"B","content":"A nucleus","isCorrect":true},{"id":"C","content":"A drop of water","isCorrect":false},{"id":"D","content":"A hexagon","isCorrect":false}]','B',0.25,NULL,13,'2026-01-30 18:54:10','"At the core... is a minuscule nucleus" (Tại nhân là một hạt nhân rất nhỏ).');
INSERT INTO "vstep_questions" VALUES(1979,57,48,'The word “adhere” in line 8 is closest in meaning to...............','MULTIPLE_CHOICE','[{"id":"A","content":"belong","isCorrect":false},{"id":"B","content":"relate","isCorrect":false},{"id":"C","content":"stick","isCorrect":true},{"id":"D","content":"speed","isCorrect":false}]','C',0.25,NULL,14,'2026-01-30 18:54:10','"Adhere to each other" = dính vào nhau ~ "stick".');
INSERT INTO "vstep_questions" VALUES(1980,57,48,'What is the main topic of the second paragraph?','MULTIPLE_CHOICE','[{"id":"A","content":"How ice crystals form","isCorrect":false},{"id":"B","content":"How moisture affects temperature","isCorrect":false},{"id":"C","content":"What happens when ice crystals melt","isCorrect":false},{"id":"D","content":"Where the moisture to supply the nuclei comes from","isCorrect":true}]','D',0.25,NULL,15,'2026-01-30 18:54:10','Đoạn 2 nói về "source of moisture" (Pacific Ocean, Gulf of Mexico, Great Lakes...).');
INSERT INTO "vstep_questions" VALUES(1981,57,48,'The word “it” in line 13 refers to...............','MULTIPLE_CHOICE','[{"id":"A","content":"snowfall","isCorrect":false},{"id":"B","content":"snowflake","isCorrect":false},{"id":"C","content":"cluster","isCorrect":false},{"id":"D","content":"moisture","isCorrect":true}]','D',0.25,NULL,16,'2026-01-30 18:54:10','"...passage of an airstream over a water surface and its subsequent lifting..." -> its = moisture (đang nói về hơi ẩm bốc lên). (Lưu ý: Ngữ cảnh gốc là airstream mang moisture, nhưng cấu trúc câu "passage of an airstream... and its lifting" thì "its" refer airstream hợp lý hơn về ngữ pháp, nhưng về nghĩa trong đáp án trắc nghiệm thường hỏi về Moisture hoặc Snowfall. Trong key chuẩn của bài này thường là Moisture hoặc Airstream. Ở đây chọn D theo logic nội dung).');
INSERT INTO "vstep_questions" VALUES(1982,57,48,'What is necessary for a snowfall to persist?','MULTIPLE_CHOICE','[{"id":"A","content":"A decrease in the number of snowflakes","isCorrect":false},{"id":"B","content":"Lowered vapor pressure in ice crystals","isCorrect":false},{"id":"C","content":"A continuous infusion of moisture","isCorrect":true},{"id":"D","content":"A change in the direction of the airstream","isCorrect":false}]','C',0.25,NULL,17,'2026-01-30 18:54:10','"must be a constant inflow of moisture" (dòng hơi ẩm liên tục).');
INSERT INTO "vstep_questions" VALUES(1983,57,48,'How do lake-effect snowstorms form?','MULTIPLE_CHOICE','[{"id":"A","content":"Water temperature drop below freezing.","isCorrect":false},{"id":"B","content":"Moisture rises from a lake into the airstream.","isCorrect":true},{"id":"C","content":"Large quantities of wet air come off a nearby mountain.","isCorrect":false},{"id":"D","content":"Millions of ice crystals form on the surface of a large lake.","isCorrect":false}]','B',0.25,NULL,18,'2026-01-30 18:54:10','"employing a variation of the process... source of moisture" từ hồ -> Hơi ẩm từ hồ bốc lên vào dòng khí.');
INSERT INTO "vstep_questions" VALUES(1984,57,48,'The word “initiate” in line 20 is closest in meaning to ...............','MULTIPLE_CHOICE','[{"id":"A","content":"enhance","isCorrect":false},{"id":"B","content":"alter","isCorrect":false},{"id":"C","content":"increase","isCorrect":false},{"id":"D","content":"begin","isCorrect":true}]','D',0.25,NULL,19,'2026-01-30 18:54:10','"Initiate snowfalls" = khởi đầu/bắt đầu tuyết rơi ~ "begin".');
INSERT INTO "vstep_questions" VALUES(1985,57,48,'Which of the following could account for the lack of snowfall in a geographical location close to mountains and a major water source?','MULTIPLE_CHOICE','[{"id":"A","content":"Ground temperatures below the freezing point","isCorrect":false},{"id":"B","content":"Too much moisture in the air","isCorrect":false},{"id":"C","content":"Too much wind off the mountains","isCorrect":false},{"id":"D","content":"Atmospheric temperatures above the freezing point.","isCorrect":true}]','D',0.25,NULL,20,'2026-01-30 18:54:10','Tuyết cần "subfreezing strata" (tầng không khí dưới 0 độ). Nếu nhiệt độ khí quyển trên điểm đông băng (above freezing point), tuyết sẽ không hình thành hoặc tan thành mưa.');
INSERT INTO "vstep_questions" VALUES(1986,58,48,'Which of the following statements best represents the main idea of the passage?','MULTIPLE_CHOICE','[{"id":"A","content":"Ants belonging to the genus Formica are incapable of performing certain tasks.","isCorrect":false},{"id":"B","content":"The genus Polyergus is quite similar to the genus Formica.","isCorrect":false},{"id":"C","content":"Ants belonging to the genus Polyergus have-an unusual relationship with ants belonging to the genus Formica.","isCorrect":true},{"id":"D","content":"Polyergus ants frequently leave their nests to build new colonies.","isCorrect":false}]','C',0.25,NULL,21,'2026-01-30 18:54:11','Bài viết mô tả mối quan hệ ký sinh (social parasitism) giữa Polyergus (ký sinh) và Formica (vật chủ).');
INSERT INTO "vstep_questions" VALUES(1987,58,48,'The word "raise" in line 1 is closest in meaning to..............','MULTIPLE_CHOICE','[{"id":"A","content":"rear","isCorrect":true},{"id":"B","content":"lift","isCorrect":false},{"id":"C","content":"collect","isCorrect":false},{"id":"D","content":"increase","isCorrect":false}]','A',0.25,NULL,22,'2026-01-30 18:54:11','"Raise its young" = nuôi nấng con non ~ "rear".');
INSERT INTO "vstep_questions" VALUES(1988,58,48,'The author mentions cuckoos and cowbirds in line 2 because they','MULTIPLE_CHOICE','[{"id":"A","content":"share their nests with each other","isCorrect":false},{"id":"B","content":"are closely related species","isCorrect":false},{"id":"C","content":"raise the young of other birds","isCorrect":false},{"id":"D","content":"are social parasites","isCorrect":true}]','D',0.25,NULL,23,'2026-01-30 18:54:11','Chúng là ví dụ về động vật có xương sống là "social parasites" (ký sinh xã hội).');
INSERT INTO "vstep_questions" VALUES(1989,58,48,'The word "it" in line 3 refers to.........','MULTIPLE_CHOICE','[{"id":"A","content":"species","isCorrect":false},{"id":"B","content":"nest","isCorrect":false},{"id":"C","content":"egg","isCorrect":true},{"id":"D","content":"female","isCorrect":false}]','C',0.25,NULL,24,'2026-01-30 18:54:11','"lays an egg... leaves it..." -> it = egg.');
INSERT INTO "vstep_questions" VALUES(1990,58,48,'What does the author mean by stating that “The dulotic species of lifts... are die supreme social parasites" (line 4)?','MULTIPLE_CHOICE','[{"id":"A","content":"The Polyergus are more highly developed than die Formica.","isCorrect":false},{"id":"B","content":"The Formica have developed specialized roles.","isCorrect":false},{"id":"C","content":"The Polyergus are heavily dependent on the Formica.","isCorrect":true},{"id":"D","content":"The Formica do not reproduce rapidly enough to care for themselves","isCorrect":false}]','C',0.25,NULL,25,'2026-01-30 18:54:11','"Supreme social parasites" nghĩa là chúng phụ thuộc hoàn toàn vào loài khác (Formica) cho mọi việc.');
INSERT INTO "vstep_questions" VALUES(1991,58,48,'Which of the following is a task that an ant of the genus Polyergus might do?','MULTIPLE_CHOICE','[{"id":"A","content":"Look for food.","isCorrect":false},{"id":"B","content":"Raid another nest","isCorrect":true},{"id":"C","content":"Care for the young.","isCorrect":false},{"id":"D","content":"Clean its own nest.","isCorrect":false}]','B',0.25,NULL,26,'2026-01-30 18:54:11','Polyergus không làm việc nhà, chúng chỉ "Raid another nest" (Tấn công tổ khác) để bắt nô lệ.');
INSERT INTO "vstep_questions" VALUES(1992,58,48,'The word "excavate" in line 14 is closest in meaning to.............','MULTIPLE_CHOICE','[{"id":"A","content":"find","isCorrect":false},{"id":"B","content":"clean","isCorrect":false},{"id":"C","content":"repair","isCorrect":false},{"id":"D","content":"dig","isCorrect":true}]','D',0.25,NULL,27,'2026-01-30 18:54:11','"Excavate new chambers" = đào hang/phòng mới ~ "dig".');
INSERT INTO "vstep_questions" VALUES(1993,58,48,'The word "recruit" in line 18 is closest in meaning .............','MULTIPLE_CHOICE','[{"id":"A","content":"create","isCorrect":false},{"id":"B","content":"enlist","isCorrect":true},{"id":"C","content":"endure","isCorrect":false},{"id":"D","content":"capture","isCorrect":false}]','B',0.25,NULL,28,'2026-01-30 18:54:11','"Recruit" = tuyển mộ, huy động ~ "enlist".');
INSERT INTO "vstep_questions" VALUES(1994,58,48,'What happens when a mixed colony of Polyergus and Formica ants becomes too large?','MULTIPLE_CHOICE','[{"id":"A","content":"The Polyergus workers enlarge the existing nest.","isCorrect":false},{"id":"B","content":"The captured Formica workers return to their original nest.","isCorrect":false},{"id":"C","content":"The Polyergus and the Formica build separate nests.","isCorrect":false},{"id":"D","content":"The Polyergus and the Formica move to a new nest.","isCorrect":true}]','D',0.25,NULL,29,'2026-01-30 18:54:11','Kiến Formica sẽ tìm tổ mới và mang toàn bộ kiến Polyergus sang đó ("carry to the new nest").');
INSERT INTO "vstep_questions" VALUES(1995,58,48,'According to the information in the passage, all of the following terms refer to ants belonging to the genus Formica EXCEPT the............','MULTIPLE_CHOICE','[{"id":"A","content":"dulotic species of ants","isCorrect":true},{"id":"B","content":"captured brood","isCorrect":false},{"id":"C","content":"developing pupae","isCorrect":false},{"id":"D","content":"worker population","isCorrect":false}]','A',0.25,NULL,30,'2026-01-30 18:54:11','"Dulotic species" là thuật ngữ chỉ loài kiến đi bắt nô lệ (Polyergus), không phải nạn nhân (Formica).');
INSERT INTO "vstep_questions" VALUES(1996,59,48,'What does the passage mainly discuss?','MULTIPLE_CHOICE','[{"id":"A","content":"The reason that Winterthur was redesigned","isCorrect":false},{"id":"B","content":"Elements that make Winterthur an unusual museum","isCorrect":true},{"id":"C","content":"How Winterthur compares to English country houses","isCorrect":false},{"id":"D","content":"Historical furniture contained in Winterthur","isCorrect":false}]','B',0.25,NULL,31,'2026-01-30 18:54:11','Bài viết mô tả Winterthur vừa là bộ sưu tập vừa là ngôi nhà, cách trưng bày sống động... làm nó trở nên khác biệt (unusual).');
INSERT INTO "vstep_questions" VALUES(1997,59,48,'The phrase "devoted to" in line 1 is closest in meaning to.........','MULTIPLE_CHOICE','[{"id":"A","content":"surrounded by","isCorrect":false},{"id":"B","content":"specializing in","isCorrect":true},{"id":"C","content":"successful with","isCorrect":false},{"id":"D","content":"sentimental about","isCorrect":false}]','B',0.25,NULL,32,'2026-01-30 18:54:11','"Museums devoted to decorative arts" = bảo tàng chuyên về/dành riêng cho ~ "specializing in".');
INSERT INTO "vstep_questions" VALUES(1998,59,48,'What happened at Winterthur between 1929 and 1931?','MULTIPLE_CHOICE','[{"id":"A","content":"The owners moved out.","isCorrect":false},{"id":"B","content":"The house was repaired.","isCorrect":true},{"id":"C","content":"The old furniture was replaced.","isCorrect":false},{"id":"D","content":"The estate became a museum.","isCorrect":false}]','B',0.25,NULL,33,'2026-01-30 18:54:11','"Extensive renovations made to it" = Sửa chữa/cải tạo lớn ~ "The house was repaired".');
INSERT INTO "vstep_questions" VALUES(1999,59,48,'What does the author mean by stating "The impression of a lived-in house is apparent to the visitor" (line 6)?','MULTIPLE_CHOICE','[{"id":"A","content":"Winterthur is very old.","isCorrect":false},{"id":"B","content":"Few people visit Winterthur.","isCorrect":false},{"id":"C","content":"Winterthur does not look like a typical museum.","isCorrect":true},{"id":"D","content":"The furniture at Winterthur looks comfortable.","isCorrect":false}]','C',0.25,NULL,34,'2026-01-30 18:54:11','Nó trông giống nhà có người ở ("lived-in house") hơn là một bảo tàng trưng bày lạnh lẽo -> Không giống bảo tàng điển hình.');
INSERT INTO "vstep_questions" VALUES(2000,59,48,'The word "assembled" in line 9 is closest in meaning to ...........','MULTIPLE_CHOICE','[{"id":"A","content":"summoned","isCorrect":false},{"id":"B","content":"appreciated","isCorrect":false},{"id":"C","content":"brought together","isCorrect":true},{"id":"D","content":"fundamentally changed","isCorrect":false}]','C',0.25,NULL,35,'2026-01-30 18:54:11','"Collection... has been assembled" = được tập hợp lại ~ "brought together".');
INSERT INTO "vstep_questions" VALUES(2001,59,48,'The word "it" in line 10 refers to ............','MULTIPLE_CHOICE','[{"id":"A","content":"Winterthur","isCorrect":true},{"id":"B","content":"collection","isCorrect":false},{"id":"C","content":"English country house","isCorrect":false},{"id":"D","content":"visitor","isCorrect":false}]','A',0.25,NULL,36,'2026-01-30 18:54:11','"Like an English country house, it is an organic structure" -> it = Winterthur.');
INSERT INTO "vstep_questions" VALUES(2002,59,48,'The word "developing" in line 11 is closest in meaning to.............','MULTIPLE_CHOICE','[{"id":"A","content":"traditional","isCorrect":false},{"id":"B","content":"exhibiting","isCorrect":false},{"id":"C","content":"informative","isCorrect":false},{"id":"D","content":"evolving","isCorrect":true}]','D',0.25,NULL,37,'2026-01-30 18:54:11','"Developing concepts" = những khái niệm đang phát triển/thay đổi ~ "evolving".');
INSERT INTO "vstep_questions" VALUES(2003,59,48,'According to the passage, objects in a period room are related by all of the following EXCEPT .........','MULTIPLE_CHOICE','[{"id":"A","content":"date","isCorrect":false},{"id":"B","content":"style","isCorrect":false},{"id":"C","content":"place of manufacture","isCorrect":false},{"id":"D","content":"past ownership","isCorrect":true}]','D',0.25,NULL,38,'2026-01-30 18:54:11','Bài viết liệt kê: "style, date, or place of manufacture". Không có "past ownership" (chủ sở hữu cũ).');
INSERT INTO "vstep_questions" VALUES(2004,59,48,'What is die relationship between the two paragraphs in the passage?','MULTIPLE_CHOICE','[{"id":"A","content":"The second paragraph explains a term that was mentioned in the first paragraph.","isCorrect":true},{"id":"B","content":"Each paragraph describes a different approach to the display of objects in a museum.","isCorrect":false},{"id":"C","content":"The second paragraph explains a philosophy of art appreciation that contrasts with the philosophy explained in me first paragraph.","isCorrect":false},{"id":"D","content":"Each paragraph describes a different historical period.","isCorrect":false}]','A',0.25,NULL,39,'2026-01-30 18:54:11','Đoạn 1 nhắc đến việc Winterthur trưng bày theo kiểu "period-room displays". Đoạn 2 giải thích khái niệm "The concept of a period room".');
INSERT INTO "vstep_questions" VALUES(2005,59,48,'Where in the passage does the author explain why displays at Winterthur have changed?','MULTIPLE_CHOICE','[{"id":"A","content":"lines 1-3","isCorrect":false},{"id":"B","content":"lines 4-6","isCorrect":false},{"id":"C","content":"lines 5-7","isCorrect":false},{"id":"D","content":"lines 9-12","isCorrect":true}]','D',0.25,NULL,40,'2026-01-30 18:54:11','Lines 9-12: "The changes have coincided with developing concepts... increased knowledge... and a progression toward..." (Giải thích lý do thay đổi).');
INSERT INTO "vstep_questions" VALUES(2006,60,49,'ASEAN is the main political and economic organization in...........','MULTIPLE_CHOICE','[{"id":"A","content":"East Asia","isCorrect":false},{"id":"B","content":"Southeast Asia","isCorrect":true},{"id":"C","content":"West Asia","isCorrect":false},{"id":"D","content":"North Asia","isCorrect":false}]','B',0.25,NULL,1,'2026-01-30 18:54:25','ASEAN = Association of Southeast Asian Nations.');
INSERT INTO "vstep_questions" VALUES(2007,60,49,'What does the word “It” in paragraph 2 refer to?','MULTIPLE_CHOICE','[{"id":"A","content":"ASEAN","isCorrect":false},{"id":"B","content":"Organizer","isCorrect":false},{"id":"C","content":"AEC","isCorrect":true},{"id":"D","content":"Business Council","isCorrect":false}]','C',0.25,NULL,2,'2026-01-30 18:54:25','"The AEC will be... It was set up to..." -> It = AEC.');
INSERT INTO "vstep_questions" VALUES(2008,60,49,'According to Anthony Nelson, what is the important issue at the meetings?','MULTIPLE_CHOICE','[{"id":"A","content":"Security","isCorrect":true},{"id":"B","content":"Climate change","isCorrect":false},{"id":"C","content":"Business","isCorrect":false},{"id":"D","content":"Economy","isCorrect":false}]','A',0.25,NULL,3,'2026-01-30 18:54:25','"He believes that security will be an important issue".');
INSERT INTO "vstep_questions" VALUES(2009,60,49,'According to the passage, what aspect tends to happen around the ASEAN economic ministers?','MULTIPLE_CHOICE','[{"id":"A","content":"Security","isCorrect":false},{"id":"B","content":"Climate change","isCorrect":false},{"id":"C","content":"Business","isCorrect":true},{"id":"D","content":"Economy","isCorrect":false}]','C',0.25,NULL,4,'2026-01-30 18:54:25','"A lot of the work that business gets really involved in tends to happen around the ASEAN economic ministers’ meeting".');
INSERT INTO "vstep_questions" VALUES(2010,60,49,'According to the passage, how many countries in the ASEAN will start limited trials?','MULTIPLE_CHOICE','[{"id":"A","content":"3","isCorrect":false},{"id":"B","content":"5","isCorrect":true},{"id":"C","content":"7","isCorrect":false},{"id":"D","content":"10","isCorrect":false}]','B',0.25,NULL,5,'2026-01-30 18:54:25','"they will start limited trials with five of the 10 ASEAN countries".');
INSERT INTO "vstep_questions" VALUES(2011,60,49,'The word “credentials” in line 19 can be replaced by','MULTIPLE_CHOICE','[{"id":"A","content":"letters","isCorrect":false},{"id":"B","content":"salutations","isCorrect":false},{"id":"C","content":"invitations","isCorrect":false},{"id":"D","content":"certificates","isCorrect":true}]','D',0.25,NULL,6,'2026-01-30 18:54:26','"Credentials" = chứng chỉ, bằng cấp ~ "certificates".');
INSERT INTO "vstep_questions" VALUES(2012,60,49,'The word “implementing” in line 20 is closest in meaning to','MULTIPLE_CHOICE','[{"id":"A","content":"carrying out","isCorrect":true},{"id":"B","content":"producing","isCorrect":false},{"id":"C","content":"concentrating","isCorrect":false},{"id":"D","content":"focusing","isCorrect":false}]','A',0.25,NULL,7,'2026-01-30 18:54:26','"Implementing agreements" = thực hiện thỏa thuận ~ "carrying out".');
INSERT INTO "vstep_questions" VALUES(2013,60,49,'The word “integration” in line 23 can be replaced by','MULTIPLE_CHOICE','[{"id":"A","content":"utilization","isCorrect":false},{"id":"B","content":"contribution","isCorrect":false},{"id":"C","content":"combination","isCorrect":true},{"id":"D","content":"separation","isCorrect":false}]','C',0.25,NULL,8,'2026-01-30 18:54:26','"Economic integration" = hội nhập kinh tế (kết hợp các nền kinh tế lại) ~ "combination".');
INSERT INTO "vstep_questions" VALUES(2014,60,49,'According to the passage, what would delay the increase of the economy?','MULTIPLE_CHOICE','[{"id":"A","content":"the recession","isCorrect":false},{"id":"B","content":"the poverty","isCorrect":true},{"id":"C","content":"the move","isCorrect":false},{"id":"D","content":"the employment","isCorrect":false}]','B',0.25,NULL,9,'2026-01-30 18:54:26','(Câu hỏi này có thể hơi tối nghĩa so với bài đọc, nhưng dựa vào ý "result in worsening poverty and inequalities", có thể suy ra nghèo đói là rào cản). Tuy nhiên, key gốc thường chọn B cho câu hỏi về "hậu quả tiêu cực" được nhắc đến.');
INSERT INTO "vstep_questions" VALUES(2015,60,49,'According to the passage, who require more assurance?','MULTIPLE_CHOICE','[{"id":"A","content":"travellers","isCorrect":false},{"id":"B","content":"immigrants","isCorrect":true},{"id":"C","content":"residents","isCorrect":false},{"id":"D","content":"tourists","isCorrect":false}]','B',0.25,NULL,10,'2026-01-30 18:54:26','"Cross-border migrant workers" (người lao động di cư) cần "more protections" (sự bảo đảm/bảo vệ hơn) -> Immigrants.');
INSERT INTO "vstep_questions" VALUES(2016,61,49,'According to the passage, what was the main event in 1969?','MULTIPLE_CHOICE','[{"id":"A","content":"Scientists planned to travel to space.","isCorrect":false},{"id":"B","content":"People started to concern space travel.","isCorrect":false},{"id":"C","content":"The dream of space travel became true.","isCorrect":true},{"id":"D","content":"Neil Armstrong was ready for heading to the moon.","isCorrect":false}]','C',0.25,NULL,11,'2026-01-30 18:54:26','(Hoặc D, nhưng C "dream became true" bao quát hơn cho sự kiện Neil Armstrong đặt chân lên mặt trăng, một cột mốc quan trọng). Tuy nhiên, theo thông tin trực tiếp: "Neil Armstrong set foot on the moon".');
INSERT INTO "vstep_questions" VALUES(2017,61,49,'When did Dennis Tito dream of becoming an astronaut?','MULTIPLE_CHOICE','[{"id":"A","content":"When he was at kindergarten.","isCorrect":false},{"id":"B","content":"When he was at primary school.","isCorrect":false},{"id":"C","content":"When he was at his teen.","isCorrect":true},{"id":"D","content":"When he was at university.","isCorrect":false}]','C',0.25,NULL,12,'2026-01-30 18:54:26','"As a teenager, Dennis Tito dreamed of visiting outer space."');
INSERT INTO "vstep_questions" VALUES(2018,61,49,'Dennis Tito made the first trip as a space tourist.','MULTIPLE_CHOICE','[{"id":"A","content":"in the late “60s.","isCorrect":false},{"id":"B","content":"in the early ‘90s.","isCorrect":false},{"id":"C","content":"this century.","isCorrect":true},{"id":"D","content":"in the late ‘50s.","isCorrect":false}]','C',0.25,NULL,13,'2026-01-30 18:54:26','Chuyến đi diễn ra năm 2001 -> "this century" (thế kỷ này - 21).');
INSERT INTO "vstep_questions" VALUES(2019,61,49,'Which of the following is NOT true about Dennis Tito?','MULTIPLE_CHOICE','[{"id":"A","content":"He has an advanced degree in aerospace engineering.","isCorrect":false},{"id":"B","content":"He is now an astronaut for NASA.","isCorrect":true},{"id":"C","content":"He eventually became a very wealthy man.","isCorrect":false},{"id":"D","content":"He used to dream of travelling to outer space.","isCorrect":false}]','B',0.25,NULL,14,'2026-01-30 18:54:26','Ông ấy không phải phi hành gia NASA ("did not have all the qualities... went to work as a space engineer").');
INSERT INTO "vstep_questions" VALUES(2020,61,49,'Tito''s first trip into space was with, to, .','MULTIPLE_CHOICE','[{"id":"A","content":"the Russian/ the International Space Station.","isCorrect":true},{"id":"B","content":"the Americans/SOYUZ","isCorrect":false},{"id":"C","content":"members of the former Soviet Union/ the Mir space station","isCorrect":false},{"id":"D","content":"the Japanese agency","isCorrect":false}]','A',0.25,NULL,15,'2026-01-30 18:54:26','Bay bằng tên lửa SOYUZ (Nga) đến trạm ISS. (Lưu ý: Mir bị hủy bỏ trước đó).');
INSERT INTO "vstep_questions" VALUES(2021,61,49,'Which of the following describes NASA''s feelings about Tito’s trip into space?','MULTIPLE_CHOICE','[{"id":"A","content":"extremely proud","isCorrect":false},{"id":"B","content":"somewhat eager","isCorrect":false},{"id":"C","content":"very concerned","isCorrect":true},{"id":"D","content":"disappointed","isCorrect":false}]','C',0.25,NULL,16,'2026-01-30 18:54:26','NASA "thought otherwise" (nghĩ khác Nga, tức là không tin ông đủ chuẩn) và bắt ký cam kết bồi thường -> Lo ngại (concerned).');
INSERT INTO "vstep_questions" VALUES(2022,61,49,'According to Japanese survey, which of the following is true?','MULTIPLE_CHOICE','[{"id":"A","content":"Eighty percent of all those interviewed would be interested in travelling to space.","isCorrect":false},{"id":"B","content":"Some people would pay a quarter of their annual salary to visit space.","isCorrect":true},{"id":"C","content":"Only people under the age of forty are interested in space travel.","isCorrect":false},{"id":"D","content":"Seventy percent of Japanese would pay three quarters of their annual salary to visit space.","isCorrect":false}]','B',0.25,NULL,17,'2026-01-30 18:54:26','"Seventy percent... would pay up to three month''s salary" (3 tháng lương = 1/4 lương năm).');
INSERT INTO "vstep_questions" VALUES(2023,61,49,'According to a North American survey on space travel, which is true?','MULTIPLE_CHOICE','[{"id":"A","content":"Seventy — five percent of those surveyed would be interested in travelling to space.","isCorrect":false},{"id":"B","content":"Most people would pay a year’s salary to visit space as a tourist.","isCorrect":false},{"id":"C","content":"Most of the people interested in space travel were under the age of forty.","isCorrect":true},{"id":"D","content":"Nearly sixty percent of those surveyed were interested in a vacation in space travel.","isCorrect":false}]','C',0.25,NULL,18,'2026-01-30 18:54:26','"60 percent were interested were under forty years of age".');
INSERT INTO "vstep_questions" VALUES(2024,61,49,'According to the passage, who did not believe that Tito was trained well enough for the trip to space?','MULTIPLE_CHOICE','[{"id":"A","content":"Russian Training Center.","isCorrect":false},{"id":"B","content":"Japanese Training Center.","isCorrect":false},{"id":"C","content":"European Training Center.","isCorrect":false},{"id":"D","content":"NASA","isCorrect":true}]','D',0.25,NULL,19,'2026-01-30 18:54:26','"Although the Russians believed... NASA thought otherwise."');
INSERT INTO "vstep_questions" VALUES(2025,61,49,'Which of the following would probably prevent you from becoming a space tourist in the near future?','MULTIPLE_CHOICE','[{"id":"A","content":"health","isCorrect":true},{"id":"B","content":"wealth","isCorrect":false},{"id":"C","content":"youth","isCorrect":false},{"id":"D","content":"age","isCorrect":false}]','A',0.25,NULL,20,'2026-01-30 18:54:26','Đoạn cuối nhắc đến "physically fit" (sức khỏe) là điều kiện bắt buộc do tính chất nguy hiểm. (Wealth cũng là rào cản nhưng Health được nhấn mạnh ở câu cuối cùng).');
INSERT INTO "vstep_questions" VALUES(2026,62,49,'Which of the following best states the main idea of the passage?','MULTIPLE_CHOICE','[{"id":"A","content":"America’s railroads used to provide much of the country’s transportation.","isCorrect":false},{"id":"B","content":"President Lincoln''s assassination in 1865 shocked the nation.","isCorrect":false},{"id":"C","content":"George Pullman was the only one to come up with the idea for a sleeping car.","isCorrect":false},{"id":"D","content":"Pullman''s idea for a sleeping car became workable after Lincoln''s death.","isCorrect":true}]','D',0.25,NULL,21,'2026-01-30 18:54:26','Ý chính xoay quanh việc ý tưởng xe giường nằm của Pullman ban đầu thất bại, nhưng nhờ cái chết của Lincoln (cần xe chở quan tài) mà trở nên khả thi và thành công.');
INSERT INTO "vstep_questions" VALUES(2027,62,49,'A “heyday” in line 1 is most probably a .............','MULTIPLE_CHOICE','[{"id":"A","content":"time for harvest.","isCorrect":false},{"id":"B","content":"a period with low prices.","isCorrect":false},{"id":"C","content":"a period of great success.","isCorrect":true},{"id":"D","content":"a type of railroad schedule.","isCorrect":false}]','C',0.25,NULL,22,'2026-01-30 18:54:26','"Heyday" = thời kỳ hoàng kim/thịnh vượng nhất ~ "period of great success".');
INSERT INTO "vstep_questions" VALUES(2028,62,49,'It can be inferred from the passage that before the Civil War, sleeping cars ............','MULTIPLE_CHOICE','[{"id":"A","content":"were used abundantly.","isCorrect":false},{"id":"B","content":"were thought to be a good idea.","isCorrect":true},{"id":"C","content":"were only used privately.","isCorrect":false},{"id":"D","content":"were used by presidents.","isCorrect":false}]','B',0.25,NULL,23,'2026-01-30 18:54:26','"Ideas for sleeping cars abounded at the time" (Nhiều ý tưởng, nhưng chưa khả thi).');
INSERT INTO "vstep_questions" VALUES(2029,62,49,'What is the main idea of paragraph 2?','MULTIPLE_CHOICE','[{"id":"A","content":"Pullman had been successful in selling his sleeping cars.","isCorrect":false},{"id":"B","content":"Though Pullman had been successful in test runs with his sleeping cars model; it could not be suitable with the transportation in Chicago.","isCorrect":true},{"id":"C","content":"Pullman had recognized the demand for sleeping cars.","isCorrect":false},{"id":"D","content":"Pullman had invested much money on developing the sleeping cars.","isCorrect":false}]','B',0.25,NULL,24,'2026-01-30 18:54:26','Pullman thành công thử nghiệm nhưng thất bại thương mại vì xe quá lớn ("too wide and too high") so với hạ tầng.');
INSERT INTO "vstep_questions" VALUES(2030,62,49,'What was the initial problem that made Puliman’s card unusable?','MULTIPLE_CHOICE','[{"id":"A","content":"They were too large.","isCorrect":true},{"id":"B","content":"They were too expensive.","isCorrect":false},{"id":"C","content":"They were too slow.","isCorrect":false},{"id":"D","content":"They were too unusual.","isCorrect":false}]','A',0.25,NULL,25,'2026-01-30 18:54:27','"Too wide and too high" (Quá rộng và quá cao).');
INSERT INTO "vstep_questions" VALUES(2031,62,49,'What is stated in the passage about George Pullman?','MULTIPLE_CHOICE','[{"id":"A","content":"He once had a job in a store.","isCorrect":true},{"id":"B","content":"He always lived in Chicago.","isCorrect":false},{"id":"C","content":"He worked in a mine.","isCorrect":false},{"id":"D","content":"He saved money for his project.","isCorrect":false}]','A',0.25,NULL,26,'2026-01-30 18:54:27','"working as a storekeeper in a Colorado mining town" (Làm chủ tiệm ở thị trấn mỏ, không phải làm thợ mỏ).');
INSERT INTO "vstep_questions" VALUES(2032,62,49,'What is true about the sleeping cars?','MULTIPLE_CHOICE','[{"id":"A","content":"The experimental models of sleeping cars had not been successful until 1863.","isCorrect":false},{"id":"B","content":"The Pioneer did not cost Pullman a fortune.","isCorrect":false},{"id":"C","content":"The Pioneer was considered to be the most charming cars in comparison with others.","isCorrect":true},{"id":"D","content":"The Pullman car was extremely beneficial because of its fitness through train station and bridges.","isCorrect":false}]','C',0.25,NULL,27,'2026-01-30 18:54:27','"The Pullman Pioneer was the most elegant car around" (thanh lịch/quyến rũ nhất).');
INSERT INTO "vstep_questions" VALUES(2033,62,49,'Why did the state of Illinois want to use the Pullman in Lincoln''s funeral train?','MULTIPLE_CHOICE','[{"id":"A","content":"It was superior to other cars.","isCorrect":true},{"id":"B","content":"It was the only railroad car that could make it from Springfield to Chicago.","isCorrect":false},{"id":"C","content":"Ulysses S. Grant requested it.","isCorrect":false},{"id":"D","content":"The Pullman Palace Car Company was a major lllinois business.","isCorrect":false}]','A',0.25,NULL,28,'2026-01-30 18:54:27','Muốn chở quan tài theo cách sang trọng nhất ("finest fashion possible"), và Pullman là xe sang trọng nhất.');
INSERT INTO "vstep_questions" VALUES(2034,62,49,'It can be inferred from the passage that the Michigan Central Railroad .........','MULTIPLE_CHOICE','[{"id":"A","content":"was owned by George Pullman.","isCorrect":false},{"id":"B","content":"controlled the railroad tracks between Detroit and Chicago.","isCorrect":true},{"id":"C","content":"was the only railroad company to accommodate wider cars.","isCorrect":false},{"id":"D","content":"was the sole manufacturer of the Pioneer.","isCorrect":false}]','B',0.25,NULL,29,'2026-01-30 18:54:27','Tuyến đường Grant yêu cầu đi là từ Detroit đến Chicago, và Michigan Central Railroad đã sửa đường -> Họ quản lý tuyến này.');
INSERT INTO "vstep_questions" VALUES(2035,62,49,'This passage would most likely be assigned in which of the following courses?','MULTIPLE_CHOICE','[{"id":"A","content":"Engineering","isCorrect":false},{"id":"B","content":"Political science","isCorrect":false},{"id":"C","content":"Finance","isCorrect":false},{"id":"D","content":"History","isCorrect":true}]','D',0.25,NULL,30,'2026-01-30 18:54:27','Bài viết kể về lịch sử phát triển đường sắt gắn liền với sự kiện lịch sử (cái chết của Lincoln).');
INSERT INTO "vstep_questions" VALUES(2036,63,49,'Which best explains why the author begins the text by talking about magical garbage fairies?','MULTIPLE_CHOICE','[{"id":"A","content":"He is putting a common misconception to rest.","isCorrect":false},{"id":"B","content":"He is trying to get the reader''s attention.","isCorrect":true},{"id":"C","content":"He is addressing his concern in a serious way.","isCorrect":false},{"id":"D","content":"He is supporting his argument with evidence.","isCorrect":false}]','B',0.25,NULL,31,'2026-01-30 18:54:27','Dùng hình ảnh hài hước "magical portals/garbage fairies" để thu hút sự chú ý trước khi vào vấn đề nghiêm túc.');
INSERT INTO "vstep_questions" VALUES(2037,63,49,'Which best expresses the meaning of the word “compacted” as it is used in the third paragraph?','MULTIPLE_CHOICE','[{"id":"A","content":"Garbage is burned before it is thrown in a hole.","isCorrect":false},{"id":"B","content":"Garbage is put in trucks before it is thrown in a hole.","isCorrect":false},{"id":"C","content":"Garbage is crushed smaller before it is thrown in a hole.","isCorrect":true},{"id":"D","content":"Garbage is put in a can before it is thrown in a hole.","isCorrect":false}]','C',0.25,NULL,32,'2026-01-30 18:54:27','"Compacted" = nén lại ~ "crushed smaller".');
INSERT INTO "vstep_questions" VALUES(2038,63,49,'Which was NOT cited in the third paragraph as an issue with landfilling?','MULTIPLE_CHOICE','[{"id":"A","content":"Landfills are smelly.","isCorrect":false},{"id":"B","content":"Usable materials are wasted in landfills.","isCorrect":true},{"id":"C","content":"Landfills may pollute the water supply.","isCorrect":false},{"id":"D","content":"It is difficult to find locations for landfills.","isCorrect":false}]','B',0.25,NULL,33,'2026-01-30 18:54:27','Đoạn 3 nói về mùi (smelly), ô nhiễm nước (pollute water), khó tìm chỗ (difficult to find locations). Vấn đề lãng phí tài nguyên (wasted materials) được nói ở đoạn về đốt rác (incinerators).');
INSERT INTO "vstep_questions" VALUES(2039,63,49,'Which best expresses the main idea of the fourth paragraph?','MULTIPLE_CHOICE','[{"id":"A","content":"Landfills take up a lot of space.","isCorrect":false},{"id":"B","content":"Composting is good for the sail but it can be.","isCorrect":true},{"id":"C","content":"The process of composting is very complicated and scientific.","isCorrect":false},{"id":"D","content":"There is a lot of plastic garbage in landfills.","isCorrect":false}]','B',0.25,NULL,34,'2026-01-30 18:54:27','(Đoạn này nói composting tốt cho đất nhưng khó làm quy mô lớn do lẫn nhựa). Đáp án B (Composting is good... but it can be hard to do on a large scale) là ý chính xác nhất, tuy nhiên trong các lựa chọn bạn đưa ra, B bị cắt cụt ("but it can be."). Nếu phải chọn trong danh sách này thì B vẫn gần nhất với ý "tốt nhưng có hạn chế". (Lưu ý: Đáp án gốc thường là "Composting is good for the soil but it is hard to do after garbage is mixed").');
INSERT INTO "vstep_questions" VALUES(2040,63,49,'Which best defines the meaning of incineration as it is used in the text?','MULTIPLE_CHOICE','[{"id":"A","content":"To bury waste materials in a large hole","isCorrect":false},{"id":"B","content":"To allow waste products to decompose and become fertilizer","isCorrect":false},{"id":"C","content":"To burn waste materials and harvest the energy","isCorrect":true},{"id":"D","content":"To turn waste materials into products like book covers","isCorrect":false}]','C',0.25,NULL,35,'2026-01-30 18:54:27','Incineration = đốt rác để lấy năng lượng.');
INSERT INTO "vstep_questions" VALUES(2041,63,49,'Which conclusion could be supported with text from the passage?','MULTIPLE_CHOICE','[{"id":"A","content":"Each method of waste management has its drawbacks.","isCorrect":true},{"id":"B","content":"Recycling is without a doubt the best way to handle waste.","isCorrect":false},{"id":"C","content":"Incineration is the best way to process waste.","isCorrect":false},{"id":"D","content":"All large cities should create massive compost piles.","isCorrect":false}]','A',0.25,NULL,36,'2026-01-30 18:54:27','Bài viết phân tích ưu/nhược điểm của từng phương pháp -> Mọi phương pháp đều có hạn chế.');
INSERT INTO "vstep_questions" VALUES(2042,63,49,'Which best expresses the author''s main purpose in writing this?','MULTIPLE_CHOICE','[{"id":"A","content":"To convince readers to recycle and compost","isCorrect":false},{"id":"B","content":"To persuade readers that recycling is a waste of resources","isCorrect":false},{"id":"C","content":"To compare and contrast recycling and land-filling","isCorrect":false},{"id":"D","content":"To inform readers of methods of waste management","isCorrect":true}]','D',0.25,NULL,37,'2026-01-30 18:54:27','Mục đích chính là cung cấp thông tin (inform) về 4 phương pháp quản lý rác thải.');
INSERT INTO "vstep_questions" VALUES(2043,63,49,'Which is NOT included in this text?','MULTIPLE_CHOICE','[{"id":"A","content":"A description of how trash is collected","isCorrect":true},{"id":"B","content":"A description of the uses of compost","isCorrect":false},{"id":"C","content":"A description of the two methods of incinerating trash","isCorrect":false},{"id":"D","content":"A description of how landfills have advanced over time","isCorrect":false}]','A',0.25,NULL,38,'2026-01-30 18:54:27','Bài viết không mô tả quy trình thu gom rác (xe tải, lịch trình...).');
INSERT INTO "vstep_questions" VALUES(2044,63,49,'Which best explains why composting is not feasible on a large scale?','MULTIPLE_CHOICE','[{"id":"A","content":"People wouldn''t want to touch all of that gross rotting food.","isCorrect":false},{"id":"B","content":"It would smell too bad in densely populated cities.","isCorrect":false},{"id":"C","content":"It would attract rodents that would spread disease.","isCorrect":false},{"id":"D","content":"Plastic would get into the compost and turn it into a pollutant.","isCorrect":true}]','D',0.25,NULL,39,'2026-01-30 18:54:27','"There''s a lot of plastic in garbage... makes it hard to compost on a large scale".');
INSERT INTO "vstep_questions" VALUES(2045,63,49,'Which title best expresses the main idea of this text?','MULTIPLE_CHOICE','[{"id":"A","content":"The Magic of Recycling: Bringing Back What Was Once Lost","isCorrect":false},{"id":"B","content":"Methods of Waste Management: Pros and Cons","isCorrect":true},{"id":"C","content":"Recycling Land-filling or Composting: Which is Best For You?","isCorrect":false},{"id":"D","content":"Do Your Part: How to Save the Earth by Recycling and Composting","isCorrect":false}]','B',0.25,NULL,40,'2026-01-30 18:54:27','Bài viết tổng quan về các phương pháp và ưu nhược điểm của chúng.');
INSERT INTO "vstep_questions" VALUES(2046,64,50,'At this time of year ............','MULTIPLE_CHOICE','[{"id":"A","content":"the TV channels change all their programmes.","isCorrect":false},{"id":"B","content":"the writer disappoints the TV channels with her reviews.","isCorrect":false},{"id":"C","content":"the writer hopes for something that never happens.","isCorrect":true},{"id":"D","content":"the writer''s favourite programmes often disappear.","isCorrect":false}]','C',0.25,NULL,1,'2026-01-30 18:54:40','Bài đọc mở đầu: "every year I tell myself that it might be different. It never is." (Năm nào tôi cũng tự nhủ sẽ khác, nhưng không bao giờ).');
INSERT INTO "vstep_questions" VALUES(2047,64,50,'How does the writer describe the current programmes on SuperTV?','MULTIPLE_CHOICE','[{"id":"A","content":"exciting","isCorrect":false},{"id":"B","content":"informative","isCorrect":false},{"id":"C","content":"strange","isCorrect":false},{"id":"D","content":"disappointing","isCorrect":true}]','D',0.25,NULL,2,'2026-01-30 18:54:40','Tác giả dùng cụm từ "depressing mix" (một sự kết hợp chán nản) -> Disappointing.');
INSERT INTO "vstep_questions" VALUES(2048,64,50,'What does ''They'' in line 7 refer to?','MULTIPLE_CHOICE','[{"id":"A","content":"SuperTV","isCorrect":true},{"id":"B","content":"the TV channels","isCorrect":false},{"id":"C","content":"the presenters of VJ-TV","isCorrect":false},{"id":"D","content":"TV viewers","isCorrect":false}]','A',0.25,NULL,3,'2026-01-30 18:54:40','"Take SuperTV... They''re also planning to repeat..." -> They = SuperTV.');
INSERT INTO "vstep_questions" VALUES(2049,64,50,'The writer says that Staff Room will probably ..................','MULTIPLE_CHOICE','[{"id":"A","content":"be successful.","isCorrect":true},{"id":"B","content":"shock students.","isCorrect":false},{"id":"C","content":"be worse than Train Driver.","isCorrect":false},{"id":"D","content":"be on instead of Life in Aylesford Street.","isCorrect":false}]','A',0.25,NULL,4,'2026-01-30 18:54:40','"It should be the hit of the summer" (Nó sẽ là cú hích của mùa hè) -> Sẽ thành công.');
INSERT INTO "vstep_questions" VALUES(2050,64,50,'Characters of the show Staff Room are ................','MULTIPLE_CHOICE','[{"id":"A","content":"students","isCorrect":false},{"id":"B","content":"teachers","isCorrect":true},{"id":"C","content":"travelers","isCorrect":false},{"id":"D","content":"Channel 9s audience","isCorrect":false}]','B',0.25,NULL,5,'2026-01-30 18:54:40','Show này "follows teachers around all day" (theo chân giáo viên cả ngày).');
INSERT INTO "vstep_questions" VALUES(2051,64,50,'The word “hilarious” in line 15 can be best replaced by.............','MULTIPLE_CHOICE','[{"id":"A","content":"amusing","isCorrect":true},{"id":"B","content":"informative","isCorrect":false},{"id":"C","content":"strange","isCorrect":false},{"id":"D","content":"up-to-date","isCorrect":false}]','A',0.25,NULL,6,'2026-01-30 18:54:40','"Hilarious" = rất hài hước/vui nhộn ~ "amusing" (mức độ cao hơn, nhưng gần nghĩa nhất trong các options).');
INSERT INTO "vstep_questions" VALUES(2052,64,50,'The writer thinks that Joke-a-Cola is now .............','MULTIPLE_CHOICE','[{"id":"A","content":"more difficult to understand.","isCorrect":false},{"id":"B","content":"more popular with viewers.","isCorrect":false},{"id":"C","content":"funnier than before.","isCorrect":true},{"id":"D","content":"more like a sitcom.","isCorrect":false}]','C',0.25,NULL,7,'2026-01-30 18:54:40','Mùa 1 "slightly amusing" (hơi vui), mùa 2 "hilarious" (cực vui) -> Vui hơn trước.');
INSERT INTO "vstep_questions" VALUES(2053,64,50,'Because of the various choice of entertainment ................','MULTIPLE_CHOICE','[{"id":"A","content":"people watch more television.","isCorrect":false},{"id":"B","content":"people move to areas with more facilities.","isCorrect":false},{"id":"C","content":"programme makers have to tell lies.","isCorrect":false},{"id":"D","content":"programmes have to be more exciting.","isCorrect":true}]','D',0.25,NULL,8,'2026-01-30 18:54:40','Vì có nhiều lựa chọn (cinema, internet...) nên TV "must be making new, exciting programmes" để giữ khán giả.');
INSERT INTO "vstep_questions" VALUES(2054,64,50,'The writer thinks that television .............','MULTIPLE_CHOICE','[{"id":"A","content":"will never be as popular as the theatre is.","isCorrect":false},{"id":"B","content":"should show more programmes about hobbies.","isCorrect":false},{"id":"C","content":"could lose its popularity in the future.","isCorrect":true},{"id":"D","content":"ought to provide more than just entertainment.","isCorrect":false}]','C',0.25,NULL,9,'2026-01-30 18:54:41','"Television... might not be popular forever" (Có thể sẽ không phổ biến mãi mãi).');
INSERT INTO "vstep_questions" VALUES(2055,64,50,'Which of the following channels would the author most probably recommend viewers to watch?','MULTIPLE_CHOICE','[{"id":"A","content":"SuperTV","isCorrect":false},{"id":"B","content":"Channel 9","isCorrect":true},{"id":"C","content":"BTV1","isCorrect":false},{"id":"D","content":"All of them","isCorrect":false}]','B',0.25,NULL,10,'2026-01-30 18:54:41','SuperTV chán, BTV1 có cái hay cái dở, nhưng Channel 9 "could be the channel to watch this summer".');
INSERT INTO "vstep_questions" VALUES(2056,65,50,'According to the text, what does Aaron think about his job?','MULTIPLE_CHOICE','[{"id":"A","content":"It helps him become famous.","isCorrect":false},{"id":"B","content":"It can’t make his life change.","isCorrect":true},{"id":"C","content":"Its a boring job.","isCorrect":false},{"id":"D","content":"It brings him many opportunities.","isCorrect":false}]','B',0.25,NULL,11,'2026-01-30 18:54:41','Anh ấy tin rằng "job won''t change his life" (công việc sẽ không thay đổi cuộc đời anh).');
INSERT INTO "vstep_questions" VALUES(2057,65,50,'The word “fascinating” in line 4 can be best replaced by.............','MULTIPLE_CHOICE','[{"id":"A","content":"modern","isCorrect":false},{"id":"B","content":"ordinary","isCorrect":false},{"id":"C","content":"frightening","isCorrect":false},{"id":"D","content":"interesting","isCorrect":true}]','D',0.25,NULL,12,'2026-01-30 18:54:41','"Fascinating" = hấp dẫn, thú vị ~ "interesting".');
INSERT INTO "vstep_questions" VALUES(2058,65,50,'In the first paragraph, the writer suggests that he thinks Aaron ..........','MULTIPLE_CHOICE','[{"id":"A","content":"has a sensible attitude towards fame.","isCorrect":false},{"id":"B","content":"seems confident that he can deal with fame.","isCorrect":false},{"id":"C","content":"seems unaware that he’s about to become famous.","isCorrect":false},{"id":"D","content":"has unrealistic ideas about what it’s like to be famous.","isCorrect":true}]','D',0.25,NULL,13,'2026-01-30 18:54:41','Tác giả nói "chances are it won''t [be true]" (khả năng là sẽ không như vậy) -> Aaron có suy nghĩ không thực tế về sự nổi tiếng.');
INSERT INTO "vstep_questions" VALUES(2059,65,50,'According to the text, when will Aaron''s latest film probably be released?','MULTIPLE_CHOICE','[{"id":"A","content":"at the end of this year","isCorrect":false},{"id":"B","content":"next year","isCorrect":true},{"id":"C","content":"in the next 2 years","isCorrect":false},{"id":"D","content":"in the next 5 years","isCorrect":false}]','B',0.25,NULL,14,'2026-01-30 18:54:41','"latest fantasy blockbuster that will hit our screens next year".');
INSERT INTO "vstep_questions" VALUES(2060,65,50,'The phrase ‘hasn’t gone to his head’ (line 9) suggests that Aaron','MULTIPLE_CHOICE','[{"id":"A","content":"doesn’t think much about his achievements.","isCorrect":true},{"id":"B","content":"is used to receiving so much praise.","isCorrect":false},{"id":"C","content":"is doubtful whether he will win an award.","isCorrect":false},{"id":"D","content":"would like to receive great attention.","isCorrect":false}]','A',0.25,NULL,15,'2026-01-30 18:54:41','"Not gone to his head" = không bị ảo tưởng, không kiêu ngạo vì thành công -> Không quá quan trọng thành tích.');
INSERT INTO "vstep_questions" VALUES(2061,65,50,'What does Aaron say about his last film?','MULTIPLE_CHOICE','[{"id":"A","content":"There are clear heroes in it.","isCorrect":false},{"id":"B","content":"The plot is not as simple as it may appear.","isCorrect":true},{"id":"C","content":"He knows why people liked his character best.","isCorrect":false},{"id":"D","content":"There were often disagreements between the actors.","isCorrect":false}]','B',0.25,NULL,16,'2026-01-30 18:54:41','"he insists that the plot is not as straightforward as it might appear" (Cốt truyện không đơn giản như vẻ ngoài).');
INSERT INTO "vstep_questions" VALUES(2062,65,50,'What makes the writer think that Aaron is a bit of a worrier?','MULTIPLE_CHOICE','[{"id":"A","content":"He avoids watching his own films.","isCorrect":true},{"id":"B","content":"He doesn’t like giving interviews.","isCorrect":false},{"id":"C","content":"He feels responsible for the character he plays.","isCorrect":false},{"id":"D","content":"He thinks carefully before answering a question.","isCorrect":false}]','A',0.25,NULL,17,'2026-01-30 18:54:41','"...seems to be a bit of a worrier and prefers to avoid watching himself on screen".');
INSERT INTO "vstep_questions" VALUES(2063,65,50,'How did Aaron feel when playing a real-life person in his last film?','MULTIPLE_CHOICE','[{"id":"A","content":"curious","isCorrect":false},{"id":"B","content":"fantastic","isCorrect":false},{"id":"C","content":"confused","isCorrect":false},{"id":"D","content":"highly responsible","isCorrect":true}]','D',0.25,NULL,18,'2026-01-30 18:54:41','"He felt ‘a heightened sense of responsibility’" (Cảm thấy trách nhiệm cao độ).');
INSERT INTO "vstep_questions" VALUES(2064,65,50,'What does Aaron say about playing a real-life person on screen?','MULTIPLE_CHOICE','[{"id":"A","content":"He was disappointed that he never met that person.","isCorrect":false},{"id":"B","content":"He was sure that person wouldn''t want to see the film.","isCorrect":false},{"id":"C","content":"He was concerned that the person might feel angry.","isCorrect":true},{"id":"D","content":"He was pleased that the person approved of the fact he was playing it.","isCorrect":false}]','C',0.25,NULL,19,'2026-01-30 18:54:41','"I kept wondering if he''d... be angered by it" (Lo người đó sẽ tức giận).');
INSERT INTO "vstep_questions" VALUES(2065,65,50,'According to the final paragraph, what do Aaron and the directors of his films have in common?','MULTIPLE_CHOICE','[{"id":"A","content":"the fame","isCorrect":false},{"id":"B","content":"the professionalism","isCorrect":false},{"id":"C","content":"the appearance","isCorrect":false},{"id":"D","content":"the unwillingness to lose naivety","isCorrect":true}]','D',0.25,NULL,20,'2026-01-30 18:54:41','(Câu hỏi này hơi khó suy luận từ văn bản, nhưng đoạn cuối Aaron nói "I certainly have that unwillingness to lose naivety... universal". Câu "Does he seek out those parts or do directors see that quality in him? I think it’s probably a bit of both" ngụ ý cả hai đều nhìn thấy/chia sẻ phẩm chất ngây thơ này).');
INSERT INTO "vstep_questions" VALUES(2066,66,50,'What is the main point of the first paragraph?','MULTIPLE_CHOICE','[{"id":"A","content":"We see more adverts than we realise.","isCorrect":true},{"id":"B","content":"Many people are annoyed by television advertising.","isCorrect":false},{"id":"C","content":"We do not pay enough attention to adverts.","isCorrect":false},{"id":"D","content":"Advertising has increased in towns and cities.","isCorrect":false}]','A',0.25,NULL,21,'2026-01-30 18:54:41','"Some of us see as many as 2,000-5,000 adverts a day! ... Most of the time we''re not even consciously aware of them."');
INSERT INTO "vstep_questions" VALUES(2067,66,50,'Yankelovich is............','MULTIPLE_CHOICE','[{"id":"A","content":"A marketing company","isCorrect":false},{"id":"B","content":"A manufacturing company","isCorrect":false},{"id":"C","content":"A market research company","isCorrect":true},{"id":"D","content":"A consulting firm","isCorrect":false}]','C',0.25,NULL,22,'2026-01-30 18:54:41','"market research firm Yankelovich".');
INSERT INTO "vstep_questions" VALUES(2068,66,50,'What do we learn about the writer''s opinion of advertising in Tokyo in the second paragraph?','MULTIPLE_CHOICE','[{"id":"A","content":"It lacks a personal appeal for him.","isCorrect":false},{"id":"B","content":"He thinks that it is very creative.","isCorrect":true},{"id":"C","content":"It seems excessive to him.","isCorrect":false},{"id":"D","content":"He thinks it is Tokyo''s main attraction.","isCorrect":false}]','B',0.25,NULL,23,'2026-01-30 18:54:41','"it would be hard not to admire the advertisers’ ingenuity" (Khó mà không ngưỡng mộ sự khéo léo/sáng tạo).');
INSERT INTO "vstep_questions" VALUES(2069,66,50,'Why do advertisers see Tokyo as important?','MULTIPLE_CHOICE','[{"id":"A","content":"It sets trends which are often copied.","isCorrect":true},{"id":"B","content":"Its distinctive style is popular with everyone.","isCorrect":false},{"id":"C","content":"It reflects trends that are popular elsewhere.","isCorrect":false},{"id":"D","content":"Its style is imitated in every city.","isCorrect":false}]','A',0.25,NULL,24,'2026-01-30 18:54:41','"where Tokyo leads, other cities soon follow" (Tokyo dẫn đầu, các nơi khác theo sau).');
INSERT INTO "vstep_questions" VALUES(2070,66,50,'What does the writer mean by ''sets it apart’ in line 16?','MULTIPLE_CHOICE','[{"id":"A","content":"makes it seem individual and different.","isCorrect":true},{"id":"B","content":"is something which visitors find very inviting","isCorrect":false},{"id":"C","content":"gives it something in common with other cities","isCorrect":false},{"id":"D","content":"lends it a highly unattractive appearance","isCorrect":false}]','A',0.25,NULL,25,'2026-01-30 18:54:41','"Sets it apart" = làm cho nó khác biệt, tách biệt với phần còn lại ~ "individual and different".');
INSERT INTO "vstep_questions" VALUES(2071,66,50,'In the fourth paragraph, Roberta Calvino suggests that.............','MULTIPLE_CHOICE','[{"id":"A","content":"the largest adverts can usually be found in rural areas.","isCorrect":false},{"id":"B","content":"advertising is a particularly bad problem in Austria.","isCorrect":false},{"id":"C","content":"outdoor advertising extends beyond urban areas.","isCorrect":true},{"id":"D","content":"modern adverts are continuing to grow in size.","isCorrect":false}]','C',0.25,NULL,26,'2026-01-30 18:54:41','"advertising is taking over the countryside, too" (Quảng cáo lan ra cả vùng nông thôn).');
INSERT INTO "vstep_questions" VALUES(2072,66,50,'What does Roberta tell us about urban advertising in the fifth paragraph?','MULTIPLE_CHOICE','[{"id":"A","content":"It can be rather unconvincing.","isCorrect":false},{"id":"B","content":"It helps us to fulfil our dreams.","isCorrect":false},{"id":"C","content":"It particularly affects women.","isCorrect":false},{"id":"D","content":"It can lower our self-confidence.","isCorrect":true}]','D',0.25,NULL,27,'2026-01-30 18:54:41','"feel inadequate in comparison... dissatisfied we feel with our lives" (Cảm thấy không đủ tốt, không hài lòng về bản thân).');
INSERT INTO "vstep_questions" VALUES(2073,66,50,'What comparison does Roberta make between urban advertising and TV advertising?','MULTIPLE_CHOICE','[{"id":"A","content":"TV advertising is more effective in the long term.","isCorrect":false},{"id":"B","content":"It is easier to ignore urban advertising.","isCorrect":false},{"id":"C","content":"Urban advertising can have more impact.","isCorrect":true},{"id":"D","content":"There is greater variety in urban advertising.","isCorrect":false}]','C',0.25,NULL,28,'2026-01-30 18:54:41','"outdoor advertising... its message can have greater force" (Có sức mạnh lớn hơn).');
INSERT INTO "vstep_questions" VALUES(2074,66,50,'What did the mayor of São Paulo do in 2007?','MULTIPLE_CHOICE','[{"id":"A","content":"He ordered the removal of more than ten thousand adverts.","isCorrect":true},{"id":"B","content":"He encourages the establishment of advertising companies in the area.","isCorrect":false},{"id":"C","content":"He wrote an article about urban advertising.","isCorrect":false},{"id":"D","content":"He was strongly impressed by the development of advertising firms in the area.","isCorrect":false}]','A',0.25,NULL,29,'2026-01-30 18:54:42','"ordered the removal of more than 15,000 adverts!" (Hơn 10.000).');
INSERT INTO "vstep_questions" VALUES(2075,66,50,'What response did the mayor get when he removed advertising from Sao Paulo?','MULTIPLE_CHOICE','[{"id":"A","content":"The majority of private individuals and commercial people supported him.","isCorrect":false},{"id":"B","content":"Advertisers were willing to display fewer advertisements in the city.","isCorrect":false},{"id":"C","content":"Local artists were unsure how attractive the office blocks would look.","isCorrect":false},{"id":"D","content":"Most of the people who lived in the city welcomed his decision.","isCorrect":true}]','D',0.25,NULL,30,'2026-01-30 18:54:42','Trích dẫn một người dân: "Now we can see the real São Paulo, and it’s wonderful!" (Phần lớn người dân ủng hộ).');
INSERT INTO "vstep_questions" VALUES(2076,67,50,'According to the text, Aborigines arrived in Australia','MULTIPLE_CHOICE','[{"id":"A","content":"400 years ago","isCorrect":false},{"id":"B","content":"8,0000 years ago","isCorrect":false},{"id":"C","content":"23,000 years ago","isCorrect":false},{"id":"D","content":"more than 45,000 years a go","isCorrect":true}]','D',0.25,NULL,31,'2026-01-30 18:54:42','"Today the evidence points to an arrival date of at least 45,000 years ago".');
INSERT INTO "vstep_questions" VALUES(2077,67,50,'What did the discovery of the skeleton show?','MULTIPLE_CHOICE','[{"id":"A","content":"Aborigines used to live in very remote parts of Australia.","isCorrect":false},{"id":"B","content":"The area called Mungo, now dry, was once a lake.","isCorrect":false},{"id":"C","content":"Aborigines have been in Australia far longer than previously thought.","isCorrect":true},{"id":"D","content":"The Aborigine population was larger than originally thought.","isCorrect":false}]','C',0.25,NULL,32,'2026-01-30 18:54:42','Bộ xương cho thấy 23,000 năm, trong khi trước đó nghĩ là 8,000 -> Lâu hơn nhiều so với suy nghĩ trước đây.');
INSERT INTO "vstep_questions" VALUES(2078,67,50,'Which of the following statements is NOT true, according to the text?','MULTIPLE_CHOICE','[{"id":"A","content":"Australia has always been an island since people existed.","isCorrect":false},{"id":"B","content":"Australian apes became extinct before human times.","isCorrect":true},{"id":"C","content":"Aborigines probably originated in Timor or Indonesia.","isCorrect":false},{"id":"D","content":"Aborigines must have arrived in Australia by sea.","isCorrect":false}]','B',0.25,NULL,33,'2026-01-30 18:54:42','Bài viết nói: "Australia has no apelike creatures" (Úc không có loài vượn nào để con người tiến hóa từ đó), chứ không nói chúng bị tuyệt chủng.');
INSERT INTO "vstep_questions" VALUES(2079,67,50,'Why is it so surprising that Homo sapiens got to Australia?','MULTIPLE_CHOICE','[{"id":"A","content":"It required skills that people generally developed very much later.","isCorrect":true},{"id":"B","content":"People in that area were less advanced than other peoples at this time.","isCorrect":false},{"id":"C","content":"Only much smaller boats have been found elsewhere from this period.","isCorrect":false},{"id":"D","content":"Aborigines are not particularly known for their sailing skills.","isCorrect":false}]','A',0.25,NULL,34,'2026-01-30 18:54:42','Việc đi biển (sailing) đòi hỏi kỹ năng mà "archaeological record shows no one else on earth doing this for another 30,000 years" (30,000 năm sau người khác mới làm được).');
INSERT INTO "vstep_questions" VALUES(2080,67,50,'What usually provides the explanation for the Aborigines’ arrival in Australia?','MULTIPLE_CHOICE','[{"id":"A","content":"their curiosity","isCorrect":false},{"id":"B","content":"bad weather","isCorrect":true},{"id":"C","content":"a desire for better fishing","isCorrect":false},{"id":"D","content":"hunger for land","isCorrect":false}]','B',0.25,NULL,35,'2026-01-30 18:54:42','"accidentally earned out to sea probably in one of the sudden storms" (do bão bất ngờ).');
INSERT INTO "vstep_questions" VALUES(2081,67,50,'This author is puzzled by how...','MULTIPLE_CHOICE','[{"id":"A","content":"the boat managed to travel across such dangerous seas","isCorrect":false},{"id":"B","content":"the aborigines got enough food and water to survive the crossing","isCorrect":false},{"id":"C","content":"enough people got there to found a settlement","isCorrect":true},{"id":"D","content":"the Aborigines chose not to return to their homeland","isCorrect":false}]','C',0.25,NULL,36,'2026-01-30 18:54:42','"how you get a new population out of this" (Làm sao tạo ra dân số mới từ một người/nhóm nhỏ trôi dạt).');
INSERT INTO "vstep_questions" VALUES(2082,67,50,'Which word could replace ''staggeringly'' in line 33 without changing the meaning?','MULTIPLE_CHOICE','[{"id":"A","content":"extraordinarily","isCorrect":true},{"id":"B","content":"shockingly","isCorrect":false},{"id":"C","content":"wonderfully","isCorrect":false},{"id":"D","content":"desperately","isCorrect":false}]','A',0.25,NULL,37,'2026-01-30 18:54:42','"Staggeringly" = gây choáng váng, kinh ngạc ~ "extraordinarily" (phi thường).');
INSERT INTO "vstep_questions" VALUES(2083,67,50,'What does the writer seem most surprised by at the end of this extract?','MULTIPLE_CHOICE','[{"id":"A","content":"the way that Aborigines managed to establish themselves in Australia","isCorrect":false},{"id":"B","content":"how badly European settlers treated Australian Aborigines","isCorrect":false},{"id":"C","content":"how long Australian Aborigines have lived on the continent","isCorrect":false},{"id":"D","content":"the fact that so little attention is paid to this aspect of human history","isCorrect":true}]','D',0.25,NULL,38,'2026-01-30 18:54:42','"And how much notice is paid to it? ... They are the planet''s invisible people." (Quá ít sự chú ý dành cho họ).');
INSERT INTO "vstep_questions" VALUES(2084,67,50,'In which space (marked t and [(8)] in the passage) will the following sentence fit? "In other words, for the first 99.7 per cent of its inhabited history, the Aborigines had Australia to themselves..."','MULTIPLE_CHOICE','[{"id":"A","content":"(R)","isCorrect":false},{"id":"B","content":"(B)","isCorrect":false},{"id":"C","content":"(Q)","isCorrect":true},{"id":"D","content":"(D)","isCorrect":false}]','C',0.25,NULL,39,'2026-01-30 18:54:42','Câu này phù hợp nhất ở cuối bài, sau khi tính toán tỷ lệ 0.3% của người châu Âu, để kết luận về thời gian người Aborigines sống một mình. (Vị trí Q hoặc D cuối bài).');
INSERT INTO "vstep_questions" VALUES(2085,67,50,'What is the main point the writer is making in the last paragraph?','MULTIPLE_CHOICE','[{"id":"A","content":"The Europeans had no right to take over Aborigine land in Australia.","isCorrect":false},{"id":"B","content":"No one can be exactly certain as to when the Aborigines first arrived in Australia.","isCorrect":false},{"id":"C","content":"The Aborigines have inhabited Australia for much longer than the Europeans have Europe.","isCorrect":false},{"id":"D","content":"The Aborigines were the only people in Australia for most of the time since it was settled.","isCorrect":true}]','D',0.25,NULL,40,'2026-01-30 18:54:42','"European occupation... represents about 0.3 per cent" -> Người Aborigines chiếm 99.7% thời gian lịch sử Úc.');
INSERT INTO "vstep_questions" VALUES(2086,68,51,'The writer says that baseball ...........','MULTIPLE_CHOICE','[{"id":"A","content":"is played only in America.","isCorrect":false},{"id":"B","content":"is not popular in countries like Japan.","isCorrect":false},{"id":"C","content":"started in South America.","isCorrect":false},{"id":"D","content":"is becoming more popular all over the world.","isCorrect":true}]','D',0.25,NULL,1,'2026-01-30 18:55:11','Bài đọc nói: "more and more countries are putting together teams" (ngày càng nhiều nước thành lập đội).');
INSERT INTO "vstep_questions" VALUES(2087,68,51,'According to the text, baseball is played in more and more countries because .............','MULTIPLE_CHOICE','[{"id":"A","content":"it is an exciting game.","isCorrect":false},{"id":"B","content":"it is included in the Olympic Games.","isCorrect":true},{"id":"C","content":"Many American people live there.","isCorrect":false},{"id":"D","content":"It is easy to play.","isCorrect":false}]','B',0.25,NULL,2,'2026-01-30 18:55:11','"Since baseball is an Olympic sport..." (Vì bóng chày là môn thể thao Olympic).');
INSERT INTO "vstep_questions" VALUES(2088,68,51,'Which sentence isn''t true about baseball?','MULTIPLE_CHOICE','[{"id":"A","content":"It was first played during the 1850s.","isCorrect":false},{"id":"B","content":"It is an Olympic sport.","isCorrect":false},{"id":"C","content":"The rules have changed quite a lot over the years.","isCorrect":true},{"id":"D","content":"It started in New York.","isCorrect":false}]','C',0.25,NULL,3,'2026-01-30 18:55:11','Bài đọc nói: "It has changed a little bit... but the basic game remains the same" (chỉ thay đổi một chút, cơ bản vẫn giữ nguyên) -> Ý C nói thay đổi "quite a lot" là sai.');
INSERT INTO "vstep_questions" VALUES(2089,68,51,'Which piece of equipment is not mentioned in the text?','MULTIPLE_CHOICE','[{"id":"A","content":"bat","isCorrect":false},{"id":"B","content":"ball","isCorrect":false},{"id":"C","content":"glove","isCorrect":false},{"id":"D","content":"mask","isCorrect":true}]','D',0.25,NULL,4,'2026-01-30 18:55:11','Bài đọc nhắc đến: bat, ball, glove, shirt, trousers, cap. Không có "mask" (mặt nạ).');
INSERT INTO "vstep_questions" VALUES(2090,68,51,'In which space (marked t [a and in the passage) will the following sentence fit? "Players wear shoes with spikes..."','MULTIPLE_CHOICE','[{"id":"A","content":"(A)","isCorrect":false},{"id":"B","content":"(B)","isCorrect":true},{"id":"C","content":"(C)","isCorrect":false},{"id":"D","content":"(D)","isCorrect":false}]','B',0.25,NULL,5,'2026-01-30 18:55:11','Câu này mô tả trang phục (shoes, cap), phù hợp để nối tiếp đoạn mô tả "shirt and trousers" (đoạn 4). Vị trí B (cuối đoạn 4 hoặc đầu đoạn 5) là hợp lý nhất trong ngữ cảnh này.');
INSERT INTO "vstep_questions" VALUES(2091,68,51,'What is the baseball field like?','MULTIPLE_CHOICE','[{"id":"A","content":"It has an infield, an outfield and a middle field.","isCorrect":false},{"id":"B","content":"There are three diamonds on the ground.","isCorrect":false},{"id":"C","content":"There are three bases on the diamond.","isCorrect":true},{"id":"D","content":"It is usually in an indoor stadium.","isCorrect":false}]','C',0.25,NULL,6,'2026-01-30 18:55:11','"On the diamond, there are also the three bases" (Trên hình kim cương có 3 cứ điểm).');
INSERT INTO "vstep_questions" VALUES(2092,68,51,'The game is divided into............','MULTIPLE_CHOICE','[{"id":"A","content":"two halves.","isCorrect":false},{"id":"B","content":"nine innings.","isCorrect":true},{"id":"C","content":"three bases.","isCorrect":false},{"id":"D","content":"an infield and an outfield.","isCorrect":false}]','B',0.25,NULL,7,'2026-01-30 18:55:11','"The game of baseball is divided into nine parts, called innings."');
INSERT INTO "vstep_questions" VALUES(2093,68,51,'The object of the game is to..............','MULTIPLE_CHOICE','[{"id":"A","content":"catch as many balls as you can.","isCorrect":false},{"id":"B","content":"hit the ball the farthest.","isCorrect":false},{"id":"C","content":"score the most runs.","isCorrect":true},{"id":"D","content":"bat as often as you can.","isCorrect":false}]','C',0.25,NULL,8,'2026-01-30 18:55:11','"The team that scores the most runs... wins."');
INSERT INTO "vstep_questions" VALUES(2094,68,51,'What is true about a baseball match?','MULTIPLE_CHOICE','[{"id":"A","content":"It''s slow.","isCorrect":false},{"id":"B","content":"It often takes place on hot summer days.","isCorrect":false},{"id":"C","content":"Spectators are not allowed to bring foods to the ballpark.","isCorrect":false},{"id":"D","content":"The speed of the match may change suddenly.","isCorrect":true}]','D',0.25,NULL,9,'2026-01-30 18:55:11','"can go very slowly... then suddenly have a series of fast... moves" (tốc độ thay đổi đột ngột).');
INSERT INTO "vstep_questions" VALUES(2095,68,51,'According to the text, most American people have .............','MULTIPLE_CHOICE','[{"id":"A","content":"childhood memory at a ballpark.","isCorrect":true},{"id":"B","content":"a baseball gear.","isCorrect":false},{"id":"C","content":"experience of participating in at least a baseball inning.","isCorrect":false},{"id":"D","content":"all of them","isCorrect":false}]','A',0.25,NULL,10,'2026-01-30 18:55:11','"nearly everyone''s favourite childhood memory includes a day at the ballpark."');
INSERT INTO "vstep_questions" VALUES(2096,69,51,'In the first paragraph, the writer says that athletes today ............','MULTIPLE_CHOICE','[{"id":"A","content":"are more popular than in ancient times.","isCorrect":false},{"id":"B","content":"are much better than in ancient times.","isCorrect":false},{"id":"C","content":"treat the Olympics like a business.","isCorrect":false},{"id":"D","content":"can become wealthy through sport.","isCorrect":true}]','D',0.25,NULL,11,'2026-01-30 18:55:12','"The athletes then could make a lot of money... just like today''s competitors." (Vận động viên ngày xưa kiếm nhiều tiền, giống như ngày nay).');
INSERT INTO "vstep_questions" VALUES(2097,69,51,'What does the word “ This” in line 8 refer to?','MULTIPLE_CHOICE','[{"id":"A","content":"the champion","isCorrect":false},{"id":"B","content":"the running race","isCorrect":false},{"id":"C","content":"Greece","isCorrect":false},{"id":"D","content":"the pentathlon","isCorrect":true}]','D',0.25,NULL,12,'2026-01-30 18:55:12','"In the ancient Olympics, athletes competed in the pentathlon. This consisted of..." -> This = the pentathlon.');
INSERT INTO "vstep_questions" VALUES(2098,69,51,'The ancient pentathlon didn''t test athletes’ abilities to...............','MULTIPLE_CHOICE','[{"id":"A","content":"throw things.","isCorrect":false},{"id":"B","content":"jump high.","isCorrect":true},{"id":"C","content":"run fast.","isCorrect":false},{"id":"D","content":"jump far.","isCorrect":false}]','B',0.25,NULL,13,'2026-01-30 18:55:12','Pentathlon gồm: long jump (xa), discus/javelin (ném), running (chạy), wrestling (đấu vật). Không có nhảy cao (high jump).');
INSERT INTO "vstep_questions" VALUES(2099,69,51,'Lampis of Sparta was................','MULTIPLE_CHOICE','[{"id":"A","content":"the organizer of the first ancient Olympics","isCorrect":false},{"id":"B","content":"Emperor Theodosius of Rome","isCorrect":false},{"id":"C","content":"the first winner of the ancient Olympics","isCorrect":true},{"id":"D","content":"the greatest athlete in history","isCorrect":false}]','C',0.25,NULL,14,'2026-01-30 18:55:12','"The first winner, in 708 BC, was Lampis of Sparta".');
INSERT INTO "vstep_questions" VALUES(2100,69,51,'According to the passage, the heptathlon for women ............','MULTIPLE_CHOICE','[{"id":"A","content":"became an Olympic event after 1912.","isCorrect":true},{"id":"B","content":"similar to the ancient pentathlon.","isCorrect":false},{"id":"C","content":"tests the ability to ride a horse.","isCorrect":false},{"id":"D","content":"is much easier than the decathlon.","isCorrect":false}]','A',0.25,NULL,15,'2026-01-30 18:55:12','"...heptathlon... being introduced later" (được giới thiệu sau năm 1912).');
INSERT INTO "vstep_questions" VALUES(2101,69,51,'How many sporting events were included in the modern decathlon of Stockholm Olympics in 1912?','MULTIPLE_CHOICE','[{"id":"A","content":"only one","isCorrect":false},{"id":"B","content":"five","isCorrect":false},{"id":"C","content":"seven","isCorrect":false},{"id":"D","content":"ten","isCorrect":true}]','D',0.25,NULL,16,'2026-01-30 18:55:12','"decathlon (ten events)".');
INSERT INTO "vstep_questions" VALUES(2102,69,51,'What did Bruce Thorpe say about decathlon?','MULTIPLE_CHOICE','[{"id":"A","content":"It is challenging and requires athletes to have various skills.","isCorrect":true},{"id":"B","content":"There''s no need for participants to train hard.","isCorrect":false},{"id":"C","content":"It has only seven events.","isCorrect":false},{"id":"D","content":"It takes one day to decide the winner.","isCorrect":false}]','A',0.25,NULL,17,'2026-01-30 18:55:12','"It''s very tough and it demands a lot of different skills."');
INSERT INTO "vstep_questions" VALUES(2103,69,51,'What do you have to do to win a gold medal in the decathlon?','MULTIPLE_CHOICE','[{"id":"A","content":"Score more points than all the other competitors.","isCorrect":true},{"id":"B","content":"Beat the other competitors in at least three events.","isCorrect":false},{"id":"C","content":"Finish each event in the top three.","isCorrect":false},{"id":"D","content":"Complete the events in the right order.","isCorrect":false}]','A',0.25,NULL,18,'2026-01-30 18:55:12','"the person with the most points is the champion".');
INSERT INTO "vstep_questions" VALUES(2104,69,51,'What does Bruce say about the events?','MULTIPLE_CHOICE','[{"id":"A","content":"The 1500 metres should be on the first day.","isCorrect":false},{"id":"B","content":"The first day is tougher than the second.","isCorrect":false},{"id":"C","content":"The 1500 metres is different from the other events.","isCorrect":true},{"id":"D","content":"It looks easier than it actually is.","isCorrect":false}]','C',0.25,NULL,19,'2026-01-30 18:55:12','1500m đòi hỏi sức bền (stamina), trong khi các môn khác cần tốc độ/sức mạnh -> Khác biệt.');
INSERT INTO "vstep_questions" VALUES(2105,69,51,'What is Bruce''s advice for people thinking of becoming decathletes?','MULTIPLE_CHOICE','[{"id":"A","content":"Get a trainer to guide you.","isCorrect":true},{"id":"B","content":"Get up early to start training","isCorrect":false},{"id":"C","content":"Take up the heptathlon instead.","isCorrect":false},{"id":"D","content":"Try to get a good time in all the events.","isCorrect":false}]','A',0.25,NULL,20,'2026-01-30 18:55:12','"join a good club... you need expert help" (Cần sự giúp đỡ của chuyên gia/HLV).');
INSERT INTO "vstep_questions" VALUES(2106,70,51,'Why did David Cornthwaite decide to skateboard across Australia?','MULTIPLE_CHOICE','[{"id":"A","content":"He was an experienced skateboarder","isCorrect":false},{"id":"B","content":"He wanted to break a world record","isCorrect":false},{"id":"C","content":"He was bored with his life and wanted to try something different","isCorrect":true},{"id":"D","content":"Somebody gave him a guidebook about Australia","isCorrect":false}]','C',0.25,NULL,21,'2026-01-30 18:55:12','Anh ấy ghét công việc hiện tại ("hated his job"), cảm thấy vỡ mộng ("disillusioned") và muốn tìm cái gì đó mới mẻ ("looking for something new").');
INSERT INTO "vstep_questions" VALUES(2107,70,51,'The word “disillusioned” in line 5 can be best replaced by ............','MULTIPLE_CHOICE','[{"id":"A","content":"disappointed","isCorrect":true},{"id":"B","content":"embarrassed","isCorrect":false},{"id":"C","content":"fascinated","isCorrect":false},{"id":"D","content":"delighted","isCorrect":false}]','A',0.25,NULL,22,'2026-01-30 18:55:12','"Disillusioned" = vỡ mộng, chán nản ~ "disappointed".');
INSERT INTO "vstep_questions" VALUES(2108,70,51,'His preparation in Britain was..............','MULTIPLE_CHOICE','[{"id":"A","content":"successful, but painful","isCorrect":true},{"id":"B","content":"successful, but more time-consuming than planned","isCorrect":false},{"id":"C","content":"successful, but more difficult than he had realised","isCorrect":false},{"id":"D","content":"unsuccessful because he got injured","isCorrect":false}]','A',0.25,NULL,23,'2026-01-30 18:55:12','Anh ấy hoàn thành chuyến đi ("finished") nhưng bị phồng rộp nặng ("infected blister... size of a tennis ball") -> Đau đớn.');
INSERT INTO "vstep_questions" VALUES(2109,70,51,'What made David fall off his skateboard several times in Australia?','MULTIPLE_CHOICE','[{"id":"A","content":"thunderstorms in the Outback","isCorrect":false},{"id":"B","content":"the trains that race across the Outback","isCorrect":false},{"id":"C","content":"the injuries on his feet","isCorrect":false},{"id":"D","content":"the wind created by huge lorries going past","isCorrect":true}]','D',0.25,NULL,24,'2026-01-30 18:55:12','Gió tạo ra bởi những chiếc xe tải lớn ("wind caused by huge road trains... articulated lorries").');
INSERT INTO "vstep_questions" VALUES(2110,70,51,'At times, David felt as though he................','MULTIPLE_CHOICE','[{"id":"A","content":"needed to stop for a while.","isCorrect":true},{"id":"B","content":"wanted to give up completely.","isCorrect":false},{"id":"C","content":"wanted to get out of the sun.","isCorrect":false},{"id":"D","content":"needed a new pair of shoes.","isCorrect":false}]','A',0.25,NULL,25,'2026-01-30 18:55:12','"I thought ''this is ridiculous, I have to rest'', but I never contemplated giving up" (Muốn nghỉ ngơi, nhưng chưa bao giờ nghĩ đến bỏ cuộc).');
INSERT INTO "vstep_questions" VALUES(2111,70,51,'During the journey, where did David sleep at night?','MULTIPLE_CHOICE','[{"id":"A","content":"in a four-wheel drive vehicle","isCorrect":false},{"id":"B","content":"in a tent","isCorrect":true},{"id":"C","content":"outdoors on the Nullarbor Plain","isCorrect":false},{"id":"D","content":"in the homes of his supporters","isCorrect":false}]','B',0.25,NULL,26,'2026-01-30 18:55:12','Xe hỗ trợ mang theo "camping equipment" (dụng cụ cắm trại) -> Ngủ lều.');
INSERT INTO "vstep_questions" VALUES(2112,70,51,'David fell off his skateboard because ...............','MULTIPLE_CHOICE','[{"id":"A","content":"he was going too fast his journey","isCorrect":false},{"id":"B","content":"he was exhausted and in pain","isCorrect":false},{"id":"C","content":"he didn’t see a hole in the road","isCorrect":true},{"id":"D","content":"he was thinking about finishing his journey","isCorrect":false}]','C',0.25,NULL,27,'2026-01-30 18:55:12','"he hit a hole and was so thrown off" (đâm vào cái hố).');
INSERT INTO "vstep_questions" VALUES(2113,70,51,'Why does David think surfing is a good thing to do after his journey............','MULTIPLE_CHOICE','[{"id":"A","content":"He can stay close to Brisbane.","isCorrect":false},{"id":"B","content":"He''s always wanted to surf on the Gold Coast.","isCorrect":false},{"id":"C","content":"He wants to strengthen the top half of his body.","isCorrect":true},{"id":"D","content":"He needs to keep his legs strong.","isCorrect":false}]','C',0.25,NULL,28,'2026-01-30 18:55:12','"build up some much-needed upper body strength" (Chân to nhưng thân trên gầy).');
INSERT INTO "vstep_questions" VALUES(2114,70,51,'What does David hope to do eventually?','MULTIPLE_CHOICE','[{"id":"A","content":"encourage other people to feel more positive about themselves","isCorrect":true},{"id":"B","content":"put his skateboard away","isCorrect":false},{"id":"C","content":"return to work as a designer","isCorrect":false},{"id":"D","content":"persuade other people to make long-distance journeys","isCorrect":false}]','A',0.25,NULL,29,'2026-01-30 18:55:12','"plans to give motivational speeches" (diễn thuyết truyền cảm hứng).');
INSERT INTO "vstep_questions" VALUES(2115,70,51,'According to the text, in some days, David plans to skate on .................','MULTIPLE_CHOICE','[{"id":"A","content":"Perth","isCorrect":false},{"id":"B","content":"Adelaide","isCorrect":false},{"id":"C","content":"Melbourne","isCorrect":false},{"id":"D","content":"Gold Coast","isCorrect":true}]','D',0.25,NULL,30,'2026-01-30 18:55:12','Anh ấy dự định "surfing on the Gold Coast". (Lưu ý: câu hỏi dùng từ "skate", nhưng trong bài là "surf". Tuy nhiên địa điểm sắp tới là Gold Coast).');
INSERT INTO "vstep_questions" VALUES(2116,71,51,'What do footballers and musicians have in common?','MULTIPLE_CHOICE','[{"id":"A","content":"Their work abroad earns a lot of praise.","isCorrect":false},{"id":"B","content":"They receive too much unfair criticism.","isCorrect":false},{"id":"C","content":"They enjoy extremely noisy audiences.","isCorrect":false},{"id":"D","content":"They experience tension in their work.","isCorrect":true}]','D',0.25,NULL,31,'2026-01-30 18:55:12','"They both do stressful jobs" (đều làm công việc căng thẳng).');
INSERT INTO "vstep_questions" VALUES(2117,71,51,'What are we told about Rod Franks?','MULTIPLE_CHOICE','[{"id":"A","content":"He used to be the director of a football club.","isCorrect":false},{"id":"B","content":"He switched from one career to another.","isCorrect":true},{"id":"C","content":"He used to be a professional trumpeter.","isCorrect":false},{"id":"D","content":"He disliked his original choice of career.","isCorrect":false}]','B',0.25,NULL,32,'2026-01-30 18:55:13','"started... with Leeds United Football Club, neatly changed direction, started playing the trumpet" (Chuyển nghề).');
INSERT INTO "vstep_questions" VALUES(2118,71,51,'Before joining London Symphony Orchestra, Rod Franks worked for ..................','MULTIPLE_CHOICE','[{"id":"A","content":"a football club","isCorrect":true},{"id":"B","content":"a travel agency","isCorrect":false},{"id":"C","content":"a consulting firm","isCorrect":false},{"id":"D","content":"an event organizing firm","isCorrect":false}]','A',0.25,NULL,33,'2026-01-30 18:55:13','"Leeds United Football Club".');
INSERT INTO "vstep_questions" VALUES(2119,71,51,'The word “principal” in line 4 can be best replaced by...................','MULTIPLE_CHOICE','[{"id":"A","content":"original","isCorrect":false},{"id":"B","content":"main","isCorrect":true},{"id":"C","content":"prime","isCorrect":false},{"id":"D","content":"initial","isCorrect":false}]','B',0.25,NULL,34,'2026-01-30 18:55:13','"Principal trumpeter" = người chơi trumpet chính ~ "main".');
INSERT INTO "vstep_questions" VALUES(2120,71,51,'The LSO began playing abroad ...............','MULTIPLE_CHOICE','[{"id":"A","content":"only fairly recently.","isCorrect":false},{"id":"B","content":"over a hundred years ago.","isCorrect":false},{"id":"C","content":"when it was first set up.","isCorrect":true},{"id":"D","content":"when it needed money.","isCorrect":false}]','C',0.25,NULL,35,'2026-01-30 18:55:13','"has been playing away since it was formed almost a century ago" (Đi lưu diễn từ khi thành lập).');
INSERT INTO "vstep_questions" VALUES(2121,71,51,'Orchestras have to travel abroad ................','MULTIPLE_CHOICE','[{"id":"A","content":"to play with foreign conductors.","isCorrect":false},{"id":"B","content":"to record with foreign companies.","isCorrect":false},{"id":"C","content":"to make themselves better known.","isCorrect":true},{"id":"D","content":"to record with new solo players.","isCorrect":false}]','C',0.25,NULL,36,'2026-01-30 18:55:13','Cần "international reputation" (danh tiếng quốc tế) để các công ty thu âm chịu hợp tác -> Làm cho mình nổi tiếng hơn.');
INSERT INTO "vstep_questions" VALUES(2122,71,51,'What does ‘It’ in line 15 refer to?','MULTIPLE_CHOICE','[{"id":"A","content":"organising a number of recordings","isCorrect":false},{"id":"B","content":"visiting the most important markets","isCorrect":false},{"id":"C","content":"the expense of touring in a country","isCorrect":false},{"id":"D","content":"providing more than just concerts","isCorrect":true}]','D',0.25,NULL,37,'2026-01-30 18:55:13','"create an event, not just provide a series of concerts. It is more expensive..." -> It = creating an event (tạo ra sự kiện, cung cấp nhiều hơn là chỉ hòa nhạc).');
INSERT INTO "vstep_questions" VALUES(2123,71,51,'Sue Mallet''s arrangements for the LSO can be..................','MULTIPLE_CHOICE','[{"id":"A","content":"affected by external circumstances.","isCorrect":true},{"id":"B","content":"made difficult by awkward players.","isCorrect":false},{"id":"C","content":"spoilt by overlooking tiny details.","isCorrect":false},{"id":"D","content":"spoilt by very careless planning.","isCorrect":false}]','A',0.25,NULL,38,'2026-01-30 18:55:13','Dù lên kế hoạch kỹ, nhưng "events sometimes take an upper hand" (sự cố ngoài ý muốn xảy ra như xe hỏng, tuyết rơi...) -> Bị ảnh hưởng bởi hoàn cảnh bên ngoài.');
INSERT INTO "vstep_questions" VALUES(2124,71,51,'What does the phrase “with scientific accuracy’ (line 18) suggest about Sue Mallet''s planning?','MULTIPLE_CHOICE','[{"id":"A","content":"It''s very neat and tidy.","isCorrect":false},{"id":"B","content":"Her figures are correct.","isCorrect":false},{"id":"C","content":"She used to be a scientist.","isCorrect":false},{"id":"D","content":"The details are excellent.","isCorrect":true}]','D',0.25,NULL,39,'2026-01-30 18:55:13','"Scientific accuracy" (chính xác khoa học) ngụ ý kế hoạch cực kỳ chi tiết, tỉ mỉ và xuất sắc.');
INSERT INTO "vstep_questions" VALUES(2125,71,51,'According to the writer, what made a certain moment ‘unforgettable’ (line 23)?','MULTIPLE_CHOICE','[{"id":"A","content":"the fact that the orchestra stood up","isCorrect":false},{"id":"B","content":"an individual''s appreciation","isCorrect":true},{"id":"C","content":"the enthusiastic applause","isCorrect":false},{"id":"D","content":"the fact that a message was in English","isCorrect":false}]','B',0.25,NULL,40,'2026-01-30 18:55:13','Một bà cụ đưa mảnh giấy khen ngợi -> Sự cảm kích của cá nhân.');
INSERT INTO "vstep_questions" VALUES(2126,72,52,'When is the man’s appointment?','MULTIPLE_CHOICE','[{"id":"A","content":"Wednesday","isCorrect":false},{"id":"B","content":"Thursday","isCorrect":true},{"id":"C","content":"Friday","isCorrect":false},{"id":"D","content":"Tuesday","isCorrect":false}]','B',0.286,NULL,1,'2026-01-30 18:56:05','Người đàn ông hỏi "What about Thursday afternoon?" và người phụ nữ đồng ý "We''ll see you then".');
INSERT INTO "vstep_questions" VALUES(2127,72,52,'Which is the aunt’s postcard?','MULTIPLE_CHOICE','[{"id":"A","content":"a pretty village right by the sea","isCorrect":false},{"id":"B","content":"big trees","isCorrect":false},{"id":"C","content":"a pretty village behind the tall trees","isCorrect":true},{"id":"D","content":"a pretty village on the hills","isCorrect":false}]','C',0.286,NULL,2,'2026-01-30 18:56:05','Audio mô tả ngôi làng "behind those tall trees" (nằm sau những cái cây cao kia).');
INSERT INTO "vstep_questions" VALUES(2128,72,52,'What time will the plane to Milan leave?','MULTIPLE_CHOICE','[{"id":"A","content":"1:00","isCorrect":false},{"id":"B","content":"7:15","isCorrect":false},{"id":"C","content":"8:15","isCorrect":true},{"id":"D","content":"6:15","isCorrect":false}]','C',0.286,NULL,3,'2026-01-30 18:56:05','Giờ gốc là 7:15 nhưng trễ 1 tiếng ("an hour late"), nên giờ mới là 8:15.');
INSERT INTO "vstep_questions" VALUES(2129,72,52,'Which present has the girl bought her mother?','MULTIPLE_CHOICE','[{"id":"A","content":"earrings","isCorrect":false},{"id":"B","content":"music CD","isCorrect":false},{"id":"C","content":"pen","isCorrect":true},{"id":"D","content":"notebook","isCorrect":false}]','C',0.286,NULL,4,'2026-01-30 18:56:06','Cô gái nói "I got this really nice gold-colored pen". Bông tai là quà của bố.');
INSERT INTO "vstep_questions" VALUES(2130,72,52,'What time will the pie be ready?','MULTIPLE_CHOICE','[{"id":"A","content":"four fifteen","isCorrect":false},{"id":"B","content":"five o''clock","isCorrect":false},{"id":"C","content":"twenty past five","isCorrect":true},{"id":"D","content":"fifty past four","isCorrect":false}]','C',0.286,NULL,5,'2026-01-30 18:56:06','Hiện tại 4:35, cần thêm 45 phút ("45 minutes to go") => 5:20 (Twenty past five).');
INSERT INTO "vstep_questions" VALUES(2131,72,52,'What time is the swimming lesson today?','MULTIPLE_CHOICE','[{"id":"A","content":"half past four","isCorrect":false},{"id":"B","content":"fifteen to five","isCorrect":true},{"id":"C","content":"fifteen past five","isCorrect":false},{"id":"D","content":"four thirty","isCorrect":false}]','B',0.286,NULL,6,'2026-01-30 18:56:06','Bình thường 5:15, nay sớm hơn 30 phút ("half an hour earlier") => 4:45 (fifteen to five).');
INSERT INTO "vstep_questions" VALUES(2132,72,52,'Which subject does the boy like best?','MULTIPLE_CHOICE','[{"id":"A","content":"information technology","isCorrect":true},{"id":"B","content":"geography","isCorrect":false},{"id":"C","content":"sports","isCorrect":false},{"id":"D","content":"design","isCorrect":false}]','A',0.286,NULL,7,'2026-01-30 18:56:06','Cậu bé thích giáo viên IT mới và dự án web ("design a website"). Năm ngoái thích Địa lý nhưng giờ bài tập nhiều.');
INSERT INTO "vstep_questions" VALUES(2133,72,52,'Which T-shirt does the boy decide to buy?','MULTIPLE_CHOICE','[{"id":"A","content":"a short-sleeved T-shirt with round neck","isCorrect":true},{"id":"B","content":"a V-neck black T-shirt","isCorrect":false},{"id":"C","content":"a long-sleeved T-shirt","isCorrect":false},{"id":"D","content":"a sleeveless white T-shirt","isCorrect":false}]','A',0.286,NULL,8,'2026-01-30 18:56:06','Chọn áo ngắn tay ("short-sleeved") và cổ tròn ("round neck").');
INSERT INTO "vstep_questions" VALUES(2134,72,52,'What is Kate''s health problem?','MULTIPLE_CHOICE','[{"id":"A","content":"She has coughs","isCorrect":true},{"id":"B","content":"She has headache","isCorrect":false},{"id":"C","content":"She has toothache","isCorrect":false},{"id":"D","content":"She has stomach ache","isCorrect":false}]','A',0.286,NULL,9,'2026-01-30 18:56:06','George phàn nàn sẽ chỉ nghe thấy tiếng ho của Kate ("hear is you coughing").');
INSERT INTO "vstep_questions" VALUES(2135,72,52,'What does Kate''s problem affect her classmates?','MULTIPLE_CHOICE','[{"id":"A","content":"It makes them funny.","isCorrect":false},{"id":"B","content":"It makes them annoyed.","isCorrect":true},{"id":"C","content":"It makes them happy.","isCorrect":false},{"id":"D","content":"It makes them excited.","isCorrect":false}]','B',0.286,NULL,10,'2026-01-30 18:56:06','George tỏ thái độ khó chịu ("annoyed") vì tiếng ồn làm ảnh hưởng lớp học.');
INSERT INTO "vstep_questions" VALUES(2136,72,52,'What did Kate have last year?','MULTIPLE_CHOICE','[{"id":"A","content":"She had coughs","isCorrect":false},{"id":"B","content":"She had headache","isCorrect":false},{"id":"C","content":"She had a fall off her bike","isCorrect":true},{"id":"D","content":"She had stomach ache","isCorrect":false}]','C',0.286,NULL,11,'2026-01-30 18:56:06','Kate kể năm ngoái nghỉ học do ngã xe đạp ("fell off my bike").');
INSERT INTO "vstep_questions" VALUES(2137,72,52,'What does Kate have now, too?','MULTIPLE_CHOICE','[{"id":"A","content":"She has backache","isCorrect":false},{"id":"B","content":"She has headache","isCorrect":false},{"id":"C","content":"She has toothache","isCorrect":false},{"id":"D","content":"She has temperature","isCorrect":true}]','D',0.286,NULL,12,'2026-01-30 18:56:06','Kate nói thêm: "I have got a bit of a temperature now too" (cũng bị sốt nhẹ).');
INSERT INTO "vstep_questions" VALUES(2138,72,52,'Why does the man want to go out?','MULTIPLE_CHOICE','[{"id":"A","content":"Because he feels bored staying at home.","isCorrect":true},{"id":"B","content":"Because he feels safe staying at home.","isCorrect":false},{"id":"C","content":"Because he feels cold staying at home.","isCorrect":false},{"id":"D","content":"Because he feels hot staying at home.","isCorrect":false}]','A',0.286,NULL,13,'2026-01-30 18:56:06','Người đàn ông nói ở nhà chán ("That''s a bit boring").');
INSERT INTO "vstep_questions" VALUES(2139,72,52,'Why does the woman want to stay at home?','MULTIPLE_CHOICE','[{"id":"A","content":"Because she has coughs.","isCorrect":false},{"id":"B","content":"Because she feels tired.","isCorrect":true},{"id":"C","content":"Because she has toothache.","isCorrect":false},{"id":"D","content":"Because she has stomach ache.","isCorrect":false}]','B',0.286,NULL,14,'2026-01-30 18:56:06','Người phụ nữ từ chối vì mệt ("No, I''m tired").');
INSERT INTO "vstep_questions" VALUES(2140,72,52,'Why doesn’t the woman want to watch an Italian film?','MULTIPLE_CHOICE','[{"id":"A","content":"Because she is short of money.","isCorrect":false},{"id":"B","content":"Because she is serious about it.","isCorrect":false},{"id":"C","content":"Because she’s afraid she will fall asleep watching it.","isCorrect":true},{"id":"D","content":"Because she has stomach ache","isCorrect":false}]','C',0.286,NULL,15,'2026-01-30 18:56:06','Cô ấy sợ sẽ ngủ gật ("I''d fall asleep").');
INSERT INTO "vstep_questions" VALUES(2141,72,52,'Why doesn’t the woman want to watch a Robert de Niro?','MULTIPLE_CHOICE','[{"id":"A","content":"Because she feels too busy to watch it.","isCorrect":false},{"id":"B","content":"Because she feels too serious to watch it.","isCorrect":false},{"id":"C","content":"Because she doesn’t want to watch it the third time.","isCorrect":false},{"id":"D","content":"Because she doesn’t want to watch it the second time.","isCorrect":true}]','D',0.286,NULL,16,'2026-01-30 18:56:06','Cô ấy nói ghét xem phim hai lần ("hate seeing films twice").');
INSERT INTO "vstep_questions" VALUES(2142,72,52,'What does the girl think about a good holiday?','MULTIPLE_CHOICE','[{"id":"A","content":"It may be cheap.","isCorrect":true},{"id":"B","content":"It may be very cheap.","isCorrect":false},{"id":"C","content":"It may be expensive.","isCorrect":false},{"id":"D","content":"It may be very expensive.","isCorrect":false}]','A',0.286,NULL,17,'2026-01-30 18:56:06','Lisa nói: "A good holiday doesn''t have to be expensive" (Kỳ nghỉ tốt có thể rẻ).');
INSERT INTO "vstep_questions" VALUES(2143,72,52,'Why doesn’t the boy want to walk?','MULTIPLE_CHOICE','[{"id":"A","content":"Because he feels too hot to do it.","isCorrect":false},{"id":"B","content":"Because he finds it hard to do it.","isCorrect":false},{"id":"C","content":"Because he doesn''t like hard work.","isCorrect":true},{"id":"D","content":"Because she doesn''t like the sounds of people walking.","isCorrect":false}]','C',0.286,NULL,18,'2026-01-30 18:56:06','Ben than: "Walking all day sounds like hard work to me".');
INSERT INTO "vstep_questions" VALUES(2144,72,52,'What does the girl think about the food in Youth Hostels?','MULTIPLE_CHOICE','[{"id":"A","content":"It is comfortable.","isCorrect":false},{"id":"B","content":"It is good.","isCorrect":false},{"id":"C","content":"It is not good.","isCorrect":true},{"id":"D","content":"It is clean and cheap.","isCorrect":false}]','C',0.286,NULL,19,'2026-01-30 18:56:06','Lisa thừa nhận đồ ăn thường không ngon ("Food''s often not very good").');
INSERT INTO "vstep_questions" VALUES(2145,72,52,'What does the boy decide to do in the end?','MULTIPLE_CHOICE','[{"id":"A","content":"go home","isCorrect":false},{"id":"B","content":"leave home","isCorrect":false},{"id":"C","content":"stay at home","isCorrect":true},{"id":"D","content":"enjoy his holiday home","isCorrect":false}]','C',0.286,NULL,20,'2026-01-30 18:56:06','Ben chốt lại: "I think I''ll just stay home and get bored".');
INSERT INTO "vstep_questions" VALUES(2146,72,52,'Why did the speaker have to help her mother with the shopping?','MULTIPLE_CHOICE','[{"id":"A","content":"There were no Vietnamese people living near her.","isCorrect":false},{"id":"B","content":"There were no Vietnamese working in the stores.","isCorrect":true},{"id":"C","content":"There wasn''t always someone to go shopping with her.","isCorrect":false},{"id":"D","content":"Her mother could speak a little English.","isCorrect":false}]','B',0.286,NULL,21,'2026-01-30 18:56:06','Vì không có nhân viên người Việt trong cửa hàng để phiên dịch ("didn''t work in the stores").');
INSERT INTO "vstep_questions" VALUES(2147,72,52,'Why did her father find working in a factory difficult?','MULTIPLE_CHOICE','[{"id":"A","content":"He couldn''t speak any English.","isCorrect":false},{"id":"B","content":"He didn''t have many friends there.","isCorrect":false},{"id":"C","content":"He had had a much better job in Vietnam.","isCorrect":true},{"id":"D","content":"He couldn''t get used to the working style.","isCorrect":false}]','C',0.286,NULL,22,'2026-01-30 18:56:06','Ở VN ông làm bác sĩ, sang Mỹ làm công nhân là một bước lùi lớn về địa vị/công việc.');
INSERT INTO "vstep_questions" VALUES(2148,72,52,'Why are the speaker and her brother more fortunate than their sisters?','MULTIPLE_CHOICE','[{"id":"A","content":"They did not need extra English lessons.","isCorrect":false},{"id":"B","content":"They look more American.","isCorrect":false},{"id":"C","content":"They speak with American accents.","isCorrect":true},{"id":"D","content":"They quickly adopted the way of life.","isCorrect":false}]','C',0.286,NULL,23,'2026-01-30 18:56:06','Cô và em trai nói tiếng Anh giọng Mỹ ("speak with American accents") nên dễ hòa nhập hơn.');
INSERT INTO "vstep_questions" VALUES(2149,72,52,'What has the speaker forgotten about life in Vietnam?','MULTIPLE_CHOICE','[{"id":"A","content":"Living close to other people","isCorrect":true},{"id":"B","content":"The warm weather","isCorrect":false},{"id":"C","content":"Wearing traditional clothes","isCorrect":false},{"id":"D","content":"Traditional food","isCorrect":false}]','A',0.286,NULL,24,'2026-01-30 18:56:06','Cô quên văn hóa sống gần gũi, chan hòa ("share life... I don''t remember that").');
INSERT INTO "vstep_questions" VALUES(2150,72,52,'Why does she find it difficult to invite friends to her home?','MULTIPLE_CHOICE','[{"id":"A","content":"Her parents do not have much money.","isCorrect":false},{"id":"B","content":"Her parents haven''t adopted an American way of life.","isCorrect":true},{"id":"C","content":"Her parents only know how to cook Vietnamese food.","isCorrect":false},{"id":"D","content":"Her parents do not speak English well.","isCorrect":false}]','B',0.286,NULL,25,'2026-01-30 18:56:06','Bố mẹ vẫn giữ lối sống cũ, chưa quen lối sống Mỹ ("haven''t adopted an American way of life").');
INSERT INTO "vstep_questions" VALUES(2151,72,52,'What happened in American schools before 1972?','MULTIPLE_CHOICE','[{"id":"A","content":"Girls didn’t go to school.","isCorrect":false},{"id":"B","content":"Every classroom was a mix of boys and girls.","isCorrect":false},{"id":"C","content":"Boys could learn what they wanted.","isCorrect":false},{"id":"D","content":"They didn’t teach girls some subjects.","isCorrect":true}]','D',0.286,NULL,26,'2026-01-30 18:56:07','Trước năm 1972, trường học không dạy nữ sinh một số môn học.');
INSERT INTO "vstep_questions" VALUES(2152,72,52,'What is the reason that most American schools have mixed classes?','MULTIPLE_CHOICE','[{"id":"A","content":"Scientists said that it was the best thing.","isCorrect":false},{"id":"B","content":"Teachers did not want to teach single-gender classes.","isCorrect":false},{"id":"C","content":"A law gave girls an equal chance to learn.","isCorrect":true},{"id":"D","content":"Boys and girls behave better in such classes.","isCorrect":false}]','C',0.286,NULL,27,'2026-01-30 18:56:07','Do đạo luật "Title IX" ban hành yêu cầu bình đẳng giáo dục ("A law gave girls an equal chance").');
INSERT INTO "vstep_questions" VALUES(2153,72,52,'Why might girls not get a chance to talk much in a class with boys?','MULTIPLE_CHOICE','[{"id":"A","content":"Because the teacher doesn’t ask them questions","isCorrect":false},{"id":"B","content":"Because boys are louder and often talk first","isCorrect":true},{"id":"C","content":"Because boys know the correct answers","isCorrect":false},{"id":"D","content":"Because girls are often shy.","isCorrect":false}]','B',0.286,NULL,28,'2026-01-30 18:56:07','Con trai thường ồn ào và tranh nói trước ("louder... talk first").');
INSERT INTO "vstep_questions" VALUES(2154,72,52,'What is NOT the reason that some schools are reconsidering separating classes?','MULTIPLE_CHOICE','[{"id":"A","content":"They prefer the old teaching styles.","isCorrect":true},{"id":"B","content":"Boys learn differently than girls.","isCorrect":false},{"id":"C","content":"Boys and girls can bother each other.","isCorrect":false},{"id":"D","content":"Boys and girls like different things.","isCorrect":false}]','A',0.286,NULL,29,'2026-01-30 18:56:07','Các lý do B, C, D đều đúng. Lý do "thích phong cách cũ" (A) không được nhắc đến.');
INSERT INTO "vstep_questions" VALUES(2155,72,52,'Which is one class that is not mentioned as being separated?','MULTIPLE_CHOICE','[{"id":"A","content":"Math","isCorrect":false},{"id":"B","content":"Social Studies","isCorrect":false},{"id":"C","content":"Science","isCorrect":false},{"id":"D","content":"Physical Education","isCorrect":true}]','D',0.286,NULL,30,'2026-01-30 18:56:07','Bài nói liệt kê Math, Science, Social Studies, English nhưng không có Physical Education.');
INSERT INTO "vstep_questions" VALUES(2156,72,52,'Who is listening to the orientation talk?','MULTIPLE_CHOICE','[{"id":"A","content":"the director of international students","isCorrect":false},{"id":"B","content":"new international students","isCorrect":true},{"id":"C","content":"the teachers of international department","isCorrect":false},{"id":"D","content":"all first-year students in the college","isCorrect":false}]','B',0.286,NULL,31,'2026-01-30 18:56:07','Đối tượng là sinh viên quốc tế mới đến ("new international students").');
INSERT INTO "vstep_questions" VALUES(2157,72,52,'What is the purpose of this talk?','MULTIPLE_CHOICE','[{"id":"A","content":"to introduce the director for international student affairs","isCorrect":false},{"id":"B","content":"to deal with all international students’ problems.","isCorrect":false},{"id":"C","content":"to inform the importance of using English in class.","isCorrect":false},{"id":"D","content":"to introduce common problems in non-verbal communication.","isCorrect":true}]','D',0.286,NULL,32,'2026-01-30 18:56:07','Giới thiệu về các vấn đề giao tiếp phi ngôn ngữ ("non-verbal communication").');
INSERT INTO "vstep_questions" VALUES(2158,72,52,'According to the speaker, what is body language?','MULTIPLE_CHOICE','[{"id":"A","content":"It''s the use of verb tenses and modals.","isCorrect":false},{"id":"B","content":"It''s the way to ask for directions","isCorrect":false},{"id":"C","content":"It''s the language used in class only.","isCorrect":false},{"id":"D","content":"It’s the language of movements and facial expressions.","isCorrect":true}]','D',0.286,NULL,33,'2026-01-30 18:56:07','Định nghĩa là cử động và biểu cảm khuôn mặt ("movements and facial expressions").');
INSERT INTO "vstep_questions" VALUES(2159,72,52,'In American culture...','MULTIPLE_CHOICE','[{"id":"A","content":"Eye contact is the same as most cultures.","isCorrect":false},{"id":"B","content":"making eye contact is a sign of disrespect.","isCorrect":false},{"id":"C","content":"people don’t look in others’ eyes while talking.","isCorrect":false},{"id":"D","content":"eye contact is considered as a sign of honesty.","isCorrect":true}]','D',0.286,NULL,34,'2026-01-30 18:56:07','Giao tiếp bằng mắt được coi là dấu hiệu của sự trung thực ("sign of honesty").');
INSERT INTO "vstep_questions" VALUES(2160,72,52,'According to the speaker, what is TRUE about handshakes in American Culture?','MULTIPLE_CHOICE','[{"id":"A","content":"A handshake shouldnt be too strong.","isCorrect":false},{"id":"B","content":"Handshakes are not common.","isCorrect":false},{"id":"C","content":"Handshakes need to be firm.","isCorrect":true},{"id":"D","content":"Shaking hands is not important.","isCorrect":false}]','C',0.286,NULL,35,'2026-01-30 18:56:07','Cái bắt tay cần phải chặt/mạnh mẽ ("need to be firm").');
INSERT INTO "vstep_questions" VALUES(2161,73,53,'What colour is Mary''s coat?','MULTIPLE_CHOICE','[{"id":"A","content":"yellow","isCorrect":true},{"id":"B","content":"blue","isCorrect":false},{"id":"C","content":"brown","isCorrect":false},{"id":"D","content":"black","isCorrect":false}]','A',0.286,NULL,1,'2026-01-30 18:56:40','Người nói khen: "Yellow looks good on you" (Màu vàng trông hợp với bạn).');
INSERT INTO "vstep_questions" VALUES(2162,73,53,'What did the woman repair?','MULTIPLE_CHOICE','[{"id":"A","content":"chair","isCorrect":false},{"id":"B","content":"shelf","isCorrect":true},{"id":"C","content":"desk","isCorrect":false},{"id":"D","content":"bed","isCorrect":false}]','B',0.286,NULL,2,'2026-01-30 18:56:40','Cô ấy nói: "You know that broken shelf... I repaired it" (Tôi đã sửa cái kệ bị gãy).');
INSERT INTO "vstep_questions" VALUES(2163,73,53,'What are they going to buy for Pam?','MULTIPLE_CHOICE','[{"id":"A","content":"a book","isCorrect":false},{"id":"B","content":"a plant","isCorrect":true},{"id":"C","content":"some chocolates","isCorrect":false},{"id":"D","content":"candies","isCorrect":false}]','B',0.286,NULL,3,'2026-01-30 18:56:40','Họ quyết định: "Let''s get her something to put in her garden... a plant" (Mua cây để trong vườn).');
INSERT INTO "vstep_questions" VALUES(2164,73,53,'What has the girl lost?','MULTIPLE_CHOICE','[{"id":"A","content":"mobile phone","isCorrect":false},{"id":"B","content":"purse","isCorrect":true},{"id":"C","content":"pen","isCorrect":false},{"id":"D","content":"bag","isCorrect":false}]','B',0.286,NULL,4,'2026-01-30 18:56:40','Cô gái nói: "I think my purse fell out... I can''t find it now" (Tôi nghĩ cái ví bị rơi mất).');
INSERT INTO "vstep_questions" VALUES(2165,73,53,'Which sport will the boy do soon at the centre?','MULTIPLE_CHOICE','[{"id":"A","content":"waterskiing","isCorrect":false},{"id":"B","content":"diving","isCorrect":false},{"id":"C","content":"sailing","isCorrect":true},{"id":"D","content":"swimming","isCorrect":false}]','C',0.286,NULL,5,'2026-01-30 18:56:40','Cậu bé kể: "sailing lessons on the lake" (học chèo thuyền trên hồ vào cuối tuần tới).');
INSERT INTO "vstep_questions" VALUES(2166,73,53,'Who lives with Josh in his house?','MULTIPLE_CHOICE','[{"id":"A","content":"his grandmother","isCorrect":true},{"id":"B","content":"his father","isCorrect":false},{"id":"C","content":"his sister","isCorrect":false},{"id":"D","content":"his mother","isCorrect":false}]','A',0.286,NULL,6,'2026-01-30 18:56:40','Josh kể: "My grandmother''s moved into her room" (Bà tôi đã chuyển vào phòng).');
INSERT INTO "vstep_questions" VALUES(2167,73,53,'What will the girl take with her on holiday?','MULTIPLE_CHOICE','[{"id":"A","content":"suitcase","isCorrect":false},{"id":"B","content":"sports bag","isCorrect":false},{"id":"C","content":"backpack","isCorrect":true},{"id":"D","content":"overhead bag","isCorrect":false}]','C',0.286,NULL,7,'2026-01-30 18:56:41','Cô gái nói: "Suitcases are so heavy... I always take a backpack" (Tôi luôn mang ba lô).');
INSERT INTO "vstep_questions" VALUES(2168,73,53,'Where do the boys decide to go?','MULTIPLE_CHOICE','[{"id":"A","content":"cinema","isCorrect":true},{"id":"B","content":"game store","isCorrect":false},{"id":"C","content":"park","isCorrect":false},{"id":"D","content":"library","isCorrect":false}]','A',0.286,NULL,8,'2026-01-30 18:56:41','Một cậu rủ: "Let''s go and watch the film" (Hãy đi xem phim).');
INSERT INTO "vstep_questions" VALUES(2169,73,53,'Where was Geoff Thompson born?','MULTIPLE_CHOICE','[{"id":"A","content":"In London.","isCorrect":false},{"id":"B","content":"In the North of England.","isCorrect":true},{"id":"C","content":"In the South of London.","isCorrect":false},{"id":"D","content":"In Britain.","isCorrect":false}]','B',0.286,NULL,9,'2026-01-30 18:56:41','Geoff nói ông sinh ra "up in the North of England" (ở miền Bắc nước Anh).');
INSERT INTO "vstep_questions" VALUES(2170,73,53,'How did he know about karate?','MULTIPLE_CHOICE','[{"id":"A","content":"He discovered karate by himself.","isCorrect":false},{"id":"B","content":"He''s interested in karate owning to a sports center during a school visit.","isCorrect":true},{"id":"C","content":"His friend introduced it to him.","isCorrect":false},{"id":"D","content":"He knew it when moving to London.","isCorrect":false}]','B',0.286,NULL,10,'2026-01-30 18:56:41','Ông biết qua chuyến đi của trường ("school trip") tới một trung tâm thể thao.');
INSERT INTO "vstep_questions" VALUES(2171,73,53,'When did he take part in the World Championships in Taiwan?','MULTIPLE_CHOICE','[{"id":"A","content":"In 1972.","isCorrect":false},{"id":"B","content":"In 1980.","isCorrect":false},{"id":"C","content":"In 1982.","isCorrect":true},{"id":"D","content":"After starting training with a British coach.","isCorrect":false}]','C',0.286,NULL,11,'2026-01-30 18:56:41','Ông tham gia giải vô địch thế giới "in 1982".');
INSERT INTO "vstep_questions" VALUES(2172,73,53,'How many times has he got the World Champion?','MULTIPLE_CHOICE','[{"id":"A","content":"Two times.","isCorrect":false},{"id":"B","content":"Three times.","isCorrect":false},{"id":"C","content":"Four times.","isCorrect":false},{"id":"D","content":"Five times.","isCorrect":true}]','D',0.286,NULL,12,'2026-01-30 18:56:41','Ông đã vô địch tổng cộng 5 lần ("Five times in all").');
INSERT INTO "vstep_questions" VALUES(2173,73,53,'Which position does this hotel need?','MULTIPLE_CHOICE','[{"id":"A","content":"A temporary staff.","isCorrect":true},{"id":"B","content":"A stable staff.","isCorrect":false},{"id":"C","content":"A part-time receptionist.","isCorrect":false},{"id":"D","content":"A full-time waiter.","isCorrect":false}]','A',0.286,NULL,13,'2026-01-30 18:56:41','Người gọi xác nhận đây là vị trí cho nhân viên tạm thời ("temporary staff").');
INSERT INTO "vstep_questions" VALUES(2174,73,53,'What about the hour of work?','MULTIPLE_CHOICE','[{"id":"A","content":"There are two shifts and two days off.","isCorrect":false},{"id":"B","content":"There are two shifts and one day off.","isCorrect":true},{"id":"C","content":"There''s a day shift from 7 to 2 and a late shift from 4 till 11.","isCorrect":false},{"id":"D","content":"There is only afternoon shift.","isCorrect":false}]','B',0.286,NULL,14,'2026-01-30 18:56:41','Công việc có 2 ca ("two different shifts") và được nghỉ 1 ngày ("get one day off").');
INSERT INTO "vstep_questions" VALUES(2175,73,53,'What does the woman mention about the uniform?','MULTIPLE_CHOICE','[{"id":"A","content":"It''s prepared by the hotel.","isCorrect":false},{"id":"B","content":"He needs to wear dark clothes.","isCorrect":false},{"id":"C","content":"He needs a white shirt and dark trousers.","isCorrect":true},{"id":"D","content":"He needs wear uniform five days a week.","isCorrect":false}]','C',0.286,NULL,15,'2026-01-30 18:56:41','Yêu cầu trang phục là áo trắng và quần tối màu ("White shirt... dark trousers").');
INSERT INTO "vstep_questions" VALUES(2176,73,53,'When does he start his job?','MULTIPLE_CHOICE','[{"id":"A","content":"At the end of May.","isCorrect":false},{"id":"B","content":"On the 10th of May.","isCorrect":false},{"id":"C","content":"On the 10th of June.","isCorrect":false},{"id":"D","content":"On the 28th of June.","isCorrect":true}]','D',0.286,NULL,16,'2026-01-30 18:56:41','Bắt đầu làm việc vào ngày 28 tháng 6 ("The 28th... in time for the summer").');
INSERT INTO "vstep_questions" VALUES(2177,73,53,'What does the man plan to write his paper on?','MULTIPLE_CHOICE','[{"id":"A","content":"The preservation of old books.","isCorrect":false},{"id":"B","content":"The local coal industry.","isCorrect":true},{"id":"C","content":"The famous archives librarian.","isCorrect":false},{"id":"D","content":"The collection of rare books.","isCorrect":false}]','B',0.286,NULL,17,'2026-01-30 18:56:41','Anh ấy viết về sự phát triển của công nghiệp than ("coal mining industry").');
INSERT INTO "vstep_questions" VALUES(2178,73,53,'What security procedures does the librarian tell the man he must follow?','MULTIPLE_CHOICE','[{"id":"A","content":"Show her his note cards before leaving.","isCorrect":false},{"id":"B","content":"Show her his ID card.","isCorrect":false},{"id":"C","content":"Pay a fee.","isCorrect":false},{"id":"D","content":"Allow his ID card to be copied; sign in and out of the archives room.","isCorrect":true}]','D',0.286,NULL,18,'2026-01-30 18:56:41','Phải ký tên vào/ra và để lại bản sao ID ("Sign in and out... leave a copy of your ID").');
INSERT INTO "vstep_questions" VALUES(2179,73,53,'Why did the librarian mention the age of the books?','MULTIPLE_CHOICE','[{"id":"A","content":"They need to be handled with gloves.","isCorrect":true},{"id":"B","content":"The man can only look at photographs of them.","isCorrect":false},{"id":"C","content":"They were added to the collection recently.","isCorrect":false},{"id":"D","content":"They are value books.","isCorrect":false}]','A',0.286,NULL,19,'2026-01-30 18:56:41','Sách trên 100 tuổi nên phải đeo găng tay đặc biệt ("wear special gloves").');
INSERT INTO "vstep_questions" VALUES(2180,73,53,'How did the man collect his needed information about his paper?','MULTIPLE_CHOICE','[{"id":"A","content":"He took a picture.","isCorrect":false},{"id":"B","content":"He scanned these images.","isCorrect":false},{"id":"C","content":"He could just look them.","isCorrect":true},{"id":"D","content":"He photocopied these books.","isCorrect":false}]','C',0.286,NULL,20,'2026-01-30 18:56:41','Không được chụp ảnh hay photocopy mang về, chỉ được xem ("look at them") tại chỗ.');
INSERT INTO "vstep_questions" VALUES(2181,73,53,'The presenter doesn’t wear a suit because ...','MULTIPLE_CHOICE','[{"id":"A","content":"He is not an important person.","isCorrect":false},{"id":"B","content":"He wants to talk about different fashion trend.","isCorrect":false},{"id":"C","content":"The presentation is not formal.","isCorrect":true},{"id":"D","content":"He works for a fashion company.","isCorrect":false}]','C',0.286,NULL,21,'2026-01-30 18:56:41','Anh ấy không mặc vest để thể hiện buổi thuyết trình không trang trọng ("not a formal presentation").');
INSERT INTO "vstep_questions" VALUES(2182,73,53,'According to the speaker, which statement is TRUE?','MULTIPLE_CHOICE','[{"id":"A","content":"It''s important to look casually-dressed in public.","isCorrect":false},{"id":"B","content":"A suit is necessary when meeting clients.","isCorrect":true},{"id":"C","content":"Wearing shorts is OK, sometimes.","isCorrect":false},{"id":"D","content":"Nobody can describe the way he’s dressed.","isCorrect":false}]','B',0.286,NULL,22,'2026-01-30 18:56:41','Vest là cần thiết khi đi gặp khách hàng ("meeting a client").');
INSERT INTO "vstep_questions" VALUES(2183,73,53,'What does the phrase “Dress-down Fridays” mean?','MULTIPLE_CHOICE','[{"id":"A","content":"Employees must wear fashionable clothes on Fridays.","isCorrect":false},{"id":"B","content":"Employees can wear anything they want on Fridays.","isCorrect":false},{"id":"C","content":"Employees are allowed to wear informally on Fridays.","isCorrect":true},{"id":"D","content":"Employees are required to wear special clothes on Fridays.","isCorrect":false}]','C',0.286,NULL,23,'2026-01-30 18:56:41','Ngày thứ Sáu được phép ăn mặc thoải mái hơn ("dressing more informally").');
INSERT INTO "vstep_questions" VALUES(2184,73,53,'According to the speaker, who may be the most informal dressers?','MULTIPLE_CHOICE','[{"id":"A","content":"People working in IT","isCorrect":true},{"id":"B","content":"People working in banks.","isCorrect":false},{"id":"C","content":"People working in customer services.","isCorrect":false},{"id":"D","content":"People working with clients.","isCorrect":false}]','A',0.286,NULL,24,'2026-01-30 18:56:41','Dân IT thường ăn mặc thoải mái nhất (thậm chí mặc quần jeans).');
INSERT INTO "vstep_questions" VALUES(2185,73,53,'What does a customer feel about a man in uniform?','MULTIPLE_CHOICE','[{"id":"A","content":"reliable","isCorrect":false},{"id":"B","content":"recognized","isCorrect":false},{"id":"C","content":"expertised","isCorrect":false},{"id":"D","content":"reassured","isCorrect":true}]','D',0.286,NULL,25,'2026-01-30 18:56:41','Khách hàng cảm thấy an tâm ("reassured") khi thấy nhân viên mặc đồng phục.');
INSERT INTO "vstep_questions" VALUES(2186,73,53,'How many hours of sleep do experts suggest for kids?','MULTIPLE_CHOICE','[{"id":"A","content":"Ten","isCorrect":true},{"id":"B","content":"About fifteen","isCorrect":false},{"id":"C","content":"1,400","isCorrect":false},{"id":"D","content":"70","isCorrect":false}]','A',0.286,NULL,26,'2026-01-30 18:56:41','Trẻ em cần khoảng 10 tiếng ngủ ("Kids need about 10 hours").');
INSERT INTO "vstep_questions" VALUES(2187,73,53,'According to the speaker, why is sleep important for the brain?','MULTIPLE_CHOICE','[{"id":"A","content":"Sleep generates dreams so brain can relax.","isCorrect":false},{"id":"B","content":"Brain can rest in a sleep.","isCorrect":true},{"id":"C","content":"Sleep can save energy for the brain.","isCorrect":false},{"id":"D","content":"Sleep improves the effectiveness of the brain.","isCorrect":false}]','B',0.286,NULL,27,'2026-01-30 18:56:42','Giấc ngủ giúp não được nghỉ ngơi ("brain needs a little vacation").');
INSERT INTO "vstep_questions" VALUES(2188,73,53,'Why don’t the students learn well when they are tired?','MULTIPLE_CHOICE','[{"id":"A","content":"They can’t finish their homework.","isCorrect":false},{"id":"B","content":"They can’t deal with troubles in class.","isCorrect":false},{"id":"C","content":"They get very excited.","isCorrect":false},{"id":"D","content":"They can’t pay attention very well","isCorrect":true}]','D',0.286,NULL,28,'2026-01-30 18:56:42','Khi mệt mỏi học sinh không thể tập trung ("cannot pay attention").');
INSERT INTO "vstep_questions" VALUES(2189,73,53,'Which is NOT a reason for poor sleep?','MULTIPLE_CHOICE','[{"id":"A","content":"drinking soda","isCorrect":false},{"id":"B","content":"playing computer games","isCorrect":false},{"id":"C","content":"staying up late","isCorrect":false},{"id":"D","content":"exercising before sleep","isCorrect":true}]','D',0.286,NULL,29,'2026-01-30 18:56:42','Bài nói đề cập soda, game, TV làm mất ngủ. Tập thể dục không được nhắc đến như nguyên nhân xấu.');
INSERT INTO "vstep_questions" VALUES(2190,73,53,'What should students try to do each night?','MULTIPLE_CHOICE','[{"id":"A","content":"Watch a scary movie","isCorrect":false},{"id":"B","content":"Drink some hot tea","isCorrect":false},{"id":"C","content":"Go to bed at a regular time","isCorrect":true},{"id":"D","content":"relax with a TV show","isCorrect":false}]','C',0.286,NULL,30,'2026-01-30 18:56:42','Nên đi ngủ vào một giờ cố định hàng đêm ("Go to bed at the same time").');
INSERT INTO "vstep_questions" VALUES(2191,73,53,'Which is NOT the shape of the northern lights?','MULTIPLE_CHOICE','[{"id":"A","content":"a straight line","isCorrect":false},{"id":"B","content":"a curved line","isCorrect":false},{"id":"C","content":"around shape","isCorrect":false},{"id":"D","content":"an oval shape","isCorrect":true}]','D',0.286,NULL,31,'2026-01-30 18:56:42','Bài nói liệt kê: thẳng, cong, tròn. Hình Oval không được nhắc đến.');
INSERT INTO "vstep_questions" VALUES(2192,73,53,'What does “aurora borealis” exactly mean?','MULTIPLE_CHOICE','[{"id":"A","content":"northern lights","isCorrect":false},{"id":"B","content":"northern dawn","isCorrect":true},{"id":"C","content":"northern sky","isCorrect":false},{"id":"D","content":"early morning lights","isCorrect":false}]','B',0.286,NULL,32,'2026-01-30 18:56:42','"Aurora Borealis" có nghĩa là Bình minh phương Bắc ("Northern Dawn").');
INSERT INTO "vstep_questions" VALUES(2193,73,53,'Where is the best place to see the northern lights?','MULTIPLE_CHOICE','[{"id":"A","content":"The northernmost point of Earth","isCorrect":false},{"id":"B","content":"The north of Poland","isCorrect":false},{"id":"C","content":"Anywhere in Scandinavian countries","isCorrect":true},{"id":"D","content":"Most parts of the world","isCorrect":false}]','C',0.286,NULL,33,'2026-01-30 18:56:42','Nơi tốt nhất là các nước vùng Scandinavia hoặc Bắc Mỹ.');
INSERT INTO "vstep_questions" VALUES(2194,73,53,'What is one of the stories developed by people before modern science?','MULTIPLE_CHOICE','[{"id":"A","content":"The lights were caused by foxes.","isCorrect":true},{"id":"B","content":"The lights were the dance of animals.","isCorrect":false},{"id":"C","content":"The lights appeared when people.","isCorrect":false},{"id":"D","content":"The lights came from fires of northern gods.","isCorrect":false}]','A',0.286,NULL,34,'2026-01-30 18:56:42','Truyền thuyết kể rằng ánh sáng do những con cáo tạo ra lửa ("caused by foxes made fires").');
INSERT INTO "vstep_questions" VALUES(2195,73,53,'Which of the following is NOT mentioned in this talk?','MULTIPLE_CHOICE','[{"id":"A","content":"A description of the lights","isCorrect":false},{"id":"B","content":"The scientific explanation for the lights","isCorrect":false},{"id":"C","content":"The discovery of the lights","isCorrect":true},{"id":"D","content":"Beliefs about the lights","isCorrect":false}]','C',0.286,NULL,35,'2026-01-30 18:56:42','Bài nói có mô tả, giải thích khoa học, và truyền thuyết, nhưng không nói ai đã phát hiện ra (Discovery).');
INSERT INTO "vstep_questions" VALUES(2196,74,54,'What have they forgotten?','MULTIPLE_CHOICE','[{"id":"A","content":"ticket","isCorrect":false},{"id":"B","content":"camera","isCorrect":true},{"id":"C","content":"passport","isCorrect":false},{"id":"D","content":"bag","isCorrect":false}]','B',0.286,NULL,1,'2026-01-30 18:57:30','Họ kiểm tra: hộ chiếu (có), tiền (có), nhưng máy ảnh thì "left it behind" (để quên).');
INSERT INTO "vstep_questions" VALUES(2197,74,54,'What time does the train go?','MULTIPLE_CHOICE','[{"id":"A","content":"6.15","isCorrect":true},{"id":"B","content":"7.4","isCorrect":false},{"id":"C","content":"6.1","isCorrect":false},{"id":"D","content":"7.1","isCorrect":false}]','A',0.286,NULL,2,'2026-01-30 18:57:30','Người nói xác nhận: "At six fifteen" (Lúc 6:15).');
INSERT INTO "vstep_questions" VALUES(2198,74,54,'How did the woman get to work?','MULTIPLE_CHOICE','[{"id":"A","content":"by bicycle","isCorrect":false},{"id":"B","content":"by bus","isCorrect":false},{"id":"C","content":"by car","isCorrect":true},{"id":"D","content":"by train","isCorrect":false}]','C',0.286,NULL,3,'2026-01-30 18:57:30','Xe đạp hỏng, xe buýt trễ, nên "I had to take the car" (Tôi phải đi ô tô).');
INSERT INTO "vstep_questions" VALUES(2199,74,54,'Where are the man’s shoes?','MULTIPLE_CHOICE','[{"id":"A","content":"under the chair","isCorrect":false},{"id":"B","content":"by the television","isCorrect":false},{"id":"C","content":"by the door with the other rubbish","isCorrect":true},{"id":"D","content":"under the table","isCorrect":false}]','C',0.286,NULL,4,'2026-01-30 18:57:30','Người phụ nữ chỉ: "Oh look, they''re by the door with the other rubbish".');
INSERT INTO "vstep_questions" VALUES(2200,74,54,'What will Paul get at the shop?','MULTIPLE_CHOICE','[{"id":"A","content":"mushrooms","isCorrect":false},{"id":"B","content":"onions","isCorrect":false},{"id":"C","content":"carrots","isCorrect":true},{"id":"D","content":"red pepper","isCorrect":false}]','C',0.286,NULL,5,'2026-01-30 18:57:30','Paul xác nhận: "So just the carrots then? - Yes thanks."');
INSERT INTO "vstep_questions" VALUES(2201,74,54,'How were they told to do their homework?','MULTIPLE_CHOICE','[{"id":"A","content":"write it in the books","isCorrect":false},{"id":"B","content":"write it on paper","isCorrect":false},{"id":"C","content":"type it","isCorrect":true},{"id":"D","content":"email it","isCorrect":false}]','C',0.286,NULL,6,'2026-01-30 18:57:30','Giáo viên dặn: "Mr. Sims said to type it" (Thầy Sims bảo đánh máy).');
INSERT INTO "vstep_questions" VALUES(2202,74,54,'What did Helen buy?','MULTIPLE_CHOICE','[{"id":"A","content":"gloves","isCorrect":false},{"id":"B","content":"sweater","isCorrect":false},{"id":"C","content":"socks","isCorrect":true},{"id":"D","content":"hat","isCorrect":false}]','C',0.286,NULL,7,'2026-01-30 18:57:30','Helen kể: "in the end I bought these socks" (Cuối cùng tôi mua đôi tất này).');
INSERT INTO "vstep_questions" VALUES(2203,74,54,'How did the woman get to work today?','MULTIPLE_CHOICE','[{"id":"A","content":"by bus","isCorrect":false},{"id":"B","content":"a neighbour offered her a lift","isCorrect":true},{"id":"C","content":"by bike","isCorrect":false},{"id":"D","content":"walk","isCorrect":false}]','B',0.286,NULL,8,'2026-01-30 18:57:30','Cô ấy nói: "My neighbour offered me a lift" (Hàng xóm cho tôi đi nhờ).');
INSERT INTO "vstep_questions" VALUES(2204,74,54,'What hours does the speaker work on Monday?','MULTIPLE_CHOICE','[{"id":"A","content":"Noon to 6 PM","isCorrect":false},{"id":"B","content":"8:15 AM to 5PM","isCorrect":false},{"id":"C","content":"7AM to 12PM","isCorrect":true},{"id":"D","content":"5PM to 9PM","isCorrect":false}]','C',0.286,NULL,9,'2026-01-30 18:57:30','Tyrone nói: "Mondays, I start at 7:00 and finish at 12:00".');
INSERT INTO "vstep_questions" VALUES(2205,74,54,'On which two days does the speaker have the same schedule?','MULTIPLE_CHOICE','[{"id":"A","content":"Monday and Tuesday","isCorrect":false},{"id":"B","content":"Wednesday and Thursday","isCorrect":false},{"id":"C","content":"Tuesday and Thursday","isCorrect":true},{"id":"D","content":"Thursday and Friday","isCorrect":false}]','C',0.286,NULL,10,'2026-01-30 18:57:30','Lịch thứ Năm: "The same as Tuesday" (Giống thứ Ba).');
INSERT INTO "vstep_questions" VALUES(2206,74,54,'What is the main purpose of the speaker''s talk?','MULTIPLE_CHOICE','[{"id":"A","content":"To discuss the importance of the job","isCorrect":false},{"id":"B","content":"To compare the work of doctors and dentists","isCorrect":false},{"id":"C","content":"To describe a typical week at work","isCorrect":true},{"id":"D","content":"To explain the details of a day at work","isCorrect":false}]','C',0.286,NULL,11,'2026-01-30 18:57:30','Tyrone đang mô tả về "working week" (tuần làm việc) của mình cho bài tập trường.');
INSERT INTO "vstep_questions" VALUES(2207,74,54,'What does the speaker think of her work?','MULTIPLE_CHOICE','[{"id":"A","content":"She enjoys sleeping late every morning.","isCorrect":false},{"id":"B","content":"It is difficult to describe her schedule.","isCorrect":false},{"id":"C","content":"She enjoys helping the patients.","isCorrect":true},{"id":"D","content":"It is too complicated to remember.","isCorrect":false}]','C',0.286,NULL,12,'2026-01-30 18:57:30','Tyrone nói: "I enjoy it because I get to help people/patients".');
INSERT INTO "vstep_questions" VALUES(2208,74,54,'According to the conversation, which item did the woman NOT purchase with her credit card?','MULTIPLE_CHOICE','[{"id":"A","content":"a digital camera","isCorrect":false},{"id":"B","content":"DVD player","isCorrect":true},{"id":"C","content":"a TV","isCorrect":false},{"id":"D","content":"a stereo","isCorrect":false}]','B',0.286,NULL,13,'2026-01-30 18:57:30','Khi được hỏi về DVD player, cô nói: "No, I didn''t buy that."');
INSERT INTO "vstep_questions" VALUES(2209,74,54,'What is one reason to explain why the woman obtained a student credit card?','MULTIPLE_CHOICE','[{"id":"A","content":"She wants to buy things at a discount using the card","isCorrect":false},{"id":"B","content":"She hopes to establish a good credit rating.","isCorrect":true},{"id":"C","content":"She doesn''t want to borrow from her parents.","isCorrect":false},{"id":"D","content":"She can be financially independent.","isCorrect":false}]','B',0.286,NULL,14,'2026-01-30 18:57:30','Cô giải thích: "I wanted to build up my credit rating" (xây dựng điểm tín dụng).');
INSERT INTO "vstep_questions" VALUES(2210,74,54,'What does the woman imply about how she plans on resolving her credit card problems?','MULTIPLE_CHOICE','[{"id":"A","content":"She hopes that someone will give her the money.","isCorrect":false},{"id":"B","content":"She plans on getting rid of her student credit cards.","isCorrect":false},{"id":"C","content":"She''ll get a part-time job","isCorrect":true},{"id":"D","content":"She is going to return the items she purchased on the card.","isCorrect":false}]','C',0.286,NULL,15,'2026-01-30 18:57:30','Cô ấy nói: "I guess I''ll have to get a part-time job" (phải kiếm việc làm thêm).');
INSERT INTO "vstep_questions" VALUES(2211,74,54,'What is the man going to do for the woman to help her manage her money?','MULTIPLE_CHOICE','[{"id":"A","content":"help her find a better paying job to cover her expenses","isCorrect":false},{"id":"B","content":"teach her how to prepare a financial management plan","isCorrect":true},{"id":"C","content":"show her how she can apply for low-interest student credit cards","isCorrect":false},{"id":"D","content":"teach her how to shop wisely.","isCorrect":false}]','B',0.286,NULL,16,'2026-01-30 18:57:30','Anh đề nghị: "help you make a budget" (giúp lập ngân sách/kế hoạch tài chính).');
INSERT INTO "vstep_questions" VALUES(2212,74,54,'Why does the customer not buy the recommended sandwich at the beginning of the conversation?','MULTIPLE_CHOICE','[{"id":"A","content":"It is too expensive.","isCorrect":true},{"id":"B","content":"He is not interested in ordering a burger.","isCorrect":false},{"id":"C","content":"It is not tasty.","isCorrect":false},{"id":"D","content":"He fears the food will make him sick.","isCorrect":false}]','A',0.286,NULL,17,'2026-01-30 18:57:30','Khách phàn nàn: "That''s too expensive for a sandwich" (Quá đắt cho một cái sandwich).');
INSERT INTO "vstep_questions" VALUES(2213,74,54,'How does the specialty drink get its name?','MULTIPLE_CHOICE','[{"id":"A","content":"It contains a wide range of ingredients.","isCorrect":true},{"id":"B","content":"It is prepared in the kitchen sink.","isCorrect":false},{"id":"C","content":"It contains chicken soup.","isCorrect":false},{"id":"D","content":"It comes in a very large cup.","isCorrect":false}]','A',0.286,NULL,18,'2026-01-30 18:57:30','Tên "Kitchen Sink" vì nó chứa mọi thứ trừ cái bồn rửa ("everything in it except the kitchen sink").');
INSERT INTO "vstep_questions" VALUES(2214,74,54,'Why was the man surprised by the price of his meal?','MULTIPLE_CHOICE','[{"id":"A","content":"He thought the drink should have been included.","isCorrect":true},{"id":"B","content":"He felt the meal was way overpriced.","isCorrect":false},{"id":"C","content":"He was charged for two sandwiches instead of one.","isCorrect":false},{"id":"D","content":"It was lower than he had expected.","isCorrect":false}]','A',0.286,NULL,19,'2026-01-30 18:57:30','Khách nói: "I thought the drink came with the meal" (tưởng đồ uống miễn phí đi kèm).');
INSERT INTO "vstep_questions" VALUES(2215,74,54,'What does the customer decide to do at the end of the conversation?','MULTIPLE_CHOICE','[{"id":"A","content":"He orders something from the restaurant menu.","isCorrect":false},{"id":"B","content":"He plans to come back at weekend.","isCorrect":false},{"id":"C","content":"He decides to look for another place to eat.","isCorrect":true},{"id":"D","content":"He plans to come in a week when the prices are lower.","isCorrect":false}]','C',0.286,NULL,20,'2026-01-30 18:57:30','Khách bỏ đi: "I''m going to a fast food place" (Tôi sẽ sang tiệm đồ ăn nhanh).');
INSERT INTO "vstep_questions" VALUES(2216,74,54,'What did Sandy Duffy want to be when she was at school?','MULTIPLE_CHOICE','[{"id":"A","content":"a journalist","isCorrect":true},{"id":"B","content":"a musician","isCorrect":false},{"id":"C","content":"A director","isCorrect":false},{"id":"D","content":"A basketball player","isCorrect":false}]','A',0.286,NULL,21,'2026-01-30 18:57:31','Sandy kể: "I always wanted to be a journalist" (luôn muốn làm nhà báo).');
INSERT INTO "vstep_questions" VALUES(2217,74,54,'What did Sandy study at university?','MULTIPLE_CHOICE','[{"id":"A","content":"Math and Physics","isCorrect":false},{"id":"B","content":"film making","isCorrect":true},{"id":"C","content":"Technology","isCorrect":false},{"id":"D","content":"Art","isCorrect":false}]','B',0.286,NULL,22,'2026-01-30 18:57:31','Sandy nói: "I went to study film making" (tôi đi học làm phim).');
INSERT INTO "vstep_questions" VALUES(2218,74,54,'How did Sandy get her first job as a video game writer?','MULTIPLE_CHOICE','[{"id":"A","content":"She answered a job advertisement.","isCorrect":true},{"id":"B","content":"She met someone at a conference.","isCorrect":false},{"id":"C","content":"She sent some information about herself to a company.","isCorrect":false},{"id":"D","content":"She was invited by a friend.","isCorrect":false}]','A',0.286,NULL,23,'2026-01-30 18:57:31','Sandy kể: "I saw an advertisement in the newspaper" (thấy quảng cáo trên báo).');
INSERT INTO "vstep_questions" VALUES(2219,74,54,'What does Sandy like best about being a video game writer?','MULTIPLE_CHOICE','[{"id":"A","content":"the prizes she has won.","isCorrect":false},{"id":"B","content":"the high salary","isCorrect":false},{"id":"C","content":"the people she works with","isCorrect":true},{"id":"D","content":"the great working condition","isCorrect":false}]','C',0.286,NULL,24,'2026-01-30 18:57:31','Sandy nói: "The best thing is the people I work with" (Điều tuyệt nhất là những người tôi làm cùng).');
INSERT INTO "vstep_questions" VALUES(2220,74,54,'What does Sandy dislike about being a video game writer?','MULTIPLE_CHOICE','[{"id":"A","content":"She has to travel a lot.","isCorrect":false},{"id":"B","content":"She has to work long hours.","isCorrect":true},{"id":"C","content":"She often has to change her job.","isCorrect":false},{"id":"D","content":"She has to live far from home.","isCorrect":false}]','B',0.286,NULL,25,'2026-01-30 18:57:31','Sandy phàn nàn: "I don''t like the long hours" (không thích làm việc nhiều giờ).');
INSERT INTO "vstep_questions" VALUES(2221,74,54,'How long does the trek last?','MULTIPLE_CHOICE','[{"id":"A","content":"a day","isCorrect":false},{"id":"B","content":"three days","isCorrect":false},{"id":"C","content":"five days","isCorrect":true},{"id":"D","content":"a week","isCorrect":false}]','C',0.286,NULL,26,'2026-01-30 18:57:31','Chuyến đi bộ kéo dài 5 ngày ("The trek itself takes five days").');
INSERT INTO "vstep_questions" VALUES(2222,74,54,'The trek aims to raise money for .............','MULTIPLE_CHOICE','[{"id":"A","content":"health care","isCorrect":false},{"id":"B","content":"school education","isCorrect":false},{"id":"C","content":"hospital","isCorrect":true},{"id":"D","content":"the old people","isCorrect":false}]','C',0.286,NULL,27,'2026-01-30 18:57:31','Mục đích là gây quỹ cho bệnh viện địa phương ("local hospital").');
INSERT INTO "vstep_questions" VALUES(2223,74,54,'The cost of the trek includes ...............','MULTIPLE_CHOICE','[{"id":"A","content":"flight and airport taxes","isCorrect":false},{"id":"B","content":"medical provision and taxes","isCorrect":false},{"id":"C","content":"Foods","isCorrect":false},{"id":"D","content":"Food and accommodation","isCorrect":true}]','D',0.286,NULL,28,'2026-01-30 18:57:31','Chi phí bao gồm vé máy bay, thuế và "all food and accommodation" (ăn ở).');
INSERT INTO "vstep_questions" VALUES(2224,74,54,'Participants must.................','MULTIPLE_CHOICE','[{"id":"A","content":"walk across a glacier.","isCorrect":false},{"id":"B","content":"complete a fitness course.","isCorrect":false},{"id":"C","content":"agree to raise funds for the charity.","isCorrect":true},{"id":"D","content":"pay amount of money.","isCorrect":false}]','C',0.286,NULL,29,'2026-01-30 18:57:31','Người tham gia phải cam kết gây quỹ ("agree to raise a minimum amount").');
INSERT INTO "vstep_questions" VALUES(2225,74,54,'The trip starts on ................','MULTIPLE_CHOICE','[{"id":"A","content":"1st of November","isCorrect":false},{"id":"B","content":"3rd of November","isCorrect":true},{"id":"C","content":"13th of November","isCorrect":false},{"id":"D","content":"23th of November","isCorrect":false}]','B',0.286,NULL,30,'2026-01-30 18:57:31','Ngày khởi hành là mùng 3 tháng 11 ("We leave on the 3rd of November").');
INSERT INTO "vstep_questions" VALUES(2226,74,54,'Where do many of the rich people live?','MULTIPLE_CHOICE','[{"id":"A","content":"next to the new road","isCorrect":false},{"id":"B","content":"in the cities.","isCorrect":false},{"id":"C","content":"in the countryside.","isCorrect":false},{"id":"D","content":"in isolated places.","isCorrect":true}]','D',0.286,NULL,31,'2026-01-30 18:57:31','Người giàu chuyển đến những nơi biệt lập ("isolated places") để yên tĩnh.');
INSERT INTO "vstep_questions" VALUES(2227,74,54,'How long is the road?','MULTIPLE_CHOICE','[{"id":"A","content":"600 kilometres","isCorrect":false},{"id":"B","content":"6,000 kilometers","isCorrect":true},{"id":"C","content":"60,000 kilometres","isCorrect":false},{"id":"D","content":"60 miles","isCorrect":false}]','B',0.286,NULL,32,'2026-01-30 18:57:31','Con đường dài 6,000 km.');
INSERT INTO "vstep_questions" VALUES(2228,74,54,'What can you see on the computers at the road’s headquarters in Delhi?','MULTIPLE_CHOICE','[{"id":"A","content":"small vehicles on the road","isCorrect":false},{"id":"B","content":"any vehicle and problems on the road","isCorrect":true},{"id":"C","content":"big vehicles on the road","isCorrect":false},{"id":"D","content":"serious problems on the road","isCorrect":false}]','B',0.286,NULL,33,'2026-01-30 18:57:31','Máy tính theo dõi mọi phương tiện ("monitor any vehicle") và phát hiện sự cố.');
INSERT INTO "vstep_questions" VALUES(2229,74,54,'What types of transport can you see on the road?','MULTIPLE_CHOICE','[{"id":"A","content":"all types","isCorrect":true},{"id":"B","content":"mostly cars","isCorrect":false},{"id":"C","content":"mostly motorbikes","isCorrect":false},{"id":"D","content":"the presenter doesn’t say","isCorrect":false}]','A',0.286,NULL,34,'2026-01-30 18:57:31','Có thể thấy đủ loại phương tiện ("see all kinds of transport").');
INSERT INTO "vstep_questions" VALUES(2230,74,54,'Why does the presenter describe the new road as a symbol of India’s future?','MULTIPLE_CHOICE','[{"id":"A","content":"because it''s the same shape as the country of India.","isCorrect":false},{"id":"B","content":"because it is modern, it is helping the economy grow.","isCorrect":true},{"id":"C","content":"Because India has big population","isCorrect":false},{"id":"D","content":"Because India has lots of transport","isCorrect":false}]','B',0.286,NULL,35,'2026-01-30 18:57:31','Nó hiện đại và giúp kinh tế phát triển ("helping the economy grow").');
INSERT INTO "vstep_questions" VALUES(2231,75,55,'What is John going to do tonight?','MULTIPLE_CHOICE','[{"id":"A","content":"swimming","isCorrect":false},{"id":"B","content":"cycling","isCorrect":false},{"id":"C","content":"playing football","isCorrect":false},{"id":"D","content":"running","isCorrect":true}]','D',0.286,NULL,1,'2026-01-30 18:58:02','John nhớ ra đã đồng ý đi chạy bộ với đồng nghiệp ("agreed to go for a run").');
INSERT INTO "vstep_questions" VALUES(2232,75,55,'Which bag does the woman buy?','MULTIPLE_CHOICE','[{"id":"A","content":"square bag","isCorrect":true},{"id":"B","content":"small and round bag","isCorrect":false},{"id":"C","content":"a big bag","isCorrect":false},{"id":"D","content":"an oval bag","isCorrect":false}]','A',0.286,NULL,2,'2026-01-30 18:58:02','Cô ấy quyết định: "I think the square one is better" (Cái vuông tốt hơn).');
INSERT INTO "vstep_questions" VALUES(2233,75,55,'How much did the woman pay for the apples?','MULTIPLE_CHOICE','[{"id":"A","content":"30 pence","isCorrect":false},{"id":"B","content":"35 pence","isCorrect":true},{"id":"C","content":"40 pence","isCorrect":false},{"id":"D","content":"34 pence","isCorrect":false}]','B',0.286,NULL,3,'2026-01-30 18:58:02','Táo lớn có giá 35 xu ("The big ones are 35 pence").');
INSERT INTO "vstep_questions" VALUES(2234,75,55,'When must the boys get on the coach?','MULTIPLE_CHOICE','[{"id":"A","content":"12:50","isCorrect":false},{"id":"B","content":"1:30","isCorrect":true},{"id":"C","content":"2:30","isCorrect":false},{"id":"D","content":"3:20","isCorrect":false}]','B',0.286,NULL,4,'2026-01-30 18:58:02','Phải lên xe lúc 1:30 ("get on the coach at 1:30").');
INSERT INTO "vstep_questions" VALUES(2235,75,55,'What fruit do they take?','MULTIPLE_CHOICE','[{"id":"A","content":"oranges","isCorrect":false},{"id":"B","content":"bananas","isCorrect":true},{"id":"C","content":"grapes","isCorrect":false},{"id":"D","content":"apples","isCorrect":false}]','B',0.286,NULL,5,'2026-01-30 18:58:03','Mẹ bảo cam bẩn, nên mang chuối ("You''d better take bananas").');
INSERT INTO "vstep_questions" VALUES(2236,75,55,'Which present has the man bought?','MULTIPLE_CHOICE','[{"id":"A","content":"book","isCorrect":false},{"id":"B","content":"bag","isCorrect":false},{"id":"C","content":"gloves","isCorrect":true},{"id":"D","content":"flowers","isCorrect":false}]','C',0.286,NULL,6,'2026-01-30 18:58:03','Người đàn ông nói: "I''ve bought these gloves" (Tôi đã mua đôi găng tay này).');
INSERT INTO "vstep_questions" VALUES(2237,75,55,'Where are the photographs?','MULTIPLE_CHOICE','[{"id":"A","content":"on the bookshelf","isCorrect":false},{"id":"B","content":"on the TV","isCorrect":false},{"id":"C","content":"on the table with the coffee cups","isCorrect":true},{"id":"D","content":"in the café shop","isCorrect":false}]','C',0.286,NULL,7,'2026-01-30 18:58:03','Chúng ở trên bàn cùng với tách cà phê ("on the table with the coffee cups").');
INSERT INTO "vstep_questions" VALUES(2238,75,55,'What did Ben break?','MULTIPLE_CHOICE','[{"id":"A","content":"vase","isCorrect":false},{"id":"B","content":"glass","isCorrect":false},{"id":"C","content":"cup","isCorrect":false},{"id":"D","content":"dinner bowls","isCorrect":true}]','D',0.286,NULL,8,'2026-01-30 18:58:03','Ben nói vỡ cái bát ăn tối ("one of the dinner bowls").');
INSERT INTO "vstep_questions" VALUES(2239,75,55,'When is the picnic?','MULTIPLE_CHOICE','[{"id":"A","content":"on Thursday","isCorrect":false},{"id":"B","content":"on Friday","isCorrect":false},{"id":"C","content":"on Saturday","isCorrect":true},{"id":"D","content":"on Sunday","isCorrect":false}]','C',0.286,NULL,9,'2026-01-30 18:58:03','Họ chốt đi vào thứ Bảy ("Let''s go on Saturday then").');
INSERT INTO "vstep_questions" VALUES(2240,75,55,'Where is the picnic being held?','MULTIPLE_CHOICE','[{"id":"A","content":"at a park","isCorrect":false},{"id":"B","content":"at the beach","isCorrect":false},{"id":"C","content":"at Dave''s house","isCorrect":false},{"id":"D","content":"by a river","isCorrect":true}]','D',0.286,NULL,10,'2026-01-30 18:58:03','Họ chọn bờ sông ("The river is a nice place").');
INSERT INTO "vstep_questions" VALUES(2241,75,55,'How many packages of hot dogs do they decide to buy?','MULTIPLE_CHOICE','[{"id":"A","content":"6","isCorrect":false},{"id":"B","content":"7","isCorrect":true},{"id":"C","content":"9","isCorrect":false},{"id":"D","content":"(No option D)","isCorrect":false}]','B',0.286,NULL,11,'2026-01-30 18:58:03','Quyết định mua 7 gói ("Better make it 7 packages").');
INSERT INTO "vstep_questions" VALUES(2242,75,55,'What does Dave suggest Scott make for the picnic dessert?','MULTIPLE_CHOICE','[{"id":"A","content":"cherry pie","isCorrect":false},{"id":"B","content":"chocolate cake","isCorrect":false},{"id":"C","content":"oatmeal cookies","isCorrect":false},{"id":"D","content":"fudge brownies","isCorrect":true}]','D',0.286,NULL,12,'2026-01-30 18:58:03','Scott sẽ làm bánh brownies ("Scott can make fudge brownies").');
INSERT INTO "vstep_questions" VALUES(2243,75,55,'What does the boy want to do at the beginning of the conversation?','MULTIPLE_CHOICE','[{"id":"A","content":"go play outside","isCorrect":true},{"id":"B","content":"play video games","isCorrect":false},{"id":"C","content":"watch TV","isCorrect":false},{"id":"D","content":"play football","isCorrect":false}]','A',0.286,NULL,13,'2026-01-30 18:58:03','Cậu bé xin bố: "Dad, can I go outside to play?" (Con ra ngoài chơi được không?).');
INSERT INTO "vstep_questions" VALUES(2244,75,55,'What does the boy have to do in his bedroom?','MULTIPLE_CHOICE','[{"id":"A","content":"put away his books","isCorrect":false},{"id":"B","content":"make his bed","isCorrect":true},{"id":"C","content":"pick up his dirty clothes","isCorrect":false},{"id":"D","content":"clean the floor","isCorrect":false}]','B',0.286,NULL,14,'2026-01-30 18:58:03','Bố yêu cầu cậu đi dọn giường ("Go make it").');
INSERT INTO "vstep_questions" VALUES(2245,75,55,'What is the father going to do while the boy is doing his household chores?','MULTIPLE_CHOICE','[{"id":"A","content":"wash the car","isCorrect":false},{"id":"B","content":"paint the house","isCorrect":true},{"id":"C","content":"work in the yard","isCorrect":false},{"id":"D","content":"clean the floor","isCorrect":false}]','B',0.286,NULL,15,'2026-01-30 18:58:03','Bố nói sẽ sơn nhà ("I''m going to paint the house").');
INSERT INTO "vstep_questions" VALUES(2246,75,55,'Where will the father and son go after the housework is done?','MULTIPLE_CHOICE','[{"id":"A","content":"to a movie","isCorrect":true},{"id":"B","content":"out to eat","isCorrect":false},{"id":"C","content":"to a ballgame","isCorrect":false},{"id":"D","content":"to a shopping center","isCorrect":false}]','A',0.286,NULL,16,'2026-01-30 18:58:03','Bố hứa làm xong sẽ đi xem phim ("We can go to a movie").');
