INSERT INTO "vstep_questions" VALUES(2250,75,55,'What are they going to do after dinner?','MULTIPLE_CHOICE','[{"id":"A","content":"The group is going to watch a musical","isCorrect":false},{"id":"B","content":"They will catch an exciting movie","isCorrect":false},{"id":"C","content":"They will be attending a Broadway play","isCorrect":true},{"id":"D","content":"They will see a football match","isCorrect":false}]','C',0.286,NULL,20,'2026-01-30 18:58:03','Sau bữa tối họ sẽ đi xem kịch Broadway ("see a Broadway play").');
INSERT INTO "vstep_questions" VALUES(2251,75,55,'The first old ship which Frank found was...','MULTIPLE_CHOICE','[{"id":"A","content":"covered by rocks","isCorrect":false},{"id":"B","content":"older than he first thought","isCorrect":true},{"id":"C","content":"easy to find","isCorrect":false},{"id":"D","content":"had a lot of gold","isCorrect":false}]','B',0.286,NULL,21,'2026-01-30 18:58:03','Con tàu cổ hơn anh ấy nghĩ lúc đầu ("older than I first thought").');
INSERT INTO "vstep_questions" VALUES(2252,75,55,'Why did Frank find the ships so quickly?','MULTIPLE_CHOICE','[{"id":"A","content":"reads history books","isCorrect":true},{"id":"B","content":"is a professional driver","isCorrect":false},{"id":"C","content":"his friends helped him","isCorrect":false},{"id":"D","content":"uses the latest equipment","isCorrect":false}]','A',0.286,NULL,22,'2026-01-30 18:58:03','Anh ấy đọc sách lịch sử ("read history books") để tìm vị trí.');
INSERT INTO "vstep_questions" VALUES(2253,75,55,'What does Frank say about the ship called The Seabird?','MULTIPLE_CHOICE','[{"id":"A","content":"It was so expensive","isCorrect":false},{"id":"B","content":"It was built in 1859","isCorrect":false},{"id":"C","content":"It sank in a storm","isCorrect":true},{"id":"D","content":"It was badly made","isCorrect":false}]','C',0.286,NULL,23,'2026-01-30 18:58:03','Tàu Seabird bị chìm trong bão ("sank in a storm").');
INSERT INTO "vstep_questions" VALUES(2254,75,55,'What did Frank say about his wedding ring?','MULTIPLE_CHOICE','[{"id":"A","content":"was made from gold he found himself","isCorrect":true},{"id":"B","content":"it was given by someone","isCorrect":false},{"id":"C","content":"is worth 88,000 pounds","isCorrect":false},{"id":"D","content":"was found by a friend","isCorrect":false}]','A',0.286,NULL,24,'2026-01-30 18:58:03','Nhẫn làm từ vàng anh ấy tự tìm thấy ("made from a piece of gold I found").');
INSERT INTO "vstep_questions" VALUES(2255,75,55,'How did Frank learn to dive?','MULTIPLE_CHOICE','[{"id":"A","content":"by joining a diving club","isCorrect":false},{"id":"B","content":"by asking the dive tutor","isCorrect":false},{"id":"C","content":"by teaching himself","isCorrect":true},{"id":"D","content":"by going on a diving holiday","isCorrect":false}]','C',0.286,NULL,25,'2026-01-30 18:58:03','Anh ấy tự học lặn ("taught myself").');
INSERT INTO "vstep_questions" VALUES(2256,75,55,'The Black Rock Caves have been home for...','MULTIPLE_CHOICE','[{"id":"A","content":"Two million years","isCorrect":true},{"id":"B","content":"A million year","isCorrect":false},{"id":"C","content":"A half a million year","isCorrect":false},{"id":"D","content":"centuries","isCorrect":false}]','A',0.286,NULL,26,'2026-01-30 18:58:03','Hang động đã tồn tại 2 triệu năm ("two million years").');
INSERT INTO "vstep_questions" VALUES(2257,75,55,'When can the cave attract the tourists?','MULTIPLE_CHOICE','[{"id":"A","content":"from April to October","isCorrect":true},{"id":"B","content":"April","isCorrect":false},{"id":"C","content":"October","isCorrect":false},{"id":"D","content":"August","isCorrect":false}]','A',0.286,NULL,27,'2026-01-30 18:58:03','Mở cửa từ tháng 4 đến tháng 10 ("April to October").');
INSERT INTO "vstep_questions" VALUES(2258,75,55,'Salter house was built in...','MULTIPLE_CHOICE','[{"id":"A","content":"1765","isCorrect":true},{"id":"B","content":"1756","isCorrect":false},{"id":"C","content":"1928","isCorrect":false},{"id":"D","content":"1982","isCorrect":false}]','A',0.286,NULL,28,'2026-01-30 18:58:04','Nhà Salter được xây năm 1765.');
INSERT INTO "vstep_questions" VALUES(2259,75,55,'The things that are worth to visit in Salter house is...','MULTIPLE_CHOICE','[{"id":"A","content":"the furniture","isCorrect":false},{"id":"B","content":"the paintings","isCorrect":false},{"id":"C","content":"the enormous meals","isCorrect":false},{"id":"D","content":"the kitchen","isCorrect":true}]','D',0.286,NULL,29,'2026-01-30 18:58:04','Nổi tiếng với căn bếp ("famous for its kitchen").');
INSERT INTO "vstep_questions" VALUES(2260,75,55,'What should tourists do as visiting The Old Port?','MULTIPLE_CHOICE','[{"id":"A","content":"take an old trek to visit the riverside","isCorrect":false},{"id":"B","content":"buy different traditional costumes","isCorrect":false},{"id":"C","content":"try sweets made in the Tea Shop","isCorrect":false},{"id":"D","content":"visit the village factory","isCorrect":true}]','D',0.286,NULL,30,'2026-01-30 18:58:04','Nên thăm nhà máy làm kẹo trong làng ("visit the village factory").');
INSERT INTO "vstep_questions" VALUES(2261,75,55,'What does the professor say about the elements in the body?','MULTIPLE_CHOICE','[{"id":"A","content":"Ideally, these should be different amounts of each.","isCorrect":false},{"id":"B","content":"The amount of each in the body is not very important.","isCorrect":false},{"id":"C","content":"They can be out of balance.","isCorrect":false},{"id":"D","content":"Different people have different elements.","isCorrect":true}]','D',0.286,NULL,31,'2026-01-30 18:58:04','Mỗi người có lượng nguyên tố khác nhau ("Different people have different amounts").');
INSERT INTO "vstep_questions" VALUES(2262,75,55,'According to the professor, what are yin and yang?','MULTIPLE_CHOICE','[{"id":"A","content":"They are opposite forces.","isCorrect":true},{"id":"B","content":"They are what make a person healthy.","isCorrect":false},{"id":"C","content":"They are four different elements.","isCorrect":false},{"id":"D","content":"They are the land and the ocean.","isCorrect":false}]','A',0.286,NULL,32,'2026-01-30 18:58:04','Âm và Dương là hai lực đối lập ("opposite forces").');
INSERT INTO "vstep_questions" VALUES(2263,75,55,'What does the professor say about yin and yang?','MULTIPLE_CHOICE','[{"id":"A","content":"They are always in balance.","isCorrect":false},{"id":"B","content":"They are always changing.","isCorrect":true},{"id":"C","content":"They don’t need to be in balance.","isCorrect":false},{"id":"D","content":"They compare with each other.","isCorrect":false}]','B',0.286,NULL,33,'2026-01-30 18:58:04','Chúng luôn thay đổi ("always changing").');
INSERT INTO "vstep_questions" VALUES(2264,75,55,'According to the Chinese, five elements of Yin and Yang are studied for the work of','MULTIPLE_CHOICE','[{"id":"A","content":"the body and spirit","isCorrect":false},{"id":"B","content":"body, mind and spirit work","isCorrect":true},{"id":"C","content":"balance and harmony","isCorrect":false},{"id":"D","content":"(No option D)","isCorrect":false}]','B',0.286,NULL,34,'2026-01-30 18:58:04','Nghiên cứu cho cơ thể, tâm trí và tinh thần ("body, mind and spirit work").');
INSERT INTO "vstep_questions" VALUES(2265,75,55,'Why does the professor says “Yin and Yang should be considered as opposite forces... like land and ocean”?','MULTIPLE_CHOICE','[{"id":"A","content":"To correct something she said earlier","isCorrect":false},{"id":"B","content":"To explain a term she just introduced","isCorrect":true},{"id":"C","content":"To explain what is wrong with a particular theory","isCorrect":false},{"id":"D","content":"To remind the students of something discussed earlier","isCorrect":false}]','B',0.286,NULL,35,'2026-01-30 18:58:04','Để giải thích/lấy ví dụ cho khái niệm "lực đối lập" vừa nhắc đến.');
