INSERT INTO "vstep_questions" VALUES(2316,77,57,'What did Jackie feel about her daughter''s performance?','MULTIPLE_CHOICE','[{"id":"A","content":"She was ashamed","isCorrect":false},{"id":"B","content":"She was amazed","isCorrect":true},{"id":"C","content":"She didn’t like it much","isCorrect":false},{"id":"D","content":"She couldn’t sing","isCorrect":false}]','B',0.286,NULL,16,'2026-01-30 18:59:16','Mọi người đều kinh ngạc ("astonished") bao gồm cả gia đình.');
INSERT INTO "vstep_questions" VALUES(2317,77,57,'What is true about Kira?','MULTIPLE_CHOICE','[{"id":"A","content":"She went home last year","isCorrect":false},{"id":"B","content":"She started a course in Pharmacy over again.","isCorrect":false},{"id":"C","content":"She is a third year student","isCorrect":true},{"id":"D","content":"She will finish her course in 12 months","isCorrect":false}]','C',0.286,NULL,17,'2026-01-30 18:59:16','Kira vào thẳng năm 3 ("straight into third year").');
INSERT INTO "vstep_questions" VALUES(2318,77,57,'What does she think about her course now?','MULTIPLE_CHOICE','[{"id":"A","content":"it is difficult","isCorrect":false},{"id":"B","content":"it is similar to the course she did","isCorrect":true},{"id":"C","content":"it is easier","isCorrect":false},{"id":"D","content":"she doesn’t like it","isCorrect":false}]','B',0.286,NULL,18,'2026-01-30 18:59:16','Nội dung rất giống ("Content was very similar").');
INSERT INTO "vstep_questions" VALUES(2319,77,57,'Why does she say her assignment is difficult?','MULTIPLE_CHOICE','[{"id":"A","content":"she is not familiar with it","isCorrect":false},{"id":"B","content":"she is expected to be critical","isCorrect":true},{"id":"C","content":"she feels terrible","isCorrect":false},{"id":"D","content":"her lecturer is terrible","isCorrect":false}]','B',0.286,NULL,19,'2026-01-30 18:59:16','Giảng viên mong đợi tư duy phản biện ("expect you to be critical").');
INSERT INTO "vstep_questions" VALUES(2320,77,57,'What does she mean about lecturers in her country?','MULTIPLE_CHOICE','[{"id":"A","content":"They are horrible","isCorrect":false},{"id":"B","content":"You can talk to them easily","isCorrect":false},{"id":"C","content":"They are knowledgeable","isCorrect":false},{"id":"D","content":"It''s hard to discuss with them","isCorrect":true}]','D',0.286,NULL,20,'2026-01-30 18:59:16','Ở đây dễ tiếp cận hơn ("Here they''re much easier to approach") => Ở nước cô ấy khó hơn.');
INSERT INTO "vstep_questions" VALUES(2321,77,57,'You do not have to provide...','MULTIPLE_CHOICE','[{"id":"A","content":"a letter of recommendation.","isCorrect":false},{"id":"B","content":"school records.","isCorrect":false},{"id":"C","content":"exam results.","isCorrect":false},{"id":"D","content":"health certificate.","isCorrect":true}]','D',0.286,NULL,21,'2026-01-30 18:59:16','Không yêu cầu giấy chứng nhận sức khỏe trong danh sách hồ sơ.');
INSERT INTO "vstep_questions" VALUES(2322,77,57,'Your required English level depends on...','MULTIPLE_CHOICE','[{"id":"A","content":"your age.","isCorrect":false},{"id":"B","content":"your chosen course.","isCorrect":true},{"id":"C","content":"your grades.","isCorrect":false},{"id":"D","content":"your nationality.","isCorrect":false}]','B',0.286,NULL,22,'2026-01-30 18:59:16','Phụ thuộc vào ngành học ("Different majors require different abilities").');
INSERT INTO "vstep_questions" VALUES(2323,77,57,'Some science Courses require you to...','MULTIPLE_CHOICE','[{"id":"A","content":"take an exam.","isCorrect":false},{"id":"B","content":"complete a foundation year.","isCorrect":true},{"id":"C","content":"do extra personal study.","isCorrect":false},{"id":"D","content":"have a higher level of English.","isCorrect":false}]','B',0.286,NULL,23,'2026-01-30 18:59:16','Yêu cầu hoàn thành năm dự bị ("complete a foundation year").');
INSERT INTO "vstep_questions" VALUES(2324,77,57,'Application for undergraduate courses is...','MULTIPLE_CHOICE','[{"id":"A","content":"always via UCAS.","isCorrect":true},{"id":"B","content":"direct with universities.","isCorrect":false},{"id":"C","content":"either via UCAS or direct with universities.","isCorrect":false},{"id":"D","content":"via a placement agency.","isCorrect":false}]','A',0.286,NULL,24,'2026-01-30 18:59:16','Luôn phải thông qua UCAS ("always via UCAS").');
INSERT INTO "vstep_questions" VALUES(2325,77,57,'British universities...','MULTIPLE_CHOICE','[{"id":"A","content":"are the best in the world.","isCorrect":false},{"id":"B","content":"rank among the top universities in the world.","isCorrect":false},{"id":"C","content":"are all well respected.","isCorrect":false},{"id":"D","content":"are generally well respected.","isCorrect":true}]','D',0.286,NULL,25,'2026-01-30 18:59:16','Được tôn trọng trên toàn cầu ("generally respected globally").');
INSERT INTO "vstep_questions" VALUES(2326,77,57,'In 1993 Dan Pearman went to Ecuador ...','MULTIPLE_CHOICE','[{"id":"A","content":"as a tour guide.","isCorrect":false},{"id":"B","content":"as part of his studies.","isCorrect":false},{"id":"C","content":"as a voluntary worker.","isCorrect":true},{"id":"D","content":"a student.","isCorrect":false}]','C',0.286,NULL,26,'2026-01-30 18:59:16','Đi với tư cách tình nguyện viên ("voluntary organization").');
INSERT INTO "vstep_questions" VALUES(2327,77,57,'Dan''s neighbour was successful in business because he...','MULTIPLE_CHOICE','[{"id":"A","content":"employed carpenters from the area.","isCorrect":false},{"id":"B","content":"was the most skilled craftsman in the town.","isCorrect":false},{"id":"C","content":"found it easy to reach customers.","isCorrect":true},{"id":"D","content":"worked very hard.","isCorrect":false}]','C',0.286,NULL,27,'2026-01-30 18:59:16','Dễ tiếp cận khách hàng hơn nhờ xe đạp ("accept jobs in 3km radius").');
INSERT INTO "vstep_questions" VALUES(2328,77,57,'Dan says the charity relies on...','MULTIPLE_CHOICE','[{"id":"A","content":"getting enough bicycles to send regularly.","isCorrect":true},{"id":"B","content":"finding new areas which need the bicycles.","isCorrect":false},{"id":"C","content":"charging for the bicycles it sends abroad.","isCorrect":false},{"id":"D","content":"getting the second-hand bikes from the rich.","isCorrect":false}]','A',0.286,NULL,28,'2026-01-30 18:59:16','Cần nguồn cung xe đạp ổn định ("constant supply of bikes").');
INSERT INTO "vstep_questions" VALUES(2329,77,57,'What does Dan say about the town of Rivas?','MULTIPLE_CHOICE','[{"id":"A","content":"It has received the greatest number of bikes.","isCorrect":false},{"id":"B","content":"It has almost as many bikes as Amsterdam.","isCorrect":false},{"id":"C","content":"Its economy has been totally transformed.","isCorrect":true},{"id":"D","content":"Everyone there owns a bicycle.","isCorrect":false}]','C',0.286,NULL,29,'2026-01-30 18:59:16','Kinh tế phát triển mạnh ("local economy has developed so much").');
INSERT INTO "vstep_questions" VALUES(2330,77,57,'What problem did the charity face in August 2000?','MULTIPLE_CHOICE','[{"id":"A","content":"It couldn’t meet its overheads.","isCorrect":true},{"id":"B","content":"It had to delay sending the bikes","isCorrect":false},{"id":"C","content":"It was criticized in British media.","isCorrect":false},{"id":"D","content":"It didn’t get enough bikes ready to send.","isCorrect":false}]','A',0.286,NULL,30,'2026-01-30 18:59:16','Hết tiền trả chi phí ("ran out of money").');
INSERT INTO "vstep_questions" VALUES(2331,77,57,'According to the speaker the main cause of back pain in women is ...','MULTIPLE_CHOICE','[{"id":"A","content":"pregnancy.","isCorrect":false},{"id":"B","content":"osteoporosis.","isCorrect":true},{"id":"C","content":"lack of exercise.","isCorrect":false},{"id":"D","content":"too much exercise.","isCorrect":false}]','B',0.286,NULL,31,'2026-01-30 18:59:16','Nguyên nhân chính là loãng xương ("osteoporosis... major cause").');
INSERT INTO "vstep_questions" VALUES(2332,77,57,'As treatment for back pain the Clinic mainly recommends...','MULTIPLE_CHOICE','[{"id":"A","content":"pain killers.","isCorrect":false},{"id":"B","content":"relaxation therapy.","isCorrect":true},{"id":"C","content":"exercise routines.","isCorrect":false},{"id":"D","content":"bed rest.","isCorrect":false}]','B',0.286,NULL,32,'2026-01-30 18:59:17','Khuyên dùng liệu pháp thư giãn ("benefits of relaxation therapy").');
INSERT INTO "vstep_questions" VALUES(2333,77,57,'The back is different from other parts of the body because...','MULTIPLE_CHOICE','[{"id":"A","content":"it is usually better at self-repair.","isCorrect":false},{"id":"B","content":"a back injury is usually more painful.","isCorrect":false},{"id":"C","content":"its response to injury often results in more damage.","isCorrect":true},{"id":"D","content":"it is worse if we keep the back as immobile as possible.","isCorrect":false}]','C',0.286,NULL,33,'2026-01-30 18:59:17','Phản ứng của cơ thể thường gây hại thêm ("counterproductive").');
INSERT INTO "vstep_questions" VALUES(2334,77,57,'Bed rest is advised...','MULTIPLE_CHOICE','[{"id":"A","content":"for a maximum of two days.","isCorrect":true},{"id":"B","content":"for less than two days.","isCorrect":false},{"id":"C","content":"for pain lasting more than two days.","isCorrect":false},{"id":"D","content":"for extreme pain only.","isCorrect":false}]','A',0.286,NULL,34,'2026-01-30 18:59:17','Chỉ nên nghỉ ngơi tối đa 2 ngày ("up to two days").');
INSERT INTO "vstep_questions" VALUES(2335,77,57,'Being overweight...','MULTIPLE_CHOICE','[{"id":"A","content":"is a major source of back pain.","isCorrect":false},{"id":"B","content":"worsens existing back pain.","isCorrect":true},{"id":"C","content":"reduces the effectiveness of exercise.","isCorrect":false},{"id":"D","content":"is the only cause of back pain.","isCorrect":false}]','B',0.286,NULL,35,'2026-01-30 18:59:17','Làm tình trạng đau lưng tồi tệ hơn ("make things worse").');
INSERT INTO "vstep_questions" VALUES(2613,93,77,'The writer says that baseball ...........','MULTIPLE_CHOICE','[{"id":"1","content":"is played only in America.","isCorrect":false},{"id":"2","content":"is not popular in countries like Japan.","isCorrect":false},{"id":"3","content":"started in South America.","isCorrect":false},{"id":"4","content":"is becoming more popular all over the world.","isCorrect":true}]','D',0.25,NULL,1,'2026-02-10 14:43:59','Bài đọc nói: "more and more countries are putting together teams" (ngày càng nhiều nước thành lập đội).');
INSERT INTO "vstep_questions" VALUES(2614,93,77,'According to the text, baseball is played in more and more countries because .............','MULTIPLE_CHOICE','[{"id":"1","content":"it is an exciting game.","isCorrect":false},{"id":"2","content":"it is included in the Olympic Games.","isCorrect":true},{"id":"3","content":"Many American people live there.","isCorrect":false},{"id":"4","content":"It is easy to play.","isCorrect":false}]','B',0.25,NULL,2,'2026-02-10 14:43:59','"Since baseball is an Olympic sport..." (Vì bóng chày là môn thể thao Olympic).');
INSERT INTO "vstep_questions" VALUES(2615,93,77,'Which sentence isn''t true about baseball?','MULTIPLE_CHOICE','[{"id":"1","content":"It was first played during the 1850s.","isCorrect":false},{"id":"2","content":"It is an Olympic sport.","isCorrect":false},{"id":"3","content":"The rules have changed quite a lot over the years.","isCorrect":true},{"id":"4","content":"It started in New York.","isCorrect":false}]','C',0.25,NULL,3,'2026-02-10 14:43:59','Bài đọc nói: "It has changed a little bit... but the basic game remains the same" (chỉ thay đổi một chút, cơ bản vẫn giữ nguyên) -> Ý C nói thay đổi "quite a lot" là sai.');
INSERT INTO "vstep_questions" VALUES(2616,93,77,'Which piece of equipment is not mentioned in the text?','MULTIPLE_CHOICE','[{"id":"1","content":"bat","isCorrect":false},{"id":"2","content":"ball","isCorrect":false},{"id":"3","content":"glove","isCorrect":false},{"id":"4","content":"mask","isCorrect":true}]','D',0.25,NULL,4,'2026-02-10 14:44:00','Bài đọc nhắc đến: bat, ball, glove, shirt, trousers, cap. Không có "mask" (mặt nạ).');
INSERT INTO "vstep_questions" VALUES(2617,93,77,'In which space (marked t [a and in the passage) will the following sentence fit? "Players wear shoes with spikes..."','MULTIPLE_CHOICE','[{"id":"1","content":"(A)","isCorrect":false},{"id":"2","content":"(B)","isCorrect":true},{"id":"3","content":"(C)","isCorrect":false},{"id":"4","content":"(D)","isCorrect":false}]','B',0.25,NULL,5,'2026-02-10 14:44:00','Câu này mô tả trang phục (shoes, cap), phù hợp để nối tiếp đoạn mô tả "shirt and trousers" (đoạn 4). Vị trí B (cuối đoạn 4 hoặc đầu đoạn 5) là hợp lý nhất trong ngữ cảnh này.');
INSERT INTO "vstep_questions" VALUES(2618,93,77,'What is the baseball field like?','MULTIPLE_CHOICE','[{"id":"1","content":"It has an infield, an outfield and a middle field.","isCorrect":false},{"id":"2","content":"There are three diamonds on the ground.","isCorrect":false},{"id":"3","content":"There are three bases on the diamond.","isCorrect":true},{"id":"4","content":"It is usually in an indoor stadium.","isCorrect":false}]','C',0.25,NULL,6,'2026-02-10 14:44:01','"On the diamond, there are also the three bases" (Trên hình kim cương có 3 cứ điểm).');
INSERT INTO "vstep_questions" VALUES(2619,93,77,'The game is divided into............','MULTIPLE_CHOICE','[{"id":"1","content":"two halves.","isCorrect":false},{"id":"2","content":"nine innings.","isCorrect":true},{"id":"3","content":"three bases.","isCorrect":false},{"id":"4","content":"an infield and an outfield.","isCorrect":false}]','B',0.25,NULL,7,'2026-02-10 14:44:01','"The game of baseball is divided into nine parts, called innings."');
INSERT INTO "vstep_questions" VALUES(2620,93,77,'The object of the game is to..............','MULTIPLE_CHOICE','[{"id":"1","content":"catch as many balls as you can.","isCorrect":false},{"id":"2","content":"hit the ball the farthest.","isCorrect":false},{"id":"3","content":"score the most runs.","isCorrect":true},{"id":"4","content":"bat as often as you can.","isCorrect":false}]','C',0.25,NULL,8,'2026-02-10 14:44:01','"The team that scores the most runs... wins."');
INSERT INTO "vstep_questions" VALUES(2621,93,77,'What is true about a baseball match?','MULTIPLE_CHOICE','[{"id":"1","content":"It''s slow.","isCorrect":false},{"id":"2","content":"It often takes place on hot summer days.","isCorrect":false},{"id":"3","content":"Spectators are not allowed to bring foods to the ballpark.","isCorrect":false},{"id":"4","content":"The speed of the match may change suddenly.","isCorrect":true}]','D',0.25,NULL,9,'2026-02-10 14:44:02','"can go very slowly... then suddenly have a series of fast... moves" (tốc độ thay đổi đột ngột).');
INSERT INTO "vstep_questions" VALUES(2622,93,77,'According to the text, most American people have .............','MULTIPLE_CHOICE','[{"id":"1","content":"childhood memory at a ballpark.","isCorrect":true},{"id":"2","content":"a baseball gear.","isCorrect":false},{"id":"3","content":"experience of participating in at least a baseball inning.","isCorrect":false},{"id":"4","content":"all of them","isCorrect":false}]','A',0.25,NULL,10,'2026-02-10 14:44:02','"nearly everyone''s favourite childhood memory includes a day at the ballpark."');
INSERT INTO "vstep_questions" VALUES(2623,94,77,'In the first paragraph, the writer says that athletes today ............','MULTIPLE_CHOICE','[{"id":"1","content":"are more popular than in ancient times.","isCorrect":false},{"id":"2","content":"are much better than in ancient times.","isCorrect":false},{"id":"3","content":"treat the Olympics like a business.","isCorrect":false},{"id":"4","content":"can become wealthy through sport.","isCorrect":true}]','D',0.25,NULL,11,'2026-02-10 14:44:03','"The athletes then could make a lot of money... just like today''s competitors." (Vận động viên ngày xưa kiếm nhiều tiền, giống như ngày nay).');
INSERT INTO "vstep_questions" VALUES(2624,94,77,'What does the word “ This” in line 8 refer to?','MULTIPLE_CHOICE','[{"id":"1","content":"the champion","isCorrect":false},{"id":"2","content":"the running race","isCorrect":false},{"id":"3","content":"Greece","isCorrect":false},{"id":"4","content":"the pentathlon","isCorrect":true}]','D',0.25,NULL,12,'2026-02-10 14:44:03','"In the ancient Olympics, athletes competed in the pentathlon. This consisted of..." -> This = the pentathlon.');
INSERT INTO "vstep_questions" VALUES(2625,94,77,'The ancient pentathlon didn''t test athletes’ abilities to...............','MULTIPLE_CHOICE','[{"id":"1","content":"throw things.","isCorrect":false},{"id":"2","content":"jump high.","isCorrect":true},{"id":"3","content":"run fast.","isCorrect":false},{"id":"4","content":"jump far.","isCorrect":false}]','B',0.25,NULL,13,'2026-02-10 14:44:03','Pentathlon gồm: long jump (xa), discus/javelin (ném), running (chạy), wrestling (đấu vật). Không có nhảy cao (high jump).');
INSERT INTO "vstep_questions" VALUES(2626,94,77,'Lampis of Sparta was................','MULTIPLE_CHOICE','[{"id":"1","content":"the organizer of the first ancient Olympics","isCorrect":false},{"id":"2","content":"Emperor Theodosius of Rome","isCorrect":false},{"id":"3","content":"the first winner of the ancient Olympics","isCorrect":true},{"id":"4","content":"the greatest athlete in history","isCorrect":false}]','C',0.25,NULL,14,'2026-02-10 14:44:04','"The first winner, in 708 BC, was Lampis of Sparta".');
INSERT INTO "vstep_questions" VALUES(2627,94,77,'According to the passage, the heptathlon for women ............','MULTIPLE_CHOICE','[{"id":"1","content":"became an Olympic event after 1912.","isCorrect":true},{"id":"2","content":"similar to the ancient pentathlon.","isCorrect":false},{"id":"3","content":"tests the ability to ride a horse.","isCorrect":false},{"id":"4","content":"is much easier than the decathlon.","isCorrect":false}]','A',0.25,NULL,15,'2026-02-10 14:44:04','"...heptathlon... being introduced later" (được giới thiệu sau năm 1912).');
INSERT INTO "vstep_questions" VALUES(2628,94,77,'How many sporting events were included in the modern decathlon of Stockholm Olympics in 1912?','MULTIPLE_CHOICE','[{"id":"1","content":"only one","isCorrect":false},{"id":"2","content":"five","isCorrect":false},{"id":"3","content":"seven","isCorrect":false},{"id":"4","content":"ten","isCorrect":true}]','D',0.25,NULL,16,'2026-02-10 14:44:05','"decathlon (ten events)".');
INSERT INTO "vstep_questions" VALUES(2629,94,77,'What did Bruce Thorpe say about decathlon?','MULTIPLE_CHOICE','[{"id":"1","content":"It is challenging and requires athletes to have various skills.","isCorrect":true},{"id":"2","content":"There''s no need for participants to train hard.","isCorrect":false},{"id":"3","content":"It has only seven events.","isCorrect":false},{"id":"4","content":"It takes one day to decide the winner.","isCorrect":false}]','A',0.25,NULL,17,'2026-02-10 14:44:05','"It''s very tough and it demands a lot of different skills."');
INSERT INTO "vstep_questions" VALUES(2630,94,77,'What do you have to do to win a gold medal in the decathlon?','MULTIPLE_CHOICE','[{"id":"1","content":"Score more points than all the other competitors.","isCorrect":true},{"id":"2","content":"Beat the other competitors in at least three events.","isCorrect":false},{"id":"3","content":"Finish each event in the top three.","isCorrect":false},{"id":"4","content":"Complete the events in the right order.","isCorrect":false}]','A',0.25,NULL,18,'2026-02-10 14:44:05','"the person with the most points is the champion".');
INSERT INTO "vstep_questions" VALUES(2631,94,77,'What does Bruce say about the events?','MULTIPLE_CHOICE','[{"id":"1","content":"The 1500 metres should be on the first day.","isCorrect":false},{"id":"2","content":"The first day is tougher than the second.","isCorrect":false},{"id":"3","content":"The 1500 metres is different from the other events.","isCorrect":true},{"id":"4","content":"It looks easier than it actually is.","isCorrect":false}]','C',0.25,NULL,19,'2026-02-10 14:44:06','1500m đòi hỏi sức bền (stamina), trong khi các môn khác cần tốc độ/sức mạnh -> Khác biệt.');
INSERT INTO "vstep_questions" VALUES(2632,94,77,'What is Bruce''s advice for people thinking of becoming decathletes?','MULTIPLE_CHOICE','[{"id":"1","content":"Get a trainer to guide you.","isCorrect":true},{"id":"2","content":"Get up early to start training","isCorrect":false},{"id":"3","content":"Take up the heptathlon instead.","isCorrect":false},{"id":"4","content":"Try to get a good time in all the events.","isCorrect":false}]','A',0.25,NULL,20,'2026-02-10 14:44:07','"join a good club... you need expert help" (Cần sự giúp đỡ của chuyên gia/HLV).');
INSERT INTO "vstep_questions" VALUES(2633,95,77,'Why did David Cornthwaite decide to skateboard across Australia?','MULTIPLE_CHOICE','[{"id":"1","content":"He was an experienced skateboarder","isCorrect":false},{"id":"2","content":"He wanted to break a world record","isCorrect":false},{"id":"3","content":"He was bored with his life and wanted to try something different","isCorrect":true},{"id":"4","content":"Somebody gave him a guidebook about Australia","isCorrect":false}]','C',0.25,NULL,21,'2026-02-10 14:44:07','Anh ấy ghét công việc hiện tại ("hated his job"), cảm thấy vỡ mộng ("disillusioned") và muốn tìm cái gì đó mới mẻ ("looking for something new").');
INSERT INTO "vstep_questions" VALUES(2634,95,77,'The word “disillusioned” in line 5 can be best replaced by ............','MULTIPLE_CHOICE','[{"id":"1","content":"disappointed","isCorrect":true},{"id":"2","content":"embarrassed","isCorrect":false},{"id":"3","content":"fascinated","isCorrect":false},{"id":"4","content":"delighted","isCorrect":false}]','A',0.25,NULL,22,'2026-02-10 14:44:08','"Disillusioned" = vỡ mộng, chán nản ~ "disappointed".');
INSERT INTO "vstep_questions" VALUES(2635,95,77,'His preparation in Britain was..............','MULTIPLE_CHOICE','[{"id":"1","content":"successful, but painful","isCorrect":true},{"id":"2","content":"successful, but more time-consuming than planned","isCorrect":false},{"id":"3","content":"successful, but more difficult than he had realised","isCorrect":false},{"id":"4","content":"unsuccessful because he got injured","isCorrect":false}]','A',0.25,NULL,23,'2026-02-10 14:44:08','Anh ấy hoàn thành chuyến đi ("finished") nhưng bị phồng rộp nặng ("infected blister... size of a tennis ball") -> Đau đớn.');
INSERT INTO "vstep_questions" VALUES(2636,95,77,'What made David fall off his skateboard several times in Australia?','MULTIPLE_CHOICE','[{"id":"1","content":"thunderstorms in the Outback","isCorrect":false},{"id":"2","content":"the trains that race across the Outback","isCorrect":false},{"id":"3","content":"the injuries on his feet","isCorrect":false},{"id":"4","content":"the wind created by huge lorries going past","isCorrect":true}]','D',0.25,NULL,24,'2026-02-10 14:44:09','Gió tạo ra bởi những chiếc xe tải lớn ("wind caused by huge road trains... articulated lorries").');
INSERT INTO "vstep_questions" VALUES(2637,95,77,'At times, David felt as though he................','MULTIPLE_CHOICE','[{"id":"1","content":"needed to stop for a while.","isCorrect":true},{"id":"2","content":"wanted to give up completely.","isCorrect":false},{"id":"3","content":"wanted to get out of the sun.","isCorrect":false},{"id":"4","content":"needed a new pair of shoes.","isCorrect":false}]','A',0.25,NULL,25,'2026-02-10 14:44:09','"I thought ''this is ridiculous, I have to rest'', but I never contemplated giving up" (Muốn nghỉ ngơi, nhưng chưa bao giờ nghĩ đến bỏ cuộc).');
INSERT INTO "vstep_questions" VALUES(2638,95,77,'During the journey, where did David sleep at night?','MULTIPLE_CHOICE','[{"id":"1","content":"in a four-wheel drive vehicle","isCorrect":false},{"id":"2","content":"in a tent","isCorrect":true},{"id":"3","content":"outdoors on the Nullarbor Plain","isCorrect":false},{"id":"4","content":"in the homes of his supporters","isCorrect":false}]','B',0.25,NULL,26,'2026-02-10 14:44:10','Xe hỗ trợ mang theo "camping equipment" (dụng cụ cắm trại) -> Ngủ lều.');
INSERT INTO "vstep_questions" VALUES(2639,95,77,'David fell off his skateboard because ...............','MULTIPLE_CHOICE','[{"id":"1","content":"he was going too fast his journey","isCorrect":false},{"id":"2","content":"he was exhausted and in pain","isCorrect":false},{"id":"3","content":"he didn’t see a hole in the road","isCorrect":true},{"id":"4","content":"he was thinking about finishing his journey","isCorrect":false}]','C',0.25,NULL,27,'2026-02-10 14:44:10','"he hit a hole and was so thrown off" (đâm vào cái hố).');
INSERT INTO "vstep_questions" VALUES(2640,95,77,'Why does David think surfing is a good thing to do after his journey............','MULTIPLE_CHOICE','[{"id":"1","content":"He can stay close to Brisbane.","isCorrect":false},{"id":"2","content":"He''s always wanted to surf on the Gold Coast.","isCorrect":false},{"id":"3","content":"He wants to strengthen the top half of his body.","isCorrect":true},{"id":"4","content":"He needs to keep his legs strong.","isCorrect":false}]','C',0.25,NULL,28,'2026-02-10 14:44:11','"build up some much-needed upper body strength" (Chân to nhưng thân trên gầy).');
INSERT INTO "vstep_questions" VALUES(2641,95,77,'What does David hope to do eventually?','MULTIPLE_CHOICE','[{"id":"1","content":"encourage other people to feel more positive about themselves","isCorrect":true},{"id":"2","content":"put his skateboard away","isCorrect":false},{"id":"3","content":"return to work as a designer","isCorrect":false},{"id":"4","content":"persuade other people to make long-distance journeys","isCorrect":false}]','A',0.25,NULL,29,'2026-02-10 14:44:12','"plans to give motivational speeches" (diễn thuyết truyền cảm hứng).');
INSERT INTO "vstep_questions" VALUES(2642,95,77,'According to the text, in some days, David plans to skate on .................','MULTIPLE_CHOICE','[{"id":"1","content":"Perth","isCorrect":false},{"id":"2","content":"Adelaide","isCorrect":false},{"id":"3","content":"Melbourne","isCorrect":false},{"id":"4","content":"Gold Coast","isCorrect":true}]','D',0.25,NULL,30,'2026-02-10 14:44:12','Anh ấy dự định "surfing on the Gold Coast". (Lưu ý: câu hỏi dùng từ "skate", nhưng trong bài là "surf". Tuy nhiên địa điểm sắp tới là Gold Coast).');
INSERT INTO "vstep_questions" VALUES(2643,96,77,'What do footballers and musicians have in common?','MULTIPLE_CHOICE','[{"id":"1","content":"Their work abroad earns a lot of praise.","isCorrect":false},{"id":"2","content":"They receive too much unfair criticism.","isCorrect":false},{"id":"3","content":"They enjoy extremely noisy audiences.","isCorrect":false},{"id":"4","content":"They experience tension in their work.","isCorrect":true}]','D',0.25,NULL,31,'2026-02-10 14:44:12','"They both do stressful jobs" (đều làm công việc căng thẳng).');
INSERT INTO "vstep_questions" VALUES(2644,96,77,'What are we told about Rod Franks?','MULTIPLE_CHOICE','[{"id":"1","content":"He used to be the director of a football club.","isCorrect":false},{"id":"2","content":"He switched from one career to another.","isCorrect":true},{"id":"3","content":"He used to be a professional trumpeter.","isCorrect":false},{"id":"4","content":"He disliked his original choice of career.","isCorrect":false}]','B',0.25,NULL,32,'2026-02-10 14:44:13','"started... with Leeds United Football Club, neatly changed direction, started playing the trumpet" (Chuyển nghề).');
INSERT INTO "vstep_questions" VALUES(2645,96,77,'Before joining London Symphony Orchestra, Rod Franks worked for ..................','MULTIPLE_CHOICE','[{"id":"1","content":"a football club","isCorrect":true},{"id":"2","content":"a travel agency","isCorrect":false},{"id":"3","content":"a consulting firm","isCorrect":false},{"id":"4","content":"an event organizing firm","isCorrect":false}]','A',0.25,NULL,33,'2026-02-10 14:44:13','"Leeds United Football Club".');
INSERT INTO "vstep_questions" VALUES(2646,96,77,'The word “principal” in line 4 can be best replaced by...................','MULTIPLE_CHOICE','[{"id":"1","content":"original","isCorrect":false},{"id":"2","content":"main","isCorrect":true},{"id":"3","content":"prime","isCorrect":false},{"id":"4","content":"initial","isCorrect":false}]','B',0.25,NULL,34,'2026-02-10 14:44:14','"Principal trumpeter" = người chơi trumpet chính ~ "main".');
INSERT INTO "vstep_questions" VALUES(2647,96,77,'The LSO began playing abroad ...............','MULTIPLE_CHOICE','[{"id":"1","content":"only fairly recently.","isCorrect":false},{"id":"2","content":"over a hundred years ago.","isCorrect":false},{"id":"3","content":"when it was first set up.","isCorrect":true},{"id":"4","content":"when it needed money.","isCorrect":false}]','C',0.25,NULL,35,'2026-02-10 14:44:14','"has been playing away since it was formed almost a century ago" (Đi lưu diễn từ khi thành lập).');
INSERT INTO "vstep_questions" VALUES(2648,96,77,'Orchestras have to travel abroad ................','MULTIPLE_CHOICE','[{"id":"1","content":"to play with foreign conductors.","isCorrect":false},{"id":"2","content":"to record with foreign companies.","isCorrect":false},{"id":"3","content":"to make themselves better known.","isCorrect":true},{"id":"4","content":"to record with new solo players.","isCorrect":false}]','C',0.25,NULL,36,'2026-02-10 14:44:15','Cần "international reputation" (danh tiếng quốc tế) để các công ty thu âm chịu hợp tác -> Làm cho mình nổi tiếng hơn.');
INSERT INTO "vstep_questions" VALUES(2649,96,77,'What does ‘It’ in line 15 refer to?','MULTIPLE_CHOICE','[{"id":"1","content":"organising a number of recordings","isCorrect":false},{"id":"2","content":"visiting the most important markets","isCorrect":false},{"id":"3","content":"the expense of touring in a country","isCorrect":false},{"id":"4","content":"providing more than just concerts","isCorrect":true}]','D',0.25,NULL,37,'2026-02-10 14:44:15','"create an event, not just provide a series of concerts. It is more expensive..." -> It = creating an event (tạo ra sự kiện, cung cấp nhiều hơn là chỉ hòa nhạc).');
INSERT INTO "vstep_questions" VALUES(2650,96,77,'Sue Mallet''s arrangements for the LSO can be..................','MULTIPLE_CHOICE','[{"id":"1","content":"affected by external circumstances.","isCorrect":true},{"id":"2","content":"made difficult by awkward players.","isCorrect":false},{"id":"3","content":"spoilt by overlooking tiny details.","isCorrect":false},{"id":"4","content":"spoilt by very careless planning.","isCorrect":false}]','A',0.25,NULL,38,'2026-02-10 14:44:16','Dù lên kế hoạch kỹ, nhưng "events sometimes take an upper hand" (sự cố ngoài ý muốn xảy ra như xe hỏng, tuyết rơi...) -> Bị ảnh hưởng bởi hoàn cảnh bên ngoài.');
INSERT INTO "vstep_questions" VALUES(2651,96,77,'What does the phrase “with scientific accuracy’ (line 18) suggest about Sue Mallet''s planning?','MULTIPLE_CHOICE','[{"id":"1","content":"It''s very neat and tidy.","isCorrect":false},{"id":"2","content":"Her figures are correct.","isCorrect":false},{"id":"3","content":"She used to be a scientist.","isCorrect":false},{"id":"4","content":"The details are excellent.","isCorrect":true}]','D',0.25,NULL,39,'2026-02-10 14:44:17','"Scientific accuracy" (chính xác khoa học) ngụ ý kế hoạch cực kỳ chi tiết, tỉ mỉ và xuất sắc.');
INSERT INTO "vstep_questions" VALUES(2652,96,77,'According to the writer, what made a certain moment ‘unforgettable’ (line 23)?','MULTIPLE_CHOICE','[{"id":"1","content":"the fact that the orchestra stood up","isCorrect":false},{"id":"2","content":"an individual''s appreciation","isCorrect":true},{"id":"3","content":"the enthusiastic applause","isCorrect":false},{"id":"4","content":"the fact that a message was in English","isCorrect":false}]','B',0.25,NULL,40,'2026-02-10 14:44:17','Một bà cụ đưa mảnh giấy khen ngợi -> Sự cảm kích của cá nhân.');
INSERT INTO "vstep_questions" VALUES(2653,97,78,'Which box of chocolates do they buy?','MULTIPLE_CHOICE','[{"id":"1","content":"the small round one","isCorrect":false},{"id":"2","content":"the big round one","isCorrect":true},{"id":"3","content":"the square one","isCorrect":false},{"id":"4","content":"the oval one","isCorrect":false}]','B',0.286,NULL,41,'2026-02-10 14:44:17','Cô gái đề nghị: "Let''s get the big round one" (Mua hộp tròn to đi).');
INSERT INTO "vstep_questions" VALUES(2654,97,78,'When’s Wendy''s birthday?','MULTIPLE_CHOICE','[{"id":"1","content":"16th May","isCorrect":false},{"id":"2","content":"18th May","isCorrect":true},{"id":"3","content":"21st May","isCorrect":false},{"id":"4","content":"26th May","isCorrect":false}]','B',0.286,NULL,42,'2026-02-10 14:44:18','Wendy xác nhận: "My birthday is on May the 18th" (18 tháng 5).');
INSERT INTO "vstep_questions" VALUES(2655,97,78,'How much petrol does the woman want?','MULTIPLE_CHOICE','[{"id":"1","content":"13 litres","isCorrect":false},{"id":"2","content":"30 litres","isCorrect":true},{"id":"3","content":"33 litres","isCorrect":false},{"id":"4","content":"43 litres","isCorrect":false}]','B',0.286,NULL,43,'2026-02-10 14:44:19','Cô ấy yêu cầu: "Could you put 30 litres of petrol..." (Đổ 30 lít).');
INSERT INTO "vstep_questions" VALUES(2656,97,78,'What time is the woman''s hair appointment?','MULTIPLE_CHOICE','[{"id":"1","content":"Saturday at 9.30 am","isCorrect":true},{"id":"2","content":"Saturday at 12.00","isCorrect":false},{"id":"3","content":"Friday at 10.00","isCorrect":false},{"id":"4","content":"Friday at 11.30","isCorrect":false}]','A',0.286,NULL,44,'2026-02-10 14:44:19','Cô chọn giờ sớm hơn vào thứ Bảy ("earlier one on Saturday") là 9:30.');
INSERT INTO "vstep_questions" VALUES(2657,97,78,'Where''s the TV guide?','MULTIPLE_CHOICE','[{"id":"1","content":"top of the TV","isCorrect":false},{"id":"2","content":"by the chair","isCorrect":false},{"id":"3","content":"under the cushion","isCorrect":true},{"id":"4","content":"by the telephone","isCorrect":false}]','C',0.286,NULL,45,'2026-02-10 14:44:19','Nó nằm dưới cái đệm ghế ("under the cushion").');
INSERT INTO "vstep_questions" VALUES(2658,97,78,'What does the man decide to take Tracy?','MULTIPLE_CHOICE','[{"id":"1","content":"flowers","isCorrect":false},{"id":"2","content":"a CD","isCorrect":true},{"id":"3","content":"sweets","isCorrect":false},{"id":"4","content":"fruit","isCorrect":false}]','B',0.286,NULL,46,'2026-02-10 14:44:20','Người đàn ông chọn "Something to listen to" (Cái gì đó để nghe) => CD.');
INSERT INTO "vstep_questions" VALUES(2659,97,78,'Which sport has the man just started?','MULTIPLE_CHOICE','[{"id":"1","content":"windsurfing","isCorrect":false},{"id":"2","content":"sailing","isCorrect":false},{"id":"3","content":"horse-riding","isCorrect":true},{"id":"4","content":"swimming","isCorrect":false}]','C',0.286,NULL,47,'2026-02-10 14:44:20','Anh ấy vừa thử cưỡi ngựa ("horse riding... now I''ve tried it").');
INSERT INTO "vstep_questions" VALUES(2660,97,78,'What was damaged in the storm?','MULTIPLE_CHOICE','[{"id":"1","content":"the house roof","isCorrect":false},{"id":"2","content":"window glass","isCorrect":true},{"id":"3","content":"a car","isCorrect":false},{"id":"4","content":"a tree","isCorrect":false}]','B',0.286,NULL,48,'2026-02-10 14:44:21','Cành cây làm vỡ kính cửa sổ ("branch... broke it [glass]").');
INSERT INTO "vstep_questions" VALUES(2661,97,78,'What are they both doing here?','MULTIPLE_CHOICE','[{"id":"1","content":"to meet Mrs Thompson","isCorrect":false},{"id":"2","content":"to listen to John singing","isCorrect":false},{"id":"3","content":"to attend singing class","isCorrect":true},{"id":"4","content":"to dance in a musical show","isCorrect":false}]','C',0.286,NULL,49,'2026-02-10 14:44:21','Cả hai đến để học hát ("come for a singing lesson").');
INSERT INTO "vstep_questions" VALUES(2662,97,78,'What does John think of Mrs Thompson?','MULTIPLE_CHOICE','[{"id":"1","content":"she isn''t strict","isCorrect":false},{"id":"2","content":"she can sing well","isCorrect":false},{"id":"3","content":"she is a good teacher","isCorrect":false},{"id":"4","content":"she makes him nervous","isCorrect":true}]','D',0.286,NULL,50,'2026-02-10 14:44:21','John nói bà ấy làm anh lo lắng ("She makes me feel so nervous").');
INSERT INTO "vstep_questions" VALUES(2663,97,78,'What does John imply about his performance?','MULTIPLE_CHOICE','[{"id":"1","content":"He does well in a real show","isCorrect":false},{"id":"2","content":"He practices it well","isCorrect":true},{"id":"3","content":"He really likes it","isCorrect":false},{"id":"4","content":"He makes some big mistakes","isCorrect":false}]','B',0.286,NULL,51,'2026-02-10 14:44:22','Anh ấy vui vì tập luyện không mắc lỗi lớn ("got through it without making any big mistakes").');
INSERT INTO "vstep_questions" VALUES(2664,97,78,'What does Louise think of a musical show?','MULTIPLE_CHOICE','[{"id":"1","content":"she is not interested","isCorrect":true},{"id":"2","content":"she is keen on that","isCorrect":false},{"id":"3","content":"she thinks she will try it","isCorrect":false},{"id":"4","content":"she would love it.","isCorrect":false}]','A',0.286,NULL,52,'2026-02-10 14:44:22','Louise không hứng thú ("I wouldn''t be keen on that").');
INSERT INTO "vstep_questions" VALUES(2665,97,78,'How many children competed for roles in the show?','MULTIPLE_CHOICE','[{"id":"1","content":"6","isCorrect":false},{"id":"2","content":"1000","isCorrect":true},{"id":"3","content":"7","isCorrect":false},{"id":"4","content":"a few hundreds","isCorrect":false}]','B',0.286,NULL,53,'2026-02-10 14:44:23','Có 1000 người tham gia thử vai ("1000 hopefuls").');
INSERT INTO "vstep_questions" VALUES(2666,97,78,'What was the first success of Olivia?','MULTIPLE_CHOICE','[{"id":"1","content":"When they came to London","isCorrect":false},{"id":"2","content":"When they visit Palladium","isCorrect":false},{"id":"3","content":"When she got the leading role","isCorrect":false},{"id":"4","content":"After she visited the local theatre","isCorrect":true}]','D',0.286,NULL,54,'2026-02-10 14:44:23','Thành công khi nhận vai chính tại nhà hát địa phương ("local theatre... leading role").');
INSERT INTO "vstep_questions" VALUES(2667,97,78,'How did Olivia practice for the role in Annie?','MULTIPLE_CHOICE','[{"id":"1","content":"Learned 200 pages","isCorrect":false},{"id":"2","content":"Practiced two hours a day","isCorrect":false},{"id":"3","content":"Her mother helped her.","isCorrect":true},{"id":"4","content":"Learned it with her homework","isCorrect":false}]','C',0.286,NULL,55,'2026-02-10 14:44:24','Mẹ giúp cô học thoại ("I decided we''d do 10 pages... I gave her a random line").');
INSERT INTO "vstep_questions" VALUES(2668,97,78,'What did Jackie feel about her daughter''s performance?','MULTIPLE_CHOICE','[{"id":"1","content":"She was ashamed","isCorrect":false},{"id":"2","content":"She was amazed","isCorrect":true},{"id":"3","content":"She didn’t like it much","isCorrect":false},{"id":"4","content":"She couldn’t sing","isCorrect":false}]','B',0.286,NULL,56,'2026-02-10 14:44:24','Mọi người đều kinh ngạc ("astonished") bao gồm cả gia đình.');
INSERT INTO "vstep_questions" VALUES(2669,97,78,'What is true about Kira?','MULTIPLE_CHOICE','[{"id":"1","content":"She went home last year","isCorrect":false},{"id":"2","content":"She started a course in Pharmacy over again.","isCorrect":false},{"id":"3","content":"She is a third year student","isCorrect":true},{"id":"4","content":"She will finish her course in 12 months","isCorrect":false}]','C',0.286,NULL,57,'2026-02-10 14:44:25','Kira vào thẳng năm 3 ("straight into third year").');
INSERT INTO "vstep_questions" VALUES(2670,97,78,'What does she think about her course now?','MULTIPLE_CHOICE','[{"id":"1","content":"it is difficult","isCorrect":false},{"id":"2","content":"it is similar to the course she did","isCorrect":true},{"id":"3","content":"it is easier","isCorrect":false},{"id":"4","content":"she doesn’t like it","isCorrect":false}]','B',0.286,NULL,58,'2026-02-10 14:44:26','Nội dung rất giống ("Content was very similar").');
INSERT INTO "vstep_questions" VALUES(2671,97,78,'Why does she say her assignment is difficult?','MULTIPLE_CHOICE','[{"id":"1","content":"she is not familiar with it","isCorrect":false},{"id":"2","content":"she is expected to be critical","isCorrect":true},{"id":"3","content":"she feels terrible","isCorrect":false},{"id":"4","content":"her lecturer is terrible","isCorrect":false}]','B',0.286,NULL,59,'2026-02-10 14:44:26','Giảng viên mong đợi tư duy phản biện ("expect you to be critical").');
INSERT INTO "vstep_questions" VALUES(2672,97,78,'What does she mean about lecturers in her country?','MULTIPLE_CHOICE','[{"id":"1","content":"They are horrible","isCorrect":false},{"id":"2","content":"You can talk to them easily","isCorrect":false},{"id":"3","content":"They are knowledgeable","isCorrect":false},{"id":"4","content":"It''s hard to discuss with them","isCorrect":true}]','D',0.286,NULL,60,'2026-02-10 14:44:27','Ở đây dễ tiếp cận hơn ("Here they''re much easier to approach") => Ở nước cô ấy khó hơn.');
INSERT INTO "vstep_questions" VALUES(2673,97,78,'You do not have to provide...','MULTIPLE_CHOICE','[{"id":"1","content":"a letter of recommendation.","isCorrect":false},{"id":"2","content":"school records.","isCorrect":false},{"id":"3","content":"exam results.","isCorrect":false},{"id":"4","content":"health certificate.","isCorrect":true}]','D',0.286,NULL,61,'2026-02-10 14:44:28','Không yêu cầu giấy chứng nhận sức khỏe trong danh sách hồ sơ.');
INSERT INTO "vstep_questions" VALUES(2674,97,78,'Your required English level depends on...','MULTIPLE_CHOICE','[{"id":"1","content":"your age.","isCorrect":false},{"id":"2","content":"your chosen course.","isCorrect":true},{"id":"3","content":"your grades.","isCorrect":false},{"id":"4","content":"your nationality.","isCorrect":false}]','B',0.286,NULL,62,'2026-02-10 14:44:28','Phụ thuộc vào ngành học ("Different majors require different abilities").');
INSERT INTO "vstep_questions" VALUES(2675,97,78,'Some science Courses require you to...','MULTIPLE_CHOICE','[{"id":"1","content":"take an exam.","isCorrect":false},{"id":"2","content":"complete a foundation year.","isCorrect":true},{"id":"3","content":"do extra personal study.","isCorrect":false},{"id":"4","content":"have a higher level of English.","isCorrect":false}]','B',0.286,NULL,63,'2026-02-10 14:44:28','Yêu cầu hoàn thành năm dự bị ("complete a foundation year").');
INSERT INTO "vstep_questions" VALUES(2676,97,78,'Application for undergraduate courses is...','MULTIPLE_CHOICE','[{"id":"1","content":"always via UCAS.","isCorrect":true},{"id":"2","content":"direct with universities.","isCorrect":false},{"id":"3","content":"either via UCAS or direct with universities.","isCorrect":false},{"id":"4","content":"via a placement agency.","isCorrect":false}]','A',0.286,NULL,64,'2026-02-10 14:44:29','Luôn phải thông qua UCAS ("always via UCAS").');
INSERT INTO "vstep_questions" VALUES(2677,97,78,'British universities...','MULTIPLE_CHOICE','[{"id":"1","content":"are the best in the world.","isCorrect":false},{"id":"2","content":"rank among the top universities in the world.","isCorrect":false},{"id":"3","content":"are all well respected.","isCorrect":false},{"id":"4","content":"are generally well respected.","isCorrect":true}]','D',0.286,NULL,65,'2026-02-10 14:44:29','Được tôn trọng trên toàn cầu ("generally respected globally").');
INSERT INTO "vstep_questions" VALUES(2678,97,78,'In 1993 Dan Pearman went to Ecuador ...','MULTIPLE_CHOICE','[{"id":"1","content":"as a tour guide.","isCorrect":false},{"id":"2","content":"as part of his studies.","isCorrect":false},{"id":"3","content":"as a voluntary worker.","isCorrect":true},{"id":"4","content":"a student.","isCorrect":false}]','C',0.286,NULL,66,'2026-02-10 14:44:29','Đi với tư cách tình nguyện viên ("voluntary organization").');
INSERT INTO "vstep_questions" VALUES(2679,97,78,'Dan''s neighbour was successful in business because he...','MULTIPLE_CHOICE','[{"id":"1","content":"employed carpenters from the area.","isCorrect":false},{"id":"2","content":"was the most skilled craftsman in the town.","isCorrect":false},{"id":"3","content":"found it easy to reach customers.","isCorrect":true},{"id":"4","content":"worked very hard.","isCorrect":false}]','C',0.286,NULL,67,'2026-02-10 14:44:30','Dễ tiếp cận khách hàng hơn nhờ xe đạp ("accept jobs in 3km radius").');
INSERT INTO "vstep_questions" VALUES(2680,97,78,'Dan says the charity relies on...','MULTIPLE_CHOICE','[{"id":"1","content":"getting enough bicycles to send regularly.","isCorrect":true},{"id":"2","content":"finding new areas which need the bicycles.","isCorrect":false},{"id":"3","content":"charging for the bicycles it sends abroad.","isCorrect":false},{"id":"4","content":"getting the second-hand bikes from the rich.","isCorrect":false}]','A',0.286,NULL,68,'2026-02-10 14:44:30','Cần nguồn cung xe đạp ổn định ("constant supply of bikes").');
INSERT INTO "vstep_questions" VALUES(2681,97,78,'What does Dan say about the town of Rivas?','MULTIPLE_CHOICE','[{"id":"1","content":"It has received the greatest number of bikes.","isCorrect":false},{"id":"2","content":"It has almost as many bikes as Amsterdam.","isCorrect":false},{"id":"3","content":"Its economy has been totally transformed.","isCorrect":true},{"id":"4","content":"Everyone there owns a bicycle.","isCorrect":false}]','C',0.286,NULL,69,'2026-02-10 14:44:31','Kinh tế phát triển mạnh ("local economy has developed so much").');
INSERT INTO "vstep_questions" VALUES(2682,97,78,'What problem did the charity face in August 2000?','MULTIPLE_CHOICE','[{"id":"1","content":"It couldn’t meet its overheads.","isCorrect":true},{"id":"2","content":"It had to delay sending the bikes","isCorrect":false},{"id":"3","content":"It was criticized in British media.","isCorrect":false},{"id":"4","content":"It didn’t get enough bikes ready to send.","isCorrect":false}]','A',0.286,NULL,70,'2026-02-10 14:44:31','Hết tiền trả chi phí ("ran out of money").');
INSERT INTO "vstep_questions" VALUES(2683,97,78,'According to the speaker the main cause of back pain in women is ...','MULTIPLE_CHOICE','[{"id":"1","content":"pregnancy.","isCorrect":false},{"id":"2","content":"osteoporosis.","isCorrect":true},{"id":"3","content":"lack of exercise.","isCorrect":false},{"id":"4","content":"too much exercise.","isCorrect":false}]','B',0.286,NULL,71,'2026-02-10 14:44:32','Nguyên nhân chính là loãng xương ("osteoporosis... major cause").');
INSERT INTO "vstep_questions" VALUES(2684,97,78,'As treatment for back pain the Clinic mainly recommends...','MULTIPLE_CHOICE','[{"id":"1","content":"pain killers.","isCorrect":false},{"id":"2","content":"relaxation therapy.","isCorrect":true},{"id":"3","content":"exercise routines.","isCorrect":false},{"id":"4","content":"bed rest.","isCorrect":false}]','B',0.286,NULL,72,'2026-02-10 14:44:32','Khuyên dùng liệu pháp thư giãn ("benefits of relaxation therapy").');
INSERT INTO "vstep_questions" VALUES(2685,97,78,'The back is different from other parts of the body because...','MULTIPLE_CHOICE','[{"id":"1","content":"it is usually better at self-repair.","isCorrect":false},{"id":"2","content":"a back injury is usually more painful.","isCorrect":false},{"id":"3","content":"its response to injury often results in more damage.","isCorrect":true},{"id":"4","content":"it is worse if we keep the back as immobile as possible.","isCorrect":false}]','C',0.286,NULL,73,'2026-02-10 14:44:32','Phản ứng của cơ thể thường gây hại thêm ("counterproductive").');
INSERT INTO "vstep_questions" VALUES(2686,97,78,'Bed rest is advised...','MULTIPLE_CHOICE','[{"id":"1","content":"for a maximum of two days.","isCorrect":true},{"id":"2","content":"for less than two days.","isCorrect":false},{"id":"3","content":"for pain lasting more than two days.","isCorrect":false},{"id":"4","content":"for extreme pain only.","isCorrect":false}]','A',0.286,NULL,74,'2026-02-10 14:44:33','Chỉ nên nghỉ ngơi tối đa 2 ngày ("up to two days").');
INSERT INTO "vstep_questions" VALUES(2687,97,78,'Being overweight...','MULTIPLE_CHOICE','[{"id":"1","content":"is a major source of back pain.","isCorrect":false},{"id":"2","content":"worsens existing back pain.","isCorrect":true},{"id":"3","content":"reduces the effectiveness of exercise.","isCorrect":false},{"id":"4","content":"is the only cause of back pain.","isCorrect":false}]','B',0.286,NULL,75,'2026-02-10 14:44:34','Làm tình trạng đau lưng tồi tệ hơn ("make things worse").');
INSERT INTO "vstep_questions" VALUES(2688,NULL,79,'Write an essay (150-200 words) about the advantages and disadvantages of online learning.','ESSAY',NULL,NULL,5,NULL,76,'2026-02-10 14:44:34',NULL);
INSERT INTO "vstep_questions" VALUES(2689,NULL,80,'Summarize the information in the chart below by selecting and reporting the main features.','ESSAY',NULL,NULL,5,NULL,77,'2026-02-10 14:44:34',NULL);
