PRAGMA defer_foreign_keys = ON;
PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE students (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    cccd TEXT NOT NULL UNIQUE,  -- Số CCCD/CMT (KHÓA CHÍNH)
    ho TEXT NOT NULL,
    ten_dem TEXT,
    ten TEXT NOT NULL,
    ho_ten_full TEXT NOT NULL,  -- Họ + tên đệm + tên (đầy đủ)
    ho_ten_normalized TEXT NOT NULL,  -- Không dấu, lowercase để search
    ngay_sinh DATE NOT NULL,
    noi_sinh TEXT NOT NULL,
    gioi_tinh TEXT CHECK(gioi_tinh IN ('Nam', 'Nữ', 'Khác')),
    email TEXT NOT NULL,
    sdt TEXT NOT NULL,
    dia_chi TEXT NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
, dan_toc TEXT DEFAULT 'Kinh', quoc_tich TEXT DEFAULT 'Việt Nam', ngay_cap_cccd DATE, don_vi_cong_tac TEXT, image_cccd_front TEXT, image_cccd_back TEXT, image_3x4 TEXT, cccd_front_image_id TEXT, cccd_back_image_id TEXT, photo_3x4_image_id TEXT, cccd_front_url_expires_at DATETIME, cccd_back_url_expires_at DATETIME, photo_3x4_url_expires_at DATETIME);
CREATE TABLE classes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    ten_lop TEXT NOT NULL,
    ngay_thi DATE NOT NULL,
    gio_thi TIME,
    dia_diem TEXT,
    open_at DATETIME NOT NULL,  -- Thời gian mở đăng ký
    close_at DATETIME NOT NULL,  -- Thời gian đóng đăng ký
    status TEXT DEFAULT 'open' CHECK(status IN ('open', 'closed', 'completed')),
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
, class_type TEXT DEFAULT 'hoc', max_students INTEGER, current_students INTEGER DEFAULT 0, ma_lop TEXT, hoc_phi INTEGER DEFAULT 0, ngay_ket_thuc DATE, ngay_bat_dau DATE);
CREATE TABLE notifications (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER,
        user_type TEXT CHECK(user_type IN ('student', 'admin', 'all')),
        title TEXT NOT NULL,
        message TEXT NOT NULL,
        type TEXT DEFAULT 'info' CHECK(type IN ('info', 'success', 'warning', 'error', 'payment', 'certificate', 'registration', 'class')),
        link TEXT,
        read BOOLEAN DEFAULT 0,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (user_id) REFERENCES students(id) ON DELETE CASCADE
      );
CREATE TABLE teachers (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        teacher_code TEXT UNIQUE NOT NULL,
        ho TEXT NOT NULL,
        ten_dem TEXT,
        ten TEXT NOT NULL,
        ho_ten_full TEXT NOT NULL,
        email TEXT UNIQUE NOT NULL,
        sdt TEXT NOT NULL,
        password_hash TEXT NOT NULL,
        department TEXT,
        position TEXT,
        status TEXT DEFAULT 'active' CHECK(status IN ('active', 'inactive', 'on_leave')),
        last_login DATETIME,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
      );
CREATE TABLE document_permissions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        document_id INTEGER NOT NULL,
        permission_type TEXT NOT NULL CHECK(permission_type IN ('public', 'class', 'student')),
        class_id INTEGER,
        student_id INTEGER,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP, online_class_id INTEGER,
        FOREIGN KEY (document_id) REFERENCES documents(id) ON DELETE CASCADE,
        FOREIGN KEY (class_id) REFERENCES classes(id) ON DELETE CASCADE,
        FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE
      );
CREATE TABLE document_downloads (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        document_id INTEGER NOT NULL,
        student_id INTEGER,
        downloaded_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (document_id) REFERENCES documents(id) ON DELETE CASCADE,
        FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE SET NULL
      );
CREATE TABLE IF NOT EXISTS "admins" (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, full_name TEXT NOT NULL, role TEXT DEFAULT 'admin' CHECK(role IN ('super_admin', 'admin', 'staff')), email TEXT, phone TEXT, last_login DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_log (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    admin_id INTEGER,
    action TEXT NOT NULL,
    table_name TEXT NOT NULL,
    record_id INTEGER NOT NULL,
    old_value TEXT,
    new_value TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (admin_id) REFERENCES admins(id)
);
CREATE TABLE payments (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    registration_id INTEGER NOT NULL,
    amount INTEGER NOT NULL,
    method TEXT CHECK(method IN ('bank_transfer', 'cash', 'other')),
    transaction_code TEXT,
    receipt_image_url TEXT,
    status TEXT DEFAULT 'pending' CHECK(status IN ('pending', 'confirmed', 'rejected', 'refunded')),
    confirmed_by INTEGER,
    confirmed_at DATETIME,
    notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (registration_id) REFERENCES registrations(id) ON DELETE CASCADE,
    FOREIGN KEY (confirmed_by) REFERENCES admins(id)
);
CREATE TABLE certificates (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id INTEGER NOT NULL,
    class_id INTEGER,
    certificate_number TEXT UNIQUE,
    title TEXT NOT NULL,
    issued_date DATE NOT NULL,
    pdf_url TEXT,
    status TEXT DEFAULT 'active' CHECK(status IN ('active', 'revoked')),
    issued_by INTEGER,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
    FOREIGN KEY (class_id) REFERENCES classes(id),
    FOREIGN KEY (issued_by) REFERENCES admins(id)
);
CREATE TABLE admin_activity_logs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    admin_id INTEGER NOT NULL,
    action TEXT NOT NULL,
    resource_type TEXT,
    resource_id INTEGER,
    details TEXT,
    ip_address TEXT,
    user_agent TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (admin_id) REFERENCES admins(id) ON DELETE CASCADE
);
CREATE TABLE password_reset_tokens (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    admin_id INTEGER NOT NULL,
    token TEXT UNIQUE NOT NULL,
    expires_at DATETIME NOT NULL,
    used BOOLEAN DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (admin_id) REFERENCES admins(id) ON DELETE CASCADE
);
CREATE TABLE documents (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    description TEXT,
    file_url TEXT NOT NULL,
    file_name TEXT NOT NULL,
    file_size INTEGER,
    file_type TEXT,
    status TEXT DEFAULT 'active' CHECK(status IN ('active', 'inactive', 'archived')),
    valid_until DATETIME,
    uploaded_by INTEGER,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, folder_id INTEGER, visibility TEXT NOT NULL DEFAULT 'internal' CHECK(visibility IN ('internal','public')), doc_type TEXT DEFAULT 'general', valid_from DATETIME,
    FOREIGN KEY (uploaded_by) REFERENCES admins(id) ON DELETE SET NULL
);
CREATE TABLE homepage_settings (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        setting_key TEXT UNIQUE NOT NULL,
        setting_value TEXT,
        value_type TEXT DEFAULT 'string' CHECK(value_type IN ('string', 'number', 'boolean', 'json')),
        description TEXT,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
      );
CREATE TABLE class_schedules (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        class_id INTEGER NOT NULL,
        day_of_week INTEGER NOT NULL CHECK(day_of_week >= 0 AND day_of_week <= 6),
        start_time TIME NOT NULL,
        end_time TIME NOT NULL,
        room TEXT,
        notes TEXT,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, meeting_link TEXT, google_event_id TEXT, meeting_status TEXT DEFAULT 'active' CHECK(meeting_status IN ('active', 'cancelled', 'ended')),
        FOREIGN KEY (class_id) REFERENCES classes(id) ON DELETE CASCADE
      );
CREATE TABLE class_teachers (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        class_id INTEGER NOT NULL,
        teacher_id INTEGER NOT NULL,
        role TEXT DEFAULT 'teacher' CHECK(role IN ('teacher', 'assistant', 'coordinator')),
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (class_id) REFERENCES classes(id) ON DELETE CASCADE,
        FOREIGN KEY (teacher_id) REFERENCES teachers(id) ON DELETE CASCADE,
        UNIQUE(class_id, teacher_id)
      );
CREATE TABLE conversations (id INTEGER PRIMARY KEY AUTOINCREMENT, student_id INTEGER, admin_id INTEGER, subject TEXT, last_message_at DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE, FOREIGN KEY (admin_id) REFERENCES admins(id) ON DELETE SET NULL);
CREATE TABLE messages (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    conversation_id INTEGER NOT NULL,
    sender_type TEXT CHECK(sender_type IN ('student', 'admin')) NOT NULL,
    sender_id INTEGER NOT NULL,
    message TEXT NOT NULL,
    read BOOLEAN DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    
    FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "exam_schedules" (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            class_id INTEGER,
            exam_name TEXT NOT NULL,
            exam_date DATETIME NOT NULL,
            duration_minutes INTEGER DEFAULT 120,
            location TEXT,
            notes TEXT,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, deleted_at DATETIME DEFAULT NULL, template_id INTEGER DEFAULT NULL REFERENCES excel_templates(id), exam_test_id INTEGER, zoom_link TEXT, zoom_meeting_id TEXT, zoom_passcode TEXT,
            FOREIGN KEY (class_id) REFERENCES classes(id) ON DELETE SET NULL
        );
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE audit_logs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    admin_id INTEGER,
    action_type TEXT NOT NULL,
    entity_type TEXT NOT NULL,
    entity_id INTEGER,
    details TEXT,
    ip_address TEXT,
    user_agent TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,

    FOREIGN KEY (admin_id) REFERENCES admins(id)
);
CREATE TABLE IF NOT EXISTS "registrations" (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id INTEGER NOT NULL,
    class_id INTEGER NOT NULL,
    so_phach TEXT,
    status TEXT DEFAULT 'pending' CHECK(status IN ('pending', 'approved', 'studying', 'completed', 'certified', 'cancelled')),
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,

    FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
    FOREIGN KEY (class_id) REFERENCES classes(id) ON DELETE CASCADE,
    UNIQUE(student_id, class_id)
);
CREATE TABLE posts_new(
  id INT,
  title TEXT,
  content TEXT,
  excerpt TEXT,
  slug TEXT,
  category TEXT,
  tags TEXT,
  status TEXT,
  featured_image TEXT,
  author_id INT,
  view_count INT,
  publish_at NUM,
  published_at NUM,
  created_at NUM,
  updated_at NUM,
  images TEXT
);
CREATE TABLE posts (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, content TEXT NOT NULL, excerpt TEXT, slug TEXT, category TEXT, tags TEXT, status TEXT DEFAULT 'draft', featured_image TEXT, author_id INTEGER, view_count INTEGER DEFAULT 0, publish_at DATETIME, published_at DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, images TEXT);
CREATE TABLE IF NOT EXISTS "exam_registrations" (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    exam_id INTEGER NOT NULL,
    student_id INTEGER NOT NULL,
    status TEXT DEFAULT 'pending' CHECK(status IN ('pending', 'approved', 'registered', 'cancelled', 'attended', 'rejected')),
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    created_by INTEGER,
    approved_at TEXT,
    approved_by INTEGER,
    FOREIGN KEY (exam_id) REFERENCES exam_schedules(id) ON DELETE CASCADE,
    FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
    UNIQUE(exam_id, student_id)
);
CREATE TABLE excel_templates (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT UNIQUE NOT NULL,         -- "PTIT", "VanTrang"
    display_name TEXT NOT NULL,        -- "Học viện PTIT"
    file_key TEXT NOT NULL,            -- R2 key: "templates/PTIT.xlsx"
    header_rows INTEGER DEFAULT 8,     -- Số dòng header
    data_start_row INTEGER DEFAULT 10, -- Dòng bắt đầu data
    date_cell TEXT,                    -- Cell ngày thi (e.g. "G7")
    column_mapping TEXT,               -- JSON: {"stt": "A", "cccd": "B", ...}
    is_active BOOLEAN DEFAULT 1,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE image_processing_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  student_id INTEGER,
  image_type TEXT NOT NULL, -- 'cccd_front', 'cccd_back', 'photo_3x4'
  original_image_id TEXT, -- Cloudflare Images ID of original
  processed_image_id TEXT, -- Cloudflare Images ID after AI processing
  processing_status TEXT DEFAULT 'pending', -- 'pending', 'processing', 'success', 'failed'
  ai_confidence_score REAL, -- 0.0 to 1.0
  quality_score REAL, -- 0.0 to 1.0 (blur, brightness check)
  error_message TEXT, -- If processing failed
  processing_details TEXT, -- JSON metadata (bounding box, transform params, etc)
  processing_started_at DATETIME,
  processing_completed_at DATETIME,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE
);
CREATE TABLE image_access_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  student_id INTEGER NOT NULL,
  accessed_by_user_id INTEGER, -- Admin/teacher who accessed
  access_type TEXT NOT NULL, -- 'view', 'download', 'delete'
  image_type TEXT, -- 'cccd_front', 'cccd_back', 'photo_3x4', 'all'
  ip_address TEXT,
  user_agent TEXT,
  accessed_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE
);
CREATE TABLE image_quality_metrics (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  image_processing_log_id INTEGER NOT NULL,
  blur_score REAL, -- 0.0 (very blurry) to 1.0 (sharp)
  brightness_score REAL, -- 0.0 (too dark) to 1.0 (good)
  contrast_score REAL,
  resolution_width INTEGER,
  resolution_height INTEGER,
  file_size_bytes INTEGER,
  has_cccd_corners BOOLEAN DEFAULT 0, -- Did we detect all 4 corners?
  aspect_ratio_match REAL, -- How close to CCCD aspect ratio (1.585)
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (image_processing_log_id) REFERENCES image_processing_logs(id) ON DELETE CASCADE
);
CREATE TABLE online_classes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    class_name TEXT NOT NULL,
    description TEXT,
    
    -- Schedule Info
    schedule_rule TEXT NOT NULL,          -- Quy tắc lịch: DAILY, WEEKLY:1,3,5, etc.
    schedule_time TEXT NOT NULL,          -- Giờ học: "19:00-21:00"
    timezone TEXT DEFAULT 'Asia/Ho_Chi_Minh',  -- Timezone cho Google Calendar
    recurrence TEXT,                       -- RRULE gốc: "RRULE:FREQ=WEEKLY;BYDAY=MO,WE,FR"
    
    -- Dates
    start_date DATE NOT NULL,
    end_date DATE,                        -- NULL = không có ngày kết thúc
    
    -- Google Calendar Integration
    meet_link TEXT,                       -- Google Meet link cố định
    calendar_event_id TEXT,               -- Google Calendar Event ID
    
    -- Class Info
    teacher_name TEXT,
    max_students INTEGER DEFAULT 50,
    status TEXT DEFAULT 'active' CHECK(status IN ('active', 'paused', 'completed', 'cancelled')),
    
    -- Metadata
    created_by INTEGER,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    
    FOREIGN KEY (created_by) REFERENCES admins(id)
);
CREATE TABLE class_videos (
  id TEXT PRIMARY KEY,              -- UUID hoặc ID do app sinh ra
  class_id TEXT NOT NULL,           -- Tham chiếu logic tới classes.id (giữ kiểu TEXT cho linh hoạt)
  title TEXT,                       -- Tiêu đề hiển thị cho học viên
  r2_key TEXT NOT NULL,             -- Đường dẫn object trong R2 (ví dụ: /videos/class_123/2026-01-15_lesson01.mp4)
  duration INTEGER,                 -- Thời lượng video (giây)
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE assignments (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  title TEXT NOT NULL,
  description TEXT,
  class_id INTEGER NOT NULL,
  due_date TEXT, 
  max_file_size INTEGER DEFAULT 10485760, 
  allowed_types TEXT DEFAULT 'image/*,video/*,application/pdf',
  status TEXT DEFAULT 'open' CHECK (status IN ('open','closed','archived')),
  max_attempts INTEGER DEFAULT 1, 
  created_by INTEGER,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (class_id) REFERENCES online_classes(id) ON DELETE CASCADE
);
CREATE TABLE assignment_submissions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  assignment_id INTEGER NOT NULL,
  student_id INTEGER NOT NULL,
  attempt INTEGER DEFAULT 1, 
  r2_key TEXT NOT NULL,
  file_name TEXT NOT NULL,
  file_size INTEGER,
  file_type TEXT,
  status TEXT DEFAULT 'submitted' CHECK (status IN ('submitted','graded','rejected')),
  grade TEXT, 
  feedback TEXT,
  submitted_at TEXT DEFAULT CURRENT_TIMESTAMP,
  graded_at TEXT,
  FOREIGN KEY (assignment_id) REFERENCES assignments(id) ON DELETE CASCADE,
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE
);
CREATE TABLE document_folders (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  parent_id INTEGER,
  folder_type TEXT NOT NULL DEFAULT 'shared' CHECK(folder_type IN ('shared','private')),
  owner_role TEXT CHECK(owner_role IN ('admin','teacher')),
  owner_id INTEGER,
  created_by_admin_id INTEGER,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (parent_id) REFERENCES document_folders(id) ON DELETE SET NULL
);
CREATE TABLE document_shares (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  document_id INTEGER NOT NULL,
  target_type TEXT NOT NULL CHECK(target_type IN ('offline_class','online_class')),
  target_id INTEGER NOT NULL,
  status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','revoked')),
  shared_by_role TEXT CHECK(shared_by_role IN ('admin','teacher')),
  shared_by_id INTEGER,
  shared_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  revoked_at DATETIME,
  FOREIGN KEY (document_id) REFERENCES documents(id) ON DELETE CASCADE
);
CREATE TABLE online_class_enrollments (id INTEGER PRIMARY KEY AUTOINCREMENT, online_class_id INTEGER, student_id INTEGER, status TEXT DEFAULT 'pending' CHECK (status IN ('active', 'pending', 'cancelled', 'rejected')), enrolled_at DATETIME DEFAULT CURRENT_TIMESTAMP, approved_at DATETIME, approved_by INTEGER, rejection_reason TEXT, FOREIGN KEY (online_class_id) REFERENCES online_classes(id) ON DELETE CASCADE, FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "attendance" (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    registration_id INTEGER NOT NULL,
    class_id INTEGER NOT NULL,
    attendance_date DATE NOT NULL,
    status TEXT CHECK(status IN ('present', 'absent', 'late', 'excused')),
    notes TEXT,
    marked_by INTEGER,
    marked_by_role TEXT DEFAULT 'admin' CHECK(marked_by_role IN ('admin', 'teacher')),
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(registration_id, attendance_date)
);
CREATE TABLE student_edit_history (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id INTEGER NOT NULL,
    admin_id INTEGER,
    changed_by_type TEXT CHECK(changed_by_type IN ('admin', 'student')),
    field_name TEXT NOT NULL,
    old_value TEXT,
    new_value TEXT,
    changed_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    ip_address TEXT,
    user_agent TEXT,
    FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
    FOREIGN KEY (admin_id) REFERENCES admins(id)
);
CREATE TABLE exam_types (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    code TEXT UNIQUE NOT NULL,
    name TEXT NOT NULL,
    description TEXT,
    language TEXT,
    icon_url TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE exam_tests (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    exam_type_id INTEGER NOT NULL,
    level TEXT,
    title TEXT NOT NULL,
    description TEXT,
    duration_minutes INTEGER NOT NULL,
    total_questions INTEGER DEFAULT 0,
    passing_score INTEGER,
    is_active BOOLEAN DEFAULT 1,
    shuffle_questions BOOLEAN DEFAULT 0,
    shuffle_options BOOLEAN DEFAULT 0,
    version INTEGER DEFAULT 1,
    created_by INTEGER,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, status TEXT DEFAULT 'draft' CHECK(status IN ('draft', 'pending_review', 'approved', 'rejected')), reviewed_by INTEGER, reviewed_at DATETIME, rejection_reason TEXT, requires_registration BOOLEAN DEFAULT 0, max_attempts_per_student INTEGER, registration_deadline DATETIME, exam_schedule_id INTEGER,
    FOREIGN KEY (exam_type_id) REFERENCES exam_types(id) ON DELETE CASCADE,
    FOREIGN KEY (created_by) REFERENCES admins(id)
);
CREATE TABLE exam_sections (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    test_id INTEGER NOT NULL,
    name TEXT NOT NULL,
    description TEXT,
    time_limit_minutes INTEGER,
    order_index INTEGER NOT NULL,
    question_count INTEGER DEFAULT 0,
    instructions TEXT,
    is_locked_after_complete BOOLEAN DEFAULT 0,
    scoring_rule TEXT DEFAULT 'points_based',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (test_id) REFERENCES exam_tests(id) ON DELETE CASCADE
);
CREATE TABLE exam_questions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    section_id INTEGER NOT NULL,
    type TEXT NOT NULL CHECK(type IN ('mcq', 'multi_select', 'fill_blank', 'matching', 'ordering', 'drag_drop', 'essay', 'speaking', 'reading_passage_group')),
    question_text TEXT NOT NULL,
    question_data TEXT,
    options_json TEXT,
    answer_key TEXT NOT NULL,
    points INTEGER DEFAULT 1,
    difficulty TEXT DEFAULT 'medium' CHECK(difficulty IN ('easy', 'medium', 'hard')),
    explanation TEXT,
    audio_url TEXT,
    image_url TEXT,
    order_index INTEGER NOT NULL,
    version INTEGER DEFAULT 1,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (section_id) REFERENCES exam_sections(id) ON DELETE CASCADE
);
CREATE TABLE exam_attempts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id INTEGER NOT NULL,
    test_id INTEGER NOT NULL,
    test_version INTEGER NOT NULL,
    start_time DATETIME NOT NULL,
    end_time DATETIME,
    submitted_at DATETIME,
    expires_at DATETIME,
    score INTEGER,
    max_score INTEGER,
    section_scores TEXT,
    status TEXT DEFAULT 'in_progress' CHECK(status IN ('in_progress', 'submitted', 'expired', 'abandoned')),
    time_spent_seconds INTEGER DEFAULT 0,
    last_heartbeat DATETIME,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
    FOREIGN KEY (test_id) REFERENCES exam_tests(id) ON DELETE CASCADE
);
CREATE TABLE exam_attempt_answers (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    attempt_id INTEGER NOT NULL,
    question_id INTEGER NOT NULL,
    question_version INTEGER NOT NULL,
    answer_data TEXT NOT NULL,
    is_correct BOOLEAN,
    points_earned INTEGER DEFAULT 0,
    answered_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (attempt_id) REFERENCES exam_attempts(id) ON DELETE CASCADE,
    FOREIGN KEY (question_id) REFERENCES exam_questions(id) ON DELETE CASCADE,
    UNIQUE(attempt_id, question_id)
);
CREATE TABLE exam_attempt_sections (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    attempt_id INTEGER NOT NULL,
    section_id INTEGER NOT NULL,
    started_at DATETIME,
    completed_at DATETIME,
    is_locked BOOLEAN DEFAULT 0,
    time_spent_seconds INTEGER DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (attempt_id) REFERENCES exam_attempts(id) ON DELETE CASCADE,
    FOREIGN KEY (section_id) REFERENCES exam_sections(id) ON DELETE CASCADE,
    UNIQUE(attempt_id, section_id)
);
CREATE TABLE exam_test_reviews (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    test_id INTEGER NOT NULL,
    reviewer_id INTEGER NOT NULL,
    action TEXT NOT NULL CHECK(action IN ('submit', 'approve', 'reject', 'request_changes')),
    comment TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (test_id) REFERENCES exam_tests(id) ON DELETE CASCADE,
    FOREIGN KEY (reviewer_id) REFERENCES admins(id)
);
CREATE TABLE exam_test_registrations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id INTEGER NOT NULL,
    test_id INTEGER NOT NULL,
    status TEXT DEFAULT 'pending' CHECK(status IN ('pending', 'approved', 'rejected')),
    requested_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    approved_at DATETIME,
    approved_by INTEGER,
    rejection_reason TEXT,
    expires_at DATETIME,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
    FOREIGN KEY (test_id) REFERENCES exam_tests(id) ON DELETE CASCADE,
    FOREIGN KEY (approved_by) REFERENCES admins(id),
    UNIQUE(student_id, test_id)
);
CREATE TABLE exam_activity_logs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    attempt_id INTEGER,
    student_id INTEGER NOT NULL,
    test_id INTEGER NOT NULL,
    action TEXT NOT NULL,
    details TEXT,
    ip_address TEXT,
    user_agent TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (attempt_id) REFERENCES exam_attempts(id) ON DELETE SET NULL,
    FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
    FOREIGN KEY (test_id) REFERENCES exam_tests(id) ON DELETE CASCADE
);
CREATE TABLE vstep_exams (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    description TEXT,
    code TEXT UNIQUE, -- e.g. VSTEP-B1-01
    level TEXT DEFAULT 'B1', -- A1, A2, B1, B2, C1, C2
    status TEXT DEFAULT 'draft' CHECK(status IN ('draft', 'published', 'archived')),
    duration INTEGER NOT NULL, -- Total minutes (e.g. 180)
    thumbnail_url TEXT, -- For premium UI
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    created_by INTEGER -- Link to admins(id)
, random_questions INTEGER DEFAULT 0, questions_per_exam INTEGER DEFAULT 0, layout_mode TEXT DEFAULT 'LANGUAGE', category_id INTEGER REFERENCES exam_categories(id), order_index INTEGER DEFAULT 0, course_id TEXT);
CREATE TABLE vstep_question_groups (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    section_id INTEGER NOT NULL,
    title TEXT, -- e.g. "Part 1: Social Interaction"
    text_content TEXT, -- Reading passage (HTML supported)
    audio_url TEXT, -- Listening audio R2 link
    image_url TEXT,
    order_index INTEGER DEFAULT 0,
    settings_json TEXT, -- Extra settings if needed
    FOREIGN KEY(section_id) REFERENCES vstep_sections(id) ON DELETE CASCADE
);
CREATE TABLE vstep_questions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    group_id INTEGER, -- Can be NULL for standalone questions
    section_id INTEGER NOT NULL, -- Redundant but useful for fast queries
    content TEXT NOT NULL, -- The question text
    type TEXT NOT NULL CHECK(type IN ('MULTIPLE_CHOICE', 'ESSAY', 'RECORDING', 'FILL_IN_BLANK')),
    
    -- JSON Fields for flexibility
    options_json TEXT, -- ["Option A", "Option B", "Option C", "Option D"]
    correct_answer TEXT, -- "A" or "Answer Key"
    
    -- Scoring & Settings
    points REAL DEFAULT 1,
    settings_json TEXT, -- {"prep_seconds": 60, "speak_seconds": 120} for Speaking
    order_index INTEGER DEFAULT 0,
    
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP, explanation TEXT,
    
    FOREIGN KEY(group_id) REFERENCES vstep_question_groups(id) ON DELETE CASCADE,
    FOREIGN KEY(section_id) REFERENCES vstep_sections(id) ON DELETE CASCADE
);
CREATE TABLE vstep_exam_attempts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id INTEGER NOT NULL,
    exam_id INTEGER NOT NULL,
    
    -- Timing
    start_time DATETIME DEFAULT CURRENT_TIMESTAMP,
    submit_time DATETIME,
    
    -- Status
    status TEXT DEFAULT 'in_progress' CHECK(status IN ('in_progress', 'completed', 'abandoned')),
    grading_status TEXT DEFAULT 'pending' CHECK(grading_status IN ('pending', 'auto_graded', 'finalized')),
    
    -- Scores (Separated for Analysis)
    score_listening REAL,
    score_reading REAL,
    score_writing REAL,
    score_speaking REAL,
    total_score REAL,
    
    teacher_feedback TEXT, -- General feedback
    inspector_id INTEGER, last_heartbeat DATETIME, -- Teacher who graded
    
    FOREIGN KEY(student_id) REFERENCES students(id),
    FOREIGN KEY(exam_id) REFERENCES vstep_exams(id)
);
CREATE TABLE vstep_answers (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    attempt_id INTEGER NOT NULL,
    question_id INTEGER NOT NULL,
    
    answer_text TEXT, -- "A" for MCQ, Full text for Essay, R2 URL for Recording
    
    score REAL, -- Score for this specific question
    feedback TEXT, -- Specific feedback for this answer
    
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    
    FOREIGN KEY(attempt_id) REFERENCES vstep_exam_attempts(id) ON DELETE CASCADE,
    FOREIGN KEY(question_id) REFERENCES vstep_questions(id) ON DELETE CASCADE,
    UNIQUE(attempt_id, question_id) -- One answer per question per attempt
);
CREATE TABLE exam_categories (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL UNIQUE,
                    code TEXT NOT NULL UNIQUE,
                    description TEXT,
                    icon TEXT,
                    color TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE credit_modules (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    description TEXT,
    total_credits INTEGER DEFAULT 10,
    structure TEXT,
    order_index INTEGER DEFAULT 0
);
CREATE TABLE credit_progress (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    module_id INTEGER NOT NULL,
    credits_earned INTEGER DEFAULT 0,
    completed_tests TEXT,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(user_id, module_id)
);
CREATE TABLE admin_audit_log (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    admin_id INTEGER NOT NULL,
    action TEXT NOT NULL,
    resource_type TEXT,
    resource_id INTEGER,
    details TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE questions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  exam_id INTEGER NOT NULL,
  question_text TEXT NOT NULL,
  correct_answer TEXT NOT NULL,
  question_order INTEGER DEFAULT 0,
  FOREIGN KEY(exam_id) REFERENCES exams(id)
);
CREATE TABLE choices (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  question_id INTEGER NOT NULL,
  label TEXT NOT NULL,
  content TEXT NOT NULL,
  FOREIGN KEY(question_id) REFERENCES questions(id)
);
CREATE TABLE attempts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  exam_id INTEGER NOT NULL,
  student_id INTEGER NOT NULL,
  submitted_at DATETIME,
  score INTEGER DEFAULT 0,
  FOREIGN KEY(exam_id) REFERENCES exams(id),
  FOREIGN KEY(student_id) REFERENCES users(id)
);
CREATE TABLE answers (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  attempt_id INTEGER NOT NULL,
  question_id INTEGER NOT NULL,
  selected_answer TEXT,
  FOREIGN KEY(attempt_id) REFERENCES attempts(id),
  FOREIGN KEY(question_id) REFERENCES questions(id)
);
CREATE TABLE IF NOT EXISTS "vstep_sections" (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    exam_id INTEGER NOT NULL,
    type TEXT NOT NULL,
    title TEXT NOT NULL,
    order_index INTEGER DEFAULT 0,
    duration INTEGER DEFAULT 0,
    instructions TEXT,
    FOREIGN KEY(exam_id) REFERENCES vstep_exams(id) ON DELETE CASCADE
);
CREATE TABLE courses (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  thumbnail_url TEXT,
  original_price INTEGER NOT NULL,
  sale_price INTEGER NOT NULL,
  rating REAL DEFAULT 0,
  students_count INTEGER DEFAULT 0,
  lectures_count INTEGER DEFAULT 0,
  description TEXT,
  created_at INTEGER DEFAULT (unixepoch()),
  updated_at INTEGER DEFAULT (unixepoch())
);
CREATE TABLE exam_parts (
  id TEXT PRIMARY KEY,
  exam_id TEXT NOT NULL,
  skill_id TEXT NOT NULL CHECK(skill_id IN ('listening', 'reading', 'writing', 'speaking')),
  part_number INTEGER NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  content TEXT,
  audio_url TEXT,
  duration_minutes INTEGER,
  question_type TEXT CHECK(question_type IN ('multiple-choice', 'essay', 'recording')),
  FOREIGN KEY (exam_id) REFERENCES exams(id)
);
CREATE TABLE exam_answers (
  id TEXT PRIMARY KEY,
  attempt_id TEXT NOT NULL,
  question_id TEXT NOT NULL,
  answer_text TEXT,
  audio_url TEXT,
  is_correct INTEGER DEFAULT 0,
  points_earned INTEGER DEFAULT 0,
  answered_at INTEGER DEFAULT (unixepoch()),
  FOREIGN KEY (attempt_id) REFERENCES exam_attempts(id),
  FOREIGN KEY (question_id) REFERENCES exam_questions(id)
);
CREATE TABLE exams (id TEXT PRIMARY KEY, course_id TEXT NOT NULL, title TEXT NOT NULL, description TEXT, duration_minutes INTEGER NOT NULL, created_at INTEGER DEFAULT (unixepoch()), FOREIGN KEY (course_id) REFERENCES courses(id));
CREATE TABLE user_sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, token TEXT NOT NULL UNIQUE, ip_address TEXT, user_agent TEXT, device_fingerprint TEXT, created_at INTEGER DEFAULT (unixepoch()), last_activity INTEGER DEFAULT (unixepoch()), expires_at INTEGER DEFAULT (unixepoch() + 604800));
CREATE TABLE enrollments (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, course_id TEXT NOT NULL, progress INTEGER DEFAULT 0, completed_lessons INTEGER DEFAULT 0, total_lessons INTEGER DEFAULT 0, expiry_date INTEGER, last_accessed INTEGER, created_at INTEGER DEFAULT (unixepoch()), FOREIGN KEY (course_id) REFERENCES courses(id));
CREATE TABLE exam_security_logs (id TEXT PRIMARY KEY, attempt_id TEXT NOT NULL, user_id TEXT NOT NULL, event_type TEXT NOT NULL, event_data TEXT, ip_address TEXT, user_agent TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
